ACTIVE_DOWNLOADS: Dict[str, dict] = {}
DOWNLOAD_TERMINAL_RETENTION_SECONDS = 60 * 60


def _prune_download_state() -> None:
    """Drop old terminal entries so the in-memory status registry cannot grow forever."""
    now = time.time()
    for model_id, state in list(ACTIVE_DOWNLOADS.items()):
        if state.get("status") not in {"completed", "error", "cancelled"}:
            continue
        finished_at = float(state.get("finished_at") or 0)
        if finished_at and now - finished_at > DOWNLOAD_TERMINAL_RETENTION_SECONDS:
            ACTIVE_DOWNLOADS.pop(model_id, None)


def _safe_download_filename(filename: str) -> str:
    """Validate a Hub filename before it is joined to the models directory."""
    value = str(filename or "").strip().replace("\\", "/")
    path = Path(value)
    if not value or path.is_absolute() or "\x00" in value or ".." in path.parts:
        raise HTTPException(400, "Invalid download filename")
    if not value.lower().endswith(".gguf"):
        raise HTTPException(400, "Only GGUF downloads are supported")
    return value


def resolve_models_root() -> Path:
    override = os.environ.get("MEERA_MODELS_ROOT")
    if override and Path(override).expanduser().exists():
        return Path(override).expanduser().resolve()
    # The desktop launcher can start this API from several working
    # directories.  Anchor the bundled model library beside this source file
    # so a restart cannot make already-installed GGUFs disappear.
    source_models = Path(__file__).resolve().parent / "models"
    if source_models.exists():
        return source_models.resolve()
    if sys.platform == "darwin":
        return Path.home() / "Library" / "Application Support" / "MeeraAI" / "models"
    return Path("./models").resolve()


def read_json_object(path: Path, default: Optional[dict] = None) -> dict:
    if not path.exists():
        return default.copy() if isinstance(default, dict) else {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    return default.copy() if isinstance(default, dict) else {}


def write_json_object(path: Path, payload: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")


def sumDirectoryBytes(dir_path: Path) -> int:
    if not dir_path.exists():
        return 0
    total = 0
    for path_obj in dir_path.rglob("*"):
        if path_obj.is_file():
            try:
                total += path_obj.stat().st_size
            except OSError:
                continue
    return total


def safe_slug(value: str) -> str:
    slug = re.sub(r"[^0-9a-zA-Z._-]+", "-", value.strip())
    slug = re.sub(r"-{2,}", "-", slug).strip("-._")
    return slug or "model"


def quant_bits_from_name(value: str) -> Optional[int]:
    match = QUANT_PATTERN.search(value or "")
    if not match:
        return None
    token = match.group(1).upper()
    if token.startswith(("Q2", "IQ2")):
        return 2
    if token.startswith(("Q3", "IQ3")):
        return 3
    if token.startswith(("Q4", "IQ4")):
        return 4
    if token.startswith(("Q5", "IQ5")):
        return 5
    if token.startswith(("Q6", "IQ6")):
        return 6
    if token.startswith("Q8"):
        return 8
    if token in {"F16", "BF16"}:
        return 16
    if token == "F32":
        return 32
    return None


def precision_label_from_name(value: str) -> str:
    bits = quant_bits_from_name(value)
    if bits:
        if bits in {16, 32}:
            return f"{bits}-bit float"
        return f"{bits}-bit quantized"
    lowered = value.lower()
    if "fp16" in lowered or "f16" in lowered or "bf16" in lowered:
        return "FP16"
    if "fp32" in lowered or "f32" in lowered:
        return "FP32"
    return "GGUF"


def humanizeModelLabel(value: str) -> str:
    normalized = re.sub(r"[-_]+", " ", value or "").replace("/", " ").strip()
    normalized = re.sub(r"(?i)(unsloth|local|gguf)", "", normalized)
    normalized = re.sub(r"\s+", " ", normalized).strip()
    return normalized or value or "Local Model"


def inferPurpose(value: str) -> Tuple[str, bool]:
    lowered = (value or "").lower()
    if any(token in lowered for token in ["asr", "speech-to-text", "transcribe"]):
        return "asr", False
    if any(token in lowered for token in ["voice", "tts", "speech"]):
        return "speech", False
    if any(token in lowered for token in ["coder", "code"]):
        return "coding", True
    if any(token in lowered for token in ["math", "reason"]):
        return "math", True
    return "chat", True


def inferDynamicModelId(folder_name: str, repo_id: Optional[str]) -> str:
    import re
    def strip_prefixes(s):
        return re.sub(r'^((local|unsloth|Quantized|TheBloke|lmstudio-community|bartowski|mradermacher|city96)[^a-zA-Z0-9]*)+', '', s, flags=re.IGNORECASE)
    
    if repo_id:
        base = repo_id.split("/")[-1] if "/" in repo_id else repo_id
        return safe_slug(strip_prefixes(base))
    return safe_slug(strip_prefixes(folder_name))


def extractRepoId(config: Optional[dict]) -> Optional[str]:
    if not isinstance(config, dict):
        return None
    for key in ["_name_or_path", "name_or_path", "model_id", "model"]:
        value = config.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return None


def extractDtype(config: Optional[dict]) -> Optional[str]:
    if not isinstance(config, dict):
        return None
    dtype = config.get("torch_dtype") or config.get("dtype")
    return dtype.strip().lower() if isinstance(dtype, str) and dtype.strip() else None


def extractQuantBits(config: Optional[dict]) -> Optional[int]:
    if not isinstance(config, dict):
        return None
    quant = config.get("quantization_config")
    if isinstance(quant, dict):
        if quant.get("load_in_4bit") is True:
            return 4
        if quant.get("load_in_8bit") is True:
            return 8
        for key in ["bits", "bit_width", "bits_per_weight"]:
            value = quant.get(key)
            if isinstance(value, int) and value in {4, 8}:
                return value
    return None


def extractParamCount(config: Optional[dict]) -> Optional[int]:
    if not isinstance(config, dict):
        return None
    for key in ["num_parameters", "n_params", "params", "parameter_count", "num_params", "model_parameters"]:
        value = config.get(key)
        if isinstance(value, int) and value > 0:
            return int(value)
        if isinstance(value, str) and value.strip().isdigit():
            return int(value.strip())
    return None


def bytesPerParam(config: Optional[dict], quant_bits: Optional[int]) -> Optional[float]:
    if quant_bits in {4, 8}:
        return float(quant_bits) / 8.0
    dtype = extractDtype(config)
    if not dtype:
        return None
    mapping = {
        "float16": 2.0,
        "fp16": 2.0,
        "bfloat16": 2.0,
        "bf16": 2.0,
        "float32": 4.0,
        "fp32": 4.0,
        "float64": 8.0,
        "fp64": 8.0,
        "int8": 1.0,
        "uint8": 1.0,
        "int4": 0.5,
    }
    return mapping.get(dtype)


def formatParamCount(count: int) -> str:
    if count >= 1_000_000_000:
        value = count / 1_000_000_000
        return f"{value:.1f}B" if value < 10 else f"{value:.0f}B"
    if count >= 1_000_000:
        value = count / 1_000_000
        return f"{value:.1f}M" if value < 10 else f"{value:.0f}M"
    if count >= 1_000:
        return f"{count / 1_000:.1f}K"
    return str(int(count))


def readIndexTotalSize(dir_path: str) -> int:
    for name in ["model.safetensors.index.json", "pytorch_model.bin.index.json"]:
        full_path = Path(dir_path) / name
        data = read_json_object(full_path)
        metadata = data.get("metadata") if isinstance(data, dict) else None
        total_size = None
        if isinstance(metadata, dict):
            total_size = metadata.get("total_size")
        if isinstance(total_size, int) and total_size > 0:
            return total_size
        total_size = data.get("total_size") if isinstance(data, dict) else None
        if isinstance(total_size, int) and total_size > 0:
            return total_size
    return 0


def deriveParamsLabel(config: Optional[dict], weight_bytes: int, size_bytes: int, quant_bits: Optional[int]) -> str:
    explicit = extractParamCount(config)
    if explicit and explicit > 0:
        return formatParamCount(explicit)
    bpp = bytesPerParam(config, quant_bits)
    base = weight_bytes if weight_bytes > 0 else size_bytes
    if bpp and base > 0:
        return formatParamCount(int(base / bpp))
    return ""


def current_hf_token() -> str:
    payload = read_json_object(HF_TOKEN_FILE, {"tokens": []})
    tokens = payload.get("tokens", [])
    if isinstance(tokens, list):
        for token in reversed(tokens):
            if isinstance(token, str) and token.strip():
                return token.strip()
    return ""


def check_download_complete(model_dir: Path, gguf_filename: str = "") -> Optional[str]:
    """Return an error string when a GGUF file is a partial download.

    Reads download_state.json (written alongside the model) and compares the
    on-disk size against the expected total. Partially-downloaded GGUF files
    must never be handed to the model runtime - they fail to parse or silently
    corrupt output.
    """
    try:
        state = read_json_object(model_dir / "download_state.json")
    except Exception:
        return None
    if not isinstance(state, dict):
        return None
    total = int(state.get("total_bytes") or 0)
    if total <= 0:
        return None
    candidates = []
    if gguf_filename:
        candidates.append(gguf_path := model_dir / gguf_filename)
    else:
        candidates = list(model_dir.glob("*.gguf"))
    for candidate in candidates:
        if not candidate.exists():
            continue
        on_disk = candidate.stat().st_size
        if on_disk < total:
            return (
                f"{candidate.name} is still downloading ({on_disk / (2 ** 20):.0f} MB "
                f"of {total / (2 ** 20):.0f} MB). Complete or resume the download "
                "before loading this model."
            )
    return None


def gguf_file_options(model_dir: Path) -> List[dict]:
    options: List[dict] = []
    for file_path in sorted(model_dir.glob("*.gguf"), key=lambda item: item.name.lower()):
        try:
            size = file_path.stat().st_size
        except OSError:
            size = 0
        options.append({
            "filename": file_path.name,
            "size": size,
            "quant_bits": quant_bits_from_name(file_path.name) or 0,
            "precision_label": precision_label_from_name(file_path.name),
        })
    return options


def load_runtime_settings_store() -> dict:
    return read_json_object(MODEL_RUNTIME_SETTINGS_FILE, {"models": {}})


def save_runtime_settings_store(store: dict) -> None:
    write_json_object(MODEL_RUNTIME_SETTINGS_FILE, store)


def scan_local_gguf_library() -> List[dict]:
    root = resolve_models_root()
    if not root.exists():
        return []

    results: List[dict] = []
    for model_dir in sorted([entry for entry in root.iterdir() if entry.is_dir()], key=lambda entry: entry.name.lower()):
        gguf_files = gguf_file_options(model_dir)
        if not gguf_files:
            continue

        config = read_json_object(model_dir / "config.json")
        manifest = read_json_object(model_dir / MODEL_MANIFEST_NAME)
        repo_id = extractRepoId(config) or str(manifest.get("repo_id") or "").strip() or None
        label_source = str(manifest.get("label") or (repo_id.split("/")[-1] if repo_id else model_dir.name))
        label = humanizeModelLabel(label_source)
        model_id = inferDynamicModelId(model_dir.name, repo_id)
        local_bytes = sumDirectoryBytes(model_dir)
        quant_bits = next((file_info["quant_bits"] or None for file_info in gguf_files if file_info.get("quant_bits")), None)
        params = deriveParamsLabel(config, readIndexTotalSize(str(model_dir)), local_bytes, quant_bits)
        purpose, chat_capable = inferPurpose(f"{label} {model_dir.name} {repo_id or ''}")
        
        caps = ["streaming"]
        if chat_capable:
            caps.append("chat")
            name_lower = f"{label} {model_dir.name} {repo_id or ''}".lower()
            if any(t in name_lower for t in ["instruct", "it", "-it", "chat"]):
                caps.append("tools")
            if any(t in name_lower for t in ["vision", "vl", "llava", "pixtral"]):
                caps.append("vision")

        incomplete_hint = check_download_complete(model_dir, gguf_files[0]["filename"] if gguf_files else "")

        tier_index = infer_gguf_tier_index({
            "params": params,
            "label": label,
            "id": model_id,
            "folder": model_dir.name,
            "repo_id": repo_id,
        })
        desired_quant = preferred_gguf_quant_for_tier(tier_index)
        available_quantizations = sorted({
            _gguf_quant_name(f) for f in gguf_files if _gguf_quant_name(f)
        })
        policy_matches = [
            f for f in gguf_files
            if (_is_iq3(f) if desired_quant == "IQ3" else _is_iq4(f))
        ]

        _catalog_item = meera_catalog_match({
            "id": model_id, "label": label, "folder": model_dir.name,
            "repo_id": repo_id, "params": params,
        })
        if _catalog_item:
            model_id = _catalog_item["id"]
            label = _catalog_item["name"]
            tier_index = int(_catalog_item["tier"]) - 1
            desired_quant = _catalog_item["quantization"]

        results.append({
            "id": model_id,
            "label": label,
            "capabilities": (_catalog_item["capabilities"] if _catalog_item else caps),
            "folder": model_dir.name,
            "display_name": (_catalog_item["name"] if _catalog_item else label),
            "role": (_catalog_item["role"] if _catalog_item else purpose),
            "model_family": (_catalog_item["model_family"] if _catalog_item else None),
            "tier_index": tier_index,
            "tier": (tier_index + 1) if tier_index is not None else None,
            "recommended_quantization": desired_quant,
            "quantization_policy": f"{desired_quant} required for this tier",
            "available_quantizations": available_quantizations,
            "policy_compliant": bool(policy_matches) if tier_index is not None else True,
            "present": True,
            "download_incomplete": incomplete_hint,
            "size_bytes": local_bytes,
            "local_bytes": local_bytes,
            "path": str(model_dir),
            "params": params or None,
            "precision": gguf_file_options(model_dir)[0]["precision_label"] if gguf_file_options(model_dir) else "GGUF",
            "repo_id": repo_id,
            "quant_bits": quant_bits,
            "model_type": "causal",
            "purpose": purpose,
            "chat_capable": chat_capable,
            "has_gguf": True,
            "gguf_files": gguf_files,
            "manifest": manifest,
        })

    return results


def lookup_local_model(model_id: str) -> Optional[dict]:
    def _canonical_id(value: object) -> str:
        normalized = re.sub(r"[^a-z0-9]+", "-", str(value or "").lower()).strip("-")
        return normalized.removeprefix("local-")

    legacy_aliases = {
        "meera-lite-1b": "meera-nano",
        "meera-core-2b": "meera-mini",
        "meera-core-3b": "meera-edge",
        "meera-pro-4b": "meera",
        "meera-reasoning-8b": "meera-deep",
        "meera-ultra-7b": "meera-ultra",
        "meera-ultra-8b": "meera-ultra",
        "meera-ultra-9b": "meera-ultra",
    }
    requested_id = _canonical_id(legacy_aliases.get(_canonical_id(model_id), model_id))
    for entry in scan_local_gguf_library():
        if requested_id and any(
            _canonical_id(entry.get(key)) == requested_id
            for key in ("id", "repo_id", "folder", "label")
        ):
            return entry
    return None



def meera_production_profile(tier: int) -> dict:
    """Curated runtime profile for the seven Meera local tiers."""
    item = meera_catalog_for_tier(tier)
    if not item:
        return {
            "tier": "normal", "context_length": 8192,
            "max_tokens": 2048, "temperature": 0.25,
            "reasoning": False,
        }

    profiles = {
        1: {"context_length": 16384, "max_tokens": 4096, "temperature": 0.25, "reasoning": False},
        2: {"context_length": 16384, "max_tokens": 6144, "temperature": 0.25, "reasoning": False},
        3: {"context_length": 12288, "max_tokens": 4096, "temperature": 0.25, "reasoning": False},
        4: {"context_length": 16384, "max_tokens": 6144, "temperature": 0.25, "reasoning": False},
        5: {"context_length": 16384, "max_tokens": 6144, "temperature": 0.25, "reasoning": False},
        6: {"context_length": 16384, "max_tokens": 8192, "temperature": 0.20, "reasoning": True},
        7: {"context_length": 16384, "max_tokens": 8192, "temperature": 0.20, "reasoning": True},
    }
    return {
        **profiles[int(tier)],
        "tier": int(tier),
        "model_id": item["id"],
        "name": item["name"],
        "quantization": item["quantization"],
        "role": item["role"],
        "capabilities": item["capabilities"],
    }

def default_runtime_settings(selected_gguf: str = "") -> dict:
    try:
        ctx = choose_context_length(tier="normal")
    except Exception:
        ctx = 16384
    return {
        "context_length": ctx,
        "gpu_layers_mode": "auto",
        "gpu_layers": -1,
        "cpu_thread_pool_size": 0,
        "cpu_batch_thread_pool_size": 0,
        "evaluation_batch_size": 1024,
        "physical_batch_size": 256,
        "max_concurrent_predictions": 1,
        "unified_kv_cache": True,
        "rope_frequency_base": None,
        "rope_frequency_scale": None,
        "offload_kv_cache": True,
        "keep_model_in_memory": True,
        "try_mmap": True,
        "use_mlock": False,
        "seed": None,
        "flash_attention": True,
        "k_cache_quantization_type": "q8_0",
        "v_cache_quantization_type": "q8_0",
        "reasoning": False,
        "strong_reasoning": False,

        "selected_gguf": selected_gguf,
        "tier": "normal",
        "mode": "normal",
    }


_GPU_INFO_CACHE: Optional[dict] = None


def detect_gpu_info() -> dict:
    """Best-effort real GPU detection.

    - On macOS prefer to detect Apple Silicon via platform.machine() and
      fall back to sysctl -n machdep.cpu.brand_string. If Apple Silicon is
      detected, report a Metal unified-memory GPU (Apple Silicon) and use
      psutil when available to obtain system memory. If psutil is missing,
      fall back to sysctl hw.memsize and parsing vm_stat.

    - Otherwise try nvidia-smi for CUDA GPUs. The function is defensive and
      caches results for the process lifetime.
    """
    global _GPU_INFO_CACHE
    if _GPU_INFO_CACHE is not None:
        return _GPU_INFO_CACHE

    info = {
        "available": False,
        "name": None,
        "backend": "cpu-fallback",
        "total_bytes": None,
        "free_bytes": None,
        "total_gib": None,
        "free_gib": None,
        "count": 0,
    }

    try:
        import subprocess
        import sys
        import platform
        import re

        def _mem_from_psutil():
            try:
                import psutil as _psutil
            except Exception:
                return None, None
            try:
                m = _psutil.virtual_memory()
                return getattr(m, "total", None), getattr(m, "available", None)
            except Exception:
                return None, None

        if sys.platform == "darwin":
            # Prefer platform.machine() to detect Apple Silicon
            machine = (platform.machine() or "").lower()
            is_arm = machine.startswith("arm") or machine in ("arm64", "aarch64")

            # Fallback to sysctl brand string if needed
            cpu_brand = ""
            try:
                cpu_brand = subprocess.run(["sysctl", "-n", "machdep.cpu.brand_string"], capture_output=True, text=True, timeout=2).stdout.strip() or ""
            except Exception:
                cpu_brand = ""

            is_apple_silicon = is_arm or ("apple" in cpu_brand.lower())

            if is_apple_silicon:
                total_bytes = None
                free_bytes = None

                # Prefer psutil if available
                total_bytes, free_bytes = _mem_from_psutil()

                # Fallback to sysctl hw.memsize for total RAM
                if total_bytes is None:
                    try:
                        res = subprocess.run(["sysctl", "-n", "hw.memsize"], capture_output=True, text=True, timeout=2)
                        if res.returncode == 0 and res.stdout.strip():
                            total_bytes = int(res.stdout.strip())
                    except Exception:
                        total_bytes = None

                # Fallback to vm_stat parsing for available memory estimate
                if free_bytes is None:
                    try:
                        res = subprocess.run(["vm_stat"], capture_output=True, text=True, timeout=2)
                        out = res.stdout or ""
                        m = re.search(r"page size of (\d+) bytes", out)
                        page_size = int(m.group(1)) if m else 4096
                        free_count = 0
                        for line in out.splitlines():
                            if any(k in line for k in ("Pages free", "Pages speculative", "Pages inactive")):
                                parts = line.split(":")
                                if len(parts) > 1:
                                    num = re.sub(r"[^0-9]", "", parts[1])
                                    if num:
                                        free_count += int(num)
                        free_bytes = free_count * page_size if free_count > 0 else None
                    except Exception:
                        free_bytes = None

                info = {
                    "available": True,
                    "name": "Apple Silicon (Metal)",
                    "backend": "metal",
                    "total_bytes": total_bytes,
                    "free_bytes": free_bytes,
                    "total_gib": round(bytes_to_gib(total_bytes), 1) if total_bytes else None,
                    "free_gib": round(bytes_to_gib(free_bytes), 1) if free_bytes else None,
                    "count": 1,
                }

                _GPU_INFO_CACHE = info
                return info

        # Fallback: try NVIDIA's nvidia-smi for CUDA GPUs
        result = subprocess.run(
            [
                "nvidia-smi",
                "--query-gpu=name,memory.total,memory.free",
                "--format=csv,noheader,nounits",
            ],
            capture_output=True,
            text=True,
            timeout=5,
        )
        if result.returncode == 0 and result.stdout.strip():
            lines = [line.strip() for line in result.stdout.strip().splitlines() if line.strip()]
            if lines:
                parsed = []
                for line in lines:
                    parts = [p.strip() for p in line.split(",")]
                    if len(parts) >= 3:
                        try:
                            name = parts[0]
                            total_mib = float(parts[1])
                            free_mib = float(parts[2])
                            parsed.append((name, total_mib, free_mib))
                        except ValueError:
                            continue
                if parsed:
                    primary_name = parsed[0][0]
                    total_bytes = int(sum(p[1] for p in parsed) * 1024 * 1024)
                    free_bytes = int(sum(p[2] for p in parsed) * 1024 * 1024)
                    info = {
                        "available": True,
                        "name": primary_name if len(parsed) == 1 else f"{primary_name} (+{len(parsed) - 1} more)",
                        "backend": "cuda",
                        "total_bytes": total_bytes,
                        "free_bytes": free_bytes,
                        "total_gib": round(bytes_to_gib(total_bytes), 1),
                        "free_gib": round(bytes_to_gib(free_bytes), 1),
                        "count": len(parsed),
                    }
    except (FileNotFoundError, OSError, ValueError):
        # nvidia-smi not present or command failed; fall through to CPU fallback
        pass
    except Exception:
        # Be defensive: avoid crashing Meera on unexpected errors
        pass

    if not info["available"] and HAS_LLAMA_GPU_OFFLOAD:
        # llama.cpp can be CUDA-enabled even when nvidia-smi is unavailable
        # in a packaged environment. Keep the runtime/UI truthful in that
        # case instead of reporting CPU-only and selecting CPU defaults.
        info = {
            **info,
            "available": True,
            "name": "CUDA accelerator",
            "backend": "cuda",
            "count": 1,
        }

    _GPU_INFO_CACHE = info
    return info


def get_system_memory_bytes() -> Tuple[Optional[int], Optional[int]]:
    total: Optional[int] = None
    available: Optional[int] = None
    try:
        import psutil
        mem = psutil.virtual_memory()
        return int(mem.total), int(mem.available)
    except ImportError:
        pass
    
    try:
        if os.name == "nt":
            import ctypes

            class MEMORYSTATUSEX(ctypes.Structure):
                _fields_ = [
                    ("dwLength", ctypes.c_ulong),
                    ("dwMemoryLoad", ctypes.c_ulong),
                    ("ullTotalPhys", ctypes.c_ulonglong),
                    ("ullAvailPhys", ctypes.c_ulonglong),
                    ("ullTotalPageFile", ctypes.c_ulonglong),
                    ("ullAvailPageFile", ctypes.c_ulonglong),
                    ("ullTotalVirtual", ctypes.c_ulonglong),
                    ("ullAvailVirtual", ctypes.c_ulonglong),
                    ("ullAvailExtendedVirtual", ctypes.c_ulonglong),
                ]

            status = MEMORYSTATUSEX()
            status.dwLength = ctypes.sizeof(MEMORYSTATUSEX)
            if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(status)):
                total = int(status.ullTotalPhys)
                available = int(status.ullAvailPhys)
        elif hasattr(os, "sysconf") and "SC_PAGE_SIZE" in os.sysconf_names and "SC_PHYS_PAGES" in os.sysconf_names:
            total = int(os.sysconf("SC_PAGE_SIZE") * os.sysconf("SC_PHYS_PAGES"))
            if "SC_AVPHYS_PAGES" in os.sysconf_names:
                available = int(os.sysconf("SC_PAGE_SIZE") * os.sysconf("SC_AVPHYS_PAGES"))
            else:
                try:
                    import psutil
                    available = psutil.virtual_memory().available
                except ImportError:
                    pass
    except Exception:
        pass
    return total, available


def bytes_to_gib(value: Optional[int]) -> float:
    amount = float(value or 0)
    if amount <= 0:
        return 0.0
    return amount / (1024 ** 3)


def format_gib(value: Optional[int]) -> str:
    gib = bytes_to_gib(value)
    return f"{gib:.1f} GB" if gib >= 1 else f"{(gib * 1024):.0f} MB"


def estimate_gguf_vram_bytes(file_size_bytes: int, quant_bits: Optional[int], context_length: int) -> int:
    size = max(int(file_size_bytes or 0), 1)
    quant = quant_bits or 8
    quant_multiplier = {
        2: 0.22,
        3: 0.28,
        4: 0.35,
        5: 0.42,
        6: 0.48,
        8: 0.56,
        16: 0.88,
        32: 1.12,
    }.get(quant, 0.56)
    kv_cache = max(256 * 1024 * 1024, int(context_length * 1024 * (8 + max(0, quant - 4))))
    runtime_overhead = max(192 * 1024 * 1024, int(size * 0.07))
    return int(size * quant_multiplier + kv_cache + runtime_overhead)


def choose_performance_class(total_memory_bytes: Optional[int], vram_bytes: int) -> str:
    total = int(total_memory_bytes or 0)
    if total <= 0:
        return "balanced"
    ratio = vram_bytes / max(total, 1)
    if ratio >= 0.8:
        return "cpu-only"
    if ratio >= 0.55:
        return "low-vram"
    if ratio >= 0.28:
        return "balanced"
    if ratio >= 0.12:
        return "performance"
    return "workstation"


def calculate_context_from_hardware(vram_gib: float, ram_gib: float, tier: str = "normal") -> int:
    """Smart mathematical calculation of context window based on detected hardware.
    
    Dynamically scales according to user's hardware:
      - 2GB VRAM: Normal=8192, Advance=12288, Expert=16384
      - 4GB VRAM: Normal=12288, Advance=16384, Expert=24576
      - 6GB VRAM (e.g. RTX 4050/3060): Normal=16384, Advance=24576, Expert=32768
      - 8GB VRAM (e.g. RTX 4060/3070): Normal=24576, Advance=32768, Expert=49152
      - 12GB+ VRAM: Normal=32768, Advance=49152, Expert=65536
      - 16GB+ VRAM: Normal=32768, Advance=65536, Expert=131072
      - System RAM fallback scales dynamically from 8192 to 32768.
    """
    tier_norm = str(tier or "normal").lower().strip()
    if tier_norm == "advance":
        tier_norm = "advanced"

    if vram_gib >= 1.5:
        # Dedicated GPU acceleration (CUDA, Metal, ROCm)
        if vram_gib >= 15.0:
            scale = {"normal": 32768, "advanced": 65536, "expert": 131072}
        elif vram_gib >= 10.5:
            scale = {"normal": 32768, "advanced": 49152, "expert": 65536}
        elif vram_gib >= 7.2:
            scale = {"normal": 24576, "advanced": 32768, "expert": 49152}
        elif vram_gib >= 5.2:  # 6GB VRAM (user's RTX 4050)
            scale = {"normal": 16384, "advanced": 24576, "expert": 32768}
        elif vram_gib >= 3.2:  # 4GB VRAM
            scale = {"normal": 12288, "advanced": 16384, "expert": 24576}
        else:  # 2GB VRAM
            scale = {"normal": 8192, "advanced": 12288, "expert": 16384}
    else:
        # CPU / Integrated GPU based on accessible RAM
        effective_ram = max(4.0, ram_gib * 0.45)
        if effective_ram >= 14.0:
            scale = {"normal": 16384, "advanced": 24576, "expert": 32768}
        elif effective_ram >= 7.0:
            scale = {"normal": 12288, "advanced": 16384, "expert": 24576}
        else:
            scale = {"normal": 8192, "advanced": 12288, "expert": 16384}

    return scale.get(tier_norm, scale["normal"])


def choose_context_length(total_memory_bytes: Optional[int] = None, file_size_bytes: int = 0, tier: str = "normal") -> int:
    gpu_info = detect_gpu_info()
    vram_gib = float(gpu_info.get("total_gib") or bytes_to_gib(gpu_info.get("total_bytes"))) if gpu_info.get("available") else 0.0
    if total_memory_bytes is None:
        total_memory_bytes, _ = get_system_memory_bytes()
    ram_gib = bytes_to_gib(total_memory_bytes)
    return calculate_context_from_hardware(vram_gib, ram_gib, tier)


def build_runtime_stage_payload(
    file_name: str = "",
    file_size_bytes: int = 0,
    quant_bits: Optional[int] = None,
    total_memory_bytes: Optional[int] = None,
) -> dict:
    gpu_info = detect_gpu_info()
    vram_gib = float(gpu_info.get("total_gib") or bytes_to_gib(gpu_info.get("total_bytes"))) if gpu_info.get("available") else 0.0
    if total_memory_bytes is None:
        total_memory_bytes, _ = get_system_memory_bytes()
    ram_gib = bytes_to_gib(total_memory_bytes)
    cpu_count = os.cpu_count() or 4

    normal_ctx = calculate_context_from_hardware(vram_gib, ram_gib, "normal")
    advanced_ctx = calculate_context_from_hardware(vram_gib, ram_gib, "advanced")
    expert_ctx = calculate_context_from_hardware(vram_gib, ram_gib, "expert")

    # Dynamic thread allocation per mode
    normal_threads = max(1, cpu_count - 2) if cpu_count > 2 else 1
    advanced_threads = max(1, cpu_count - 1)
    expert_threads = cpu_count

    # Dynamic batch allocation per mode & VRAM
    if vram_gib >= 7.5:
        normal_batch, normal_ubatch = 1024, 256
        advanced_batch, advanced_ubatch = 1536, 384
        expert_batch, expert_ubatch = 2048, 512
    elif vram_gib >= 5.0:  # 6GB VRAM
        normal_batch, normal_ubatch = 512, 128
        advanced_batch, advanced_ubatch = 1024, 256
        expert_batch, expert_ubatch = 2048, 512
    elif vram_gib >= 3.0:  # 4GB VRAM
        normal_batch, normal_ubatch = 512, 128
        advanced_batch, advanced_ubatch = 768, 192
        expert_batch, expert_ubatch = 1024, 256
    else:  # 2GB / CPU
        normal_batch, normal_ubatch = 512, 128
        advanced_batch, advanced_ubatch = 512, 128
        expert_batch, expert_ubatch = 1024, 256

    normal_settings = {
        **default_runtime_settings(file_name),
        "context_length": normal_ctx,
        "cpu_thread_pool_size": normal_threads,
        "cpu_batch_thread_pool_size": cpu_count,
        "evaluation_batch_size": normal_batch,
        "physical_batch_size": normal_ubatch,
        "gpu_layers_mode": "auto",
        "gpu_layers": -1,
        "offload_kv_cache": True,
        "flash_attention": True,
        "k_cache_quantization_type": "f16" if vram_gib >= 10.0 else "q8_0",
        "v_cache_quantization_type": "f16" if vram_gib >= 10.0 else "q8_0",
        "tier": "normal",
        "mode": "normal",
        "temperature": 0.7,
        "top_p": 0.9,
    }

    advanced_settings = {
        **normal_settings,
        "context_length": advanced_ctx,
        "cpu_thread_pool_size": advanced_threads,
        "cpu_batch_thread_pool_size": cpu_count,
        "evaluation_batch_size": advanced_batch,
        "physical_batch_size": advanced_ubatch,
        "gpu_layers_mode": "max",
        "gpu_layers": -1,
        "flash_attention": True,
        "k_cache_quantization_type": "q8_0" if vram_gib >= 5.0 else "q4_0",
        "v_cache_quantization_type": "q8_0" if vram_gib >= 5.0 else "q4_0",
        "tier": "advanced",
        "mode": "advance",
        "temperature": 0.6,
        "top_p": 0.95,
    }

    expert_settings = {
        **advanced_settings,
        "context_length": expert_ctx,
        "cpu_thread_pool_size": expert_threads,
        "cpu_batch_thread_pool_size": cpu_count,
        "evaluation_batch_size": expert_batch,
        "physical_batch_size": expert_ubatch,
        "gpu_layers_mode": "custom",
        "gpu_layers": -1,
        "keep_model_in_memory": True,
        "try_mmap": True,
        "use_mlock": False,
        "flash_attention": True,
        "k_cache_quantization_type": "q4_0",
        "v_cache_quantization_type": "q4_0",
        "tier": "expert",
        "mode": "expert",
        "temperature": 0.5,
        "top_p": 0.95,
    }

    hw_name = gpu_info.get("name") or "CPU"
    hw_desc = f"{hw_name} ({vram_gib:.1f} GB VRAM)" if vram_gib > 0 else f"System RAM ({ram_gib:.1f} GB)"

    return {
        "normal": {
            "settings": normal_settings,
            "estimated_vram_bytes": estimate_gguf_vram_bytes(file_size_bytes, quant_bits, normal_ctx),
            "label": "Normal",
            "context_window": normal_ctx,
            "caption": f"{normal_ctx // 1024}k Context · Stable & Balanced",
        },
        "advanced": {
            "settings": advanced_settings,
            "estimated_vram_bytes": estimate_gguf_vram_bytes(file_size_bytes, quant_bits, advanced_ctx),
            "label": "Advance",
            "context_window": advanced_ctx,
            "caption": f"{advanced_ctx // 1024}k Context · High Speed",
        },
        "expert": {
            "settings": expert_settings,
            "estimated_vram_bytes": estimate_gguf_vram_bytes(file_size_bytes, quant_bits, expert_ctx),
            "label": "Expert",
            "context_window": expert_ctx,
            "caption": f"{expert_ctx // 1024}k Context · Max Reasoning",
        },
        "hardware": {
            "device": hw_desc,
            "gpu_name": hw_name,
            "vram_gib": vram_gib,
            "ram_gib": ram_gib,
            "backend": gpu_info.get("backend") or "cpu",
        },
        "recommended_tier": "advanced" if vram_gib >= 5.0 else "normal",
        "formula": f"Dynamically calculated from hardware specs: {hw_desc}",
    }


def select_runtime_recommendation(stage_payload: dict) -> dict:
    recommended_tier = str(stage_payload.get("recommended_tier") or "normal").strip()
    if recommended_tier not in {"normal", "advanced", "expert"}:
        recommended_tier = "normal"
    return stage_payload.get(recommended_tier, stage_payload.get("normal", {})).get("settings", default_runtime_settings())


def rewrite_hf_readme_assets(readme: str, repo_id: str) -> str:
    if not readme:
        return ""
    raw_base = f"https://huggingface.co/{repo_id}/resolve/main/"
    readme = re.sub(
        r'(<img[^>]+src=["\'])(?!https?://|data:|/)([^"\']+)(["\'][^>]*>)',
        lambda match: f"{match.group(1)}{raw_base}{match.group(2).lstrip('./')}{match.group(3)}",
        readme,
        flags=re.IGNORECASE,
    )
    readme = re.sub(
        r'(!\[[^\]]*\]\()((?!https?://|/|data:)[^)]+)(\))',
        lambda match: f"{match.group(1)}{raw_base}{match.group(2).lstrip('./')}{match.group(3)}",
        readme,
    )
    readme = re.sub(
        r'(<a[^>]+href=["\'])(?!https?://|mailto:|/)([^"\']+)(["\'][^>]*>)',
        lambda match: f"{match.group(1)}{raw_base}{match.group(2).lstrip('./')}{match.group(3)}",
        readme,
        flags=re.IGNORECASE,
    )
    return readme


def explain_model_load_error(error: Exception, model_label: str, gguf_path: Optional[Path] = None) -> Tuple[str, str]:
    raw_message = str(getattr(error, "detail", None) or error).strip() or "Unable to load the selected GGUF model."
    lower = raw_message.lower()
    if "unexpected keyword argument 'repetition_penalty'" in lower:
        return (
            f"Native llama.cpp load failed for {model_label} because the runtime used an unsupported parameter name.",
            "The backend now maps that option to `repeat_penalty`. Restart the backend and load the model again.",
        )
    if "no such file" in lower or "not found" in lower:
        return (
            f"GGUF file not found for {model_label}.",
            f"Verify that the selected GGUF file exists on disk{f' at {gguf_path}' if gguf_path else ''} and try loading again.",
        )
    if "cannot allocate" in lower or "out of memory" in lower:
        return (
            f"Model load failed for {model_label} because the machine ran out of memory.",
            "Choose a smaller GGUF quantization, lower the context length, or reduce GPU offload and retry.",
        )
    if "context" in lower and "train" in lower:
        return (
            f"Model load failed for {model_label} because the selected context is beyond the model's safe range.",
            "Reduce the context length in recommended settings and reload the model.",
        )
    return (
        f"Model load failed for {model_label}.",
        "Check the GGUF file, reduce the context length, or choose a smaller quantization and try again.",
    )


def build_hardware_profile(
    headline: str,
    file_size_bytes: int,
    quant_bits: Optional[int],
    context_length: int,
    selected_vram_bytes: int,
) -> dict:
    total_mem, available_mem = get_system_memory_bytes()
    gpu_info = detect_gpu_info()
    return {
        "cpu": {
            "logical_cores": os.cpu_count() or 0,
            "physical_cores": max(1, (os.cpu_count() or 2) // 2),
        },
        "memory": {
            "total_bytes": total_mem,
            "available_bytes": available_mem,
            "total_gib": round(bytes_to_gib(total_mem), 1) if total_mem else None,
            "available_gib": round(bytes_to_gib(available_mem), 1) if available_mem else None,
        },
        "gpu": gpu_info,
        "performance_class": choose_performance_class(total_mem, selected_vram_bytes),
        "headline": headline,
        "model": {
            "file_size_bytes": file_size_bytes,
            "quant_bits": quant_bits,
            "context_length": context_length,
            "estimated_vram_bytes": selected_vram_bytes,
        },
    }




