# ==================================================
# SECTION 4: PERSISTENCE LAYER
# ==================================================

class PersistenceManager:
    """Unified persistence for config, database, and file storage."""

    def __init__(self):
        self._config: Optional[AppConfig] = None
        self._mcp_servers: Dict[str, MCPServerConfig] = {}
        # Use a write lock for serializing DB writes; allow concurrent reads using separate connections
        self._write_lock = threading.Lock()
        # Keep _db_lock name for backward compatibility but have it point to write lock
        self._db_lock = self._write_lock
        # Embedding update batch buffer (store tuples of (chunk_id, embedding_json))
        self._embedding_batch: List[Tuple[str, str]] = []
        self._batch_lock = threading.Lock()
        self._batch_max_size = 200
        self._batch_flush_interval = 2.0
        self._stop_batch = threading.Event()
        self._batch_thread = threading.Thread(target=self._embedding_batch_worker, daemon=True)
        self._batch_thread.start()
        self._ensure_dirs()
        self._init_db()

    def _ensure_dirs(self):
        for d in [DATA_DIR, DOCUMENTS_DIR, INDEXES_DIR, UPLOAD_DIR]:
            d.mkdir(parents=True, exist_ok=True)

    def _get_db_conn(self):
        conn = sqlite3.connect(str(DB_FILE), timeout=30.0)
        conn.execute("PRAGMA journal_mode = WAL")
        conn.execute("PRAGMA synchronous = NORMAL")
        return conn

    # --- Embedding batch flushing for rag_chunks ---
    def _embedding_batch_worker(self):
        # Background thread that periodically flushes embedding updates
        while not self._stop_batch.is_set():
            try:
                self.flush_embedding_batch()
            except Exception:
                # Avoid crashing the worker thread
                pass
            time.sleep(self._batch_flush_interval)

    def add_embedding_to_batch(self, chunk_id: str, embedding_json: str):
        """Add an embedding update to the in-memory batch. Flushes when threshold reached."""
        with self._batch_lock:
            self._embedding_batch.append((chunk_id, embedding_json))
            if len(self._embedding_batch) >= self._batch_max_size:
                # flush synchronously to reduce memory usage
                self.flush_embedding_batch()

    def flush_embedding_batch(self):
        """Flush pending embedding updates to the DB in a single transaction."""
        with self._batch_lock:
            if not self._embedding_batch:
                return
            items = self._embedding_batch
            self._embedding_batch = []
        # Perform batched update under write lock
        with self._write_lock:
            conn = self._get_db_conn()
            try:
                conn.execute("BEGIN")
                params = [(e_json, cid) for cid, e_json in items]
                conn.executemany("UPDATE rag_chunks SET embedding=? WHERE id=?", params)
                conn.commit()
            finally:
                conn.close()

    def _init_db(self):
        with self._db_lock:
            conn = self._get_db_conn()
            conn.execute("""
                CREATE TABLE IF NOT EXISTS conversations (
                    id TEXT PRIMARY KEY,
                    title TEXT NOT NULL DEFAULT 'New Chat',
                    model TEXT NOT NULL DEFAULT '',
                    system_prompt TEXT NOT NULL DEFAULT '',
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL
                )
            """)
            conn.execute("""
                CREATE TABLE IF NOT EXISTS messages (
                    id TEXT PRIMARY KEY,
                    conversation_id TEXT NOT NULL,
                    role TEXT NOT NULL,
                    content TEXT NOT NULL,
                    tool_calls TEXT,
                    tool_call_id TEXT,
                    name TEXT,
                    created_at TEXT NOT NULL,
                    FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE
                )
            """)
            conn.execute("""
                CREATE TABLE IF NOT EXISTS rag_documents (
                    id TEXT PRIMARY KEY,
                    filename TEXT NOT NULL,
                    file_type TEXT NOT NULL,
                    size_bytes INTEGER NOT NULL,
                    pages INTEGER DEFAULT 0,
                    chunks INTEGER DEFAULT 0,
                    indexed INTEGER DEFAULT 0,
                    indexed_at TEXT,
                    uploaded_at TEXT NOT NULL,
                    file_path TEXT NOT NULL
                )
            """)
            conn.execute("""
                CREATE TABLE IF NOT EXISTS rag_chunks (
                    id TEXT PRIMARY KEY,
                    document_id TEXT NOT NULL,
                    page_number INTEGER NOT NULL,
                    chunk_index INTEGER NOT NULL,
                    text TEXT NOT NULL,
                    embedding BLOB,
                    FOREIGN KEY (document_id) REFERENCES rag_documents(id) ON DELETE CASCADE
                )
            """)
            conn.execute("""
                CREATE INDEX IF NOT EXISTS idx_messages_conv
                ON messages(conversation_id, created_at)
            """)
            conn.execute("""
                CREATE INDEX IF NOT EXISTS idx_rag_chunks_doc
                ON rag_chunks(document_id)
            """)
            conn.execute("""
                CREATE INDEX IF NOT EXISTS idx_conversations_updated_at
                ON conversations(updated_at DESC)
            """)
            conn.execute("""
                CREATE INDEX IF NOT EXISTS idx_rag_documents_uploaded_at
                ON rag_documents(uploaded_at DESC)
            """)
            conn.execute("""
                CREATE INDEX IF NOT EXISTS idx_rag_chunks_doc_page_idx
                ON rag_chunks(document_id, page_number, chunk_index)
            """)
            conn.commit()
            conn.close()

    # --- Config ---

    @property
    def config(self) -> AppConfig:
        if self._config is None:
            self._config = self._load_config()
        return self._config

    @config.setter
    def config(self, value: AppConfig):
        self._config = value
        self._save_config(value)

    def _load_config(self) -> AppConfig:
        if CONFIG_FILE.exists():
            try:
                data = json.loads(CONFIG_FILE.read_text(encoding="utf-8"))
                return AppConfig.model_validate(data)
            except Exception as e:
                logger.error(f"Config load error: {e}")
        return AppConfig()

    def _save_config(self, config: AppConfig):
        CONFIG_FILE.write_text(
            config.model_dump_json(indent=2), encoding="utf-8"
        )

    # --- MCP Servers Config ---

    @property
    def mcp_servers(self) -> Dict[str, MCPServerConfig]:
        if not self._mcp_servers:
            self._mcp_servers = self._load_mcp_config()
        return self._mcp_servers

    def _load_mcp_config(self) -> Dict[str, MCPServerConfig]:
        if MCP_CONFIG_FILE.exists():
            try:
                data = json.loads(MCP_CONFIG_FILE.read_text(encoding="utf-8"))
                return {
                    k: MCPServerConfig.model_validate(v)
                    for k, v in data.get("mcpServers", {}).items()
                }
            except Exception as e:
                logger.error(f"MCP config load error: {e}")
        return {}

    def save_mcp_config(self):
        data = {"mcpServers": {
            k: v.model_dump() for k, v in self._mcp_servers.items()
        }}
        MCP_CONFIG_FILE.write_text(
            json.dumps(data, indent=2), encoding="utf-8"
        )

    # --- Conversations ---

    def create_conversation(self, conv_id: str, model: str = "",
                            system_prompt: str = "") -> str:
        now = datetime.now(timezone.utc).isoformat()
        with self._db_lock:
            conn = self._get_db_conn()
            conn.execute(
                "INSERT OR REPLACE INTO conversations VALUES (?,?,?,?,?,?)",
                (conv_id, "New Chat", model, system_prompt, now, now)
            )
            conn.commit()
            conn.close()
        return conv_id

    def update_conversation_title(self, conv_id: str, title: str):
        now = datetime.now(timezone.utc).isoformat()
        with self._db_lock:
            conn = self._get_db_conn()
            conn.execute(
                "UPDATE conversations SET title=?, updated_at=? WHERE id=?",
                (title, now, conv_id)
            )
            conn.commit()
            conn.close()

    def update_conversation_model(self, conv_id: str, model: str):
        now = datetime.now(timezone.utc).isoformat()
        with self._db_lock:
            conn = self._get_db_conn()
            conn.execute(
                "UPDATE conversations SET model=?, updated_at=? WHERE id=?",
                (model, now, conv_id)
            )
            conn.commit()
            conn.close()

    def list_conversations(self) -> List[ConversationSummary]:
        conn = self._get_db_conn()
        try:
            conn.row_factory = sqlite3.Row
            rows = conn.execute("""
                SELECT c.id, c.title, c.model, c.created_at, c.updated_at,
                       COUNT(m.id) as message_count
                FROM conversations c
                LEFT JOIN messages m ON m.conversation_id = c.id
                GROUP BY c.id
                ORDER BY c.updated_at DESC
            """).fetchall()
        finally:
            conn.close()
        return [ConversationSummary(**dict(r)) for r in rows]

    def get_conversation(self, conv_id: str) -> Optional[ConversationFull]:
        conn = self._get_db_conn()
        try:
            conn.row_factory = sqlite3.Row
            row = conn.execute(
                "SELECT * FROM conversations WHERE id=?", (conv_id,)
            ).fetchone()
            if not row:
                return None
            msgs = conn.execute(
                "SELECT * FROM messages WHERE conversation_id=? ORDER BY created_at",
                (conv_id,)
            ).fetchall()
        finally:
            conn.close()
        messages = []
        for m in msgs:
            msg_dict = {
                "role": m["role"],
                "content": m["content"],
            }
            if m["tool_calls"]:
                msg_dict["tool_calls"] = json.loads(m["tool_calls"])
            if m["tool_call_id"]:
                msg_dict["tool_call_id"] = m["tool_call_id"]
            if m["name"]:
                msg_dict["name"] = m["name"]
            messages.append(msg_dict)
        return ConversationFull(
            id=row["id"], title=row["title"], model=row["model"],
            created_at=row["created_at"], updated_at=row["updated_at"],
            messages=messages, system_prompt=row.get("system_prompt", "")
        )

    def add_message(self, conv_id: str, role: str, content: str,
                    tool_calls: Optional[list] = None,
                    tool_call_id: Optional[str] = None,
                    name: Optional[str] = None):
        now = datetime.now(timezone.utc).isoformat()
        msg_id = f"msg-{uuid.uuid4().hex[:16]}"
        with self._db_lock:
            conn = self._get_db_conn()
            conn.execute(
                "INSERT INTO messages VALUES (?,?,?,?,?,?,?,?)",
                (msg_id, conv_id, role, content,
                 json.dumps(tool_calls) if tool_calls else None,
                 tool_call_id, name, now)
            )
            conn.execute(
                "UPDATE conversations SET updated_at=? WHERE id=?",
                (now, conv_id)
            )
            conn.commit()
            conn.close()
        return msg_id

    def delete_conversation(self, conv_id: str):
        with self._db_lock:
            conn = self._get_db_conn()
            conn.execute("DELETE FROM messages WHERE conversation_id=?", (conv_id,))
            conn.execute("DELETE FROM conversations WHERE id=?", (conv_id,))
            conn.commit()
            conn.close()

    def delete_all_conversations(self):
        with self._db_lock:
            conn = self._get_db_conn()
            conn.execute("DELETE FROM messages")
            conn.execute("DELETE FROM conversations")
            conn.commit()
            conn.close()

    # --- RAG Documents ---

    def add_rag_document(self, doc: RAGDocumentInfo, file_path: str):
        with self._db_lock:
            conn = self._get_db_conn()
            conn.execute(
                "INSERT OR REPLACE INTO rag_documents VALUES (?,?,?,?,?,?,?,?,?,?)",
                (doc.id, doc.filename, doc.file_type, doc.size_bytes,
                 doc.pages, doc.chunks, int(doc.indexed), doc.indexed_at,
                 doc.uploaded_at, file_path)
            )
            conn.commit()
            conn.close()

    def update_rag_document_indexed(self, doc_id: str, pages: int, chunks: int):
        now = datetime.now(timezone.utc).isoformat()
        with self._db_lock:
            conn = self._get_db_conn()
            conn.execute(
                "UPDATE rag_documents SET indexed=1, indexed_at=?, pages=?, chunks=? WHERE id=?",
                (now, pages, chunks, doc_id)
            )
            conn.commit()
            conn.close()

    def list_rag_documents(self) -> List[RAGDocumentInfo]:
        conn = self._get_db_conn()
        try:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                "SELECT * FROM rag_documents ORDER BY uploaded_at DESC"
            ).fetchall()
        finally:
            conn.close()
        return [RAGDocumentInfo(**dict(r)) for r in rows]

    def delete_rag_document(self, doc_id: str):
        with self._db_lock:
            conn = self._get_db_conn()
            row = conn.execute(
                "SELECT file_path FROM rag_documents WHERE id=?", (doc_id,)
            ).fetchone()
            if row and row[0]:
                try:
                    Path(row[0]).unlink(missing_ok=True)
                except Exception:
                    pass
            conn.execute("DELETE FROM rag_chunks WHERE document_id=?", (doc_id,))
            conn.execute("DELETE FROM rag_documents WHERE id=?", (doc_id,))
            conn.commit()
            conn.close()
        # Remove index file
        idx_file = INDEXES_DIR / f"{doc_id}.json"
        idx_file.unlink(missing_ok=True)
        pageindex_cache = INDEXES_DIR / f"{doc_id}.pageindex.json"
        pageindex_cache.unlink(missing_ok=True)

    # --- RAG Chunks ---

    def store_chunks(self, doc_id: str, chunks: List[Tuple[int, int, str]]):
        with self._db_lock:
            conn = self._get_db_conn()
            for page_num, chunk_idx, text in chunks:
                chunk_id = f"chunk-{doc_id}-{page_num}-{chunk_idx}"
                conn.execute(
                    "INSERT OR REPLACE INTO rag_chunks VALUES (?,?,?,?,?,?)",
                    (chunk_id, doc_id, page_num, chunk_idx, text, None)
                )
            conn.commit()
            conn.close()

    def get_all_chunks_for_search(self) -> List[dict]:
        conn = self._get_db_conn()
        try:
            conn.row_factory = sqlite3.Row
            rows = conn.execute("""
                SELECT rc.*, rd.filename, rd.id as doc_id
                FROM rag_chunks rc
                JOIN rag_documents rd ON rd.id = rc.document_id
                WHERE rd.indexed = 1
            """).fetchall()
        finally:
            conn.close()
        return [dict(r) for r in rows]

    def get_chunks_by_document(self, doc_id: str) -> List[dict]:
        conn = self._get_db_conn()
        try:
            conn.row_factory = sqlite3.Row
            rows = conn.execute(
                "SELECT * FROM rag_chunks WHERE document_id=? ORDER BY page_number, chunk_index",
                (doc_id,)
            ).fetchall()
        finally:
            conn.close()
        return [dict(r) for r in rows]


# ==================================================
# SECTION 5: PARAMETER RESOLVER
# ==================================================

class ParameterResolver:
    """
    Resolves inference parameters with priority:
    1. User-specified (manual) â€“ highest
    2. Model-specific defaults
    3. Provider-specific defaults
    4. Global defaults â€“ lowest
    """

    MODEL_DEFAULTS: Dict[str, dict] = {
        "claude": {"temperature": 1.0, "top_p": 0.9, "max_tokens": 16384},
        "gpt-4": {"temperature": 0.7, "top_p": 1.0, "max_tokens": 16384},
        "gpt-3.5": {"temperature": 0.7, "top_p": 1.0, "max_tokens": 8192},
        "gemini": {"temperature": 1.0, "top_p": 0.95, "max_tokens": 16384},
        "llama": {"temperature": 0.7, "top_p": 0.9, "top_k": 40, "max_tokens": 8192},
        "mistral": {"temperature": 0.7, "top_p": 0.9, "top_k": 40, "max_tokens": 8192},
        "qwen": {"temperature": 0.7, "top_p": 0.9, "top_k": 40, "max_tokens": 16384},
        "deepseek": {"temperature": 0.7, "top_p": 0.9, "top_k": 40, "max_tokens": 16384},
        "phi": {"temperature": 0.6, "top_p": 0.9, "max_tokens": 4096},
        "gemma": {"temperature": 0.7, "top_p": 0.95, "max_tokens": 8192, "repetition_penalty": 1.0},
        "command": {"temperature": 0.7, "top_p": 0.9, "max_tokens": 8192},
    }

    PROVIDER_DEFAULTS: Dict[str, dict] = {
        "anthropic": {"max_tokens": 16384, "temperature": 1.0},
        "google": {"max_tokens": 16384, "temperature": 1.0, "top_p": 0.95},
        "openai": {"max_tokens": 16384, "temperature": 0.7},
        "cohere": {"max_tokens": 8192, "temperature": 0.7},
        "ollama": {"top_k": 40, "repetition_penalty": 1.1},
        "lmstudio": {"top_k": 40, "repetition_penalty": 1.1},
    }

    def __init__(self, global_defaults: ParameterDefaults):
        self.global_defaults = global_defaults

    def resolve(self, request: ChatCompletionRequest,
                provider_id: str = "") -> dict:
        """Resolve all parameters into a final dict."""
        base = self.global_defaults.model_dump()

        # Apply provider defaults
        for pid, pdefs in self.PROVIDER_DEFAULTS.items():
            if pid in provider_id.lower():
                for k, v in pdefs.items():
                    if k in base:
                        base[k] = v

        # Apply model defaults
        model_lower = request.model.lower()
        for pattern, mdefs in self.MODEL_DEFAULTS.items():
            if pattern in model_lower:
                for k, v in mdefs.items():
                    if k in base:
                        base[k] = v

        # Apply user-specified overrides (manual takes priority)
        user_overrides = {}
        for field_name in [
            "temperature", "top_p", "top_k", "max_tokens",
            "frequency_penalty", "presence_penalty", "repetition_penalty", "stop",
            "reasoning", "strong_reasoning"
        ]:
            val = getattr(request, field_name, None)
            if val is not None:
                user_overrides[field_name] = val

        base.update(user_overrides)

        # Gemini requires top_p >= 0.95; do not let a lower default or override
        # violate the provider contract and trigger 400s from the upstream API.
        provider_name = (provider_id or "").lower()
        model_name = (request.model or "").lower()
        if "gemini" in provider_name or "gemini" in model_name or "google" in provider_name:
            if "top_p" in base and base["top_p"] is not None:
                base["top_p"] = max(float(base["top_p"]), 0.95)

        # Clean up None values
        return {k: v for k, v in base.items() if v is not None}


# ==================================================
# SECTION 6: CLOUD INFERENCE ENGINE
# ==================================================

class CloudInferenceEngine:
    """Handles all cloud provider API calls with unified interface."""

    # Router-style providers serve model ids that legitimately contain "/"
    # (e.g. OpenRouter's "anthropic/claude-3.5-sonnet", Together's
    # "meta-llama/Llama-3.3-70B-Instruct-Turbo"). For those, never strip a
    # leading segment. For single-provider APIs (openai, gemini, groq, ...)
    # a "provider/model" prefix is almost always a UI artifact and must be
    # removed before the id reaches the wire.
    _MULTI_MODEL_ROUTERS = frozenset({"openrouter", "huggingface", "together", "together_gguf", "generic_openai"})

    @staticmethod
    def _strip_provider_prefix(model: Optional[str], provider_id: str) -> str:
        """Normalize a model identifier before sending it to a cloud API.

        The desktop model picker can hand down ids such as
        ``cloud/gemini/gemini-2.5-flash``, ``gemini/gemini-1.5-flash`` or
        ``models/gemini-2.5-flash``. Google and most single-vendor OpenAI
        endpoints reject those prefixes with "Unknown model", so they are
        stripped here. Model ids that legitimately contain slashes (OpenRouter,
        Together, Hugging Face routers) are left untouched.
        """
        if not model:
            return model or ""
        m = str(model).strip()
        for prefix in ("cloud/", "models/"):
            if m.startswith(prefix):
                m = m[len(prefix):]
        first, sep, rest = m.partition("/")
        if not sep or not rest:
            return m
        first_l = first.lower()
        rest_l = rest.lower()
        if provider_id == "gemini" and first_l in ("gemini", "google", "googleai") and (
            rest_l.startswith("gemini") or "-" in rest or "_" in rest
        ):
            return rest
        if provider_id.lower() in CloudInferenceEngine._MULTI_MODEL_ROUTERS:
            return m
        if first_l == provider_id.lower() and "/" not in rest and not rest.startswith("models/"):
            return rest
        return m

    def __init__(self, persistence: PersistenceManager):
        self.persistence = persistence
        self._clients: Dict[str, httpx.AsyncClient] = {}

    def _get_client(self, provider_id: str) -> httpx.AsyncClient:
        if provider_id not in self._clients:
            self._clients[provider_id] = httpx.AsyncClient(
                timeout=httpx.Timeout(1800.0, connect=10.0),
                limits=httpx.Limits(max_connections=20, max_keepalive_connections=5)
            )
        return self._clients[provider_id]

    def _get_provider_info(self, provider_id: str) -> dict:
        config = self.persistence.config
        conn = config.cloud_providers.get(provider_id)
        if not conn:
            raise HTTPException(404, f"Provider '{provider_id}' not configured")
        info = CLOUD_PROVIDERS.get(provider_id, {})
        # Built-in providers own their endpoint. Only the explicit generic
        # connector may override it; this prevents one provider's URL from
        # leaking into another provider's model catalog.
        base_url = (
            conn.base_url
            if provider_id == "generic_openai" and conn.base_url
            else info.get("base_url", "")
        )
        return {
            **info,
            "base_url": base_url,
            "api_key": conn.api_key,
        }

    def _build_headers(self, provider_id: str, info: dict) -> dict:
        headers = {"Content-Type": "application/json"}
        auth_header = info.get("auth_header", "Authorization")
        auth_prefix = info.get("auth_prefix", "Bearer ")
        api_key = info.get("api_key", "")
        if api_key:
            headers[auth_header] = f"{auth_prefix}{api_key}"
        if info.get("version_header"):
            headers[info["version_header"]] = info["version_value"]
        return headers

    async def list_models(self, provider_id: str) -> List[ModelInfo]:
        info = self._get_provider_info(provider_id)
        client = self._get_client(provider_id)
        headers = self._build_headers(provider_id, info)
        endpoint = info.get("models_endpoint", "/models")
        base_url = info["base_url"].rstrip("/")
        if base_url.endswith("/openai"):
            base_url = base_url[:-7]
        url = f"{base_url}{endpoint}"

        try:
            resp = await client.get(url, headers=headers)
            resp.raise_for_status()
            data = resp.json()
        except Exception as e:
            logger.error(f"Failed to list models for {provider_id}: {e}")
            if provider_id == "gemini":
                data = {
                    "data": [
                        {"id": "gemini-2.5-flash"},
                        {"id": "gemini-2.5-pro"},
                        {"id": "gemini-2.0-flash"},
                        {"id": "gemini-2.0-flash-lite"},
                        {"id": "gemini-1.5-flash"},
                        {"id": "gemini-1.5-pro"},
                        {"id": "gemini-3.7-flash"},
                        {"id": "gemini-3.6-flash"},
                        {"id": "gemini-3.5-flash"},
                        {"id": "gemini-3.5-flash-thinking"},
                        {"id": "gemini-3.1-pro"},
                        {"id": "gemini-auto"},
                        {"id": "gemini-3.5-flash-thinking-lite"},
                        {"id": "gemini-flash-lite"},
                    ]
                }
            elif provider_id == "huggingface":
                # The router does not always expose /v1/models. Fall back to
                # Hugging Face's live public catalog so model discovery keeps
                # working even when the inference router changes.
                try:
                    catalog_headers = {"Accept": "application/json"}
                    token = info.get("api_key", "")
                    if token:
                        catalog_headers["Authorization"] = "Bearer " + token
                    catalog = await client.get(
                        "https://huggingface.co/api/models",
                        params={
                            "pipeline_tag": "text-generation",
                            "sort": "downloads",
                            "direction": "-1",
                            "limit": "100",
                        },
                        headers=catalog_headers,
                    )
                    catalog.raise_for_status()
                    data = {"data": catalog.json()}
                except Exception as catalog_error:
                    raise HTTPException(502, f"Hugging Face model catalog unavailable: {catalog_error}") from catalog_error
            else:
                raise HTTPException(502, f"{CLOUD_PROVIDERS.get(provider_id, {}).get('name', provider_id)} model catalog unavailable: {e}") from e

        models = []
        raw_models = data.get("data") or data.get("models") or (data if isinstance(data, list) else [])
        for m in raw_models:
            mid = m.get("id", m.get("name", ""))
            if mid.startswith("models/"):
                mid = mid[7:]
            if not mid:
                continue
            models.append(ModelInfo(
                id=mid,
                name=m.get("name", mid).removeprefix("models/"),
                provider=provider_id,
                owned_by=m.get("owned_by", provider_id),
                is_gguf="gguf" in mid.lower(),
                is_local=False,
                capabilities=self._detect_capabilities(info, m),
            ))
        if not models and provider_id == "gemini":
            for mid in [
                "gemini-2.5-flash", "gemini-2.5-pro", "gemini-2.0-flash", "gemini-2.0-flash-lite",
                "gemini-1.5-flash", "gemini-1.5-pro", "gemini-3.7-flash", "gemini-3.6-flash",
                "gemini-3.5-flash", "gemini-3.5-flash-thinking", "gemini-3.1-pro", "gemini-auto",
                "gemini-flash-lite"
            ]:
                models.append(ModelInfo(
                    id=mid,
                    name=mid,
                    provider=provider_id,
                    owned_by=provider_id,
                    is_gguf=False,
                    is_local=False,
                    capabilities=["chat", "vision", "tools", "streaming"],
                ))
        if not models:
            raise HTTPException(502, f"No models were returned by {CLOUD_PROVIDERS.get(provider_id, {}).get('name', provider_id)}.")
        return models

    def _detect_capabilities(self, info: dict, model_data: dict) -> List[str]:
        caps = ["chat"]
        if info.get("vision"):
            caps.append("vision")
        if info.get("tools"):
            caps.append("tools")
        if info.get("streaming"):
            caps.append("streaming")
        mid = model_data.get("id", "").lower()
        if any(v in mid for v in ["vision", "vl", "img"]):
            if "vision" not in caps:
                caps.append("vision")
        return caps

    async def test_connection(self, provider_id: str) -> Tuple[bool, str, List[str]]:
        """Test provider connection, return (success, error, models)."""
        try:
            models = await self.list_models(provider_id)
            return True, "", [m.id for m in models]
        except Exception as e:
            return False, str(e), []

    async def chat_completion(
        self,
        provider_id: str,
        model: str,
        messages: List[dict],
        params: dict,
        tools: Optional[List[dict]] = None,
        tool_choice: Optional[Union[str, dict]] = None,
        stream: bool = False,
    ) -> AsyncGenerator[str, None] | dict:
        info = self._get_provider_info(provider_id)
        fmt = info.get("format", "openai")

        if fmt == "openai":
            return await self._chat_openai(info, model, messages, params,
                                           tools, tool_choice, stream, provider_id)
        elif fmt == "anthropic":
            return await self._chat_anthropic(info, model, messages, params,
                                              tools, tool_choice, stream, provider_id)
        elif fmt == "google":
            return await self._chat_google(info, model, messages, params,
                                           tools, tool_choice, stream, provider_id)
        elif fmt == "cohere":
            return await self._chat_cohere(info, model, messages, params,
                                           tools, stream, provider_id)
        else:
            raise HTTPException(400, f"Unsupported format: {fmt}")

    @staticmethod
    def _clamp_provider_max_tokens(body: dict, error_text: str) -> bool:
        """Adapt to provider-specific output caps without surfacing a retryable 4xx."""
        match = re.search(
            r"max_tokens.*?(?:less than or equal to|maximum value[^0-9]*is)\s*[`'\"]?(\d+)",
            error_text,
            re.IGNORECASE,
        )
        if not match:
            match = re.search(r"less than or equal to\s*[`'\"]?(\d+)", error_text, re.IGNORECASE)
        if not match:
            return False
        provider_limit = int(match.group(1))
        requested = int(body.get("max_tokens") or provider_limit)
        safe_limit = max(1, min(requested, provider_limit))
        if safe_limit >= requested:
            return False
        body["max_tokens"] = safe_limit
        return True

    async def _chat_openai(self, info, model, messages, params,
                           tools, tool_choice, stream, provider_id):
        client = self._get_client(provider_id)
        headers = self._build_headers(provider_id, info)
        base_url = info.get("base_url", "").rstrip("/")
        ep = info.get("chat_endpoint", "")
        url = base_url if base_url.endswith(ep) else f"{base_url}{ep}"

        if provider_id == "gemini":
            model = model or "gemini-2.5-flash"
        model = self._strip_provider_prefix(model, provider_id)

        system_content = []
        regular_messages = []
        for m in messages:
            role = m.get("role", "")
            if role in ("system", "developer"):
                content = m.get("content", "")
                if isinstance(content, list):
                    text_parts = [b.get("text", "") for b in content if isinstance(b, dict) and b.get("type") == "text"]
                    system_content.append("\n".join(text_parts))
                else:
                    system_content.append(str(content))
            else:
                rm = dict(m)
                if rm.get("content") is None:
                    rm["content"] = ""
                if role in ("user", "assistant") and "name" in rm:
                    rm.pop("name", None)
                regular_messages.append(rm)
        
        sanitized_messages = []
        if system_content:
            sanitized_messages.append({"role": "system", "content": "\n\n".join(system_content)})
        sanitized_messages.extend(regular_messages)

        body: dict = {
            "model": model,
            "messages": sanitized_messages,
            "stream": stream,
        }
        # Add supported params
        param_map = {
            "temperature": "temperature", "top_p": "top_p",
            "max_tokens": "max_tokens", "frequency_penalty": "frequency_penalty",
            "presence_penalty": "presence_penalty", "stop": "stop",
            "seed": "seed", "response_format": "response_format",
        }
        for src, dst in param_map.items():
            if src in params and params[src] is not None:
                body[dst] = params[src]
        # Cloud reasoning is best-effort and provider-native. OpenAI-compatible
        # endpoints generally understand reasoning_effort; unsupported providers
        # simply receive the normal request.
        if params.get("reasoning") is True:
            body["reasoning_effort"] = "high" if params.get("strong_reasoning") else "medium"
        elif params.get("reasoning") is False and provider_id not in {"gemini"}:
            body["reasoning_effort"] = "none"
        if tools:
            sanitized_tools = []
            is_gemini = provider_id == "gemini" or "googleapis.com" in info.get("base_url", "")
            for t in tools:
                st = dict(t)
                st.pop("mcp_server", None)
                if "function" in st and isinstance(st["function"], dict):
                    sf = dict(st["function"])
                    if "parameters" not in sf or not sf["parameters"] or sf["parameters"].get("properties") == {}:
                        # Gemini requires parameters to be present, even if empty.
                        sf["parameters"] = {"type": "object", "properties": {}}
                    if is_gemini:
                        sf.pop("strict", None)
                    st["function"] = sf
                sanitized_tools.append(st)
            body["tools"] = sanitized_tools
        if tool_choice:
            body["tool_choice"] = tool_choice

        if "stop" in body and isinstance(body["stop"], list) and len(body["stop"]) > 4:
            body["stop"] = body["stop"][:4]

        if provider_id == "gemini" or "googleapis.com" in info.get("base_url", ""):
            body.pop("presence_penalty", None)
            body.pop("frequency_penalty", None)
            body.pop("seed", None)
            if "top_p" in body and body["top_p"] is not None:
                body["top_p"] = max(float(body["top_p"]), 0.95)

        logger.debug(f"Cloud {provider_id} payload model={body.get('model')} stream={stream}")

        if stream:
            return self._stream_openai(client, url, headers, body)
        else:
            resp = await client.post(url, headers=headers, json=body, timeout=1800)
            if resp.status_code >= 400:
                error_text = resp.text
                if self._clamp_provider_max_tokens(body, error_text):
                    logger.warning(
                        "Provider rejected max_tokens; retrying with provider limit=%s",
                        body["max_tokens"],
                    )
                    resp = await client.post(url, headers=headers, json=body, timeout=1800)
                if resp.status_code >= 400:
                    logger.error(f"Provider API error {resp.status_code}: {resp.text}")
                    raise HTTPException(resp.status_code, f"Provider API error: {resp.text}")
            resp.raise_for_status()
            return resp.json()

    async def _stream_openai(self, client, url, headers, body):
        retried = False
        while True:
            async with client.stream("POST", url, headers=headers, json=body, timeout=1800) as resp:
                if resp.status_code >= 400:
                    await resp.aread()
                    error_text = resp.text
                    if not retried and self._clamp_provider_max_tokens(body, error_text):
                        retried = True
                        logger.warning(
                            "Provider rejected streaming max_tokens; retrying with provider limit=%s",
                            body["max_tokens"],
                        )
                        continue
                    logger.error(f"Provider stream error {resp.status_code}: {error_text}")
                    raise HTTPException(resp.status_code, f"Provider API error: {error_text}")
                resp.raise_for_status()
                async for line in resp.aiter_lines():
                    line = line.strip()
                    if not line or line.startswith(":"):
                        continue
                    if line.startswith("data:"):
                        data = line[5:].strip()
                        if data == "[DONE]":
                            yield "data: [DONE]\n\n"
                            break
                        if not data:
                            continue
                        try:
                            parsed = json.loads(data)
                            if isinstance(parsed, list):
                                for item in parsed:
                                    yield f"data: {json.dumps(item, ensure_ascii=False)}\n\n"
                            else:
                                yield f"data: {json.dumps(parsed, ensure_ascii=False)}\n\n"
                        except json.JSONDecodeError:
                            continue
                    else:
                        try:
                            parsed = json.loads(line)
                            if isinstance(parsed, list):
                                for item in parsed:
                                    yield f"data: {json.dumps(item, ensure_ascii=False)}\n\n"
                            else:
                                yield f"data: {json.dumps(parsed, ensure_ascii=False)}\n\n"
                        except json.JSONDecodeError:
                            continue
                return

    @staticmethod
    def _to_anthropic_content(content):
        """Anthropic's API expects image blocks as {"type": "image", "source":
        {"type": "base64", "media_type": ..., "data": ...}} - not the OpenAI-style
        {"type": "image_url", "image_url": {"url": "data:...;base64,..."}} that
        the rest of this codebase builds messages with. Translate here so
        image attachments actually work when Anthropic is the selected provider."""
        if isinstance(content, str) or not isinstance(content, list):
            return content
        blocks = []
        for part in content:
            if not isinstance(part, dict):
                continue
            if part.get("type") == "image_url":
                url = part.get("image_url", {}).get("url", "")
                if url.startswith("data:") and ";base64," in url:
                    mime, b64_data = url[5:].split(";base64,", 1)
                    blocks.append({
                        "type": "image",
                        "source": {"type": "base64", "media_type": mime, "data": b64_data},
                    })
            else:
                blocks.append(part)
        return blocks

    async def _chat_anthropic(self, info, model, messages, params,
                              tools, tool_choice, stream, provider_id):
        client = self._get_client(provider_id)
        headers = self._build_headers(provider_id, info)
        model = self._strip_provider_prefix(model, provider_id)
        base_url = info.get("base_url", "").rstrip("/")
        ep = info.get("chat_endpoint", "")
        url = base_url if base_url.endswith(ep) else f"{base_url}{ep}"

        # Convert messages to Anthropic format
        system_msg = ""
        anthropic_msgs = []
        for m in messages:
            if m.get("role") == "system":
                system_msg = m.get("content", "")
                continue
            # â”€â”€ Multi-turn thinking block preservation â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            # If the assistant previously produced thinking blocks (Claude
            # extended thinking with cryptographic signatures), they must
            # be echoed back verbatim or Anthropic returns 400.
            m_thinking_blocks = m.get("thinking_blocks")
            if m.get("role") == "assistant" and isinstance(m_thinking_blocks, list) and m_thinking_blocks:
                blocks = []
                for tb in m_thinking_blocks:
                    if isinstance(tb, dict) and tb.get("type") == "thinking":
                        blk = {"type": "thinking", "thinking": tb["thinking"]}
                        if tb.get("signature"):
                            blk["signature"] = tb["signature"]
                        blocks.append(blk)
                # Append the actual text/tool content after thinking blocks
                content = self._to_anthropic_content(m.get("content", ""))
                if isinstance(content, str):
                    if content:
                        blocks.append({"type": "text", "text": content})
                elif isinstance(content, list):
                    blocks.extend(content)
                # Also include any tool_use blocks
                if m.get("tool_calls"):
                    for tc in m["tool_calls"]:
                        blocks.append({
                            "type": "tool_use",
                            "id": tc["id"],
                            "name": tc["function"]["name"],
                            "input": tc["function"].get("arguments", {}),
                        })
                msg = {"role": "assistant", "content": blocks if blocks else ""}
                anthropic_msgs.append(msg)
                continue

            msg = {"role": m["role"], "content": self._to_anthropic_content(m.get("content", ""))}
            if m.get("tool_calls"):
                blocks = []
                for tc in m["tool_calls"]:
                    blocks.append({
                        "type": "tool_use",
                        "id": tc["id"],
                        "name": tc["function"]["name"],
                        "input": tc["function"].get("arguments", {}),
                    })
                msg["content"] = blocks
            elif m.get("role") == "tool":
                msg = {
                    "role": "user",
                    "content": [{
                        "type": "tool_result",
                        "tool_use_id": m.get("tool_call_id", ""),
                        "content": m.get("content", ""),
                    }]
                }
            anthropic_msgs.append(msg)

        # Determine whether to enable extended thinking for this Claude model.
        # Claude 3.7+ and Claude 4+ support extended thinking. When enabled,
        # the model produces a dedicated thinking content block *before* its
        # visible reply, streamed via separate content_block_delta events
        # with delta.type == "thinking_delta".  We request a generous token
        # budget so the model can reason deeply without being cut short.
        _model_lower = model.lower()
        _supports_extended_thinking = any(
            tag in _model_lower
            for tag in ("claude-3.7", "claude-4", "claude-sonnet-4", "claude-opus-4")
        )
        _thinking_enabled = _supports_extended_thinking and stream

        base_max_tokens = int(params.get("max_tokens") or 16000)
        # When extended thinking is on, Anthropic requires max_tokens to be
        # large enough to cover *both* thinking + output tokens.  We bump it
        # to at least 16k thinking + the original output budget.
        if _thinking_enabled:
            effective_max = max(16000 + base_max_tokens, 32768)
        else:
            effective_max = base_max_tokens

        body: dict = {
            "model": model,
            "messages": anthropic_msgs,
            "max_tokens": effective_max,
            "stream": stream,
        }
        if _thinking_enabled:
            body["thinking"] = {"type": "enabled", "budget_tokens": min(16000, effective_max - base_max_tokens)}
            # Anthropic requires temperature=1 when thinking is enabled.
            body.pop("temperature", None)
        if system_msg:
            body["system"] = system_msg
        if "temperature" in params and not _thinking_enabled:
            body["temperature"] = params["temperature"]
        if "top_p" in params:
            body["top_p"] = params["top_p"]
        if "top_k" in params:
            body["top_k"] = params["top_k"]

        # Convert tools to Anthropic format
        if tools:
            anthropic_tools = []
            for t in tools:
                if t.get("type") == "function":
                    anthropic_tools.append({
                        "name": t["function"]["name"],
                        "description": t["function"].get("description", ""),
                        "input_schema": t["function"].get("parameters", {}),
                    })
            if anthropic_tools:
                body["tools"] = anthropic_tools
        if tool_choice:
            if isinstance(tool_choice, str) and tool_choice == "auto":
                body["tool_choice"] = {"type": "auto"}
            elif isinstance(tool_choice, dict):
                body["tool_choice"] = {"type": "tool", "name": tool_choice.get("function", {}).get("name", "")}

        if stream:
            return self._stream_anthropic(client, url, headers, body)
        else:
            resp = await client.post(url, headers=headers, json=body, timeout=1800)
            resp.raise_for_status()
            return self._convert_anthropic_response(resp.json(), model)

    async def _stream_anthropic(self, client, url, headers, body):
        """Stream Anthropic responses, properly handling extended thinking.

        Claude 3.7+ / 4+ with extended thinking enabled emits:
          - message_start
          - content_block_start  (type: "thinking" | "text" | "tool_use")
          - content_block_delta  (delta.type: "thinking_delta" | "text_delta" | "input_json_delta" | "signature_delta")
          - content_block_stop
          - message_delta
          - message_stop

        We yield proper SSE lifecycle events so the frontend can render a
        genuine, token-by-token thinking block:
          event: thinking_start   - first reasoning token is about to arrive
          event: thinking         - each reasoning chunk (existing event name)
          event: thinking_end     - reasoning finished, visible answer next
          data: {...}             - OpenAI-format text/tool chunks (unchanged)
        """
        _thinking_started = False
        _current_block_type = None  # "thinking" | "text" | "tool_use" | None
        _msg_id = ""
        # Accumulate thinking blocks for multi-turn signature preservation.
        # Claude signs every thinking block; subsequent turns must echo them
        # back verbatim or Anthropic rejects the request with 400.
        _accumulated_thinking_blocks: list = []
        _current_thinking_text = ""
        _current_thinking_signature = ""

        def _thinking_start_sse(msg_id: str) -> str:
            return f"event: thinking_start\ndata: {json.dumps({'id': msg_id, 'started_at': int(time.time() * 1000)}, ensure_ascii=False)}\n\n"

        def _thinking_end_sse(msg_id: str, duration_ms: int = 0) -> str:
            return f"event: thinking_end\ndata: {json.dumps({'id': msg_id, 'duration_ms': duration_ms}, ensure_ascii=False)}\n\n"

        def _thinking_delta_sse(text: str) -> str:
            return f"event: thinking\ndata: {json.dumps({'chunk': text}, ensure_ascii=False)}\n\n"

        _thinking_first_token_at: Optional[float] = None

        async with client.stream("POST", url, headers=headers, json=body,
                                 timeout=1800) as resp:
            resp.raise_for_status()
            async for line in resp.aiter_lines():
                line = line.strip()
                if not line or not line.startswith("data: "):
                    continue
                data = line[6:]
                try:
                    event = json.loads(data)
                except json.JSONDecodeError:
                    continue
                evt_type = event.get("type", "")

                # â”€â”€ message_start: capture the message id â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                if evt_type == "message_start":
                    _msg_id = event.get("message", {}).get("id", "")
                    # Yield the role chunk so downstream sees the assistant role
                    chunk = self._convert_anthropic_stream_chunk(event, body.get("model", ""))
                    if chunk:
                        yield f"data: {json.dumps(chunk)}\n\n"
                    continue

                # â”€â”€ content_block_start: detect thinking vs text vs tool â”€
                if evt_type == "content_block_start":
                    block = event.get("content_block", {})
                    _current_block_type = block.get("type", "")

                    if _current_block_type == "thinking":
                        # Claude is about to stream its internal reasoning.
                        _thinking_first_token_at = time.time()
                        yield _thinking_start_sse(_msg_id)
                    else:
                        # text or tool_use block starting - if we were in a
                        # thinking block that never got a proper stop (shouldn't
                        # happen but be defensive), close it now.
                        if _thinking_started and _current_block_type == "text":
                            duration = int((time.time() - _thinking_first_token_at) * 1000) if _thinking_first_token_at else 0
                            yield _thinking_end_sse(_msg_id, duration)
                            _thinking_started = False
                    continue

                # â”€â”€ content_block_delta: the actual streamed tokens â”€â”€â”€â”€â”€â”€â”€
                if evt_type == "content_block_delta":
                    delta = event.get("delta", {})
                    delta_type = delta.get("type", "")

                    if delta_type == "thinking_delta":
                        # â”€â”€ This is the real model reasoning stream â”€â”€â”€â”€â”€â”€â”€
                        thinking_text = delta.get("thinking", "")
                        if thinking_text:
                            _thinking_started = True
                            _current_thinking_text += thinking_text
                            yield _thinking_delta_sse(thinking_text)
                        continue

                    if delta_type == "signature_delta":
                        # Cryptographic signature for thinking block integrity.
                        # Accumulate it - we must echo the full block (text +
                        # signature) back to Claude in subsequent turns.
                        _current_thinking_signature += delta.get("signature", "")
                        continue

                    # text_delta and input_json_delta: convert normally
                    chunk = self._convert_anthropic_stream_chunk(event, body.get("model", ""))
                    if chunk:
                        yield f"data: {json.dumps(chunk)}\n\n"
                    continue

                # â”€â”€ content_block_stop: close the current block â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                if evt_type == "content_block_stop":
                    if _current_block_type == "thinking" and _thinking_started:
                        duration = int((time.time() - _thinking_first_token_at) * 1000) if _thinking_first_token_at else 0
                        yield _thinking_end_sse(_msg_id, duration)
                        _thinking_started = False
                        # Finalize the thinking block for multi-turn echo.
                        if _current_thinking_text:
                            block: dict = {
                                "type": "thinking",
                                "thinking": _current_thinking_text,
                            }
                            if _current_thinking_signature:
                                block["signature"] = _current_thinking_signature
                            _accumulated_thinking_blocks.append(block)
                        _current_thinking_text = ""
                        _current_thinking_signature = ""
                    _current_block_type = None
                    continue

                # â”€â”€ message_delta: stop_reason â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                if evt_type == "message_delta":
                    chunk = self._convert_anthropic_stream_chunk(event, body.get("model", ""))
                    if chunk:
                        yield f"data: {json.dumps(chunk)}\n\n"
                    continue

                # â”€â”€ message_stop: done â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                if evt_type == "message_stop":
                    # Defensive: if a thinking block is still open, close it.
                    if _thinking_started:
                        duration = int((time.time() - _thinking_first_token_at) * 1000) if _thinking_first_token_at else 0
                        yield _thinking_end_sse(_msg_id, duration)
                        _thinking_started = False
                        # Also finalize any dangling thinking block
                        if _current_thinking_text:
                            block: dict = {
                                "type": "thinking",
                                "thinking": _current_thinking_text,
                            }
                            if _current_thinking_signature:
                                block["signature"] = _current_thinking_signature
                            _accumulated_thinking_blocks.append(block)
                            _current_thinking_text = ""
                            _current_thinking_signature = ""
                    # Emit accumulated thinking blocks for multi-turn
                    # signature preservation.  The frontend stores these and
                    # sends them back on the next request so Claude sees its
                    # own signed thinking blocks in the conversation history.
                    if _accumulated_thinking_blocks:
                        yield (
                            "event: thinking_blocks\ndata: "
                            + json.dumps({"blocks": _accumulated_thinking_blocks}, ensure_ascii=False)
                            + "\n\n"
                        )
                    yield "data: [DONE]\n\n"
                    break

    def _convert_anthropic_response(self, resp, model):
        content = resp.get("content", [])
        text_parts = []
        tool_calls = []
        for block in content:
            if block.get("type") == "text":
                text_parts.append(block["text"])
            elif block.get("type") == "tool_use":
                tool_calls.append({
                    "id": block["id"],
                    "type": "function",
                    "function": {
                        "name": block["name"],
                        "arguments": json.dumps(block.get("input", {})),
                    }
                })
        msg = {"role": "assistant", "content": "\n".join(text_parts)}
        if tool_calls:
            msg["tool_calls"] = tool_calls
        return {
            "id": resp.get("id", f"chatcmpl-{uuid.uuid4().hex[:12]}"),
            "object": "chat.completion",
            "created": int(time.time()),
            "model": model,
            "choices": [{
                "index": 0, "message": msg,
                "finish_reason": "tool_calls" if tool_calls else resp.get("stop_reason", "stop")
            }],
            "usage": {
                "prompt_tokens": resp.get("usage", {}).get("input_tokens", 0),
                "completion_tokens": resp.get("usage", {}).get("output_tokens", 0),
                "total_tokens": resp.get("usage", {}).get("input_tokens", 0) +
                                resp.get("usage", {}).get("output_tokens", 0),
            }
        }

    def _convert_anthropic_stream_chunk(self, event, model):
        evt_type = event.get("type", "")
        chunk_id = event.get("message", {}).get("id", f"chatcmpl-{uuid.uuid4().hex[:12]}")

        if evt_type == "content_block_delta":
            delta = event.get("delta", {})
            if delta.get("type") == "text_delta":
                return {
                    "id": chunk_id, "object": "chat.completion.chunk",
                    "created": int(time.time()), "model": model,
                    "choices": [{
                        "index": 0,
                        "delta": {"content": delta.get("text", "")},
                        "finish_reason": None
                    }]
                }
            elif delta.get("type") == "input_json_delta":
                return None  # Tool call streaming - simplified
        elif evt_type == "message_start":
            return {
                "id": chunk_id, "object": "chat.completion.chunk",
                "created": int(time.time()), "model": model,
                "choices": [{"index": 0, "delta": {"role": "assistant"}, "finish_reason": None}]
            }
        elif evt_type == "message_delta":
            return {
                "id": chunk_id, "object": "chat.completion.chunk",
                "created": int(time.time()), "model": model,
                "choices": [{"index": 0, "delta": {}, "finish_reason": event.get("delta", {}).get("stop_reason", "stop")}]
            }
        return None

    async def _chat_google(self, info, model, messages, params,
                           tools, tool_choice, stream, provider_id):
        client = self._get_client(provider_id)
        headers = self._build_headers(provider_id, info)
        api_key = info.get("api_key", "")
        model = self._strip_provider_prefix(model, provider_id)
        url = f"{info['base_url']}/models/{model}:generateContent?key={api_key}"
        if stream:
            url = f"{info['base_url']}/models/{model}:streamGenerateContent?key={api_key}&alt=sse"

        # Convert messages to Google format
        system_instruction = None
        contents = []
        for m in messages:
            if m.get("role") == "system":
                system_instruction = {"parts": [{"text": m.get("content", "")}]}
                continue
            role = "user" if m["role"] == "user" else "model"
            parts = []
            content = m.get("content", "")
            if isinstance(content, str):
                parts.append({"text": content})
            elif isinstance(content, list):
                for c in content:
                    if isinstance(c, dict):
                        if c.get("type") == "text":
                            parts.append({"text": c.get("text", "")})
                        elif c.get("type") == "image_url":
                            img_url = c.get("image_url", {}).get("url", "")
                            if img_url.startswith("data:"):
                                b64 = img_url.split(",", 1)[1]
                                mime = img_url.split(";")[0].split(":")[1]
                                parts.append({"inlineData": {"mimeType": mime, "data": b64}})
            if m.get("tool_calls"):
                for tc in m["tool_calls"]:
                    parts.append({
                        "functionCall": {
                            "name": tc["function"]["name"],
                            "args": tc["function"].get("arguments", {}),
                        }
                    })
            elif m.get("role") == "tool":
                parts.append({
                    "functionResponse": {
                        "name": m.get("name", ""),
                        "response": {"content": m.get("content", "")},
                    }
                })
                role = "function"
            if parts:
                contents.append({"role": role, "parts": parts})

        body: dict = {"contents": contents}
        if system_instruction:
            body["systemInstruction"] = system_instruction
        gen_config = {}
        if "temperature" in params:
            gen_config["temperature"] = params["temperature"]
        if "top_p" in params:
            gen_config["topP"] = params["top_p"]
        if "top_k" in params:
            gen_config["topK"] = params["top_k"]
        if "max_tokens" in params:
            gen_config["maxOutputTokens"] = params["max_tokens"]
        if gen_config:
            body["generationConfig"] = gen_config

        if tools:
            google_tools = []
            for t in tools:
                if t.get("type") == "function":
                    google_tools.append({
                        "functionDeclarations": [{
                            "name": t["function"]["name"],
                            "description": t["function"].get("description", ""),
                            "parameters": t["function"].get("parameters", {}),
                        }]
                    })
            if google_tools:
                body["tools"] = google_tools

        if stream:
            return self._stream_google(client, url, headers, body, model)
        else:
            resp = await client.post(url, headers=headers, json=body, timeout=1800)
            resp.raise_for_status()
            return self._convert_google_response(resp.json(), model)

    async def _stream_google(self, client, url, headers, body, model):
        async with client.stream("POST", url, headers=headers, json=body,
                                 timeout=1800) as resp:
            resp.raise_for_status()
            async for line in resp.aiter_lines():
                line = line.strip()
                if not line or not line.startswith("data: "):
                    continue
                data = line[6:]
                try:
                    event = json.loads(data)
                    chunk = self._convert_google_stream_chunk(event, model)
                    if chunk:
                        yield f"data: {json.dumps(chunk)}\n\n"
                except json.JSONDecodeError:
                    continue
            yield "data: [DONE]\n\n"

    def _convert_google_response(self, resp, model):
        candidates = resp.get("candidates", [])
        if not candidates:
            return {"choices": [], "model": model}
        cand = candidates[0]
        parts = cand.get("content", {}).get("parts", [])
        text = ""
        tool_calls = []
        for p in parts:
            if "text" in p:
                text += p["text"]
            elif "functionCall" in p:
                fc = p["functionCall"]
                tool_calls.append({
                    "id": f"call_{uuid.uuid4().hex[:12]}",
                    "type": "function",
                    "function": {
                        "name": fc["name"],
                        "arguments": json.dumps(fc.get("args", {})),
                    }
                })
        msg = {"role": "assistant", "content": text}
        if tool_calls:
            msg["tool_calls"] = tool_calls
        usage = resp.get("usageMetadata", {})
        return {
            "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
            "object": "chat.completion",
            "created": int(time.time()),
            "model": model,
            "choices": [{
                "index": 0, "message": msg,
                "finish_reason": "tool_calls" if tool_calls else cand.get("finishReason", "stop").lower()
            }],
            "usage": {
                "prompt_tokens": usage.get("promptTokenCount", 0),
                "completion_tokens": usage.get("candidatesTokenCount", 0),
                "total_tokens": usage.get("totalTokenCount", 0),
            }
        }

    def _convert_google_stream_chunk(self, event, model):
        """Convert a Google Gemini streaming chunk.

        Gemini 2.5 Pro/Flash may include thought parts (reasoning) marked
        with ``thought: true``.  We route these into the ``reasoning``
        delta field so the _stream_with_tools loop picks them up and
        forwards as thinking events - exactly like OpenAI o-series.
        """
        candidates = event.get("candidates", [])
        if not candidates:
            return None
        cand = candidates[0]
        parts = cand.get("content", {}).get("parts", [])
        text = ""
        reasoning = ""
        for p in parts:
            if p.get("thought"):
                # Gemini's thought part - this is the model reasoning.
                reasoning += p.get("text", "")
            elif "text" in p:
                text += p["text"]

        delta: dict = {}
        if text:
            delta["content"] = text
        if reasoning:
            delta["reasoning"] = reasoning

        return {
            "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
            "object": "chat.completion.chunk",
            "created": int(time.time()),
            "model": model,
            "choices": [{
                "index": 0,
                "delta": delta,
                "finish_reason": cand.get("finishReason", None)
            }]
        }

    async def _chat_cohere(self, info, model, messages, params,
                           tools, stream, provider_id):
        client = self._get_client(provider_id)
        headers = self._build_headers(provider_id, info)
        model = self._strip_provider_prefix(model, provider_id)
        base_url = info.get("base_url", "").rstrip("/")
        ep = info.get("chat_endpoint", "")
        url = base_url if base_url.endswith(ep) else f"{base_url}{ep}"

        chat_history = []
        last_message = ""
        for m in messages:
            if m["role"] == "system":
                continue
            if m["role"] == "user":
                last_message = m.get("content", "") if isinstance(m.get("content"), str) else str(m.get("content", ""))
            else:
                chat_history.append({
                    "role": "USER" if m["role"] == "user" else "CHATBOT",
                    "message": m.get("content", "")
                })

        body = {
            "model": model,
            "message": last_message,
            "chat_history": chat_history,
            "stream": stream,
        }
        if "temperature" in params:
            body["temperature"] = params["temperature"]
        if "top_p" in params:
            body["p"] = params["top_p"]
        if "top_k" in params:
            body["k"] = params["top_k"]
        if "max_tokens" in params:
            body["max_tokens"] = params["max_tokens"]

        if stream:
            return self._stream_cohere(client, url, headers, body, model)
        else:
            resp = await client.post(url, headers=headers, json=body, timeout=1800)
            resp.raise_for_status()
            data = resp.json()
            return {
                "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                "object": "chat.completion",
                "created": int(time.time()),
                "model": model,
                "choices": [{
                    "index": 0,
                    "message": {"role": "assistant", "content": data.get("text", "")},
                    "finish_reason": "stop"
                }],
                "usage": {
                    "prompt_tokens": data.get("meta", {}).get("billed_units", {}).get("input_tokens", 0),
                    "completion_tokens": data.get("meta", {}).get("billed_units", {}).get("output_tokens", 0),
                    "total_tokens": 0,
                }
            }

    async def _stream_cohere(self, client, url, headers, body, model):
        async with client.stream("POST", url, headers=headers, json=body,
                                 timeout=1800) as resp:
            resp.raise_for_status()
            async for line in resp.aiter_lines():
                line = line.strip()
                if not line:
                    continue
                try:
                    event = json.loads(line)
                    if event.get("event_type") == "text-generation":
                        chunk = {
                            "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                            "object": "chat.completion.chunk",
                            "created": int(time.time()),
                            "model": model,
                            "choices": [{
                                "index": 0,
                                "delta": {"content": event.get("text", "")},
                                "finish_reason": None
                            }]
                        }
                        yield f"data: {json.dumps(chunk)}\n\n"
                    elif event.get("event_type") == "stream-end":
                        yield "data: [DONE]\n\n"
                        break
                except json.JSONDecodeError:
                    continue

    async def close(self):
        for client in self._clients.values():
            await client.aclose()
        self._clients.clear()


# ==================================================
# SECTION 7: LOCAL INFERENCE ENGINE
# ==================================================

class LocalInferenceEngine:
    """Handles local GGUF inference via LM Studio, Ollama, llama.cpp, KoboldCpp."""

    def __init__(self, persistence: PersistenceManager):
        self.persistence = persistence
        self._clients: Dict[str, httpx.AsyncClient] = {}

    def _get_client(self, provider_id: str) -> httpx.AsyncClient:
        if provider_id not in self._clients:
            self._clients[provider_id] = httpx.AsyncClient(
                timeout=httpx.Timeout(600.0, connect=5.0),
                limits=httpx.Limits(max_connections=5)
            )
        return self._clients[provider_id]

    def _get_local_config(self, provider_id: str) -> dict:
        config = self.persistence.config
        local = config.local_providers.get(provider_id)
        if not local:
            raise HTTPException(404, f"Local provider '{provider_id}' not configured")
        info = LOCAL_PROVIDERS.get(provider_id, {})
        return {
            **info,
            "base_url": local.base_url,
            "format": info.get("format", "openai"),
        }

    @staticmethod
    def _build_headers(provider_id: str, info: Optional[dict] = None) -> dict:
        """Headers for local inference servers (LM Studio, Ollama, llama.cpp,
        KoboldCpp). Local servers generally do not require authentication, so
        only Content-Type is set by default. If an explicit api_key is ever
        configured for the local provider it is forwarded as a Bearer token."""
        headers = {"Content-Type": "application/json"}
        api_key = (info or {}).get("api_key") or ""
        if api_key:
            headers["Authorization"] = f"Bearer {api_key}"
        return headers

    async def list_models(self, provider_id: str) -> List[ModelInfo]:
        info = self._get_local_config(provider_id)
        client = self._get_client(provider_id)
        fmt = info.get("format", "openai")
        endpoint = info.get("models_endpoint", "/v1/models")
        base_url = info["base_url"].rstrip("/")
        if base_url.endswith("/openai"):
            base_url = base_url[:-7]
        url = f"{base_url}{endpoint}"

        try:
            resp = await client.get(url, timeout=5.0)
            resp.raise_for_status()
            data = resp.json()
        except Exception as e:
            disk_models = []
            for entry in scan_local_gguf_library():
                quant_bits = entry.get("quant_bits")
                disk_models.append(ModelInfo(
                    id=entry["id"],
                    name=entry["label"],
                    provider=provider_id,
                    owned_by=entry.get("repo_id") or entry["folder"],
                    quantization=str(quant_bits or entry.get("precision") or ""),
                    quant_category=None,
                    size_gb=round(float(entry.get("size_bytes", 0)) / (1024**3), 2) if entry.get("size_bytes") else None,
                    is_gguf=True,
                    is_local=True,
                    capabilities=entry.get("capabilities", ["streaming"]),
                    modified_at=None,
                ))
            return disk_models

        models = []
        if fmt == "openai":
            raw = data.get("data", [])
            for m in raw:
                mid = m.get("id", "")
                quant, cat = self._detect_gguf_quant(mid)
                models.append(ModelInfo(
                    id=mid,
                    name=m.get("id", mid),
                    provider=provider_id,
                    owned_by=info.get("name", provider_id),
                    quantization=quant,
                    quant_category=cat,
                    is_gguf=True,
                    is_local=True,
                    capabilities=["chat", "streaming", "tools"],
                    modified_at=m.get("modified_at") or m.get("last_modified"),
                ))
        elif fmt == "ollama":
            raw = data.get("models", [])
            for m in raw:
                name = m.get("name", m.get("model", ""))
                size = m.get("size", 0)
                quant, cat = self._detect_gguf_quant(name)
                models.append(ModelInfo(
                    id=name,
                    name=name,
                    provider=provider_id,
                    owned_by=info.get("name", provider_id),
                    quantization=quant,
                    quant_category=cat,
                    size_gb=round(size / (1024**3), 2) if size else None,
                    is_gguf=True,
                    is_local=True,
                    capabilities=["chat", "streaming", "tools"],
                    modified_at=m.get("modified_at"),
                ))
        elif fmt == "kobold":
            name = data.get("result", "")
            if name:
                quant, cat = self._detect_gguf_quant(name)
                models.append(ModelInfo(
                    id=name,
                    name=name,
                    provider=provider_id,
                    owned_by=info.get("name", provider_id),
                    quantization=quant,
                    quant_category=cat,
                    is_gguf=True,
                    is_local=True,
                    capabilities=["chat", "streaming"],
                ))
        return models

    def _detect_gguf_quant(self, model_id: str) -> Tuple[Optional[str], Optional[str]]:
        match = QUANT_PATTERN.search(model_id)
        if match:
            quant = match.group(1).upper()
            for cat, quants in GGUF_QUANTIZATIONS.items():
                if quant in quants:
                    return quant, cat
            return quant, "Unknown"
        return None, None

    async def test_connection(self, provider_id: str) -> Tuple[bool, str, List[str]]:
        try:
            models = await self.list_models(provider_id)
            return True, "", [m.id for m in models]
        except Exception as e:
            return False, str(e), []

    async def chat_completion(
        self,
        provider_id: str,
        model: str,
        messages: List[dict],
        params: dict,
        tools: Optional[List[dict]] = None,
        tool_choice: Optional[Union[str, dict]] = None,
        stream: bool = False,
        ) -> AsyncGenerator[str, None] | dict:
        if provider_id == "__native__":
            return await self._chat_native(model, messages, params, tools, tool_choice, stream)
        info = self._get_local_config(provider_id)
        fmt = info.get("format", "openai")

        if fmt == "openai":
            return await self._chat_openai_compatible(info, model, messages,
                                                      params, tools, tool_choice,
                                                      stream, provider_id)
        elif fmt == "ollama":
            return await self._chat_ollama(info, model, messages, params,
                                           tools, stream, provider_id)
        elif fmt == "kobold":
            return await self._chat_kobold(info, model, messages, params,
                                           stream, provider_id)
        else:
            raise HTTPException(400, f"Unsupported local format: {fmt}")

    async def _chat_native(
        self,
        model: str,
        messages: List[dict],
        params: dict,
        tools: Optional[List[dict]] = None,
        tool_choice: Optional[Union[str, dict]] = None,
        stream: bool = False,
    ) -> AsyncGenerator[str, None] | dict:
        # Qwen and other ChatML templates support system roles. Folding every
        # instruction into the user turn made small models echo work logs.
        architecture = str(getattr(NATIVE_GGUF_RUNTIME._llama, "metadata", {}).get("general.architecture", ""))
        if architecture.startswith("gemma"):
            messages = fold_system_messages_into_user(messages)
        else:
            system_parts = []
            turns = []
            for message in messages:
                if message.get("role") == "system":
                    system_parts.append(_flatten_message_content_for_text_model(message.get("content")))
                else:
                    turns.extend(fold_system_messages_into_user([message]))
            messages = ([{"role": "system", "content": "\n\n".join(system_parts)}] if system_parts else []) + turns
        if stream:
            return await NATIVE_GGUF_RUNTIME.chat_completion(messages, params, tools, tool_choice, stream=True)
        return await NATIVE_GGUF_RUNTIME.chat_completion(messages, params, tools, tool_choice, stream=False)

    async def _chat_openai_compatible(self, info, model, messages, params,
                                       tools, tool_choice, stream, provider_id):
        client = self._get_client(provider_id)
        headers = self._build_headers(provider_id, info)
        base_url = info.get("base_url", "").rstrip("/")
        ep = info.get("chat_endpoint", "")
        url = base_url if base_url.endswith(ep) else f"{base_url}{ep}"

        body: dict = {
            "model": model,
            "messages": messages,
            "stream": stream,
        }
        for p in ["temperature", "top_p", "max_tokens", "frequency_penalty",
                   "presence_penalty", "stop", "seed"]:
            if p in params and params[p] is not None:
                body[p] = params[p]
        if "top_k" in params:
            body["top_k"] = params["top_k"]
        if "repetition_penalty" in params:
            body["repetition_penalty"] = params["repetition_penalty"]
        if tools:
            body["tools"] = tools
        if tool_choice:
            body["tool_choice"] = tool_choice

        if "stop" in body and isinstance(body["stop"], list) and len(body["stop"]) > 4:
            body["stop"] = body["stop"][:4]

        if stream:
            return self._stream_openai_compatible(client, url, headers, body)
        else:
            resp = await client.post(url, headers=headers, json=body, timeout=1800)
            if resp.status_code >= 400:
                logger.error(f"Local provider error {resp.status_code}: {resp.text}")
                raise HTTPException(resp.status_code, f"Local provider error: {resp.text}")
            resp.raise_for_status()
            return resp.json()

    async def _stream_openai_compatible(self, client, url, headers, body):
        async with client.stream("POST", url, headers=headers, json=body, timeout=1800) as resp:
            if resp.status_code >= 400:
                await resp.aread()
                logger.error(f"Local provider stream error {resp.status_code}: {resp.text}")
                raise HTTPException(resp.status_code, f"Local provider error: {resp.text}")
            resp.raise_for_status()
            async for line in resp.aiter_lines():
                line = line.strip()
                if not line:
                    continue
                if line.startswith("data: "):
                    data = line[6:]
                    if data.strip() == "[DONE]":
                        yield "data: [DONE]\n\n"
                        break
                    try:
                        yield f"data: {data}\n\n"
                    except Exception:
                        continue
                else:
                    try:
                        yield f"data: {line}\n\n"
                    except Exception:
                        continue

    async def _chat_ollama(self, info, model, messages, params,
                           tools, stream, provider_id):
        client = self._get_client(provider_id)
        base_url = info.get("base_url", "").rstrip("/")
        ep = info.get("chat_endpoint", "")
        url = base_url if base_url.endswith(ep) else f"{base_url}{ep}"

        body: dict = {
            "model": model,
            "messages": messages,
            "stream": stream,
            "keep_alive": -1,
        }
        opts = {}
        for p in ["temperature", "top_p", "top_k", "num_predict"]:
            if p in params:
                opts[p] = params[p]
        if "max_tokens" in params:
            opts["num_predict"] = params["max_tokens"]
        if "repetition_penalty" in params:
            opts["repeat_penalty"] = params["repetition_penalty"]
        if "stop" in params:
            opts["stop"] = params["stop"]
        if opts:
            body["options"] = opts
        if tools:
            ollama_tools = []
            for t in tools:
                if t.get("type") == "function":
                    ollama_tools.append({
                        "type": "function",
                        "function": {
                            "name": t["function"]["name"],
                            "description": t["function"].get("description", ""),
                            "parameters": t["function"].get("parameters", {}),
                        }
                    })
            if ollama_tools:
                body["tools"] = ollama_tools

        if stream:
            return self._stream_ollama(client, url, body, model)
        else:
            resp = await client.post(url, json=body, timeout=1800)
            resp.raise_for_status()
            return resp.json()

    async def _stream_ollama(self, client, url, body, model):
        async with client.stream("POST", url, json=body, timeout=1800) as resp:
            if resp.status_code >= 400:
                await resp.aread()
                logger.error(f"Ollama stream error {resp.status_code}: {resp.text}")
                raise HTTPException(resp.status_code, f"Ollama error: {resp.text}")
            buffer = ""
            async for chunk in resp.aiter_text():
                buffer += chunk
                while "\n" in buffer:
                    line, buffer = buffer.split("\n", 1)
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        event = json.loads(line)
                        msg = event.get("message", {})
                        content = msg.get("content", "")
                        if content:
                            chunk_data = {
                                "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                                "object": "chat.completion.chunk",
                                "created": int(time.time()),
                                "model": model,
                                "choices": [{
                                    "index": 0,
                                    "delta": {"content": content},
                                    "finish_reason": None
                                }]
                            }
                            yield f"data: {json.dumps(chunk_data)}\n\n"
                        if event.get("done"):
                            # Handle tool calls in final message
                            if msg.get("tool_calls"):
                                tc_chunk = {
                                    "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                                    "object": "chat.completion.chunk",
                                    "created": int(time.time()),
                                    "model": model,
                                    "choices": [{
                                        "index": 0,
                                        "delta": {"tool_calls": msg["tool_calls"]},
                                        "finish_reason": "tool_calls"
                                    }]
                                }
                                yield f"data: {json.dumps(tc_chunk)}\n\n"
                            else:
                                final_chunk = {
                                    "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                                    "object": "chat.completion.chunk",
                                    "created": int(time.time()),
                                    "model": model,
                                    "choices": [{
                                        "index": 0, "delta": {},
                                        "finish_reason": "stop"
                                    }]
                                }
                                yield f"data: {json.dumps(final_chunk)}\n\n"
                            yield "data: [DONE]\n\n"
                            break
                    except json.JSONDecodeError:
                        continue

    async def _chat_kobold(self, info, model, messages, params, stream, provider_id):
        client = self._get_client(provider_id)
        url = f"{info['base_url']}{info['chat_endpoint']}"

        prompt = ""
        for m in messages:
            if m["role"] == "system":
                prompt += f"### System:\n{m.get('content', '')}\n\n"
            elif m["role"] == "user":
                prompt += f"### User:\n{m.get('content', '')}\n\n"
            elif m["role"] == "assistant":
                prompt += f"### Assistant:\n{m.get('content', '')}\n\n"
        prompt += "### Assistant:\n"

        body = {
            "prompt": prompt,
            "max_length": params.get("max_tokens", 512),
            "temperature": params.get("temperature", 0.7),
            "top_p": params.get("top_p", 0.9),
            "top_k": params.get("top_k", 40),
            "rep_pen": params.get("repetition_penalty", 1.1),
        }

        if stream:
            return self._stream_kobold(client, url, body, model)
        else:
            resp = await client.post(url, json=body, timeout=1800)
            resp.raise_for_status()
            data = resp.json()
            results = data.get("results", [])
            text = results[0].get("text", "") if results else ""
            return {
                "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                "object": "chat.completion",
                "created": int(time.time()),
                "model": model,
                "choices": [{
                    "index": 0,
                    "message": {"role": "assistant", "content": text},
                    "finish_reason": "stop"
                }],
                "usage": {"prompt_tokens": 0, "completion_tokens": 0, "total_tokens": 0}
            }

    async def _stream_kobold(self, client, url, body, model):
        async with client.stream("POST", url, json=body, timeout=1800) as resp:
            if resp.status_code >= 400:
                await resp.aread()
                logger.error(f"KoboldCpp stream error {resp.status_code}: {resp.text}")
                raise HTTPException(resp.status_code, f"KoboldCpp error: {resp.text}")
            async for line in resp.aiter_lines():
                line = line.strip()
                if not line:
                    continue
                try:
                    event = json.loads(line)
                    token = event.get("token", {})
                    text = token.get("text", "")
                    if text:
                        chunk_data = {
                            "id": f"chatcmpl-{uuid.uuid4().hex[:12]}",
                            "object": "chat.completion.chunk",
                            "created": int(time.time()),
                            "model": model,
                            "choices": [{
                                "index": 0,
                                "delta": {"content": text},
                                "finish_reason": None
                            }]
                        }
                        yield f"data: {json.dumps(chunk_data)}\n\n"
                    if event.get("stop"):
                        yield "data: [DONE]\n\n"
                        break
                except json.JSONDecodeError:
                    continue

    async def close(self):
        for client in self._clients.values():
            await client.aclose()
        self._clients.clear()


# ==================================================
# SECTION 8: MCP CLIENT & MANAGER
# ==================================================

@dataclass
class MCPConnection:
    """Represents a live MCP server connection."""
    name: str
    config: MCPServerConfig
    transport: MCPTransportType
    connected: bool = False
    process: Optional[asyncio.subprocess.Process] = None
    sse_session: Optional[httpx.AsyncClient] = None
    sse_url: Optional[str] = None
    tools: List[MCPToolDef] = field(default_factory=list)
    error: Optional[str] = None
    connected_at: Optional[str] = None
    _request_id: int = 0
    _pending: Dict[int, asyncio.Future] = field(default_factory=dict)
    _read_task: Optional[asyncio.Task] = None
    _lock: asyncio.Lock = field(default_factory=asyncio.Lock)

    def next_id(self) -> int:
        self._request_id += 1
        return self._request_id


class MCPManager:
    """
    Full MCP (Model Context Protocol) manager.
    Supports stdio and SSE transports, compatible with LM Studio config format.
    """

    def __init__(self, persistence: PersistenceManager):
        self.persistence = persistence
        self.connections: Dict[str, MCPConnection] = {}
        self._lock = asyncio.Lock()

    async def initialize(self):
        """Load saved servers and auto-connect enabled ones."""
        servers = self.persistence.mcp_servers
        for name, config in servers.items():
            self.connections[name] = MCPConnection(
                name=name, config=config, transport=config.transport
            )
        if self.persistence.config.mcp_auto_connect:
            for name, conn in self.connections.items():
                if conn.config.auto_connect and conn.config.enabled:
                    try:
                        await self.connect(name)
                    except Exception as e:
                        logger.error(f"Auto-connect {name} failed: {e}")
                        conn.error = str(e)

    async def add_server(self, name: str, config: MCPServerConfig):
        async with self._lock:
            self.connections[name] = MCPConnection(
                name=name, config=config, transport=config.transport
            )
            self.persistence.mcp_servers[name] = config
            self.persistence.save_mcp_config()

    async def remove_server(self, name: str):
        async with self._lock:
            conn = self.connections.pop(name, None)
            if conn:
                await self._disconnect(conn)
            self.persistence.mcp_servers.pop(name, None)
            self.persistence.save_mcp_config()

    async def connect(self, name: str):
        async with self._lock:
            conn = self.connections.get(name)
            if not conn:
                raise HTTPException(404, f"MCP server '{name}' not found")
            if conn.connected:
                return

            if conn.transport == MCPTransportType.STDIO:
                await self._connect_stdio(conn)
            elif conn.transport == MCPTransportType.SSE:
                await self._connect_sse(conn)

    async def _connect_stdio(self, conn: MCPConnection):
        """Connect to MCP server via stdio (subprocess)."""
        config = conn.config
        if not config.command:
            raise ValueError(f"Missing command for stdio server '{conn.name}'")

        cmd = [config.command] + config.args
        env = {**os.environ, **config.env}

        try:
            process = await _safe_create_subprocess_exec(
                *cmd,
                stdin=asyncio.subprocess.PIPE,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                env=env,
                cwd=config.cwd or None,
            )
        except Exception as e:
            conn.error = f"Failed to start process: {e}"
            raise

        conn.process = process
        conn._read_task = asyncio.create_task(
            self._read_stdio_loop(conn), name=f"mcp-read-{conn.name}"
        )

        # Initialize handshake
        try:
            init_result = await self._send_request(conn, "initialize", {
                "protocolVersion": "2024-11-05",
                "capabilities": {
                    "roots": {"listChanged": True},
                },
                "clientInfo": {
                    "name": APP_NAME,
                    "version": APP_VERSION,
                },
            }, timeout=15)

            # Send initialized notification
            await self._send_notification(conn, "notifications/initialized", {})

            conn.connected = True
            conn.connected_at = datetime.now(timezone.utc).isoformat()
            conn.error = None

            # Fetch tools
            if init_result.get("capabilities", {}).get("tools"):
                await self._refresh_tools(conn)

            # Update config
            conn.config.enabled = True
            self.persistence.mcp_servers[conn.name] = conn.config
            self.persistence.save_mcp_config()

            logger.info(f"MCP server '{conn.name}' connected (stdio, pid={process.pid})")

        except Exception as e:
            conn.error = str(e)
            if process:
                try:
                    # Prefer killing the whole process group on POSIX so
                    # any children are also terminated.
                    if os.name != "nt" and getattr(process, "pid", None):
                        try:
                            os.killpg(os.getpgid(process.pid), signal.SIGTERM)
                        except Exception:
                            pass
                    process.kill()
                except Exception:
                    pass
            if conn._read_task:
                conn._read_task.cancel()
            conn.process = None
            raise

    async def _connect_sse(self, conn: MCPConnection):
        """Connect to MCP server via SSE (HTTP)."""
        config = conn.config
        if not config.url:
            raise ValueError(f"Missing URL for SSE server '{conn.name}'")

        try:
            client = httpx.AsyncClient(timeout=httpx.Timeout(30.0))
            resp = await client.get(config.url)
            resp.raise_for_status()
            sse_url = config.url

            # Parse SSE to get message endpoint
            message_url = config.url.replace("/sse", "/messages")
            if not message_url.endswith("/messages"):
                message_url = config.url.rsplit("/", 1)[0] + "/messages"

            conn.sse_session = client
            conn.sse_url = sse_url

            # Initialize via POST
            init_result = await self._send_sse_request(conn, message_url, "initialize", {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": APP_NAME, "version": APP_VERSION},
            }, timeout=15)

            await self._send_sse_notification(conn, message_url, "notifications/initialized", {})

            conn.connected = True
            conn.connected_at = datetime.now(timezone.utc).isoformat()
            conn.error = None

            if init_result.get("capabilities", {}).get("tools"):
                await self._refresh_tools(conn)

            logger.info(f"MCP server '{conn.name}' connected (SSE, url={config.url})")

        except Exception as e:
            conn.error = str(e)
            if conn.sse_session:
                await conn.sse_session.aclose()
            conn.sse_session = None
            raise

    async def _read_stdio_loop(self, conn: MCPConnection):
        """Continuously read from MCP process stdout."""
        try:
            while conn.process and conn.process.stdout:
                line = await conn.process.stdout.readline()
                if not line:
                    break
                try:
                    msg = json.loads(line.decode("utf-8").strip())
                    await self._handle_message(conn, msg)
                except json.JSONDecodeError:
                    pass
                except Exception as e:
                    logger.debug(f"MCP read error for {conn.name}: {e}")
        except asyncio.CancelledError:
            pass
        except Exception as e:
            logger.error(f"MCP stdio read loop error for {conn.name}: {e}")
        finally:
            if conn.connected:
                conn.connected = False
                conn.error = "Process terminated"
                conn.process = None

    async def _handle_message(self, conn: MCPConnection, msg: dict):
        """Handle incoming JSON-RPC message."""
        if "id" in msg and msg["id"] in conn._pending:
            future = conn._pending.pop(msg["id"])
            if not future.done():
                if "error" in msg:
                    future.set_exception(Exception(msg["error"].get("message", "MCP error")))
                else:
                    future.set_result(msg.get("result", {}))

    async def _send_request(self, conn: MCPConnection, method: str,
                            params: dict, timeout: float = 30) -> dict:
        """Send JSON-RPC request and wait for response."""
        request_id = conn.next_id()
        msg = {
            "jsonrpc": "2.0",
            "id": request_id,
            "method": method,
            "params": params,
        }

        async with conn._lock:
            if conn.process and conn.process.stdin:
                data = json.dumps(msg) + "\n"
                conn.process.stdin.write(data.encode("utf-8"))
                await conn.process.stdin.drain()
            else:
                raise ConnectionError(f"Not connected to '{conn.name}'")

        future: asyncio.Future = asyncio.get_event_loop().create_future()
        conn._pending[request_id] = future

        try:
            return await asyncio.wait_for(future, timeout=timeout)
        except asyncio.TimeoutError:
            conn._pending.pop(request_id, None)
            raise TimeoutError(f"MCP request '{method}' timed out")

    async def _send_notification(self, conn: MCPConnection, method: str, params: dict):
        """Send JSON-RPC notification (no response expected)."""
        msg = {
            "jsonrpc": "2.0",
            "method": method,
            "params": params,
        }
        async with conn._lock:
            if conn.process and conn.process.stdin:
                data = json.dumps(msg) + "\n"
                conn.process.stdin.write(data.encode("utf-8"))
                await conn.process.stdin.drain()

    async def _send_sse_request(self, conn: MCPConnection, message_url: str,
                                 method: str, params: dict,
                                 timeout: float = 30) -> dict:
        """Send JSON-RPC request via SSE POST endpoint."""
        request_id = conn.next_id()
        msg = {
            "jsonrpc": "2.0",
            "id": request_id,
            "method": method,
            "params": params,
        }
        if conn.sse_session:
            resp = await conn.sse_session.post(
                message_url, json=msg, timeout=timeout
            )
            resp.raise_for_status()
            data = resp.json()
            if "error" in data:
                raise Exception(data["error"].get("message", "MCP error"))
            return data.get("result", {})
        raise ConnectionError(f"SSE not connected for '{conn.name}'")

    async def _send_sse_notification(self, conn: MCPConnection, message_url: str,
                                      method: str, params: dict):
        """Send JSON-RPC notification via SSE POST endpoint."""
        msg = {
            "jsonrpc": "2.0",
            "method": method,
            "params": params,
        }
        if conn.sse_session:
            try:
                await conn.sse_session.post(message_url, json=msg, timeout=5)
            except Exception:
                pass

    async def _refresh_tools(self, conn: MCPConnection):
        """Fetch tool list from connected MCP server."""
        try:
            if conn.transport == MCPTransportType.STDIO:
                result = await self._send_request(conn, "tools/list", {}, timeout=10)
            elif conn.transport == MCPTransportType.SSE:
                config = conn.config
                message_url = config.url.replace("/sse", "/messages")
                if not message_url.endswith("/messages"):
                    message_url = config.url.rsplit("/", 1)[0] + "/messages"
                result = await self._send_sse_request(conn, message_url, "tools/list", {}, timeout=10)
            else:
                return

            tools = []
            for t in result.get("tools", []):
                tools.append(MCPToolDef(
                    name=t.get("name", ""),
                    description=t.get("description", ""),
                    input_schema=t.get("inputSchema", {}),
                ))
            conn.tools = tools
            logger.info(f"MCP '{conn.name}': {len(tools)} tools loaded")
        except Exception as e:
            logger.error(f"Failed to refresh tools for '{conn.name}': {e}")

    async def disconnect(self, name: str):
        async with self._lock:
            conn = self.connections.get(name)
            if conn:
                await self._disconnect(conn)

    async def _disconnect(self, conn: MCPConnection):
        was_connected = conn.connected
        conn.connected = False
        conn.error = None

        if conn._read_task:
            conn._read_task.cancel()
            try:
                await conn._read_task
            except asyncio.CancelledError:
                pass
            conn._read_task = None

        if conn.process:
            try:
                conn.process.stdin.write(json.dumps({
                    "jsonrpc": "2.0", "method": "shutdown", "params": {}
                }).encode() + b"\n")
                await conn.process.stdin.drain()
                await asyncio.sleep(0.1)
                conn.process.stdin.write(json.dumps({
                    "jsonrpc": "2.0", "method": "exit", "params": {}
                }).encode() + b"\n")
                await conn.process.stdin.drain()
                await asyncio.sleep(0.2)
            except Exception:
                pass
            try:
                conn.process.terminate()
                await asyncio.wait_for(conn.process.wait(), timeout=3)
            except asyncio.TimeoutError:
                try:
                    if os.name != "nt" and getattr(conn.process, "pid", None):
                        try:
                            os.killpg(os.getpgid(conn.process.pid), signal.SIGTERM)
                        except Exception:
                            pass
                    conn.process.kill()
                except Exception:
                    pass
            except Exception:
                pass
            conn.process = None

        if conn.sse_session:
            await conn.sse_session.aclose()
            conn.sse_session = None

        conn.tools = []
        if was_connected:
            logger.info(f"MCP server '{conn.name}' disconnected")

    async def call_tool(self, server_name: str, tool_name: str,
                        arguments: dict) -> Any:
        """Execute a tool on a connected MCP server."""
        conn = self.connections.get(server_name)
        if not conn:
            raise HTTPException(404, f"MCP server '{server_name}' not found")
        if not conn.connected:
            raise HTTPException(400, f"MCP server '{server_name}' not connected")

        try:
            if conn.transport == MCPTransportType.STDIO:
                result = await self._send_request(conn, "tools/call", {
                    "name": tool_name,
                    "arguments": arguments,
                }, timeout=120)
            elif conn.transport == MCPTransportType.SSE:
                config = conn.config
                message_url = config.url.replace("/sse", "/messages")
                if not message_url.endswith("/messages"):
                    message_url = config.url.rsplit("/", 1)[0] + "/messages"
                result = await self._send_sse_request(conn, message_url, "tools/call", {
                    "name": tool_name,
                    "arguments": arguments,
                }, timeout=120)
            else:
                raise HTTPException(400, "Unknown transport")

            # Extract text content from result
            content = result.get("content", [])
            text_parts = []
            for c in content:
                if c.get("type") == "text":
                    text_parts.append(c["text"])
                elif c.get("type") == "image":
                    text_parts.append(f"[Image: {c.get('mimeType', 'image')}]")
                else:
                    text_parts.append(json.dumps(c))
            return {
                "content": "\n".join(text_parts),
                "is_error": result.get("isError", False),
                "raw": result,
            }
        except Exception as e:
            return {
                "content": f"Tool execution error: {e}",
                "is_error": True,
                "raw": None,
            }

    def get_all_tools(self) -> List[dict]:
        """Get all tools from all connected servers in OpenAI format."""
        all_tools = []
        for name, conn in self.connections.items():
            if conn.connected:
                for tool in conn.tools:
                    all_tools.append({
                        "type": "function",
                        "function": {
                            "name": tool.name,
                            "description": tool.description,
                            "parameters": tool.input_schema,
                        },
                        "mcp_server": name,
                    })
        return all_tools

    def get_server_status(self) -> List[MCPServerStatus]:
        statuses = []
        for name, conn in self.connections.items():
            statuses.append(MCPServerStatus(
                name=conn.name,
                transport=conn.transport.value,
                connected=conn.connected,
                tools=conn.tools,
                error=conn.error,
                pid=conn.process.pid if conn.process else None,
                connected_at=conn.connected_at,
            ))
        return statuses

    async def shutdown(self):
        for conn in self.connections.values():
            await self._disconnect(conn)
        self.connections.clear()


# ==================================================
# SECTION 9: PAGE-INDEXING RAG SERVICE
# ==================================================

class PageIndexingRAG:
    """
    Production hierarchical RAG for large local documents.

    Pipeline:
      extract -> normalize -> page map -> semantic chunks -> embeddings ->
      hybrid dense/lexical retrieval -> neighbor/coverage expansion ->
      sentence-level context compression -> strict context packing.

    The local LLM never needs the whole file. A large file can therefore be
    arbitrarily bigger than the model context window while the answer still
    draws from relevant parts of the complete document.
    """

    _IMAGE_ATTACHMENT_EXTENSIONS = {"png", "jpg", "jpeg", "webp", "bmp", "tif", "tiff", "gif"}

    # Large-file policy: files over 500 KiB are ALWAYS indexed/chunked; they
    # are never blindly injected or hard-truncated into the model prompt.
    LARGE_FILE_BYTES = 500 * 1024
    LARGE_CHUNK_WORDS = 520
    LARGE_CHUNK_OVERLAP = 72
    RETRIEVAL_CANDIDATES = 48
    RETRIEVAL_RETURN = 18
    CONTEXT_TARGET_CHARS = 7000
    CONTEXT_HARD_LIMIT_CHARS = 8000

    def __init__(self, persistence: PersistenceManager,
                 cloud_engine: Optional[CloudInferenceEngine] = None,
                 local_engine: Optional[LocalInferenceEngine] = None):
        self.persistence = persistence
        self.cloud_engine = cloud_engine
        self.local_engine = local_engine
        self._indexing = False
        self._index_progress = 0.0
        self._index_current_file = ""
        self._embeddings_cache: Dict[str, List[float]] = {}
        self._pageindex_client: Optional["PageIndexClient"] = None
        self._pageindex_doc_cache: Dict[str, str] = {}
        self._ocr_engine: Any = None
        if HAS_PAGEINDEX and PAGEINDEX_API_KEY:
            try:
                self._pageindex_client = PageIndexClient(api_key=PAGEINDEX_API_KEY)
                logger.info("PageIndex client initialized from PAGEINDEX_API_KEY")
            except Exception as e:
                logger.warning(f"PageIndex client initialization failed: {e}")

    def _pageindex_cache_path(self, doc_id: str) -> Path:
        return INDEXES_DIR / f"{doc_id}.pageindex.json"

    def _load_pageindex_cache(self, doc_id: str) -> dict:
        if doc_id in self._pageindex_doc_cache:
            return {"pageindex_doc_id": self._pageindex_doc_cache[doc_id]}
        cache_path = self._pageindex_cache_path(doc_id)
        if not cache_path.exists():
            return {}
        try:
            return json.loads(cache_path.read_text(encoding="utf-8"))
        except Exception as e:
            logger.warning(f"Failed to read PageIndex cache for {doc_id}: {e}")
            return {}

    def _save_pageindex_cache(self, doc_id: str, payload: dict):
        cache_path = self._pageindex_cache_path(doc_id)
        try:
            cache_path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
            pageindex_doc_id = payload.get("pageindex_doc_id")
            if pageindex_doc_id:
                self._pageindex_doc_cache[doc_id] = pageindex_doc_id
        except Exception as e:
            logger.warning(f"Failed to persist PageIndex cache for {doc_id}: {e}")

    def _remove_pageindex_cache(self, doc_id: str):
        self._pageindex_doc_cache.pop(doc_id, None)
        self._pageindex_cache_path(doc_id).unlink(missing_ok=True)

    @staticmethod
    def _normalize_preview_title(page: dict, fallback: str) -> str:
        title = str(page.get("title") or "").strip()
        return title or fallback

    @staticmethod
    def _is_pageindex_supported(file_type: str) -> bool:
        return file_type.lower() in {"pdf", "md", "markdown"}

    @property
    def is_indexing(self) -> bool:
        return self._indexing

    @property
    def status(self) -> RAGIndexStatus:
        docs = self.persistence.list_rag_documents()
        return RAGIndexStatus(
            total_documents=len(docs),
            indexed_documents=sum(1 for d in docs if d.indexed),
            total_pages=sum(d.pages for d in docs),
            total_chunks=sum(d.chunks for d in docs),
            indexing=self._indexing,
            current_file=self._index_current_file if self._indexing else None,
            progress=self._index_progress,
        )

    async def upload_document(self, file: UploadFile) -> RAGDocumentInfo:
        """Save uploaded file and create document record."""
        doc_id = f"doc-{uuid.uuid4().hex[:16]}"
        filename = file.filename or "unknown"
        file_ext = Path(filename).suffix.lower()
        file_type = file_ext.lstrip(".")

        # Save file
        file_path = DOCUMENTS_DIR / f"{doc_id}{file_ext}"
        content = await file.read()
        file_path.write_bytes(content)

        doc = RAGDocumentInfo(
            id=doc_id,
            filename=filename,
            file_type=file_type,
            size_bytes=len(content),
            pages=0,
            chunks=0,
            indexed=False,
            uploaded_at=datetime.now(timezone.utc).isoformat(),
        )
        self.persistence.add_rag_document(doc, str(file_path))
        return doc

    def _ocr_pdf_pages(self, file_path: Path) -> List[dict]:
        """OCR scanned/image-only PDF pages into page-preserving text.

        This is deliberately deterministic and happens BEFORE any LLM/tool
        orchestration. A scanned attachment must become real document context;
        otherwise the agent sees only the filename and can hallucinate an
        unrelated document. RapidOCR is preferred because it is self-contained;
        pytesseract is a fallback when a Tesseract installation is available.
        """
        global RapidOCR, HAS_RAPIDOCR
        if not HAS_PYMUPDF:
            raise HTTPException(
                415,
                f"'{file_path.name}' is image-only and cannot be OCR'd because "
                "PyMuPDF (fitz) is not installed. Install: pip install pymupdf"
            )

        ocr_engine = self._ocr_engine
        if ocr_engine is None:
            rapidocr_factory = RapidOCR
            if rapidocr_factory is None:
                # Dependencies can be repaired while the desktop app is open.
                # Resolve again at use-time instead of requiring a full reboot.
                try:
                    from rapidocr_onnxruntime import RapidOCR as discovered_rapidocr
                    RapidOCR = discovered_rapidocr
                    HAS_RAPIDOCR = True
                    rapidocr_factory = discovered_rapidocr
                except ImportError:
                    rapidocr_factory = None
            if rapidocr_factory is not None:
                try:
                    ocr_engine = rapidocr_factory()
                    self._ocr_engine = ocr_engine
                except Exception as exc:
                    logger.warning("RapidOCR initialization failed: %s", exc)
                    ocr_engine = None

        if ocr_engine is None and not (HAS_TESSERACT and HAS_PIL):
            raise HTTPException(
                415,
                f"'{file_path.name}' has no extractable text. OCR support is unavailable. "
                "Install rapidocr_onnxruntime (preferred) or pytesseract with Tesseract."
            )

        pages: List[dict] = []
        try:
            pdf = fitz.open(str(file_path))
        except Exception as exc:
            raise HTTPException(
                415,
                f"'{file_path.name}' could not be rendered for OCR: {exc}"
            ) from exc

        try:
            for index, page in enumerate(pdf):
                try:
                    # 2x render is a good accuracy/speed compromise for
                    # certificates, scanned forms and normal documents.
                    pix = page.get_pixmap(matrix=fitz.Matrix(2.0, 2.0), alpha=False)
                    raw_png = pix.tobytes("png")
                    text = ""

                    if ocr_engine is not None:
                        try:
                            result, _ = ocr_engine(raw_png)
                            if result:
                                # RapidOCR returns [box, text, score].
                                text = "\n".join(
                                    str(item[1]).strip()
                                    for item in result
                                    if isinstance(item, (list, tuple)) and len(item) > 1 and str(item[1]).strip()
                                )
                        except Exception as exc:
                            logger.warning(
                                "RapidOCR failed on page %s of %s: %s",
                                index + 1, file_path.name, exc
                            )

                    if not text and HAS_TESSERACT and HAS_PIL:
                        try:
                            image = Image.open(io.BytesIO(raw_png))
                            text = pytesseract.image_to_string(image, config="--psm 6") or ""
                        except Exception as exc:
                            logger.warning(
                                "Tesseract OCR failed on page %s of %s: %s",
                                index + 1, file_path.name, exc
                            )

                    pages.append({"page": index + 1, "text": text.strip(), "ocr": True})
                except Exception as page_exc:
                    logger.warning(
                        "OCR failed on page %s of %s: %s",
                        index + 1, file_path.name, page_exc
                    )
                    pages.append({"page": index + 1, "text": "", "ocr": True})
        finally:
            with contextlib.suppress(Exception):
                pdf.close()

        if not any((page.get("text") or "").strip() for page in pages):
            raise HTTPException(
                422,
                f"'{file_path.name}' appears to be scanned/image-only, but OCR could not "
                "recover readable text from any page."
            )
        return pages

    def _extract_text_from_pdf(self, file_path: Path) -> List[dict]:
        """Extract PDF text, with OCR fallback for scanned/image-only PDFs.

        Text extraction is always preferred. If a structurally valid PDF has
        zero text on every page, OCR is attempted before the attachment is
        declared unreadable. This prevents the chat agent from receiving an
        empty document and hallucinating an answer from unrelated context.
        """
        if not HAS_PDFPLUMBER and not HAS_PYPDF:
            # We can still OCR a scanned PDF when PyMuPDF is available.
            if HAS_PYMUPDF:
                return self._ocr_pdf_pages(file_path)
            raise HTTPException(
                500,
                "No PDF text/OCR library available on the server. Install "
                "pypdf pdfplumber pymupdf rapidocr_onnxruntime"
            )

        pages: List[dict] = []
        last_error: Optional[Exception] = None

        if HAS_PDFPLUMBER:
            try:
                with pdfplumber.open(str(file_path)) as pdf:
                    for i, page in enumerate(pdf.pages):
                        try:
                            text = page.extract_text() or ""
                        except Exception as page_err:
                            logger.warning(
                                f"pdfplumber failed on page {i + 1} of {file_path.name}: {page_err}"
                            )
                            text = ""
                        pages.append({"page": i + 1, "text": text})
            except Exception as e:
                last_error = e
                logger.warning(
                    f"pdfplumber failed to open {file_path.name}, trying pypdf: {e}"
                )
                pages = []

        if not pages and HAS_PYPDF:
            try:
                reader = PdfReader(str(file_path))
                if getattr(reader, "is_encrypted", False):
                    try:
                        reader.decrypt("")
                    except Exception as decrypt_err:
                        raise HTTPException(
                            415,
                            f"'{file_path.name}' is password-protected and could not be "
                            "opened with an empty password. Remove the password protection "
                            "and re-attach the file."
                        ) from decrypt_err
                for i, page in enumerate(reader.pages):
                    try:
                        text = page.extract_text() or ""
                    except Exception as page_err:
                        logger.warning(
                            f"pypdf failed on page {i + 1} of {file_path.name}: {page_err}"
                        )
                        text = ""
                    pages.append({"page": i + 1, "text": text})
            except HTTPException:
                raise
            except Exception as e:
                last_error = e
                pages = []

        if not pages:
            if HAS_PYMUPDF:
                return self._ocr_pdf_pages(file_path)
            raise HTTPException(
                415,
                f"'{file_path.name}' could not be opened as a PDF"
                + (f" ({last_error})" if last_error else "")
                + ". The file may be corrupted or not a valid PDF."
            )

        if any((page.get("text") or "").strip() for page in pages):
            return pages

        # Structurally valid but textless: this is the critical scanned-PDF
        # path that previously returned an error and allowed the model to
        # continue without document evidence.
        if HAS_PYMUPDF:
            return self._ocr_pdf_pages(file_path)

        raise HTTPException(
            422,
            f"'{file_path.name}' has no extractable text - it looks like a "
            "scanned or image-only PDF, and OCR support is not installed. "
            "Install rapidocr_onnxruntime (preferred) or pytesseract with Tesseract."
        )

    def _extract_text_from_txt(self, file_path: Path) -> List[dict]:
        """Extract text from plain text, splitting by page markers or fixed size."""
        text = file_path.read_text(encoding="utf-8", errors="replace")
        # Try to detect page breaks
        page_breaks = re.split(r'\f|\n{3,}', text)
        if len(page_breaks) > 1:
            return [{"page": i + 1, "title": f"Page {i + 1}", "kind": "text", "text": t.strip()}
                    for i, t in enumerate(page_breaks) if t.strip()]
        # Split by approximate page size (3000 chars)
        pages = []
        chunk_size = 3000
        for i in range(0, len(text), chunk_size):
            page_no = len(pages) + 1
            pages.append({
                "page": page_no,
                "title": f"Page {page_no}",
                "kind": "text",
                "text": text[i:i+chunk_size].strip(),
            })
        return pages if pages else [{"page": 1, "title": "Page 1", "kind": "text", "text": text}]

    def _extract_text_from_md(self, file_path: Path) -> List[dict]:
        """Extract text from markdown."""
        text = file_path.read_text(encoding="utf-8", errors="replace")
        pages = []
        current_title = "Markdown"
        current_lines: List[str] = []
        for line in text.splitlines():
            heading = re.match(r"^(#{1,6})\s+(.*)$", line)
            if heading:
                if current_lines:
                    pages.append({
                        "page": len(pages) + 1,
                        "title": current_title,
                        "kind": "markdown-section",
                        "text": "\n".join(current_lines).strip(),
                    })
                    current_lines = []
                current_title = heading.group(2).strip() or f"Section {len(pages) + 1}"
            current_lines.append(line)
        if current_lines:
            pages.append({
                "page": len(pages) + 1,
                "title": current_title,
                "kind": "markdown-section",
                "text": "\n".join(current_lines).strip(),
            })
        return pages if pages else [{"page": 1, "title": "Markdown", "kind": "markdown", "text": text}]

    def _extract_text_from_code(self, file_path: Path) -> List[dict]:
        """Extract text from code files."""
        text = file_path.read_text(encoding="utf-8", errors="replace")
        lines = text.split('\n')
        pages = []
        chunk = 200  # lines per page
        for i in range(0, len(lines), chunk):
            pages.append({
                "page": len(pages) + 1,
                "title": f"Lines {i + 1}-{min(i + chunk, len(lines))}",
                "kind": "code",
                "text": '\n'.join(lines[i:i+chunk])
            })
        return pages if pages else [{"page": 1, "title": "Code", "kind": "code", "text": text}]

    def _extract_text_from_csv(self, file_path: Path) -> List[dict]:
        """Extract text from CSV/TSV as structured table pages."""
        delimiter = "\t" if file_path.suffix.lower() == ".tsv" else ","
        try:
            with file_path.open("r", encoding="utf-8", errors="replace", newline="") as handle:
                reader = csv.reader(handle, delimiter=delimiter)
                rows = []
                for row in reader:
                    cells = [cell.strip() for cell in row if cell and cell.strip()]
                    if cells:
                        rows.append(" | ".join(cells))
                    if len(rows) >= 500:
                        rows.append("... (table truncated)")
                        break
        except Exception:
            return self._extract_text_from_txt(file_path)
        return [{
            "page": 1,
            "title": file_path.name,
            "kind": "table",
            "text": "\n".join(rows),
        }]

    def _extract_text_from_html(self, file_path: Path) -> List[dict]:
        """Extract text from HTML while preserving heading-like structure."""
        raw = file_path.read_text(encoding="utf-8", errors="replace")
        text = re.sub(r"(?is)<(script|style).*?>.*?</\1>", " ", raw)
        text = re.sub(r"(?is)<br\s*/?>", "\n", text)
        text = re.sub(r"(?is)</(p|div|li|tr|h[1-6])>", "\n", text)
        text = re.sub(r"(?is)<[^>]+>", " ", text)
        text = html_unescape(re.sub(r"[ \t]+", " ", text))
        lines = [line.strip() for line in text.splitlines() if line.strip()]
        return [{
            "page": 1,
            "title": file_path.name,
            "kind": "html",
            "text": "\n".join(lines),
        }]

    def _extract_text_from_docx(self, file_path: Path) -> List[dict]:
        """Extract text from a Word (.docx) file with heading-aware sections."""
        if not HAS_DOCX:
            # DOCX is a ZIP of WordprocessingML. Keep resume/profile import
            # functional in lean packaged builds where python-docx is absent.
            try:
                with zipfile.ZipFile(file_path) as archive:
                    member_names = [
                        name for name in archive.namelist()
                        if name == "word/document.xml"
                        or re.fullmatch(r"word/(?:header|footer)\d+\.xml", name)
                    ]
                    member_names.sort(key=lambda name: (name != "word/document.xml", name))
                    lines: List[str] = []
                    word_ns = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
                    for member_name in member_names:
                        root = ET.fromstring(archive.read(member_name))
                        for paragraph in root.iter(f"{word_ns}p"):
                            fragments = [
                                node.text or ""
                                for node in paragraph.iter(f"{word_ns}t")
                            ]
                            text = "".join(fragments).strip()
                            if text:
                                lines.append(text)
            except (OSError, zipfile.BadZipFile, ET.ParseError, KeyError) as exc:
                raise HTTPException(
                    415,
                    f"'{file_path.name}' could not be opened as a .docx file ({exc})."
                ) from exc
            if not lines:
                raise HTTPException(
                    422,
                    f"'{file_path.name}' has no extractable Word document text."
                )
            return [{
                "page": 1,
                "title": "Word document",
                "kind": "docx-section",
                "text": "\n".join(lines),
            }]
        try:
            document = _docx_lib.Document(str(file_path))
        except Exception as e:
            raise HTTPException(
                415,
                f"'{file_path.name}' could not be opened as a .docx file ({e}). "
                "If this is an older .doc (not .docx) file, re-save it as .docx "
                "in Word and re-attach."
            ) from e
        sections: List[dict] = []
        current_title = "Document"
        current_lines: List[str] = []

        def flush_section():
            nonlocal current_lines
            content = "\n".join(line for line in current_lines if line.strip()).strip()
            if content:
                sections.append({
                    "page": len(sections) + 1,
                    "title": current_title,
                    "kind": "docx-section",
                    "text": content,
                })
            current_lines = []

        for paragraph in document.paragraphs:
            text = paragraph.text.strip()
            if not text:
                continue
            style_name = getattr(getattr(paragraph, "style", None), "name", "") or ""
            if style_name.lower().startswith("heading"):
                flush_section()
                current_title = text
                current_lines.append(text)
                continue
            current_lines.append(text)

        for table_index, table in enumerate(document.tables, start=1):
            rows = []
            for row in table.rows:
                row_values = [cell.text.strip() for cell in row.cells if cell.text.strip()]
                if row_values:
                    rows.append(" | ".join(row_values))
            if rows:
                if current_lines:
                    current_lines.append("")
                current_lines.append(f"[Table {table_index}]")
                current_lines.extend(rows)

        flush_section()
        if not sections:
            raise HTTPException(
                422,
                f"'{file_path.name}' has no extractable text in its body paragraphs "
                "or tables - its content may be in text boxes, headers/footers, or "
                "embedded images, which aren't extracted."
            )
        return sections

    def _extract_text_from_xlsx(self, file_path: Path) -> List[dict]:
        """Extract text from an Excel (.xlsx/.xlsm) file, one 'page' per sheet."""
        if not HAS_OPENPYXL:
            raise HTTPException(
                500,
                "No .xlsx library available. Install openpyxl: pip install openpyxl"
            )
        try:
            wb = openpyxl.load_workbook(str(file_path), data_only=True, read_only=True)
        except Exception as e:
            raise HTTPException(
                415,
                f"'{file_path.name}' could not be opened as an Excel file ({e}). "
                "If this is an older .xls file, re-save it as .xlsx and re-attach."
            ) from e
        pages = []
        for sheet in wb.worksheets:
            lines = []
            for row in sheet.iter_rows(values_only=True):
                cells = [str(c) for c in row if c is not None]
                if cells:
                    lines.append(" | ".join(cells))
                if len(lines) >= 500:  # cap per-sheet rows to stay sane
                    lines.append("... (sheet truncated)")
                    break
            pages.append({
                "page": len(pages) + 1,
                "title": sheet.title,
                "kind": "sheet",
                "text": f"[Sheet: {sheet.title}]\n" + "\n".join(lines),
            })
        return pages if pages else [{"page": 1, "title": "Workbook", "kind": "sheet", "text": ""}]

    def _extract_text_from_pptx(self, file_path: Path) -> List[dict]:
        """Extract text from a PowerPoint (.pptx) file, one 'page' per slide."""
        if not HAS_PPTX:
            raise HTTPException(
                500,
                "No .pptx library available. Install python-pptx: pip install python-pptx"
            )
        try:
            prs = Presentation(str(file_path))
        except Exception as e:
            raise HTTPException(
                415,
                f"'{file_path.name}' could not be opened as a PowerPoint file ({e})."
            ) from e
        pages = []
        for i, slide in enumerate(prs.slides):
            lines = []
            for shape in slide.shapes:
                if getattr(shape, "has_text_frame", False) and shape.text_frame is not None:
                    text = shape.text_frame.text.strip()
                    if text:
                        lines.append(text)
                if getattr(shape, "has_table", False):
                    for row in shape.table.rows:
                        row_text = " | ".join(cell.text.strip() for cell in row.cells if cell.text.strip())
                        if row_text:
                            lines.append(row_text)
            pages.append({
                "page": i + 1,
                "title": f"Slide {i + 1}",
                "kind": "slide",
                "text": "\n".join(lines),
            })
        return pages if pages else [{"page": 1, "title": "Slides", "kind": "slide", "text": ""}]

    @staticmethod
    def _extract_text_unsupported_binary(file_path: Path) -> List[dict]:
        """OpenDocument (.odt/.ods/.odp) and other binary formats we don't have
        a parser for. Raise clearly instead of reading the raw zip/binary bytes
        as 'text' and handing the model garbage that looks like real content."""
        raise HTTPException(
            415,
            f"'{file_path.suffix}' files aren't supported for text extraction yet. "
            "Try converting to .docx/.xlsx/.pptx/.pdf/.txt first."
        )

    def _extract_pages(self, file_path: Path, file_type: str) -> List[dict]:
        """Extract pages based on file type."""
        extractors = {
            "pdf": self._extract_text_from_pdf,
            "txt": self._extract_text_from_txt,
            "md": self._extract_text_from_md,
            "markdown": self._extract_text_from_md,
            "py": self._extract_text_from_code,
            "js": self._extract_text_from_code,
            "ts": self._extract_text_from_code,
            "json": self._extract_text_from_code,
            "csv": self._extract_text_from_csv,
            "tsv": self._extract_text_from_csv,
            "html": self._extract_text_from_html,
            "xml": self._extract_text_from_code,
            "java": self._extract_text_from_code,
            "cpp": self._extract_text_from_code,
            "c": self._extract_text_from_code,
            "h": self._extract_text_from_code,
            "rs": self._extract_text_from_code,
            "go": self._extract_text_from_code,
            "rb": self._extract_text_from_code,
            "php": self._extract_text_from_code,
            "sh": self._extract_text_from_code,
            "bat": self._extract_text_from_code,
            "ps1": self._extract_text_from_code,
            "sql": self._extract_text_from_code,
            "yaml": self._extract_text_from_code,
            "yml": self._extract_text_from_code,
            "toml": self._extract_text_from_code,
            "ini": self._extract_text_from_code,
            "cfg": self._extract_text_from_code,
            "log": self._extract_text_from_txt,
            "rtf": self._extract_text_from_txt,
            "docx": self._extract_text_from_docx,
            "doc": self._extract_text_from_docx,  # best-effort; true .doc needs antiword/textract
            "xlsx": self._extract_text_from_xlsx,
            "xlsm": self._extract_text_from_xlsx,
            "xls": self._extract_text_from_xlsx,
            "pptx": self._extract_text_from_pptx,
            "odt": self._extract_text_unsupported_binary,
            "ods": self._extract_text_unsupported_binary,
            "odp": self._extract_text_unsupported_binary,
        }
        extractor = extractors.get(file_type, self._extract_text_from_txt)
        try:
            return extractor(file_path)
        except HTTPException:
            raise
        except Exception as e:
            logger.error(f"Unexpected error extracting '{file_path.name}' as {file_type}: {e}\n{traceback.format_exc()}")
            raise HTTPException(
                500,
                f"Unexpected error while reading '{file_path.name}': {e}"
            ) from e

    def _build_preview_sections(self, pages: List[dict], max_sections: int = 30) -> List[AttachmentPreviewSection]:
        sections: List[AttachmentPreviewSection] = []
        for page in pages[:max_sections]:
            text = str(page.get("text", "") or "").strip()
            if not text:
                continue
            sections.append(AttachmentPreviewSection(
                page=int(page.get("page", len(sections) + 1) or len(sections) + 1),
                title=self._normalize_preview_title(page, f"Page {len(sections) + 1}"),
                kind=str(page.get("kind", "text") or "text"),
                text=text,
            ))
        return sections

    def build_attachment_preview(self, file_path: Path, file_type: str, file_name: str, size_bytes: int = 0) -> AttachmentPreviewResponse:
        lowered_type = file_type.lower()
        if lowered_type.startswith("image/") or file_path.suffix.lower().lstrip(".") in self._IMAGE_ATTACHMENT_EXTENSIONS:
            return AttachmentPreviewResponse(
                name=file_name,
                file_type=file_type or "image/*",
                size_bytes=size_bytes,
                page_count=1,
                preview_mode="image",
                summary="Image attachment preview",
                sections=[],
                notes=[],
            )
        pages = self._extract_pages(file_path, file_type)
        sections = self._build_preview_sections(pages)
        summary_parts = [f"{len(sections)} section(s)"]
        if any(section.kind == "sheet" for section in sections):
            summary_parts.append("spreadsheet layout preserved")
        if any(section.kind in {"docx-section", "markdown-section"} for section in sections):
            summary_parts.append("section headings preserved")
        if file_type.lower() == "pdf":
            summary_parts.append("pdf pages preserved")
        summary = " â€¢ ".join(summary_parts) if summary_parts else "Preview generated"
        return AttachmentPreviewResponse(
            name=file_name,
            file_type=file_type or "text/plain",
            size_bytes=size_bytes,
            page_count=len(pages),
            # Keep document rendering inside the app. The Electron PDF iframe
            # is blank in some packaged runtimes, while the extracted section
            # view works consistently for PDF, Word, spreadsheets, slides, and
            # text-based documents.
            preview_mode="image" if file_type.lower().startswith("image/") else "structured",
            summary=summary,
            sections=sections,
            notes=[],
        )

    async def _index_with_pageindex(self, doc_id: str, file_path: Path, file_type: str) -> Optional[str]:
        if not self._pageindex_client or not self._is_pageindex_supported(file_type):
            return None
        try:
            response = self._pageindex_client.submit_document(str(file_path))
            pageindex_doc_id = str(response.get("doc_id") or response.get("document_id") or "").strip()
            if not pageindex_doc_id:
                return None
            tree: dict = {}
            try:
                tree = self._pageindex_client.get_tree(pageindex_doc_id, node_summary=True)
            except Exception as e:
                logger.warning(f"PageIndex tree fetch failed for {doc_id}: {e}")
            self._save_pageindex_cache(doc_id, {
                "pageindex_doc_id": pageindex_doc_id,
                "file_type": file_type,
                "tree": tree,
                "indexed_at": datetime.now(timezone.utc).isoformat(),
            })
            return pageindex_doc_id
        except Exception as e:
            logger.warning(f"PageIndex indexing skipped for {file_path.name}: {e}")
            return None

    async def _query_pageindex(self, doc_info: RAGDocumentInfo, query: str) -> List[RAGQueryResult]:
        cache = self._load_pageindex_cache(doc_info.id)
        pageindex_doc_id = str(cache.get("pageindex_doc_id") or "").strip()
        if not pageindex_doc_id or not self._pageindex_client:
            return []
        try:
            submit = self._pageindex_client.submit_query(pageindex_doc_id, query, thinking=True)
            retrieval_id = str(submit.get("retrieval_id") or submit.get("id") or "").strip()
            if not retrieval_id:
                return []
            deadline = time.monotonic() + 30.0
            payload: dict = {}
            while time.monotonic() < deadline:
                payload = self._pageindex_client.get_retrieval(retrieval_id)
                if str(payload.get("status", "")).lower() == "completed":
                    break
                await asyncio.sleep(0.75)
            results: List[RAGQueryResult] = []
            for node in payload.get("retrieved_nodes", []) or []:
                node_title = str(node.get("title") or node.get("node_title") or "PageIndex node").strip()
                relevant_contents = node.get("relevant_contents") or []
                if isinstance(relevant_contents, dict):
                    relevant_contents = [relevant_contents]
                for content in relevant_contents:
                    if not isinstance(content, dict):
                        continue
                    page_number = int(content.get("page_index") or content.get("page_number") or 1)
                    snippet = str(content.get("relevant_content") or content.get("content") or content.get("text") or "").strip()
                    if not snippet:
                        continue
                    score = content.get("score")
                    try:
                        score_value = float(score) if score is not None else 1.0
                    except Exception:
                        score_value = 1.0
                    results.append(RAGQueryResult(
                        page_number=page_number,
                        chunk_index=len(results),
                        text=f"{node_title}\n{snippet}".strip(),
                        score=round(score_value, 4),
                        document_id=doc_info.id,
                        document_name=doc_info.filename,
                    ))
            return results
        except Exception as e:
            logger.warning(f"PageIndex retrieval failed for {doc_info.filename}: {e}")
            return []

    def _chunk_text(self, text: str, chunk_size: int, overlap: int) -> List[str]:
        """Split text into coherent overlapping chunks, preferring paragraph boundaries."""
        if not text.strip():
            return []
        paragraphs = [p.strip() for p in re.split(r"\n\s*\n+", text) if p.strip()]
        if not paragraphs:
            return []
        chunks: List[str] = []
        current: List[str] = []
        current_words = 0
        for para in paragraphs:
            pw = len(para.split())
            if current and current_words + pw > chunk_size:
                chunks.append("\n\n".join(current).strip())
                tail_words = " ".join(current).split()[-max(0, overlap):]
                current = [" ".join(tail_words)] if tail_words else []
                current_words = len(tail_words)
            if pw > chunk_size:
                words = para.split()
                start = 0
                while start < len(words):
                    end = min(start + chunk_size, len(words))
                    piece = " ".join(words[start:end]).strip()
                    if piece:
                        chunks.append(piece)
                    if end >= len(words):
                        break
                    start = max(end - overlap, start + 1)
                current=[]; current_words=0
            else:
                current.append(para); current_words += pw
        if current:
            piece="\n\n".join(current).strip()
            if piece: chunks.append(piece)
        return chunks

    @staticmethod
    def _rag_tokens(text: str) -> List[str]:
        return re.findall(r"[a-z0-9][a-z0-9_\-]{1,}", str(text or "").lower())

    @classmethod
    def _lexical_score(cls, query: str, text: str) -> float:
        q = set(cls._rag_tokens(query))
        if not q:
            return 0.0
        t = cls._rag_tokens(text)
        if not t:
            return 0.0
        tf = {}
        for tok in t: tf[tok] = tf.get(tok, 0) + 1
        matched = sum(1 for tok in q if tok in tf)
        weighted = sum(min(tf.get(tok, 0), 4) for tok in q)
        return min(1.0, (matched / max(1, len(q))) * 0.65 + (weighted / max(1, len(q)*2)) * 0.35)

    @staticmethod
    def _is_broad_document_query(query: str) -> bool:
        q = str(query or "").lower()
        return bool(re.search(r"\b(explain|summari[sz]e|overview|what(?:'s| is) in|describe|analy[sz]e)\b", q))

    async def _hybrid_rank_chunks(self, chunks: List[dict], query: str, limit: int = RETRIEVAL_RETURN) -> List[dict]:
        """Dense + lexical retrieval with document coverage and neighbor expansion."""
        if not chunks or not query.strip():
            return []
        qemb = await self._get_embedding(query)
        scored=[]
        broad=self._is_broad_document_query(query)
        for idx, chunk in enumerate(chunks):
            emb=chunk.get("embedding")
            if isinstance(emb,str):
                try: emb=json.loads(emb)
                except Exception: emb=None
            if not emb:
                emb=self._fallback_embedding(chunk.get("text", ""))
            dense=self._cosine_similarity(qemb, emb)
            lexical=self._lexical_score(query, chunk.get("text", ""))
            score=0.72*dense+0.28*lexical
            if broad:
                # Broad requests need coverage, not only the most semantically
                # similar paragraph. Give unseen pages/sections a modest bonus.
                score += 0.035 / max(1, idx+1)
            scored.append((score, idx, chunk))
        scored.sort(key=lambda x:x[0], reverse=True)
        selected=[]; selected_idx=set(); pages=set()
        for score,idx,ch in scored[:self.RETRIEVAL_CANDIDATES]:
            page=ch.get("page_number")
            bonus=0.0 if page in pages else 0.02
            ch2=dict(ch); ch2["_rag_score"]=score+bonus
            selected.append(ch2); selected_idx.add(idx); pages.add(page)
        selected.sort(key=lambda x:x.get("_rag_score",0), reverse=True)
        # Expand immediate neighbors so answers do not lose definitions/examples
        # that happen to straddle a chunk boundary.
        by_key={(c.get("page_number"),c.get("chunk_index")):i for i,c in enumerate(chunks)}
        expanded=[]
        for ch in selected[:limit]:
            expanded.append(ch)
            key=(ch.get("page_number"),ch.get("chunk_index"))
            for delta in (-1,1):
                pos=by_key.get((key[0], (key[1] or 0)+delta))
                if pos is not None and chunks[pos] not in expanded:
                    expanded.append(chunks[pos])
        return expanded

    def _compress_context(self, candidates: List[dict], query: str, max_chars: int = CONTEXT_TARGET_CHARS) -> str:
        """Sentence-level extractive compression; deterministic, fast, no LLM call."""
        if not candidates: return ""
        q=set(self._rag_tokens(query))
        sentences=[]
        seen=set()
        for rank,ch in enumerate(candidates):
            text=str(ch.get("text") or "").strip()
            for sent in re.split(r"(?<=[.!?])\s+|\n+", text):
                sent=re.sub(r"\s+", " ", sent).strip()
                if len(sent)<35: continue
                key=sent.lower()
                if key in seen: continue
                seen.add(key)
                toks=set(self._rag_tokens(sent))
                overlap=len(q & toks)/max(1,len(q)) if q else 0.0
                score=0.70*overlap + 0.30*(1.0/(1+rank))
                sentences.append((score, ch.get("page_number",0), sent))
        # Keep orientation from the first source plus high-value sentences.
        sentences.sort(key=lambda x:x[0], reverse=True)
        chosen=[]; used_chars=0; pages=set()
        for score,page,sent in sentences:
            extra=len(sent)+16
            if used_chars+extra>max_chars: continue
            if page in pages and score<0.12: continue
            chosen.append((page,sent)); pages.add(page); used_chars+=extra
            if used_chars>=max_chars*0.94: break
        chosen.sort(key=lambda x:x[0])
        parts=[f"[Page {page}] {sent}" for page,sent in chosen]
        return "\n".join(parts)[:self.CONTEXT_HARD_LIMIT_CHARS]

    async def _get_embedding(self, text: str) -> List[float]:
        """Generate embedding for text using available model."""
        config = self.persistence.config
        cache_key = hashlib.md5(text.encode()).hexdigest()

        if cache_key in self._embeddings_cache:
            return self._embeddings_cache[cache_key]

        # Try cloud embedding
        if config.inference.mode == InferenceMode.CLOUD and self.cloud_engine:
            provider = config.inference.default_cloud_provider
            if provider and provider in self.persistence.config.cloud_providers:
                conn = self.persistence.config.cloud_providers[provider]
                info = CLOUD_PROVIDERS.get(provider, {})
                base_url = (
                    conn.base_url
                    if provider == "generic_openai" and conn.base_url
                    else info.get("base_url", "")
                )
                api_key = conn.api_key

                # Try provider's embedding endpoint
                embed_url = f"{base_url}/embeddings"
                headers = {"Content-Type": "application/json"}
                auth_header = info.get("auth_header", "Authorization")
                auth_prefix = info.get("auth_prefix", "Bearer ")
                if api_key:
                    headers[auth_header] = f"{auth_prefix}{api_key}"

                async with httpx.AsyncClient(timeout=30) as client:
                    try:
                        embed_model = "text-embedding-004" if provider in ("gemini", "google") else "text-embedding-3-small"
                        resp = await client.post(embed_url, headers=headers, json={
                            "model": embed_model,
                            "input": text[:8000],
                        })
                        if resp.status_code == 200:
                            data = resp.json()
                            embedding = data["data"][0]["embedding"]
                            self._embeddings_cache[cache_key] = embedding
                            return embedding
                    except Exception:
                        pass

        # Try local embedding via LM Studio / Ollama
        for prov_id, prov_conf in config.local_providers.items():
            if not prov_conf.enabled:
                continue
            info = LOCAL_PROVIDERS.get(prov_id, {})
            base_url = prov_conf.base_url

            try:
                if prov_id == "ollama":
                    embed_url = f"{base_url}/api/embeddings"
                    async with httpx.AsyncClient(timeout=30) as client:
                        resp = await client.post(embed_url, json={
                            "model": "nomic-embed-text",
                            "prompt": text[:8000],
                        })
                        if resp.status_code == 200:
                            data = resp.json()
                            embedding = data.get("embedding", [])
                            if embedding:
                                self._embeddings_cache[cache_key] = embedding
                                return embedding
                else:
                    embed_url = f"{base_url}/v1/embeddings"
                    async with httpx.AsyncClient(timeout=30) as client:
                        resp = await client.post(embed_url, json={
                            "model": "text-embedding",
                            "input": text[:8000],
                        })
                        if resp.status_code == 200:
                            data = resp.json()
                            embedding = data["data"][0]["embedding"]
                            self._embeddings_cache[cache_key] = embedding
                            return embedding
            except Exception:
                continue

        # Fallback: simple TF-IDF-like embedding (deterministic hash-based)
        return self._fallback_embedding(text)

    def _fallback_embedding(self, text: str, dim: int = 384) -> List[float]:
        """Generate a deterministic pseudo-embedding when no model is available."""
        words = text.lower().split()[:100]
        vec = [0.0] * dim
        for i, word in enumerate(words):
            h = int(hashlib.md5(word.encode()).hexdigest(), 16)
            for j in range(min(8, dim)):
                idx = (h + j * 37) % dim
                vec[idx] += 1.0 / (i + 1)
        norm = math.sqrt(sum(x * x for x in vec))
        if norm > 0:
            vec = [x / norm for x in vec]
        return vec

    @staticmethod
    def _cosine_similarity(a: List[float], b: List[float]) -> float:
        """Compute cosine similarity between two vectors."""
        if not a or not b or len(a) != len(b):
            return 0.0
        if HAS_NUMPY:
            a_arr = np.array(a, dtype=np.float32)
            b_arr = np.array(b, dtype=np.float32)
            norm_a = np.linalg.norm(a_arr)
            norm_b = np.linalg.norm(b_arr)
            if norm_a == 0 or norm_b == 0:
                return 0.0
            return float(np.dot(a_arr, b_arr) / (norm_a * norm_b))
        else:
            dot = sum(x * y for x, y in zip(a, b))
            norm_a = math.sqrt(sum(x * x for x in a))
            norm_b = math.sqrt(sum(x * x for x in b))
            if norm_a == 0 or norm_b == 0:
                return 0.0
            return dot / (norm_a * norm_b)

    async def index_document(self, doc_id: str, progress_callback=None):
        """Index a document once, with visible pipeline stages and concurrent embeddings."""
        if self._indexing:
            raise HTTPException(409, "Indexing already in progress")
        docs=self.persistence.list_rag_documents()
        doc_info=next((d for d in docs if d.id==doc_id),None)
        if not doc_info: raise HTTPException(404,f"Document '{doc_id}' not found")
        self._indexing=True; self._index_progress=0.0; self._index_current_file=doc_info.filename
        def stage(label,pct,detail=None):
            self._index_progress=pct/100.0
            if progress_callback:
                try: progress_callback(label,pct,detail)
                except Exception: pass
        try:
            file_path=Path(doc_info.file_path) if getattr(doc_info,'file_path',None) else None
            if not file_path or not file_path.exists():
                matching=list(DOCUMENTS_DIR.glob(f"{doc_id}.*"))
                if matching: file_path=matching[0]
                else: raise HTTPException(404,f"File for document '{doc_id}' not found")
            stage("Extracting document",5,f"{doc_info.filename} · {doc_info.size_bytes/1024:.0f} KiB")
            pages=self._extract_pages(file_path,doc_info.file_type)
            total_pages=max(1,len(pages))
            stage("Building page map",15,f"{total_pages} page(s)")
            await self._index_with_pageindex(doc_id,file_path,doc_info.file_type)
            config=self.persistence.config
            large=doc_info.size_bytes>=self.LARGE_FILE_BYTES
            chunk_size=self.LARGE_CHUNK_WORDS if large else min(int(config.rag_chunk_size),650)
            overlap=self.LARGE_CHUNK_OVERLAP if large else min(int(config.rag_chunk_overlap),80)
            stage("Chunking document",25,f"{chunk_size}-word windows · {overlap}-word overlap")
            all_chunks=[]
            for i,page in enumerate(pages):
                title=str(page.get('title') or '').strip()
                text=str(page.get('text') or '').strip()
                if title: text=f"{title}\n{text}".strip()
                chunks=self._chunk_text(text,chunk_size,overlap)
                for j,ch in enumerate(chunks): all_chunks.append((page.get('page',i+1),j,ch))
            self.persistence.store_chunks(doc_id,all_chunks)
            stage("Embedding chunks",45,f"{len(all_chunks)} chunks · concurrent batches")
            records=self.persistence.get_chunks_by_document(doc_id)
            missing=[r for r in records if not r.get('embedding')]
            sem=asyncio.Semaphore(8)
            async def one(rec):
                async with sem:
                    return rec['id'], await self._get_embedding(rec['text'])
            done=0
            for batch_start in range(0,len(missing),32):
                batch=missing[batch_start:batch_start+32]
                pairs=await asyncio.gather(*(one(r) for r in batch),return_exceptions=True)
                for pair in pairs:
                    if isinstance(pair,Exception):
                        logger.warning("Embedding batch item failed: %s",pair); continue
                    cid,emb=pair
                    self.persistence.add_embedding_to_batch(cid,json.dumps(emb))
                    done+=1
                self.persistence.flush_embedding_batch()
                stage("Embedding chunks",45+int(35*done/max(1,len(missing))),f"{done}/{len(missing)} embedded")
            stage("Index ready",85,f"{len(records)} searchable chunks")
            self.persistence.update_rag_document_indexed(doc_id,total_pages,len(all_chunks))
            stage("Index complete",100,f"{total_pages} pages · {len(all_chunks)} chunks")
            logger.info("Indexed '%s': %s pages, %s chunks (large=%s)",doc_info.filename,total_pages,len(all_chunks),large)
        finally:
            self._indexing=False; self._index_progress=0.0; self._index_current_file=""

    async def index_all(self):
        """Index all unindexed documents."""
        docs = self.persistence.list_rag_documents()
        unindexed = [d for d in docs if not d.indexed]
        for doc in unindexed:
            await self.index_document(doc.id)

    async def search(self, query: str, top_k: int = 5) -> List[RAGQueryResult]:
        """Search indexed documents for relevant chunks."""
        exec_mgr = None  # We disable execution manager tracing here to avoid emitting empty search steps
        
        if not query.strip():
            return []

        results: List[RAGQueryResult] = []
        seen: Set[Tuple[str, int, str]] = set()

        if exec_mgr:
            exec_mgr.child(rag_id, f"{rag_id}_pageindex", "Searching Cloud Integrations")

        docs = self.persistence.list_rag_documents()
        pageindex_docs = 0
        for doc_info in docs:
            cache = self._load_pageindex_cache(doc_info.id)
            if cache.get("pageindex_doc_id") and self._is_pageindex_supported(doc_info.file_type):
                pageindex_docs += 1
                if pageindex_docs > 5:
                    break
                pageindex_results = await self._query_pageindex(doc_info, query)
                for item in pageindex_results:
                    key = (item.document_id, item.page_number, item.text)
                    if key in seen:
                        continue
                    seen.add(key)
                    results.append(item)
                    
        if exec_mgr:
            exec_mgr.complete(f"{rag_id}_pageindex", "Cloud Search Complete")

        if len(results) < top_k:
            if exec_mgr:
                exec_mgr.child(rag_id, f"{rag_id}_embed", "Embedding Query")
            query_embedding = await self._get_embedding(query)
            if exec_mgr:
                exec_mgr.complete(f"{rag_id}_embed", "Query Embedded")
                
            all_chunks = self.persistence.get_all_chunks_for_search()
            if all_chunks:
                if exec_mgr:
                    exec_mgr.child(rag_id, f"{rag_id}_scan", "Finding Relevant Documents")
                scored = []
                for chunk in all_chunks:
                    emb_str = chunk.get("embedding")
                    if emb_str:
                        try:
                            chunk_emb = json.loads(emb_str)
                        except Exception:
                            chunk_emb = self._fallback_embedding(chunk.get("text", ""))
                    else:
                        chunk_emb = self._fallback_embedding(chunk.get("text", ""))
                    score = self._cosine_similarity(query_embedding, chunk_emb)
                    scored.append((score, chunk))

                if exec_mgr:
                    exec_mgr.complete(f"{rag_id}_scan", f"Scanned {len(all_chunks)} chunks")
                    exec_mgr.child(rag_id, f"{rag_id}_rank", "Ranking Documents")
                    
                scored.sort(key=lambda x: x[0], reverse=True)
                for score, chunk in scored:
                    item = RAGQueryResult(
                        page_number=chunk["page_number"],
                        chunk_index=chunk["chunk_index"],
                        text=chunk["text"],
                        score=round(score, 4),
                        document_id=chunk["document_id"],
                        document_name=chunk["filename"],
                    )
                    key = (item.document_id, item.page_number, item.text)
                    if key in seen:
                        continue
                    seen.add(key)
                    results.append(item)
                    if len(results) >= top_k:
                        break
                        
                if exec_mgr:
                    exec_mgr.complete(f"{rag_id}_rank", "Ranking Complete")

        results.sort(key=lambda item: item.score, reverse=True)
        results = results[:top_k]
        
        if exec_mgr:
            if not results:
                exec_mgr.cancel(rag_id, "No relevant contexts found")
            else:
                docs_preview = "; ".join(
                    dict.fromkeys(r.document_name for r in results[:3] if r.document_name)
                )
                context_summary = f"Found {len(results)} contexts"
                if docs_preview:
                    context_summary += f" in {docs_preview}"
                    if len(results) > 3:
                        context_summary += ", ..."
                exec_mgr.complete(rag_id, context_summary)
            
        return results

    def build_context(self, results: List[RAGQueryResult]) -> str:
        """Build RAG context string from search results."""
        if not results:
            return ""
        parts = []
        for r in results:
            parts.append(
                f"[Document: {r.document_name}, Page {r.page_number} "
                f"(relevance: {r.score:.2f})]\n{r.text}"
            )
        return "\n\n---\n\n".join(parts)


# ==================================================
# SECTION 10: IMAGE SEARCH SERVICE
# ==================================================

# Sentinel separating structured (JSON-LD) data -- Recipe, HowTo, FAQPage,
# JobPosting, Product, or any other schema.org type this module knows how
# to parse -- from the loose prose extracted from a page. Used by
# ImageSearchService so downstream truncation (web_summary) can keep the
# structured part whole and only trim the prose that follows it.
_STRUCTURED_DATA_MARKER = "\n\n--- Full page text ---\n\n"


class ImageSearchService:
    """
    Web image search service.
    Supports multiple backends: DuckDuckGo (free), Google, Bing, Unsplash, Pexels.
    """

    def __init__(self, persistence: PersistenceManager):
        self.persistence = persistence
        self._client: Optional[httpx.AsyncClient] = None

    async def _get_client(self) -> httpx.AsyncClient:
        if self._client is None:
            self._client = httpx.AsyncClient(
                timeout=httpx.Timeout(15.0),
                follow_redirects=True,
                headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"}
            )
        return self._client

    @staticmethod
    def _enhance_wallpaper_query(query: str) -> str:
        """Transform a vague or short wallpaper query into a precise,
        high-quality image search query that returns relevant wallpapers."""
        q = query.strip().lower()
        # Already specific enough - don't over-modify
        wallpaper_indicators = [
            "wallpaper", "background", "desktop", "phone wallpaper",
            "lock screen", "home screen", "4k wallpaper", "hd wallpaper",
            "ultrawide wallpaper", "iphone wallpaper", "android wallpaper",
            "mac wallpaper", "pc wallpaper", "iPad wallpaper",
        ]
        is_wallpaper_query = any(ind in q for ind in wallpaper_indicators)

        if is_wallpaper_query:
            # Query already mentions wallpaper - just ensure quality modifiers
            if not any(w in q for w in ["4k", "hd", "high resolution", "high quality", "ultra hd", "uhd"]):
                q = f"{q} 4k high quality"
            return q.strip()

        # No wallpaper keyword detected - the user typed something like
        # "mountains" or "dark aesthetic" meaning they want a wallpaper of it.
        # Build a proper wallpaper search query.
        quality_suffix = "4k wallpaper desktop high quality"

        # Detect common themes and add descriptive boosters
        theme_boosters = {
            "dark": "dark moody aesthetic",
            "light": "light bright clean minimal",
            "nature": "nature landscape scenic beautiful",
            "ocean": "ocean sea waves beach scenic",
            "forest": "forest trees green peaceful",
            "mountain": "mountain peaks landscape dramatic",
            "space": "space galaxy stars nebula cosmic",
            "city": "city skyline urban night lights",
            "night": "night sky stars dark",
            "sunset": "sunset golden hour warm",
            "sunrise": "sunrise dawn morning light",
            "rain": "rain moody cozy aesthetic",
            "snow": "snow winter frost cold",
            "abstract": "abstract art colorful modern",
            "minimal": "minimal clean simple elegant",
            "anime": "anime art style beautiful",
            "car": "car automotive luxury sport",
            "aesthetic": "aesthetic vibes mood",
        }

        boosted = q
        for keyword, booster in theme_boosters.items():
            if keyword in q:
                boosted = f"{booster} {q}"
                break

        return f"{boosted} {quality_suffix}".strip()

    async def search(self, query: str, max_results: int = 3,
                     backend: Optional[str] = None,
                     safe_search: bool = True) -> ImageSearchResponse:
        config = self.persistence.config.image_search
        be = backend or config.backend

        # Auto-detect wallpaper queries and enhance them for accuracy
        enhanced_query = self._enhance_wallpaper_query(query)
        use_enhanced = (enhanced_query.lower() != query.strip().lower())
        if use_enhanced:
            logger.info(f"Wallpaper query enhanced: '{query}' â†’ '{enhanced_query}'")

        # Use enhanced query for all backends when wallpaper detected
        search_query = enhanced_query if use_enhanced else query

        # Standard search flow - all backends now receive the (possibly
        # enhanced) query, so wallpaper searches are accurate everywhere.
        if be == "duckduckgo":
            images = await self._search_duckduckgo(search_query, max_results, safe_search)
        elif be == "unsplash":
            images = await self._search_unsplash(search_query, max_results, config.api_key)
        elif be == "pexels":
            images = await self._search_pexels(search_query, max_results, config.api_key)
        elif be == "google":
            images = await self._search_google(search_query, max_results, config.api_key, safe_search)
        elif be == "bing":
            images = await self._search_bing(search_query, max_results, config.api_key, safe_search)
        else:
            images = await self._search_duckduckgo(search_query, max_results, safe_search)

        # Build markdown
        md_parts = []
        for img in images:
            md_parts.append(f"![{img.title or query}]({img.url})")
        markdown = "\n".join(md_parts)

        return ImageSearchResponse(
            query=query,
            images=images,
            markdown=markdown,
        )

    async def search_web(self, query: str, max_results: int = 5, safe_search: bool = True) -> List[dict]:
        """Search the web and return text results for grounding and tool use."""
        exec_mgr = get_exec_manager()
        search_id = f"search_{uuid.uuid4().hex[:8]}"
        engines_id = f"{search_id}_engines"
        
        if exec_mgr:
            exec_mgr.start(search_id, "Searching the Web", description=f'Query: "{query}"', tool="search")
            exec_mgr.child(search_id, engines_id, "Searching Trusted Sources")

        engines = []
        if os.environ.get("BRAVE_SEARCH_API_KEY"):
            engines.append(self._search_web_brave)
        engines.extend((
            self._search_web_ddg_html,
            self._search_web_ddg_instant,
            self._search_web_duckduckgo_lib,
            self._search_web_bing_html,
            self._search_web_startpage,
            self._search_web_mojeek,
            self._search_web_ddg_lite,
            self._search_web_wikipedia,
        ))
        accumulated_results: List[dict] = []
        seen_urls = set()
        for engine in engines:
            needed = max_results - len(accumulated_results)
            if needed <= 0:
                break
            try:
                engine_res = await engine(query, needed, safe_search)
            except Exception as e:
                logger.debug(f"search_web engine {engine.__name__} failed: {e}")
                engine_res = []
            if engine_res:
                logger.info(f"search_web: got {len(engine_res)} result(s) from {engine.__name__} for query={query!r}")
                for r in engine_res:
                    url = str(r.get("url") or "").strip()
                    if url and url not in seen_urls:
                        seen_urls.add(url)
                        accumulated_results.append(r)
                if len(accumulated_results) >= max_results:
                    break

        if accumulated_results:
            results = accumulated_results[:max_results]
            if exec_mgr:
                exec_mgr.complete(engines_id, "Extracted Information")
                titles_preview = "; ".join(
                    str(r.get("title") or r.get("url") or "").strip()
                    for r in results[:3]
                    if isinstance(r, dict) and (r.get("title") or r.get("url"))
                )
                result_summary = f"Found {len(results)} results"
                if titles_preview:
                    result_summary += f": {titles_preview}"
                    if len(results) > 3:
                        result_summary += ", ..."
                exec_mgr.complete(search_id, result_summary)
            return results
                
        if exec_mgr:
            exec_mgr.fail(engines_id, "Search Failed", "All search engines returned empty results or failed.")
            exec_mgr.fail(search_id, "Search Failed", "No results were found.")
            
        logger.warning(
            f"search_web: all engines returned no results for query={query!r}. "
            "All free engines (Wikipedia, duckduckgo_search, Mojeek, Startpage, DDG/Bing HTML) "
            "failed or were blocked from this server's IP. Set BRAVE_SEARCH_API_KEY as an "
            "environment variable for a reliable free-tier fallback (2,000 free queries/month, "
            "no credit card: https://brave.com/search/api/)."
        )
        return []

    async def search_news_feed(self, query: str, max_results: int = 8) -> List[dict]:
        """Return real current story items instead of news home/archive pages."""
        normalized = re.sub(r"\s+", " ", str(query or "")).strip()
        if not normalized:
            return []
        lowered = normalized.casefold()
        broad_news = bool(re.search(
            r"\b(?:major\s+india\s+and\s+world\s+news|general\s+news|top\s+headlines)\b",
            lowered,
        ))
        if broad_news:
            feed_url = "https://news.google.com/rss?hl=en-IN&gl=IN&ceid=IN:en"
        else:
            feed_url = (
                "https://news.google.com/rss/search?q="
                + quote_plus(normalized)
                + "&hl=en-IN&gl=IN&ceid=IN:en"
            )
        try:
            client = await self._get_client()
            response = await client.get(feed_url, timeout=httpx.Timeout(8.0))
            response.raise_for_status()
            root = ET.fromstring(response.content)
        except Exception as exc:
            logger.debug("Google News RSS lookup failed for %r: %s", normalized, exc)
            return []

        results: List[dict] = []
        seen_titles: Set[str] = set()
        for item in root.findall(".//item"):
            title = html_unescape(str(item.findtext("title") or "")).strip()
            url = html_unescape(str(item.findtext("link") or "")).strip()
            published = str(item.findtext("pubDate") or "").strip()
            source_node = item.find("source")
            source = str(source_node.text or "").strip() if source_node is not None else "Google News"
            publisher_url = (
                str(source_node.attrib.get("url") or "").strip()
                if source_node is not None
                else ""
            )
            key = re.sub(r"\s+-\s+[^-]{2,80}$", "", title).casefold()
            if not title or not url or key in seen_titles:
                continue
            seen_titles.add(key)
            # Google News descriptions contain an HTML cluster of related
            # headlines. Feeding that cluster to a small model makes it recite
            # publisher names and merge unrelated stories. The item title is
            # the precise event headline; keep that as the factual summary.
            description = re.sub(r"\s+-\s+[^-]{2,80}$", "", title).strip() or title
            if published:
                description = f"{description} Published {published}."
            results.append({
                "title": title,
                # Publisher URLs are short, stable, and keep the 2B model's
                # tiny output budget focused on speech instead of copying a
                # 500-character Google redirect token-by-token.
                "url": publisher_url if publisher_url.startswith("http") else url,
                "snippet": description,
                "source": source,
            })
            if len(results) >= max(1, min(max_results, 12)):
                break
        return results

    async def _search_web_duckduckgo_lib(self, query: str, max_results: int, safe_search: bool) -> List[dict]:
        """Uses the `duckduckgo_search` (ddgs) PyPI package, which talks to
        DDG's internal JSON backend with proper request signing instead of
        scraping HTML. It rotates through DDG's regional endpoints and is
        far less likely to be blocked from a datacenter IP than the raw
        html.duckduckgo.com scraper below. Free, no API key required."""
        try:
            from ddgs import DDGS  # modern package name
        except ImportError:
            try:
                from duckduckgo_search import DDGS  # legacy package name
            except ImportError:
                return []

        def _run() -> List[dict]:
            out: List[dict] = []
            safesearch = "moderate" if safe_search else "off"
            try:
                with DDGS() as ddgs:
                    hits = list(ddgs.text(query, safesearch=safesearch, max_results=max_results))
            except TypeError:
                # Older/newer ddgs releases have changed this signature a
                # few times; retry with just the bare essentials so a
                # version mismatch doesn't take the whole engine down.
                try:
                    with DDGS() as ddgs:
                        hits = list(ddgs.text(query, max_results=max_results))
                except Exception as e:
                    logger.debug(f"duckduckgo_search lib failed for {query!r}: {e}")
                    hits = []
            except Exception as e:
                logger.debug(f"duckduckgo_search lib failed for {query!r}: {e}")
                hits = []
            for item in hits:
                out.append({
                    "title": str(item.get("title") or query).strip(),
                    "url": str(item.get("href") or item.get("url") or "").strip(),
                    "snippet": str(item.get("body") or item.get("snippet") or "").strip(),
                    "source": "duckduckgo",
                })
            return out

        return await asyncio.to_thread(_run)

    async def _search_web_mojeek(self, query: str, max_results: int, safe_search: bool) -> List[dict]:
        """Mojeek runs its own independent index (not a Google/Bing proxy)
        and offers a plain HTML results page that, unlike DDG/Bing, does not
        aggressively block server-side/datacenter requests. Free, no key."""
        client = await self._get_client()
        results: List[dict] = []
        params = {"q": query}
        if safe_search:
            params["safe"] = "1"
        resp = await client.get("https://www.mojeek.com/search", params=params, headers=self._search_headers())
        resp.raise_for_status()
        html = resp.text
        blocks = re.split(r'<a class="ob"', html, flags=re.IGNORECASE)
        for block in blocks[1:]:
            if len(results) >= max_results:
                break
            href_match = re.search(r'href="([^"]+)"', block, flags=re.IGNORECASE)
            if not href_match:
                continue
            url = html_unescape(href_match.group(1))
            title_match = re.search(r'>(.*?)</a>', block, flags=re.IGNORECASE | re.DOTALL)
            title = re.sub(r"<[^>]+>", "", title_match.group(1)).strip() if title_match else ""
            snippet_match = re.search(r'<p class="s">(.*?)</p>', block, flags=re.IGNORECASE | re.DOTALL)
            snippet = re.sub(r"<[^>]+>", "", snippet_match.group(1)).strip() if snippet_match else ""
            if not snippet:
                continue
            results.append({
                "title": html_unescape(title) or query,
                "url": url,
                "snippet": html_unescape(snippet),
                "source": "mojeek",
            })
        return results

    async def _search_web_startpage(self, query: str, max_results: int, safe_search: bool) -> List[dict]:
        """Startpage proxies Google results via its own HTML frontend and is
        typically more tolerant of server-side requests than querying Google
        directly. Free, no key required."""
        client = await self._get_client()
        results: List[dict] = []
        params = {"query": query, "cat": "web"}
        resp = await client.post("https://www.startpage.com/sp/search", data=params, headers=self._search_headers())
        resp.raise_for_status()
        html = resp.text
        blocks = re.split(r'<div class="w-gl__result', html, flags=re.IGNORECASE)
        for block in blocks[1:]:
            if len(results) >= max_results:
                break
            link_match = re.search(r'<a[^>]+class="[^"]*w-gl__result-url[^"]*"[^>]+href="([^"]+)"', block, flags=re.IGNORECASE)
            if not link_match:
                link_match = re.search(r'href="([^"]+)"', block, flags=re.IGNORECASE)
            if not link_match:
                continue
            url = html_unescape(link_match.group(1))
            title_match = re.search(r'<h3[^>]*>(.*?)</h3>', block, flags=re.IGNORECASE | re.DOTALL)
            title = re.sub(r"<[^>]+>", "", title_match.group(1)).strip() if title_match else ""
            snippet_match = re.search(r'<p[^>]+class="[^"]*w-gl__description[^"]*"[^>]*>(.*?)</p>', block, flags=re.IGNORECASE | re.DOTALL)
            snippet = re.sub(r"<[^>]+>", "", snippet_match.group(1)).strip() if snippet_match else ""
            if not snippet:
                continue
            results.append({
                "title": html_unescape(title) or query,
                "url": url,
                "snippet": html_unescape(snippet),
                "source": "startpage",
            })
        return results

    async def _search_web_brave(self, query: str, max_results: int, safe_search: bool) -> List[dict]:
        api_key = os.environ.get("BRAVE_SEARCH_API_KEY", "")
        if not api_key:
            return []
        client = await self._get_client()
        resp = await client.get(
            "https://api.search.brave.com/res/v1/web/search",
            params={
                "q": query,
                "count": max(1, min(max_results, 10)),
                "safesearch": "strict" if safe_search else "off",
            },
            headers={
                "Accept": "application/json",
                "X-Subscription-Token": api_key,
            },
        )
        resp.raise_for_status()
        data = resp.json()
        results = []
        for item in (data.get("web") or {}).get("results") or []:
            results.append({
                "title": str(item.get("title") or query).strip(),
                "url": str(item.get("url") or "").strip(),
                "snippet": str(item.get("description") or "").strip(),
                "source": "brave",
            })
        return results

    def _search_headers(self) -> dict:
        return {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
            "Accept-Language": "en-US,en;q=0.9",
            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        }

    async def _search_web_wikipedia(self, query: str, max_results: int, safe_search: bool) -> List[dict]:
        """Wikipedia's public API needs no key and is far more reliable than
        scraping DDG/Bing, which are frequently blocked from server/cloud IPs
        and can silently return zero results. This is placed ahead of the
        HTML scrapers specifically because named people, places, and
        organizations - the exact class of query that produced a confidently
        wrong biography when grounding silently failed - are Wikipedia's
        strong suit. It naturally returns nothing for queries it can't match
        (prices, live scores, breaking news), so later engines still run for
        those cases."""
        client = await self._get_client()
        try:
            search_resp = await client.get(
                "https://en.wikipedia.org/w/api.php",
                params={
                    "action": "query",
                    "list": "search",
                    "srsearch": query,
                    "format": "json",
                    "srlimit": str(max(1, min(max_results, 5))),
                },
                headers=self._search_headers(),
            )
            search_resp.raise_for_status()
            hits = ((search_resp.json().get("query") or {}).get("search")) or []
        except Exception as e:
            logger.debug(f"Wikipedia search failed for {query!r}: {e}")
            return []

        if not hits:
            return []

        results: List[dict] = []
        for hit in hits[:max_results]:
            title = str(hit.get("title") or "").strip()
            if not title:
                continue
            extract = ""
            try:
                extract_resp = await client.get(
                    "https://en.wikipedia.org/w/api.php",
                    params={
                        "action": "query",
                        "prop": "extracts",
                        "explaintext": "1",
                        "titles": title,
                        "format": "json",
                    },
                    headers=self._search_headers(),
                )
                extract_resp.raise_for_status()
                pages = ((extract_resp.json().get("query") or {}).get("pages")) or {}
                for page in pages.values():
                    extract = str(page.get("extract") or "").strip()
                    break
            except Exception as e:
                logger.debug(f"Wikipedia extract fetch failed for {title!r}: {e}")

            if not extract:
                # Fall back to the search snippet (has <span> highlight tags to strip)
                extract = re.sub(r"<[^>]+>", "", str(hit.get("snippet") or "")).strip()
            if not extract:
                continue

            results.append({
                "title": title,
                "url": f"https://en.wikipedia.org/wiki/{title.replace(' ', '_')}",
                "snippet": extract[:12000], # Drastically increased from 2500 to capture life history
                "source": "wikipedia",
            })
        return results

    async def _search_web_ddg_html(self, query: str, max_results: int, safe_search: bool) -> List[dict]:
        import urllib.parse
        client = await self._get_client()
        results: List[dict] = []
        params = {"q": query}
        if safe_search:
            params["kp"] = "1"
        try:
            resp = await client.post("https://html.duckduckgo.com/html/", data=params, headers=self._search_headers())
            resp.raise_for_status()
            html = resp.text
        except Exception as e:
            logger.debug(f"DDG HTML request failed for {query!r}: {e}")
            return []

        # Extract full web-result cards
        items = re.findall(
            r'<div[^>]*class="[^"]*web-result[^"]*"[^>]*>.*?<a[^>]*class="result__a"[^>]*href="([^"]+)"[^>]*>(.*?)</a>.*?<a[^>]*class="result__snippet"[^>]*>(.*?)</a>',
            html,
            re.DOTALL | re.IGNORECASE
        )
        if not items:
            items = re.findall(
                r'<a[^>]*class="result__a"[^>]*href="([^"]+)"[^>]*>(.*?)</a>.*?<a[^>]*class="result__snippet"[^>]*>(.*?)</a>',
                html,
                re.DOTALL | re.IGNORECASE
            )

        for raw_url, title_html, snippet_html in items:
            if len(results) >= max_results:
                break
            # Unquote DuckDuckGo redirect wrapper to get genuine target URL
            m_uddg = re.search(r'uddg=([^&]+)', raw_url)
            if m_uddg:
                url = urllib.parse.unquote(m_uddg.group(1))
            else:
                url = html_unescape(raw_url).strip()

            title = html_unescape(re.sub(r"<[^>]+>", "", title_html)).strip()
            snippet = html_unescape(re.sub(r"<[^>]+>", "", snippet_html)).strip()
            if not url or not title:
                continue

            results.append({
                "title": title or query,
                "url": url,
                "snippet": snippet,
                "source": "duckduckgo",
            })
        return results

    async def _search_web_ddg_lite(self, query: str, max_results: int, safe_search: bool) -> List[dict]:
        client = await self._get_client()
        results: List[dict] = []
        params = {"q": query}
        if safe_search:
            params["kp"] = "1"
        resp = await client.post("https://lite.duckduckgo.com/lite/", data=params, headers=self._search_headers())
        resp.raise_for_status()
        html = resp.text
        links = re.findall(r'<a[^>]+class="result-link"[^>]+href="([^"]+)"[^>]*>(.*?)</a>', html, flags=re.IGNORECASE | re.DOTALL)
        snippets = re.findall(r'<td class="result-snippet">(.*?)</td>', html, flags=re.IGNORECASE | re.DOTALL)
        for i, (url, title) in enumerate(links):
            if len(results) >= max_results:
                break
            snippet = re.sub(r"<[^>]+>", "", snippets[i]).strip() if i < len(snippets) else ""
            if not snippet:
                continue
            results.append({
                "title": html_unescape(re.sub(r"<[^>]+>", "", title)).strip() or query,
                "url": html_unescape(url),
                "snippet": html_unescape(snippet),
                "source": "duckduckgo",
            })
        return results

    async def _search_web_bing_html(self, query: str, max_results: int, safe_search: bool) -> List[dict]:
        client = await self._get_client()
        results: List[dict] = []
        params = {"q": query, "count": str(max_results)}
        if safe_search:
            params["adlt"] = "strict"
        resp = await client.get("https://www.bing.com/search", params=params, headers=self._search_headers())
        resp.raise_for_status()
        html = resp.text
        blocks = re.split(r'<li class="b_algo"', html, flags=re.IGNORECASE)
        for block in blocks[1:]:
            if len(results) >= max_results:
                break
            link_match = re.search(r'<h2><a href="([^"]+)"[^>]*>(.*?)</a></h2>', block, flags=re.IGNORECASE | re.DOTALL)
            if not link_match:
                continue
            url = html_unescape(link_match.group(1))
            title = re.sub(r"<[^>]+>", "", link_match.group(2)).strip()
            snippet_match = re.search(r'<p>(.*?)</p>', block, flags=re.IGNORECASE | re.DOTALL)
            snippet = re.sub(r"<[^>]+>", "", snippet_match.group(1)).strip() if snippet_match else ""
            if not snippet:
                continue
            results.append({
                "title": html_unescape(title) or query,
                "url": url,
                "snippet": html_unescape(snippet),
                "source": "bing",
            })
        return results

    async def _search_web_ddg_instant(self, query: str, max_results: int, safe_search: bool) -> List[dict]:
        client = await self._get_client()
        results: List[dict] = []
        resp = await client.get("https://api.duckduckgo.com/", params={
            "q": query,
            "format": "json",
            "no_html": "1",
            "no_redirect": "1",
            "t": "meeraai",
        }, headers=self._search_headers())
        resp.raise_for_status()
        data = resp.json()
        abstract = str(data.get("AbstractText") or "").strip()
        abstract_url = str(data.get("AbstractURL") or "").strip()
        heading = str(data.get("Heading") or query).strip()
        if abstract:
            results.append({
                "title": heading,
                "url": abstract_url or f"https://duckduckgo.com/?q={query}",
                "snippet": abstract,
                "source": "duckduckgo",
            })
        for topic in data.get("RelatedTopics") or []:
            if len(results) >= max_results:
                break
            if isinstance(topic, dict) and topic.get("Text") and topic.get("FirstURL"):
                results.append({
                    "title": str(topic.get("Text")).split(" - ")[0],
                    "url": str(topic.get("FirstURL")),
                    "snippet": str(topic.get("Text")),
                    "source": "duckduckgo",
                })
        return results

    async def web_summary(self, query: str, max_results: int = 10) -> str:
        """Search the web and build a rich grounding context.
        Strategy: get search results, then FETCH and READ the top 2-3 pages
        to get full article content - this is what makes ChatGPT answers so good.
        Falls back to snippets only if page fetching fails."""
        results = await self.search_web(query, max_results=max_results, safe_search=True)
        if not results:
            return ""

        # â”€â”€ Phase 1: Fetch full page content from top results (ChatGPT-style) â”€â”€
        page_contents: List[dict] = []
        fetch_entries = []
        for item in results[:3]:  # Read top 3 results in parallel
            url = str(item.get("url") or "").strip()
            title = str(item.get("title") or "").strip()
            if url and url.startswith("http"):
                fetch_entries.append((title, url))

        if fetch_entries:
            # Fire all fetches concurrently with asyncio.gather for speed
            async def _safe_fetch(title: str, url: str) -> Optional[dict]:
                try:
                    content = await self._fetch_url_content(url, max_chars=16000)
                    if content and len(content) > 100:
                        return {"title": title, "url": url, "content": content}
                except Exception:
                    pass
                return None

            gathered = await asyncio.gather(
                *[_safe_fetch(t, u) for t, u in fetch_entries],
                return_exceptions=False,
            )
            page_contents = [p for p in gathered if p is not None]

        # â”€â”€ Phase 2: Build grounding notes â”€â”€
        notes: List[str] = []

        # If we got full page content, use that (high quality)
        if page_contents:
            for page in page_contents:
                title = page["title"]
                url = page["url"]
                content = page["content"]
                # Keep any structured data (JSON-LD: Recipe, HowTo, FAQPage,
                # JobPosting, Product, ...) intact -- it is compact and
                # precise -- and only truncate the loose prose that follows
                # it. A flat content[:4000] slice could otherwise cut the
                # real payload (ingredients/steps, Q&A pairs, salary, price)
                # out entirely on pages with a long intro -- common on
                # content-marketing pages of every kind, not just
                # recipe/how-to blogs -- which is exactly the "found the
                # content but never writes anything useful" bug this exists
                # to prevent, on any topic.
                if _STRUCTURED_DATA_MARKER in content:
                    structured_part, _, prose_part = content.partition(_STRUCTURED_DATA_MARKER)
                    remaining_budget = max(500, 4000 - len(structured_part))
                    snippet = structured_part + _STRUCTURED_DATA_MARKER + prose_part[:remaining_budget]
                else:
                    # Truncate to keep total context manageable
                    snippet = content[:4000]
                notes.append(
                    f"[Source: {title} - {url}]\n{snippet}"
                )

        # Also include remaining search results as quick references
        for item in results:
            title = str(item.get("title") or "").strip()
            snippet = str(item.get("snippet") or "").strip()
            url = str(item.get("url") or "").strip()
            # Skip if we already read this page fully
            if any(p["url"] == url for p in page_contents):
                continue
            if snippet:
                notes.append(f"[{title}]({url}) {snippet}")
            elif title or url:
                notes.append(f"[{title}]({url})")

        # Fallback: if page fetches all failed, try meta descriptions
        if not page_contents and not any(len(n) > 100 for n in notes):
            snippetless = [r for r in results if not r.get("snippet")]
            for item in snippetless[:3]:
                url = item.get("url", "")
                if not url:
                    continue
                desc = await self._fetch_meta_description(url)
                if desc:
                    notes.append(f"({item.get('title', '')}, {url}) {desc}")

        return "\n\n---\n\n".join(notes).strip()

    async def _fetch_meta_description(self, url: str) -> str:
        """Best-effort fetch of a page's meta description / og:description /
        first <p> for grounding when the search engine returned no snippet.
        Bounded by a short timeout and never raises."""
        try:
            client = await self._get_client()
            resp = await client.get(url, timeout=httpx.Timeout(8.0))
            if not resp.is_success:
                return ""
            html = resp.text[:20000]
            # <meta name="description" content="...">
            m = (
                re.search(
                    r'<meta[^>]+name=["\']description["\'][^>]+content=["\']([^"\']+)["\']',
                    html, re.IGNORECASE,
                )
                or re.search(
                    r'<meta[^>]+content=["\']([^"\']+)["\'][^>]+name=["\']description["\']',
                    html, re.IGNORECASE,
                )
            )
            if m:
                return html_unescape(m.group(1)).strip()
            # <meta property="og:description" content="...">
            m = (
                re.search(
                    r'<meta[^>]+property=["\']og:description["\'][^>]+content=["\']([^"\']+)["\']',
                    html, re.IGNORECASE,
                )
                or re.search(
                    r'<meta[^>]+content=["\']([^"\']+)["\'][^>]+property=["\']og:description["\']',
                    html, re.IGNORECASE,
                )
            )
            if m:
                return html_unescape(m.group(1)).strip()
            # First <p> with real text.
            for p_match in re.finditer(r'<p[^>]*>(.*?)</p>', html, re.IGNORECASE | re.DOTALL):
                para = re.sub(r'<[^>]+>', '', p_match.group(1)).strip()
                if len(para) > 40:
                    return html_unescape(para)[:400]
            return ""
        except Exception:
            return ""

    @staticmethod
    def _jsonld_text(value: Any) -> str:
        """Best-effort plain-text extraction from a JSON-LD field, which
        schema.org allows to be a bare string, a {"@type":"...", "text":...}
        object, or (rarely) a {"name": ...} object."""
        if isinstance(value, str):
            return html_unescape(re.sub(r"<[^>]+>", "", value)).strip()
        if isinstance(value, dict):
            return ImageSearchService._jsonld_text(value.get("text") or value.get("name") or "")
        return ""

    @staticmethod
    def _jsonld_flatten_steps(value: Any) -> List[str]:
        """Recursively flatten a recipeInstructions/step field into an
        ordered list of step text, handling every shape schema.org allows:
        a single string, a list of strings, a list of HowToStep objects, or
        HowToSection objects that nest their own list of steps."""
        steps: List[str] = []
        if isinstance(value, str):
            parts = [p.strip() for p in re.split(r"\n+", value) if p.strip()]
            steps.extend(parts or ([value.strip()] if value.strip() else []))
        elif isinstance(value, list):
            for item in value:
                steps.extend(ImageSearchService._jsonld_flatten_steps(item))
        elif isinstance(value, dict):
            if value.get("@type") == "HowToSection":
                section_name = ImageSearchService._jsonld_text(value.get("name"))
                sub_steps = ImageSearchService._jsonld_flatten_steps(value.get("itemListElement") or [])
                if section_name and sub_steps:
                    steps.append(f"[{section_name}]")
                steps.extend(sub_steps)
            else:
                text = ImageSearchService._jsonld_text(value)
                if text:
                    steps.append(text)
        return steps

    @staticmethod
    def _format_jsonld_node(node: dict) -> str:
        """Turn one schema.org JSON-LD node into a compact, model-ready
        text block, for whichever @type it actually is. Returns "" for a
        @type with no formatter below, or if a matched node has empty or
        malformed fields -- the caller just moves on to the next node in
        the page graph, so this never raises on an unknown or partial
        type."""
        raw_types = node.get("@type")
        type_set = {raw_types} if isinstance(raw_types, str) else set(raw_types or [])
        if not type_set:
            return ""
        if type_set & {"Recipe", "HowTo"}:
            return ImageSearchService._format_recipe_or_howto_node(node, type_set)
        if "FAQPage" in type_set:
            return ImageSearchService._format_faq_node(node)
        if "JobPosting" in type_set:
            return ImageSearchService._format_job_posting_node(node)
        if type_set & {"Product", "Offer"}:
            return ImageSearchService._format_product_node(node)
        return ""

    @staticmethod
    def _format_recipe_or_howto_node(node: dict, type_set: Set[str]) -> str:
        """Recipe/HowTo formatter: name, timing/yield if present,
        ingredients (Recipe only), and numbered steps. Returns "" if the
        matched node carries no usable ingredients/steps (e.g. it matched
        on @type alone but the fields were empty or malformed)."""
        is_recipe = "Recipe" in type_set
        is_howto = "HowTo" in type_set

        name = ImageSearchService._jsonld_text(node.get("name")) or ("Recipe" if is_recipe else "How-To Guide")

        ingredient_lines: List[str] = []
        if is_recipe:
            ingredients = node.get("recipeIngredient") or node.get("ingredients") or []
            if isinstance(ingredients, str):
                ingredients = [ingredients]
            ingredient_lines = [
                f"- {ImageSearchService._jsonld_text(i)}"
                for i in ingredients if ImageSearchService._jsonld_text(i)
            ]

        raw_steps = ImageSearchService._jsonld_flatten_steps(
            node.get("recipeInstructions") if is_recipe else node.get("step")
        )
        instruction_lines = [f"{i}. {s}" for i, s in enumerate(raw_steps, start=1) if s]

        if not ingredient_lines and not instruction_lines:
            return ""

        kind_label = "RECIPE" if is_recipe else "HOW-TO"
        parts = [f"{kind_label} (structured data): {name}"]
        if is_recipe:
            yield_text = ImageSearchService._jsonld_text(node.get("recipeYield"))
            if yield_text:
                parts.append(f"Yield: {yield_text}")
            for label, key in (("Prep time", "prepTime"), ("Cook time", "cookTime"), ("Total time", "totalTime")):
                val = node.get(key)
                if isinstance(val, str) and val.strip():
                    parts.append(f"{label}: {val.strip()}")
        if ingredient_lines:
            parts.append("Ingredients:\n" + "\n".join(ingredient_lines))
        if instruction_lines:
            parts.append("Steps:\n" + "\n".join(instruction_lines))
        return "\n".join(parts)

    @staticmethod
    def _format_faq_node(node: dict) -> str:
        """FAQPage -> the actual question/answer pairs. FAQ schema is one
        of the worst offenders for hiding the answer behind an accordion
        widget a plain-text extractor never expands, even though the full
        Q&A text sits in the JSON-LD either way."""
        entries = node.get("mainEntity") or []
        if isinstance(entries, dict):
            entries = [entries]
        if not isinstance(entries, list):
            return ""
        qa_lines: List[str] = []
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            question = ImageSearchService._jsonld_text(entry.get("name"))
            answer_node = entry.get("acceptedAnswer") or {}
            answer = ImageSearchService._jsonld_text(
                answer_node.get("text") if isinstance(answer_node, dict) else answer_node
            )
            if question and answer:
                qa_lines.append(f"Q: {question}\nA: {answer}")
        if not qa_lines:
            return ""
        return "FAQ (structured data):\n" + "\n\n".join(qa_lines)

    @staticmethod
    def _format_job_posting_node(node: dict) -> str:
        """JobPosting -> title, employer, location, salary, and the actual
        qualifications/responsibilities text, which listing pages routinely
        bury under company-culture marketing copy above the fold."""
        title = ImageSearchService._jsonld_text(node.get("title") or node.get("name"))
        if not title:
            return ""
        parts = [f"JOB POSTING (structured data): {title}"]

        org = node.get("hiringOrganization") or {}
        org_name = ImageSearchService._jsonld_text(org.get("name") if isinstance(org, dict) else org)
        if org_name:
            parts.append(f"Employer: {org_name}")

        location = node.get("jobLocation") or {}
        if isinstance(location, list):
            location = location[0] if location else {}
        address = location.get("address") if isinstance(location, dict) else {}
        locality = ImageSearchService._jsonld_text(address.get("addressLocality")) if isinstance(address, dict) else ""
        if locality:
            parts.append(f"Location: {locality}")

        salary = node.get("baseSalary") or {}
        if isinstance(salary, dict):
            value = salary.get("value") or {}
            if isinstance(value, dict):
                min_v, max_v, unit = value.get("minValue"), value.get("maxValue"), value.get("unitText")
                currency = ImageSearchService._jsonld_text(salary.get("currency"))
                if min_v or max_v:
                    span = f"{min_v}-{max_v}" if (min_v and max_v and min_v != max_v) else str(min_v or max_v)
                    unit_suffix = f" per {unit.lower()}" if isinstance(unit, str) and unit else ""
                    parts.append(f"Salary: {currency} {span}{unit_suffix}".strip())

        for label, key in (("Employment type", "employmentType"), ("Posted", "datePosted")):
            val = ImageSearchService._jsonld_text(node.get(key))
            if val:
                parts.append(f"{label}: {val}")

        description = ImageSearchService._jsonld_text(node.get("description"))
        if description:
            parts.append("Description:\n" + description[:2000])

        return "\n".join(parts) if len(parts) > 1 else ""

    @staticmethod
    def _format_product_node(node: dict) -> str:
        """Product (plus nested Offer/AggregateRating) -> name, price,
        availability, and rating: the numbers that shopping/spec pages
        routinely bury under lifestyle marketing copy."""
        name = ImageSearchService._jsonld_text(node.get("name"))
        if not name:
            return ""
        parts = [f"PRODUCT (structured data): {name}"]

        offers = node.get("offers") or {}
        if isinstance(offers, list):
            offers = offers[0] if offers else {}
        if isinstance(offers, dict):
            price = ImageSearchService._jsonld_text(offers.get("price"))
            currency = ImageSearchService._jsonld_text(offers.get("priceCurrency"))
            if price:
                parts.append(f"Price: {currency} {price}".strip())
            availability = ImageSearchService._jsonld_text(offers.get("availability"))
            if availability:
                parts.append(f"Availability: {availability.rsplit('/', 1)[-1]}")

        rating = node.get("aggregateRating") or {}
        if isinstance(rating, dict):
            rating_value = ImageSearchService._jsonld_text(rating.get("ratingValue"))
            rating_count = ImageSearchService._jsonld_text(rating.get("reviewCount") or rating.get("ratingCount"))
            if rating_value:
                suffix = f" ({rating_count} reviews)" if rating_count else ""
                parts.append(f"Rating: {rating_value}/5{suffix}")

        description = ImageSearchService._jsonld_text(node.get("description"))
        if description:
            parts.append("Description:\n" + description[:1000])

        return "\n".join(parts) if len(parts) > 1 else ""

    @staticmethod
    def _extract_structured_recipe(html: str) -> str:
        """Pull Recipe/HowTo structured data (JSON-LD schema.org) straight
        out of raw page HTML, before any tag-stripping happens.

        This targets a specific, very common failure mode: recipe and
        how-to blogs almost universally pad the page with a long personal
        or SEO-driven story ABOVE the actual ingredient list and numbered
        steps. A plain top-to-bottom text extractor -- especially once
        truncated to keep the context budget sane -- tends to capture that
        intro and never reach the real content, so the model ends up with
        "moist, buttery, perfect for parties" marketing prose and none of
        the actual amounts or steps. That's the "found the recipe but
        never writes anything useful" bug.

        Nearly every modern recipe/how-to page also embeds a clean,
        structured copy of those exact same ingredients/steps as JSON-LD
        (schema.org Recipe/HowTo), so Google can render its rich-snippet
        cards. That data is precise, compact, and has none of the
        storytelling padding, so it's worth checking for first."""
        out_blocks: List[str] = []
        for match in re.finditer(
            r'<script[^>]+type=["\']application/ld\+json["\'][^>]*>(.*?)</script>',
            html, re.IGNORECASE | re.DOTALL,
        ):
            raw = html_unescape(match.group(1)).strip()
            if not raw:
                continue
            try:
                data = json.loads(raw, strict=False)
            except Exception:
                # Some sites emit malformed JSON-LD (trailing commas,
                # stray control characters, concatenated objects). Not
                # worth a full recovery parser -- just skip this block.
                continue

            nodes: List[dict] = []

            def _collect(node: Any) -> None:
                if isinstance(node, dict):
                    graph = node.get("@graph")
                    if isinstance(graph, list):
                        for sub in graph:
                            _collect(sub)
                    else:
                        nodes.append(node)
                elif isinstance(node, list):
                    for sub in node:
                        _collect(sub)

            _collect(data)

            for node in nodes:
                block = ImageSearchService._format_jsonld_node(node)
                if block:
                    out_blocks.append(block)

        return "\n\n".join(out_blocks).strip()

    # Increased max_chars to feed the model deeper context for long-form answers
    async def _fetch_url_content(self, url: str, max_chars: int = 16000) -> str:
        """Fetch and extract readable text content from a URL.
        This is the key upgrade that makes answers ChatGPT-like: instead of
        relying on 1-line search snippets, we actually READ the page.
        Returns cleaned article text, bounded by max_chars. Never raises."""
        try:
            client = await self._get_client()
            resp = await client.get(
                url,
                timeout=httpx.Timeout(12.0, connect=5.0),
                headers=self._search_headers(),
                follow_redirects=True,
            )
            if not resp.is_success:
                return ""
            content_type = resp.headers.get("content-type", "")
            # Only process HTML pages
            if "text/html" not in content_type and "text/plain" not in content_type:
                return ""

            html = resp.text

            # Pull Recipe/HowTo structured data (JSON-LD schema.org) out of
            # the raw HTML *before* the tag-stripping below removes the
            # <script> blocks it lives in. See _extract_structured_recipe
            # for why this matters: recipe/how-to blogs almost always pad
            # the page with a long story ABOVE the actual ingredient list
            # and steps, so reading top-to-bottom and truncating (below,
            # and again in web_summary) tends to capture the intro and
            # miss the real content -- structured data has none of that
            # padding.
            structured_data = self._extract_structured_recipe(html)

            # Remove script, style, nav, footer, header, aside, form elements
            html = re.sub(
                r'<(script|style|nav|footer|header|aside|form|iframe|noscript)[^>]*>.*?</\1>',
                '', html, flags=re.IGNORECASE | re.DOTALL,
            )
            # Remove HTML comments
            html = re.sub(r'<!--.*?-->', '', html, flags=re.DOTALL)

            # Try to find <article> or <main> content first (higher quality)
            main_block = (
                re.search(r'<article[^>]*>(.*?)</article>', html, re.IGNORECASE | re.DOTALL)
                or re.search(r'<main[^>]*>(.*?)</main>', html, re.IGNORECASE | re.DOTALL)
                or re.search(r'<div[^>]+class="[^"]*(?:article|content|post|entry|story|body)[^"]*"[^>]*>(.*?)</div>', html, re.IGNORECASE | re.DOTALL)
            )
            if main_block:
                text_block = main_block.group(1)
            else:
                # Fall back to body content
                body_match = re.search(r'<body[^>]*>(.*)</body>', html, re.IGNORECASE | re.DOTALL)
                text_block = body_match.group(1) if body_match else html

            # Replace <br>, <li>, <tr>, </p>, </div>, </h1-h6> with newlines
            text_block = re.sub(r'<br\s*/?\s*>', '\n', text_block, flags=re.IGNORECASE)
            text_block = re.sub(r'</?(?:p|div|h[1-6]|li|tr|blockquote)[^>]*>', '\n', text_block, flags=re.IGNORECASE)
            # Replace <li> with bullet
            text_block = re.sub(r'<li[^>]*>', '\n- ', text_block, flags=re.IGNORECASE)

            # Strip all remaining HTML tags
            text_block = re.sub(r'<[^>]+>', '', text_block)
            # Decode HTML entities
            text_block = html_unescape(text_block)
            # Collapse whitespace but keep paragraph breaks
            lines = []
            for line in text_block.split('\n'):
                line = line.strip()
                if line and len(line) > 15:  # Skip very short fragments
                    lines.append(line)
            # Also keep short lines that look like list items
            text_block = '\n'.join(lines)

            # Collapse excessive newlines
            text_block = re.sub(r'\n{3,}', '\n\n', text_block).strip()

            if len(text_block) > max_chars:
                text_block = text_block[:max_chars].rsplit('\n', 1)[0]

            if structured_data:
                # Structured data goes first so it survives the harder
                # per-page truncation applied later in web_summary(); the
                # marker lets that step keep this part whole and only trim
                # the prose that follows.
                return structured_data + _STRUCTURED_DATA_MARKER + text_block
            return text_block
        except Exception as e:
            logger.debug(f"_fetch_url_content failed for {url}: {e}")
            return ""

    async def _search_duckduckgo(self, query: str, max_results: int,
                                  safe_search: bool) -> List[ImageResult]:
        """Search DuckDuckGo for images (free, no API key)."""
        client = await self._get_client()
        images = []

        try:
            # Use DuckDuckGo lite HTML search
            params = {"q": query, "iax": "images", "ia": "images"}
            if safe_search:
                params["safe"] = "on"

            resp = await client.get(
                "https://html.duckduckgo.com/html/",
                params=params,
            )
            resp.raise_for_status()
            html = resp.text

            # Extract image URLs from DDG HTML
            # DDG embeds image data in JSON within the HTML
            json_matches = re.findall(
                r'ddg\_results\.images\[\d+\]\s*=\s*({.*?});',
                html, re.DOTALL
            )
            for match in json_matches[:max_results]:
                try:
                    data = json.loads(match)
                    thumbnail = data.get("thumbnail", "")
                    full_url = data.get("image", "") or thumbnail
                    width = data.get("width", 0)
                    height = data.get("height", 0)
                    if full_url and width >= height: # Filter for landscape/wallpaper suitability
                        images.append(ImageResult(
                            url=full_url,
                            thumbnail_url=thumbnail,
                            width=width,
                            height=height,
                            title=data.get("title", ""),
                            source="duckduckgo",
                        ))
                except json.JSONDecodeError:
                    continue

            # Fallback: extract from img tags
            if not images:
                img_urls = re.findall(
                    r'src="(https?://[^"]*\.(?:jpg|jpeg|png|gif|webp)[^"]*)"',
                    html, re.IGNORECASE
                )
                for url in img_urls[:max_results]:
                    images.append(ImageResult(
                        url=url, source="duckduckgo",
                        title=query,
                    ))

        except Exception as e:
            logger.error(f"DuckDuckGo image search error: {e}")

        return images

    async def _search_unsplash(self, query: str, max_results: int,
                                api_key: Optional[str]) -> List[ImageResult]:
        if not api_key:
            return await self._search_duckduckgo(query, max_results, True)
        client = await self._get_client()
        try:
            resp = await client.get(
                "https://api.unsplash.com/search/photos",
                params={"query": query, "per_page": max_results, "orientation": "landscape"},
                headers={"Authorization": f"Client-ID {api_key}"}
            )
            resp.raise_for_status()
            data = resp.json()
            return [ImageResult(
                url=r["urls"]["full"],
                thumbnail_url=r["urls"]["thumb"],
                width=r["width"],
                height=r["height"],
                title=r.get("description") or r.get("alt_description") or query,
                source="unsplash",
            ) for r in data.get("results", []) if r.get("width", 0) > r.get("height", 0)]
        except Exception as e:
            logger.error(f"Unsplash search error: {e}")
            return []

    async def _search_pexels(self, query: str, max_results: int,
                              api_key: Optional[str]) -> List[ImageResult]:
        if not api_key:
            return await self._search_duckduckgo(query, max_results, True)
        client = await self._get_client()
        try:
            resp = await client.get(
                "https://api.pexels.com/v1/search",
                params={"query": query, "per_page": max_results},
                headers={"Authorization": api_key}
            )
            resp.raise_for_status()
            data = resp.json()
            return [ImageResult(
                url=r["src"]["large"],
                thumbnail_url=r["src"]["tiny"],
                width=r["width"],
                height=r["height"],
                title=r.get("alt") or query,
                source="pexels",
            ) for r in data.get("photos", [])]
        except Exception as e:
            logger.error(f"Pexels search error: {e}")
            return []

    async def _search_google(self, query: str, max_results: int,
                              api_key: Optional[str],
                              safe_search: bool) -> List[ImageResult]:
        if not api_key:
            return await self._search_duckduckgo(query, max_results, safe_search)
        # Google Custom Search API
        client = await self._get_client()
        try:
            cx = api_key.split("|")[1] if "|" in api_key else ""
            key = api_key.split("|")[0]
            resp = await client.get(
                "https://www.googleapis.com/customsearch/v1",
                params={
                    "key": key, "cx": cx, "q": query,
                    "searchType": "image", "num": max_results,
                    "safe": "active" if safe_search else "off",
                }
            )
            resp.raise_for_status()
            data = resp.json()
            return [ImageResult(
                url=item["link"],
                thumbnail_url=item.get("image", {}).get("thumbnailLink"),
                width=item.get("image", {}).get("width"),
                height=item.get("image", {}).get("height"),
                title=item.get("title", ""),
                source="google",
            ) for item in data.get("items", [])]
        except Exception as e:
            logger.error(f"Google image search error: {e}")
            return []

    async def _search_bing(self, query: str, max_results: int,
                            api_key: Optional[str],
                            safe_search: bool) -> List[ImageResult]:
        if not api_key:
            return await self._search_duckduckgo(query, max_results, safe_search)
        client = await self._get_client()
        try:
            resp = await client.get(
                "https://api.bing.microsoft.com/v7.0/images/search",
                params={
                    "q": query, "count": max_results,
                    "safeSearch": "Moderate" if safe_search else "Off",
                },
                headers={"Ocp-Apim-Subscription-Key": api_key}
            )
            resp.raise_for_status()
            data = resp.json()
            return [ImageResult(
                url=item["contentUrl"],
                thumbnail_url=item.get("thumbnailUrl"),
                width=item.get("width"),
                height=item.get("height"),
                title=item.get("name", ""),
                source="bing",
            ) for item in data.get("value", [])]
        except Exception as e:
            logger.error(f"Bing image search error: {e}")
            return []

    def get_image_tool_definition(self) -> dict:
        """Return the image search tool definition for model tool calling."""
        return {
            "type": "function",
            "function": {
                "name": "search_web_images",
                "description": (
                    "Search the internet for images. Use this when the user asks "
                    "to see an image of something, when showing an image would "
                    "help explain or illustrate the topic, OR when answering any "
                    "question about a specific named person (e.g. 'who is X', a "
                    "biography, an executive, celebrity, historical figure, athlete). "
                    "For person queries, call this near the start of your response "
                    "using the person's full name as the query, so their photo can "
                    "load alongside your answer. For wallpaper or "
                    "background image requests, include descriptive keywords like "
                    "scenic, aesthetic, 4k, or the subject matter to get accurate "
                    "results. Returns image URLs that will be displayed to the user."
                ),
                "parameters": {
                    "type": "object",
                    "properties": {
                        "query": {
                            "type": "string",
                            "description": "Search query for finding relevant images. "
                                         "Be specific and descriptive. For wallpapers, "
                                         "include the subject + style (e.g. "
                                         "'dark mountain landscape 4k wallpaper').",
                        },
                    },
                    "required": ["query"],
                },
            },
            "mcp_server": "__builtin__",
        }

    def get_web_tool_definition(self) -> dict:
        """Return the web search tool definition for internet-grounded answers."""
        return {
            "type": "function",
            "function": {
                "name": "search_web",
                "description": (
                    "Search the internet for current, factual information and return text snippets with links. "
                    "Use this for latest news, product details, current prices, live facts, or anything that benefits from web grounding. "
                    "SHOPPING/PRODUCT COMPARISONS: if the user wants multiple products compared (e.g. several phones, laptops, or "
                    "other items with prices), you need a distinct source URL for EVERY item so each one can get its own buy link -- "
                    "set max_results to 10 and, if one search doesn't surface enough distinct products, run additional searches "
                    "(e.g. per brand or category) rather than answering with fewer sources than products. "
                    "If the user asks for a document or PDF (e.g. 'ACPC cutoff'), append 'filetype:pdf' to the query. "
                    "IMPORTANT: When you provide a link to a PDF, you MUST format the markdown link exactly like this to open it in-app: "
                    "[View PDF](/api/documents/proxy?url=<THE_PDF_URL>)"
                ),
                "parameters": {
                    "type": "object",
                    "properties": {
                        "query": {
                            "type": "string",
                            "description": "A concise search query for web lookup.",
                        },
                        "max_results": {
                            "type": "integer",
                            "description": "Maximum number of results to return.",
                            "minimum": 1,
                            "maximum": 10,
                        },
                    },
                    "required": ["query"],
                },
            },
            "mcp_server": "__builtin__",
        }

    async def close(self):
        if self._client:
            await self._client.aclose()
            self._client = None


