# SECTION 11: GGUF MODEL MANAGER
# ==================================================

class GGUFModelManager:
    """Manages GGUF model listing, categorization, and filtering."""

    def __init__(self, persistence: PersistenceManager,
                 local_engine: LocalInferenceEngine,
                 cloud_engine: CloudInferenceEngine):
        self.persistence = persistence
        self.local_engine = local_engine
        self.cloud_engine = cloud_engine
        self._cache: Optional[List[ModelInfo]] = None
        self._cache_time: float = 0
        self._cache_ttl: float = 30.0  # seconds

    async def get_all_models(self, force_refresh: bool = False) -> List[ModelInfo]:
        """Get all available models, GGUF filtered for local."""
        now = time.time()
        if self._cache and not force_refresh and (now - self._cache_time) < self._cache_ttl:
            return self._cache

        models_dict = {}
        config = self.persistence.config

        # Local models (GGUF only)
        for entry in scan_local_gguf_library():
            m_id = entry.get("repo_id") or entry["id"]
            models_dict[m_id] = ModelInfo(
                id=entry["id"],
                name=entry["label"],
                provider=entry.get("repo_id") or "local_disk",
                owned_by=entry.get("repo_id") or entry["folder"],
                quantization=str(entry.get("quant_bits") or entry.get("precision") or ""),
                quant_category=None,
                size_gb=round(float(entry.get("size_bytes", 0)) / (1024**3), 2) if entry.get("size_bytes") else None,
                is_gguf=True,
                is_local=True,
                capabilities=entry.get("capabilities", ["streaming"]),
                modified_at=None,
            )

        # Cloud models: the chat model catalog must contain every model the
        # provider exposes.  GGUF is a local-file property, not a cloud-model
        # filter.  The old code also keyed by provider, which silently kept
        # only the first model returned by each provider.
        for prov_id, conn in config.cloud_providers.items():
            if conn.connected:
                try:
                    cloud_models = await self.cloud_engine.list_models(prov_id)
                    for m in cloud_models:
                        m.is_gguf = "gguf" in m.id.lower() or prov_id == "together_gguf"
                        m_id = f"{m.provider}:{m.id}"
                        if m_id not in models_dict:
                            models_dict[m_id] = m
                except Exception:
                    pass

        models = list(models_dict.values())
        self._cache = models
        self._cache_time = now
        return models

    async def get_local_models(self, force_refresh: bool = False) -> List[ModelInfo]:
        """Get local GGUF models only."""
        all_models = await self.get_all_models(force_refresh)
        return [m for m in all_models if m.is_local]

    async def get_cloud_gguf_models(self, force_refresh: bool = False) -> List[ModelInfo]:
        """Get cloud GGUF models only."""
        all_models = await self.get_all_models(force_refresh)
        return [m for m in all_models if not m.is_local and m.is_gguf]

    def get_quantization_categories(self,
                                     models: List[ModelInfo]) -> List[GGUFCategory]:
        """Categorize models by quantization type."""
        categories = OrderedDict()
        for cat_name in GGUF_QUANTIZATIONS:
            categories[cat_name] = GGUFCategory(
                category=cat_name,
                quant_types=GGUF_QUANTIZATIONS[cat_name],
            )

        uncategorized = GGUFCategory(category="Unknown/Other", quant_types=[])

        for model in models:
            if model.quant_category and model.quant_category in categories:
                categories[model.quant_category].models.append(model)
            elif model.quantization:
                uncategorized.models.append(model)
                if model.quantization not in uncategorized.quant_types:
                    uncategorized.quant_types.append(model.quantization)

        result = [c for c in categories.values() if c.models]
        if uncategorized.models:
            result.append(uncategorized)
        return result

    async def get_model_by_id(self, model_id: str) -> Optional[ModelInfo]:
        """Find a specific model by ID."""
        models = await self.get_all_models()
        for m in models:
            if m.id == model_id:
                return m
        return None

    def invalidate_cache(self):
        self._cache = None
        self._cache_time = 0

class ExecutionEvent(BaseModel):
    id: str
    title: str
    description: Optional[str] = None
    status: Literal["pending", "running", "waiting", "completed", "failed", "cancelled", "retrying", "skipped"]
    progress: float = 0.0
    icon: Optional[str] = None
    tool: Optional[str] = None
    parent: Optional[str] = None
    metadata: dict = Field(default_factory=dict)
    timestamp: float

current_execution_manager: contextvars.ContextVar["Optional[ExecutionManager]"] = contextvars.ContextVar("current_execution_manager", default=None)

def get_exec_manager() -> "Optional[ExecutionManager]":
    return current_execution_manager.get()

class ExecutionManager:
    def __init__(self, step_queue: "Optional[asyncio.Queue]"):
        self.step_queue = step_queue
        # Tracks event_id -> parent_id for every event this manager has ever
        # started. Lifecycle updates (progress/complete/fail/cancel/stage)
        # only take an event_id, not a parent, so without this each update
        # would emit parent=None. The frontend uses exclude_none-stripped
        # payloads to rebuild the tree by id, so a missing parent on an
        # update silently detaches that node and it renders as a root-level
        # row instead of nested under its section. This dict is what lets
        # every subsequent update re-attach to the same parent it started
        # with, so the tree shape stays stable for the life of the event.
        self._parents: Dict[str, Optional[str]] = {}

    def _emit(self, event: ExecutionEvent):
        if self.step_queue is None:
            return
        try:
            payload = event.model_dump(exclude_none=True)
            self.step_queue.put_nowait({"type": "execution", "data": payload})
        except Exception as e:
            logger.debug(f"ExecutionManager _emit error: {e}")

    def start(self, event_id: str, title: str, description: Optional[str] = None, icon: Optional[str] = None, tool: Optional[str] = None, parent: Optional[str] = None):
        self._parents[event_id] = parent
        event = ExecutionEvent(
            id=event_id,
            title=title,
            description=description,
            status="running",
            progress=0.0,
            icon=icon,
            tool=tool,
            parent=parent,
            timestamp=time.time()
        )
        self._emit(event)

    def child(self, parent_id: str, event_id: str, title: str, description: Optional[str] = None, icon: Optional[str] = None, tool: Optional[str] = None):
        self.start(event_id, title, description, icon, tool, parent=parent_id)

    def progress(self, event_id: str, title: str, progress: float, description: Optional[str] = None):
        event = ExecutionEvent(
            id=event_id,
            title=title,
            description=description,
            status="running",
            progress=progress,
            parent=self._parents.get(event_id),
            timestamp=time.time()
        )
        self._emit(event)

    def complete(self, event_id: str, title: str, description: Optional[str] = None):
        event = ExecutionEvent(
            id=event_id,
            title=title,
            description=description,
            status="completed",
            progress=100.0,
            parent=self._parents.get(event_id),
            timestamp=time.time()
        )
        self._emit(event)

    def fail(self, event_id: str, title: str, error: str):
        event = ExecutionEvent(
            id=event_id,
            title=title,
            description=error,
            status="failed",
            progress=100.0,
            parent=self._parents.get(event_id),
            timestamp=time.time()
        )
        self._emit(event)

    def cancel(self, event_id: str, title: str, reason: Optional[str] = None):
        event = ExecutionEvent(
            id=event_id,
            title=title,
            description=reason,
            status="cancelled",
            progress=100.0,
            parent=self._parents.get(event_id),
            timestamp=time.time()
        )
        self._emit(event)

    def finish(self, event_id: str, title: str, description: Optional[str] = None):
        """Alias for complete()"""
        self.complete(event_id, title, description)

    def stage(self, event_id: str, title: str, description: Optional[str] = None):
        """Update the title/description without changing progress or status."""
        event = ExecutionEvent(
            id=event_id,
            title=title,
            description=description,
            status="running",
            progress=50.0,  # Generic progress for a staging event
            parent=self._parents.get(event_id),
            timestamp=time.time()
        )
        self._emit(event)

    def parallel(self, parent_id: str, events: List[Dict[str, Any]]):
        """Start multiple child events concurrently."""
        for ev in events:
            self.child(
                parent_id=parent_id,
                event_id=ev["id"],
                title=ev["title"],
                description=ev.get("description"),
                icon=ev.get("icon"),
                tool=ev.get("tool")
            )

# ==================================================
# SECTION 11.5: BROWSER AUTOMATION SERVICE
# ==================================================

class BrowserAutomationService:
    """Server-side browser automation for agentic web tasks.

    The service supports navigation, form inspection/filling, clicking,
    extraction, screenshots, ordered multi-step flows, and guarded checkout
    handoff. It is intentionally conservative: it never enters payment details,
    never bypasses login/OTP/CAPTCHA, and never completes a final booking,
    purchase, reservation confirmation, or payment.
    """

    def __init__(self):
        self._playwright = None
        self._browser = None
        self._context = None
        self._page = None
        self._lock = asyncio.Lock()
        self._initialized = False
        self._init_attempted = False
        self._init_error: Optional[str] = None
        self._sessions: Dict[str, dict] = {}
        BROWSER_SCREENSHOTS_DIR.mkdir(parents=True, exist_ok=True)

    @property
    def available(self) -> bool:
        if not HAS_PLAYWRIGHT:
            return False
        if self._init_error and ("not installed" in self._init_error or "failed" in self._init_error.lower() or "not support" in self._init_error.lower()):
            return False
        cache_dir = Path.home() / "Library" / "Caches" / "ms-playwright"
        if sys.platform == "win32":
            cache_dir = Path(os.environ.get("LOCALAPPDATA", "")) / "ms-playwright"
        elif sys.platform == "linux":
            cache_dir = Path.home() / ".cache" / "ms-playwright"
        if not cache_dir.exists():
            return False
        try:
            return any(
                p.is_dir() and any(k in p.name.lower() for k in ("chromium", "chrome", "firefox", "webkit"))
                for p in cache_dir.iterdir()
            )
        except Exception:
            return False

    @property
    def is_ready(self) -> bool:
        return bool(self._initialized and self._browser and self._page)

    @property
    def init_error(self) -> Optional[str]:
        return self._init_error

    def reset_init(self) -> None:
        self._init_attempted = False
        self._init_error = None

    async def initialize(self) -> None:
        if not HAS_PLAYWRIGHT:
            self._init_error = "Playwright is not installed. Run: pip install playwright && playwright install chromium"
            logger.info("Browser automation disabled: Playwright is not installed.")
            return
        if self._init_attempted:
            return
        self._init_attempted = True
        try:
            self._playwright = await async_playwright().start()
            self._browser = await self._playwright.chromium.launch(
                headless=True,
                args=[
                    "--no-sandbox",
                    "--disable-setuid-sandbox",
                    "--disable-dev-shm-usage",
                    "--disable-blink-features=AutomationControlled",
                    "--window-size=1920,1080",
                ],
            )
            self._context = await self._browser.new_context(
                viewport={"width": 1920, "height": 1080},
                user_agent=(
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                    "AppleWebKit/537.36 (KHTML, like Gecko) "
                    "Chrome/125.0.0.0 Safari/537.36"
                ),
                locale="en-US",
            )
            await self._context.add_init_script(
                """
                Object.defineProperty(navigator, 'webdriver', { get: () => undefined });
                window.chrome = window.chrome || { runtime: {} };
                Object.defineProperty(navigator, 'languages', { get: () => ['en-US', 'en'] });
                Object.defineProperty(navigator, 'plugins', { get: () => [1, 2, 3, 4, 5] });
                """
            )
            self._page = await self._context.new_page()
            self._initialized = True
            logger.info("BrowserAutomationService initialized.")
        except Exception as exc:
            err = str(exc)
            if "Executable doesn't exist" in err or "playwright install" in err.lower():
                self._init_error = "Chromium is not installed. Run: playwright install chromium"
            else:
                self._init_error = f"Browser initialization failed: {err}"
            self._initialized = False
            logger.warning(self._init_error)

    async def close(self) -> None:
        for obj in (self._context, self._browser):
            try:
                if obj:
                    await obj.close()
            except Exception:
                pass
        try:
            if self._playwright:
                await self._playwright.stop()
        except Exception:
            pass
        self._playwright = None
        self._browser = None
        self._context = None
        self._page = None
        self._initialized = False

    async def _ensure_page(self):
        if not HAS_PLAYWRIGHT:
            raise RuntimeError("Playwright is not installed. Run: pip install playwright && playwright install chromium")
        if not self.is_ready:
            self.reset_init()
            await self.initialize()
        if not self.is_ready:
            raise RuntimeError(self._init_error or "Browser failed to initialize.")
        return self._page

    def _normalize_url(self, value: str) -> str:
        url = str(value or "").strip()
        if not url:
            return "about:blank"
        url = re.sub(r"(?i)\bbookings\.com\b", "booking.com", url)
        if re.match(r"^(https?|file|data):", url, re.IGNORECASE):
            return url
        if re.match(r"^[\w.-]+\.[a-z]{2,}([/?#].*)?$", url, re.IGNORECASE):
            return f"https://{url}"
        return f"https://www.google.com/search?q={quote_plus(url)}"

    async def navigate(self, url: str, wait_for: str = "domcontentloaded", timeout: int = 30000) -> dict:
        try:
            page = await self._ensure_page()
        except Exception as exc:
            logger.warning(f"Browser navigation unavailable: {exc}")
            return {"ok": False, "error": str(exc)}
        async with self._lock:
            try:
                target = self._normalize_url(url)
                response = await page.goto(target, wait_until=wait_for, timeout=timeout)
                try:
                    await page.wait_for_load_state("networkidle", timeout=8000)
                except Exception:
                    pass
                if "booking.com/searchresults" in target:
                    await page.wait_for_timeout(4000)
                    try:
                        await page.evaluate("() => window.scrollBy(0, Math.min(900, document.body.scrollHeight || 900))")
                        await page.wait_for_timeout(1200)
                        await page.evaluate("() => window.scrollTo(0, 0)")
                    except Exception:
                        pass
                else:
                    await page.wait_for_timeout(1200)
                return {
                    "ok": True,
                    "url": page.url,
                    "title": await page.title(),
                    "status": response.status if response else 0,
                }
            except Exception as exc:
                return {"ok": False, "error": str(exc)}

    async def click(self, selector: str, timeout: int = 10000) -> dict:
        page = await self._ensure_page()
        async with self._lock:
            try:
                await page.click(selector, timeout=timeout)
                await page.wait_for_timeout(800)
                return {"ok": True, "action": f"Clicked {selector}"}
            except Exception as css_exc:
                try:
                    await page.get_by_text(selector, exact=False).first.click(timeout=min(timeout, 5000))
                    await page.wait_for_timeout(800)
                    return {"ok": True, "action": f"Clicked visible text {selector}"}
                except Exception:
                    return {"ok": False, "error": str(css_exc)}

    async def type_text(self, selector: str, text: str, clear_first: bool = True, timeout: int = 10000) -> dict:
        page = await self._ensure_page()
        async with self._lock:
            try:
                if clear_first:
                    await page.fill(selector, text, timeout=timeout)
                else:
                    await page.type(selector, text, timeout=timeout)
                return {"ok": True, "action": f"Typed into {selector}"}
            except Exception as css_exc:
                for getter in (
                    lambda: page.get_by_placeholder(selector).first,
                    lambda: page.get_by_label(selector).first,
                    lambda: page.get_by_role("textbox", name=re.compile(re.escape(selector), re.IGNORECASE)).first,
                ):
                    try:
                        await getter().fill(text, timeout=min(timeout, 5000))
                        return {"ok": True, "action": f"Typed into matched field {selector}"}
                    except Exception:
                        continue
                return {"ok": False, "error": str(css_exc)}

    async def press_key(self, key: str) -> dict:
        page = await self._ensure_page()
        async with self._lock:
            try:
                await page.keyboard.press(key)
                await page.wait_for_timeout(400)
                return {"ok": True, "action": f"Pressed {key}"}
            except Exception as exc:
                return {"ok": False, "error": str(exc)}

    async def select_option(self, selector: str, value: str) -> dict:
        page = await self._ensure_page()
        async with self._lock:
            try:
                await page.select_option(selector, value=value)
                return {"ok": True, "action": f"Selected {value} in {selector}"}
            except Exception as exc:
                return {"ok": False, "error": str(exc)}

    async def scroll(self, direction: str = "down", amount: int = 700) -> dict:
        page = await self._ensure_page()
        async with self._lock:
            try:
                if direction == "up":
                    delta = -abs(int(amount))
                    await page.evaluate("(dy) => window.scrollBy(0, dy)", delta)
                elif direction == "top":
                    await page.evaluate("() => window.scrollTo(0, 0)")
                elif direction == "bottom":
                    await page.evaluate("() => window.scrollTo(0, document.body.scrollHeight)")
                else:
                    delta = abs(int(amount))
                    await page.evaluate("(dy) => window.scrollBy(0, dy)", delta)
                await page.wait_for_timeout(500)
                return {"ok": True, "action": f"Scrolled {direction}"}
            except Exception as exc:
                return {"ok": False, "error": str(exc)}

    async def wait_for_selector(self, selector: str, timeout: int = 10000) -> dict:
        page = await self._ensure_page()
        async with self._lock:
            try:
                await page.wait_for_selector(selector, timeout=timeout)
                return {"ok": True, "action": f"Element appeared: {selector}"}
            except Exception as exc:
                return {"ok": False, "error": str(exc)}

    async def execute_js(self, script: str) -> dict:
        page = await self._ensure_page()
        async with self._lock:
            try:
                result = await page.evaluate(script)
                return {"ok": True, "result": str(result)[:5000]}
            except Exception as exc:
                return {"ok": False, "error": str(exc)}

    async def screenshot(self, full_page: bool = False) -> dict:
        page = await self._ensure_page()
        async with self._lock:
            try:
                data = await page.screenshot(full_page=full_page)
                filename = f"browser_{uuid.uuid4().hex[:10]}.png"
                path = BROWSER_SCREENSHOTS_DIR / filename
                path.write_bytes(data)
                return {
                    "ok": True,
                    "screenshot_base64": base64.b64encode(data).decode("ascii"),
                    "path": str(path),
                    "size": len(data),
                }
            except Exception as exc:
                return {"ok": False, "error": str(exc)}

    async def extract_page(self, extract_type: str = "text", selector: str = "") -> dict:
        page = await self._ensure_page()
        async with self._lock:
            try:
                scope = selector or "body"
                if extract_type == "text":
                    return {"ok": True, "type": "text", "content": (await page.inner_text(scope))[:12000]}
                if extract_type == "html":
                    return {"ok": True, "type": "html", "content": (await page.content())[:20000]}
                if extract_type == "links":
                    links = await page.evaluate("""() => Array.from(document.querySelectorAll('a[href]'))
                        .map(a => ({text: (a.innerText || '').trim().slice(0, 140), href: a.href}))
                        .filter(x => x.text && x.href).slice(0, 80)""")
                    return {"ok": True, "type": "links", "content": links}
                if extract_type == "forms":
                    forms = await page.evaluate("""() => Array.from(document.querySelectorAll('input, select, textarea, button'))
                        .slice(0, 80).map(el => ({
                            tag: el.tagName.toLowerCase(),
                            type: el.type || '',
                            name: el.name || '',
                            id: el.id || '',
                            placeholder: el.placeholder || '',
                            value: el.value || '',
                            text: (el.innerText || '').trim().slice(0, 100),
                            label: el.labels && el.labels[0] ? el.labels[0].innerText.trim() : '',
                            selector: el.id ? ('#' + CSS.escape(el.id)) : (el.name ? `${el.tagName.toLowerCase()}[name="${el.name}"]` : el.tagName.toLowerCase())
                        }))""")
                    return {"ok": True, "type": "forms", "content": forms}
                if extract_type == "tables":
                    tables = await page.evaluate("""() => Array.from(document.querySelectorAll('table')).slice(0, 8).map((table, index) => ({
                        index,
                        rows: Array.from(table.querySelectorAll('tr')).slice(0, 30)
                            .map(tr => Array.from(tr.querySelectorAll('th,td')).map(td => td.innerText.trim()))
                    }))""")
                    return {"ok": True, "type": "tables", "content": tables}
                if extract_type == "images":
                    images = await page.evaluate("""() => {
                        const pickFromSrcset = (srcset) => {
                            if (!srcset) return "";
                            const parts = String(srcset).split(",").map(x => x.trim()).filter(Boolean);
                            if (!parts.length) return "";
                            return parts[parts.length - 1].split(/\\s+/)[0] || "";
                        };
                        const absolutize = (value) => {
                            if (!value) return "";
                            try { return new URL(value, location.href).href; } catch (e) { return ""; }
                        };
                        const seen = new Set();
                        return Array.from(document.querySelectorAll("img, picture source"))
                            .map((el) => {
                                const src =
                                    el.currentSrc ||
                                    el.src ||
                                    el.getAttribute("data-src") ||
                                    el.getAttribute("data-lazy-src") ||
                                    pickFromSrcset(el.getAttribute("srcset")) ||
                                    pickFromSrcset(el.getAttribute("data-srcset")) ||
                                    "";
                                const url = absolutize(src);
                                const rect = el.getBoundingClientRect ? el.getBoundingClientRect() : { width: 0, height: 0 };
                                const alt = (el.getAttribute("alt") || el.getAttribute("aria-label") || "").replace(/\\s+/g, " ").trim();
                                return {
                                    url,
                                    alt,
                                    width: Math.round(rect.width || el.naturalWidth || 0),
                                    height: Math.round(rect.height || el.naturalHeight || 0)
                                };
                            })
                            .filter((img) => {
                                if (!img.url || seen.has(img.url)) return false;
                                if (/^(data:|blob:)/i.test(img.url)) return false;
                                if (/\\.(svg|ico)(?:\\?|$)/i.test(img.url)) return false;
                                seen.add(img.url);
                                return (img.width >= 80 || img.height >= 80 || img.alt.length > 8);
                            })
                            .slice(0, 12);
                    }""")
                    return {"ok": True, "type": "images", "content": images}
                if extract_type == "prices":
                    result = await page.evaluate("""() => {
                        const lines = document.body.innerText.split(/\n/).map(x => x.trim()).filter(Boolean);
                        const re = /(?:Rs\\.?|INR|₹|\\$|USD|EUR|GBP)\\s*[\\d,]+(?:\\.\\d{1,2})?|[\\d,]+\\s*(?:Rs|INR|₹|USD|EUR|GBP)/i;
                        return lines.filter(line => re.test(line)).slice(0, 60).map(line => line.slice(0, 220));
                    }""")
                    return {"ok": True, "type": "prices", "content": result}
                return {"ok": False, "error": f"Unknown extract type: {extract_type}"}
            except Exception as exc:
                return {"ok": False, "error": str(exc)}

    async def get_page_info(self) -> dict:
        page = await self._ensure_page()
        try:
            return {"ok": True, "url": page.url, "title": await page.title()}
        except Exception as exc:
            return {"ok": False, "error": str(exc)}

    async def _checkout_state_unlocked(self, page: Page, preference: str = "") -> dict:
        return await page.evaluate(
            """(preference) => {
                const visible = (el) => {
                    if (!el) return false;
                    const style = window.getComputedStyle(el);
                    if (style.visibility === "hidden" || style.display === "none") return false;
                    const rect = el.getBoundingClientRect();
                    return rect.width > 2 && rect.height > 2;
                };
                const textOf = (el) => (el?.innerText || el?.textContent || el?.value || el?.getAttribute("aria-label") || "").replace(/\\s+/g, " ").trim();
                const labelFor = (el) => {
                    const own = [
                        el.getAttribute("aria-label"),
                        el.getAttribute("placeholder"),
                        el.getAttribute("name"),
                        el.getAttribute("id"),
                        el.getAttribute("autocomplete")
                    ].filter(Boolean).join(" ");
                    const id = el.getAttribute("id");
                    const explicit = id ? document.querySelector(`label[for="${CSS.escape(id)}"]`) : null;
                    const wrapper = el.closest("label");
                    return `${own} ${textOf(explicit)} ${textOf(wrapper)}`.replace(/\\s+/g, " ").trim();
                };
                const pageText = (document.body?.innerText || "").replace(/\\s+/g, " ").trim();
                const lowerText = pageText.toLowerCase();
                const url = location.href;
                const unsafeRe = /\\b(pay\\s*now|make\\s*payment|complete\\s*(booking|reservation|purchase|order)|confirm\\s*(booking|reservation|purchase|order)|place\\s*order|submit\\s*(booking|reservation|order)|final\\s*confirmation)\\b/i;
                const paymentFieldRe = /\\b(card\\s*number|credit\\s*card|debit\\s*card|cvv|cvc|security\\s*code|expiry|expiration|cc-number|cc-exp|payment\\s*method|billing)\\b/i;
                const loginRe = /\\b(sign\\s*in|log\\s*in|login|password|one-time password|otp|verification code)\\b/i;
                const paymentInputs = Array.from(document.querySelectorAll("input, textarea, select"))
                    .filter(visible)
                    .map((el) => ({ label: labelFor(el), type: (el.type || "").toLowerCase(), autocomplete: el.getAttribute("autocomplete") || "" }))
                    .filter((item) => paymentFieldRe.test(`${item.label} ${item.type} ${item.autocomplete}`));
                const passwordInputs = Array.from(document.querySelectorAll('input[type="password"]')).filter(visible).length;
                const captcha = Boolean(
                    document.querySelector('iframe[src*="recaptcha"], iframe[src*="hcaptcha"], [class*="captcha" i], [id*="captcha" i]') ||
                    /\\b(captcha|i am not a robot|verify you are human)\\b/i.test(lowerText)
                );
                const unsafeButtons = Array.from(document.querySelectorAll("button, a, input[type='submit'], input[type='button']"))
                    .filter(visible)
                    .map((el) => ({ text: textOf(el).slice(0, 120), selector: "" }))
                    .filter((item) => unsafeRe.test(item.text));
                const fields = Array.from(document.querySelectorAll("input, textarea, select"))
                    .filter(visible)
                    .map((el, idx) => {
                        const label = labelFor(el);
                        const type = (el.type || el.tagName || "").toLowerCase();
                        const value = el.value || "";
                        const required = Boolean(el.required || el.getAttribute("aria-required") === "true");
                        let kind = "";
                        if (/\\b(first\\s*name|given\\s*name)\\b/i.test(label)) kind = "first_name";
                        else if (/\\b(last\\s*name|surname|family\\s*name)\\b/i.test(label)) kind = "last_name";
                        else if (/\\b(full\\s*name|guest\\s*name|name)\\b/i.test(label)) kind = "full_name";
                        else if (/\\b(email|e-mail)\\b/i.test(label) || type === "email") kind = "email";
                        else if (/\\b(phone|mobile|telephone|contact\\s*number)\\b/i.test(label) || type === "tel") kind = "phone";
                        else if (/\\b(address|city|country|zip|postal)\\b/i.test(label)) kind = "address";
                        else if (/\\b(special\\s*request|arrival|remarks|message)\\b/i.test(label)) kind = "optional_note";
                        const selector = `input, textarea, select`;
                        el.setAttribute("data-meera-field-id", `field-${idx}`);
                        return { id: `field-${idx}`, kind, label: label.slice(0, 140), type, required, empty: !String(value).trim(), selector: `[data-meera-field-id="field-${idx}"]` };
                    })
                    .filter((item) => item.kind && !paymentFieldRe.test(`${item.label} ${item.type}`));
                const safeProgressRe = /\\b(see\\s*availability|show\\s*prices|select\\s*room|choose\\s*(this\\s*)?room|reserve|i'?ll\\s*reserve|book\\s*now|continue|next|continue\\s*to\\s*(booking|checkout|payment)|go\\s*to\\s*checkout|proceed\\s*to\\s*checkout|review\\s*(details|booking)|confirm\\s*details)\\b/i;
                const candidates = Array.from(document.querySelectorAll("button, a, input[type='submit'], input[type='button']"))
                    .filter(visible)
                    .map((el, idx) => {
                        const text = textOf(el);
                        el.setAttribute("data-meera-action-id", `action-${idx}`);
                        let score = 0;
                        if (/see\\s*availability/i.test(text)) score += 20;
                        if (/select|choose/i.test(text)) score += 18;
                        if (/reserve|book\\s*now/i.test(text)) score += 14;
                        if (/continue|next|checkout|review/i.test(text)) score += 12;
                        if (preference && text.toLowerCase().includes(String(preference).toLowerCase())) score += 8;
                        return { text: text.slice(0, 160), selector: `[data-meera-action-id="action-${idx}"]`, score };
                    })
                    .filter((item) => item.text && safeProgressRe.test(item.text) && !unsafeRe.test(item.text))
                    .sort((a, b) => b.score - a.score)
                    .slice(0, 8);
                return {
                    url,
                    title: document.title,
                    at_payment_page: paymentInputs.length > 0 || /\\b(payment details|payment method|card details|billing details)\\b/i.test(lowerText),
                    login_required: passwordInputs > 0 || (/\\b(sign in to continue|log in to continue|enter your password)\\b/i.test(lowerText) && !/continue as guest/i.test(lowerText)),
                    captcha_required: captcha,
                    unsafe_final_actions_visible: unsafeButtons,
                    payment_fields: paymentInputs.slice(0, 8),
                    fillable_fields: fields.slice(0, 20),
                    empty_required_profile_fields: fields.filter((item) => item.required && item.empty && item.kind !== "optional_note").slice(0, 10),
                    next_actions: candidates,
                    page_excerpt: pageText.slice(0, 1200)
                };
            }""",
            preference or "",
        )

    async def _fill_checkout_details_unlocked(self, page: Page, state: dict, guest_details: dict) -> dict:
        details = guest_details if isinstance(guest_details, dict) else {}
        if not details:
            return {"ok": True, "filled": [], "missing": [f for f in state.get("empty_required_profile_fields", [])]}

        def _value_for(kind: str) -> str:
            if kind == "full_name":
                return str(details.get("full_name") or details.get("name") or " ".join(
                    str(details.get(k) or "").strip() for k in ("first_name", "last_name")
                ).strip())
            if kind == "first_name":
                return str(details.get("first_name") or "").strip()
            if kind == "last_name":
                return str(details.get("last_name") or "").strip()
            if kind == "email":
                return str(details.get("email") or "").strip()
            if kind == "phone":
                return str(details.get("phone") or details.get("mobile") or "").strip()
            if kind == "address":
                return str(details.get("address") or details.get("city") or details.get("country") or "").strip()
            if kind == "optional_note":
                return str(details.get("note") or details.get("special_request") or "").strip()
            return ""

        filled: List[dict] = []
        missing: List[dict] = []
        for field in state.get("fillable_fields", []):
            if not isinstance(field, dict) or not field.get("empty"):
                continue
            kind = str(field.get("kind") or "")
            value = _value_for(kind)
            if not value:
                if field.get("required") and kind != "optional_note":
                    missing.append(field)
                continue
            selector = str(field.get("selector") or "")
            try:
                await page.locator(selector).first.fill(value, timeout=2500)
                filled.append({"kind": kind, "label": field.get("label", "")})
            except Exception:
                if field.get("required") and kind != "optional_note":
                    missing.append(field)
        if filled:
            await page.wait_for_timeout(500)
        return {"ok": True, "filled": filled, "missing": missing}

    async def checkout_handoff(
        self,
        preference: str = "",
        guest_details: Optional[dict] = None,
        max_steps: int = 10,
        on_progress=None,
    ) -> dict:
        """Advance a booking flow to the payment handoff screen without paying.

        This routine is deliberately conservative. It may click safe progression
        CTAs and fill user-provided non-payment guest details, but it stops on
        payment fields, login/password/OTP, CAPTCHA, or final confirmation/pay
        controls.
        """
        page = await self._ensure_page()
        max_steps = max(1, min(int(max_steps or 10), 20))
        trace: List[dict] = []
        async with self._lock:
            for step in range(1, max_steps + 1):
                state = await self._checkout_state_unlocked(page, preference)
                if on_progress:
                    await on_progress("checkout_state", {"step": step, "url": state.get("url"), "title": state.get("title")})

                if state.get("captcha_required"):
                    return {"ok": True, "status": "captcha_required", "message": "Stopped at CAPTCHA/human verification.", "trace": trace, "state": state}
                if state.get("login_required"):
                    return {"ok": True, "status": "login_required", "message": "Stopped at login/OTP/password step.", "trace": trace, "state": state}
                if state.get("at_payment_page"):
                    return {"ok": True, "status": "payment_handoff", "message": "Reached the payment page. User must review and pay manually.", "trace": trace, "state": state}
                if state.get("unsafe_final_actions_visible"):
                    return {"ok": True, "status": "final_confirmation_handoff", "message": "Stopped before a final booking/payment confirmation action.", "trace": trace, "state": state}

                fill_result = await self._fill_checkout_details_unlocked(page, state, guest_details or {})
                if fill_result.get("filled"):
                    trace.append({"step": step, "action": "fill_guest_details", **fill_result})
                    state = await self._checkout_state_unlocked(page, preference)
                missing = fill_result.get("missing") or state.get("empty_required_profile_fields") or []
                if missing:
                    return {
                        "ok": True,
                        "status": "requires_user_data",
                        "message": "Required guest details are missing before checkout can continue.",
                        "missing_fields": missing,
                        "trace": trace,
                        "state": state,
                    }

                actions = state.get("next_actions") or []
                if not actions:
                    await page.evaluate("() => window.scrollBy(0, Math.max(650, window.innerHeight * 0.75))")
                    await page.wait_for_timeout(700)
                    trace.append({"step": step, "action": "scroll_for_next_action"})
                    next_state = await self._checkout_state_unlocked(page, preference)
                    if not (next_state.get("next_actions") or []):
                        return {"ok": True, "status": "no_safe_next_action", "message": "No safe booking progression button was visible.", "trace": trace, "state": next_state}
                    state = next_state
                    actions = state.get("next_actions") or []

                action = actions[0]
                selector = str(action.get("selector") or "")
                label = str(action.get("text") or "Continue")
                await page.locator(selector).first.click(timeout=5000)
                await page.wait_for_load_state("domcontentloaded", timeout=12000).catch(lambda _: None) if False else None
                await page.wait_for_timeout(1500)
                trace.append({"step": step, "action": "click_progress", "label": label, "selector": selector, "url": page.url})

            state = await self._checkout_state_unlocked(page, preference)
            return {"ok": True, "status": "step_limit_reached", "message": "Reached the checkout handoff step limit before payment page.", "trace": trace, "state": state}

    async def extract_booking_results(self) -> dict:
        page = await self._ensure_page()
        async with self._lock:
            try:
                cards = await page.evaluate(
                    """() => {
                        const selectors = [
                            '[data-testid="property-card"]',
                            '[data-testid="property-card-container"]',
                            '[data-testid="property-card-desktop-single-image"]',
                            '.sr_property_block',
                            '.property-card',
                            '[role="listitem"]'
                        ];
                        const seen = new Set();
                        const nodes = [];
                        for (const selector of selectors) {
                            for (const node of document.querySelectorAll(selector)) {
                                if (!seen.has(node)) {
                                    seen.add(node);
                                    nodes.push(node);
                                }
                            }
                            if (nodes.length >= 10) break;
                        }
                        const priceRe = /(?:INR|Rs\\.?|₹|US\\$|\\$|€|£)\\s*[\\d,]+(?:\\.\\d{1,2})?|[\\d,]+\\s*(?:INR|Rs\\.?|₹)/i;
                        const pickFromSrcset = (srcset) => {
                            if (!srcset) return "";
                            const parts = String(srcset).split(",").map(x => x.trim()).filter(Boolean);
                            if (!parts.length) return "";
                            return parts[parts.length - 1].split(/\\s+/)[0] || "";
                        };
                        const absolutize = (value) => {
                            if (!value) return "";
                            try { return new URL(value, location.href).href; } catch (e) { return ""; }
                        };
                        return nodes.slice(0, 8).map((node) => {
                            const text = (node.innerText || '').replace(/\\s+/g, ' ').trim();
                            const rawLink = node.querySelector('a[href]')?.href || '';
                            let link = rawLink;
                            try {
                                const u = new URL(rawLink);
                                link = u.origin + u.pathname;
                            } catch (e) {}
                            const title =
                                node.querySelector('[data-testid="title"]')?.innerText ||
                                node.querySelector('h3')?.innerText ||
                                node.querySelector('h2')?.innerText ||
                                (text.split(/\\s{2,}|\\n/)[0] || '').slice(0, 120);
                            const priceText =
                                node.querySelector('[data-testid="price-and-discounted-price"]')?.innerText ||
                                node.querySelector('[data-testid="price-for-x-nights"]')?.innerText ||
                                (text.match(priceRe) || [''])[0];
                            const rating =
                                node.querySelector('[data-testid="review-score"]')?.innerText ||
                                node.querySelector('[aria-label*="Scored"]')?.getAttribute('aria-label') ||
                                '';
                            const imgEl = node.querySelector('img');
                            const image =
                                imgEl ? absolutize(
                                    imgEl.currentSrc ||
                                    imgEl.src ||
                                    imgEl.getAttribute('data-src') ||
                                    imgEl.getAttribute('data-lazy-src') ||
                                    pickFromSrcset(imgEl.getAttribute('srcset')) ||
                                    pickFromSrcset(imgEl.getAttribute('data-srcset')) ||
                                    ''
                                ) : '';
                            return {
                                title: (title || '').replace(/\\s+/g, ' ').trim().slice(0, 160),
                                price: (priceText || '').replace(/\\s+/g, ' ').trim().slice(0, 80),
                                rating: (rating || '').replace(/\\s+/g, ' ').trim().slice(0, 120),
                                link,
                                image,
                                text: text.slice(0, 360)
                            };
                        }).filter(card => card.title || card.price || card.text);
                    }"""
                )
                return {"ok": True, "type": "booking_results", "content": cards}
            except Exception as exc:
                return {"ok": False, "error": str(exc)}

    async def web_search(self, query: str) -> dict:
        target = f"https://www.google.com/search?q={quote_plus(query)}&num=10"
        nav = await self.navigate(target)
        if not nav.get("ok"):
            return nav
        links = await self.extract_page("links")
        text = await self.extract_page("text")
        return {
            "ok": True,
            "query": query,
            "url": nav.get("url"),
            "title": nav.get("title"),
            "links": links.get("content", []) if links.get("ok") else [],
            "content": text.get("content", "") if text.get("ok") else "",
        }

    async def autonomous_flow(self, steps: list, on_progress=None) -> dict:
        results = []
        session_id = uuid.uuid4().hex[:12]
        self._sessions[session_id] = {"started_at": time.time(), "steps": len(steps), "status": "running"}
        for index, raw_step in enumerate(steps):
            if not isinstance(raw_step, dict):
                continue
            action = str(raw_step.get("action") or "").strip().lower()
            label = str(raw_step.get("label") or f"Step {index + 1}: {action}")
            if on_progress:
                await on_progress("step", {"step": index + 1, "total": len(steps), "action": action, "label": label})
            try:
                if action == "navigate":
                    result = await self.navigate(raw_step.get("url", ""), raw_step.get("wait_for", "domcontentloaded"))
                elif action == "click":
                    result = await self.click(raw_step.get("selector", ""))
                elif action == "type":
                    result = await self.type_text(raw_step.get("selector", ""), str(raw_step.get("text") or ""), bool(raw_step.get("clear_first", True)))
                elif action == "select":
                    result = await self.select_option(raw_step.get("selector", ""), str(raw_step.get("value") or ""))
                elif action == "press":
                    result = await self.press_key(str(raw_step.get("key") or "Enter"))
                elif action == "scroll":
                    result = await self.scroll(str(raw_step.get("direction") or "down"), int(raw_step.get("amount") or 700))
                elif action == "wait":
                    result = await self.wait_for_selector(raw_step.get("selector", ""), int(raw_step.get("timeout") or 10000))
                elif action == "extract":
                    result = await self.extract_page(str(raw_step.get("extract_type") or "text"), str(raw_step.get("selector") or ""))
                elif action == "screenshot":
                    result = await self.screenshot(bool(raw_step.get("full_page", False)))
                elif action == "js":
                    result = await self.execute_js(str(raw_step.get("script") or ""))
                elif action == "pause":
                    await asyncio.sleep(float(raw_step.get("seconds") or 1.0))
                    result = {"ok": True, "action": "Paused"}
                else:
                    result = {"ok": False, "error": f"Unknown action: {action}"}
            except Exception as exc:
                result = {"ok": False, "error": str(exc)}
            result = {"step": index + 1, "label": label, "action": action, **result}
            results.append(result)
            if on_progress:
                await on_progress("step_complete", {"step": index + 1, "ok": bool(result.get("ok"))})
            if not result.get("ok") and raw_step.get("critical", False):
                break
        self._sessions[session_id]["status"] = "completed"
        return {"ok": True, "session_id": session_id, "steps_completed": len(results), "results": results}

    async def autonomous_book(self, steps: list, on_progress=None) -> dict:
        return await self.autonomous_flow(steps, on_progress=on_progress)

    async def fill_form(self, fields: dict, submit_selector: Optional[str] = None) -> dict:
        """Automatically inspect and fill multiple input/textarea/select fields and optionally submit."""
        page = await self._ensure_page()
        async with self._lock:
            results = []
            for field_key, value in fields.items():
                filled = False
                val_str = str(value)
                candidates = [
                    f'input[name="{field_key}"]',
                    f'textarea[name="{field_key}"]',
                    f'input[id="{field_key}"]',
                    f'textarea[id="{field_key}"]',
                    f'input[placeholder*="{field_key}" i]',
                    f'textarea[placeholder*="{field_key}" i]',
                    f'input[aria-label*="{field_key}" i]',
                    f'select[name="{field_key}"]',
                    f'select[id="{field_key}"]',
                    field_key,
                ]
                for sel in candidates:
                    try:
                        loc = page.locator(sel).first
                        if await loc.count() > 0 and await loc.is_visible():
                            tag_name = await loc.evaluate("el => el.tagName.toLowerCase()")
                            if tag_name == "select":
                                await loc.select_option(label=val_str)
                            elif tag_name in ("input", "textarea"):
                                input_type = await loc.evaluate("el => el.type ? el.type.toLowerCase() : ''")
                                if input_type in ("checkbox", "radio"):
                                    if val_str.lower() in ("true", "1", "yes", "on"):
                                        await loc.check()
                                else:
                                    await loc.fill(val_str)
                            filled = True
                            results.append({"field": field_key, "selector": sel, "status": "filled", "value": val_str})
                            break
                    except Exception:
                        continue
                if not filled:
                    results.append({"field": field_key, "status": "not_found"})

            submitted = False
            if submit_selector:
                try:
                    loc = page.locator(submit_selector).first
                    if await loc.count() > 0:
                        await loc.click()
                        await page.wait_for_timeout(1000)
                        submitted = True
                except Exception as e:
                    logger.debug(f"Submit button click failed: {e}")

            return {
                "ok": True,
                "fields_processed": len(results),
                "details": results,
                "submitted": submitted,
                "url": page.url,
            }


