    def get_gmail_tool_definitions(self) -> list:
        """
        Return the Gmail tool definitions (search, read, send).

        Deliberately no `token` parameter on any of these: the model never
        sees or handles the OAuth token. Whether Gmail is connected and
        which account it's connected to is entirely a server-side fact
        (self.oauth_tokens), checked in _execute_builtin_tool. This also
        sidesteps the earlier failure mode where small local models would
        mangle a long token string when asked to reproduce it in a tool call.
        """
        return [
            {
                "type": "function",
                "function": {
                    "name": "search_gmail",
                    "description": (
                        "Search the user's connected Gmail inbox for messages matching a query. "
                        "Returns sender, date, subject, and a short snippet for each match. "
                        "Use this when the user asks about their emails, inbox, or messages."
                    ),
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "query": {
                                "type": "string",
                                "description": "Gmail search query (e.g. 'is:inbox', 'from:boss', 'subject:urgent', 'is:unread').",
                            },
                            "max_results": {
                                "type": "integer",
                                "description": "Maximum number of emails to fetch (default 5).",
                            },
                        },
                        "required": ["query"],
                    },
                },
                "mcp_server": "__builtin__",
            },
            {
                "type": "function",
                "function": {
                    "name": "read_gmail_message",
                    "description": (
                        "Fetch the full body of a single Gmail message by its message id. "
                        "Use this after search_gmail to read the complete content of a specific email, "
                        "not just its snippet."
                    ),
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "message_id": {
                                "type": "string",
                                "description": "The Gmail message id, as returned by search_gmail.",
                            },
                        },
                        "required": ["message_id"],
                    },
                },
                "mcp_server": "__builtin__",
            },
            {
                "type": "function",
                "function": {
                    "name": "send_gmail",
                    "description": (
                        "Send an email from the user's connected Gmail account. "
                        "Only call this after the user has clearly asked you to send this specific "
                        "email - confirm recipient, subject, and body with the user first if there's "
                        "any ambiguity about what they want sent."
                    ),
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "to": {
                                "type": "string",
                                "description": "Recipient email address.",
                            },
                            "subject": {
                                "type": "string",
                                "description": "Email subject line.",
                            },
                            "body": {
                                "type": "string",
                                "description": "Plain-text email body.",
                            },
                        },
                        "required": ["to", "subject", "body"],
                    },
                },
                "mcp_server": "__builtin__",
            },
            {
                "type": "function",
                "function": {
                    "name": "reply_gmail",
                    "description": (
                        "Reply in-thread to a Gmail message from the user's connected Gmail account. "
                        "Use this when the user asks you to reply to an email found with search_gmail "
                        "or read_gmail_message."
                    ),
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "message_id": {
                                "type": "string",
                                "description": "The Gmail message id being replied to.",
                            },
                            "body": {
                                "type": "string",
                                "description": "Plain-text reply body.",
                            },
                        },
                        "required": ["message_id", "body"],
                    },
                },
                "mcp_server": "__builtin__",
            },
        ]

    async def _search_gmail(self, token: str, query: str, max_results: int = 5) -> dict:
        """Execute the search_gmail tool logic using the Gmail API."""
        def _header(headers_list: list, name: str, default: str = "") -> str:
            return next((h.get("value", "") for h in headers_list if h.get("name", "").lower() == name.lower()), default)

        try:
            async with httpx.AsyncClient() as client:
                headers = {"Authorization": f"Bearer {token}"}
                list_url = "https://gmail.googleapis.com/gmail/v1/users/me/messages"
                params = {"q": query, "maxResults": max_results}
                resp = await client.get(list_url, headers=headers, params=params, timeout=10.0)
                if not resp.is_success:
                    return {"content": f"Failed to search Gmail: {resp.text}", "is_error": True}

                data = resp.json()
                messages = data.get("messages", [])
                if not messages:
                    return {"content": "No emails found matching the query.", "is_error": False}

                email_summaries = []
                for msg in messages:
                    msg_id = msg.get("id")
                    if not msg_id:
                        continue
                    msg_url = f"https://gmail.googleapis.com/gmail/v1/users/me/messages/{msg_id}"
                    msg_resp = await client.get(
                        msg_url, headers=headers,
                        params={"format": "metadata", "metadataHeaders": ["Subject", "From", "Date"]},
                        timeout=5.0,
                    )
                    if msg_resp.is_success:
                        msg_data = msg_resp.json()
                        snippet = msg_data.get("snippet", "")
                        thread_id = msg_data.get("threadId", "")
                        headers_list = msg_data.get("payload", {}).get("headers", [])
                        subject = _header(headers_list, "Subject", "No Subject")
                        from_addr = _header(headers_list, "From", "Unknown Sender")
                        date = _header(headers_list, "Date", "Unknown Date")
                        email_summaries.append(
                            f"id: {msg_id}\nthread_id: {thread_id}\nFrom: {from_addr}\nDate: {date}\nSubject: {subject}\nSnippet: {snippet}\n---"
                        )

                if not email_summaries:
                    return {"content": "Found messages but failed to fetch their details.", "is_error": True}

                return {"content": "Found emails:\n\n" + "\n".join(email_summaries), "is_error": False}
        except Exception as e:
            logger.error(f"Error fetching Gmail: {e}")
            return {"content": f"Error accessing Gmail API: {str(e)}", "is_error": True}

    async def _read_gmail_message(self, token: str, message_id: str) -> dict:
        """Fetch the full body of a single Gmail message."""
        def _header(headers_list: list, name: str, default: str = "") -> str:
            return next((h.get("value", "") for h in headers_list if h.get("name", "").lower() == name.lower()), default)

        try:
            async with httpx.AsyncClient() as client:
                headers = {"Authorization": f"Bearer {token}"}
                msg_url = f"https://gmail.googleapis.com/gmail/v1/users/me/messages/{message_id}"
                resp = await client.get(msg_url, headers=headers, params={"format": "full"}, timeout=10.0)
                if not resp.is_success:
                    return {"content": f"Failed to fetch message: {resp.text}", "is_error": True}

                msg_data = resp.json()
                headers_list = msg_data.get("payload", {}).get("headers", [])
                subject = _header(headers_list, "Subject", "No Subject")
                from_addr = _header(headers_list, "From", "Unknown Sender")
                date = _header(headers_list, "Date", "Unknown Date")
                message_id_header = _header(headers_list, "Message-ID")
                references = _header(headers_list, "References")
                thread_id = msg_data.get("threadId", "")

                body_text = self._extract_gmail_body(msg_data.get("payload", {}))
                if not body_text:
                    body_text = msg_data.get("snippet", "(no readable body found)")

                return {
                    "content": (
                        f"id: {message_id}\nthread_id: {thread_id}\nFrom: {from_addr}\nDate: {date}\n"
                        f"Subject: {subject}\nMessage-ID: {message_id_header}\nReferences: {references}\n\n{body_text}"
                    ),
                    "is_error": False,
                }
        except Exception as e:
            logger.error(f"Error reading Gmail message: {e}")
            return {"content": f"Error reading Gmail message: {str(e)}", "is_error": True}

    def _extract_gmail_body(self, payload: dict) -> str:
        """Recursively pull a text/plain (preferred) or text/html body out of a Gmail payload."""
        import base64 as _base64

        def _decode(data: str) -> str:
            try:
                return _base64.urlsafe_b64decode(data.encode("utf-8")).decode("utf-8", errors="replace")
            except Exception:
                return ""

        mime_type = payload.get("mimeType", "")
        body = payload.get("body", {})
        if mime_type == "text/plain" and body.get("data"):
            return _decode(body["data"])

        parts = payload.get("parts", [])
        plain_fallback = ""
        for part in parts:
            part_mime = part.get("mimeType", "")
            part_body = part.get("body", {})
            if part_mime == "text/plain" and part_body.get("data"):
                return _decode(part_body["data"])
            if part_mime == "text/html" and part_body.get("data") and not plain_fallback:
                plain_fallback = _decode(part_body["data"])
            if part.get("parts"):
                nested = self._extract_gmail_body(part)
                if nested:
                    return nested
        return plain_fallback

    async def _send_gmail(self, token: str, to: str, subject: str, body: str) -> dict:
        """Send an email via the Gmail API using the authenticated user's account."""
        import base64 as _base64
        from email.mime.text import MIMEText

        try:
            mime_msg = MIMEText(body)
            mime_msg["to"] = to
            mime_msg["subject"] = subject
            raw = _base64.urlsafe_b64encode(mime_msg.as_bytes()).decode("utf-8")

            async with httpx.AsyncClient() as client:
                headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
                send_url = "https://gmail.googleapis.com/gmail/v1/users/me/messages/send"
                resp = await client.post(send_url, headers=headers, json={"raw": raw}, timeout=10.0)
                if not resp.is_success:
                    return {"content": f"Failed to send email: {resp.text}", "is_error": True}

                return {"content": f"Email sent to {to} with subject '{subject}'.", "is_error": False}
        except Exception as e:
            logger.error(f"Error sending Gmail message: {e}")
            return {"content": f"Error sending email: {str(e)}", "is_error": True}

    async def _reply_gmail(self, token: str, message_id: str, body: str) -> dict:
        """Reply to a Gmail message in its original thread."""
        import base64 as _base64
        from email.mime.text import MIMEText
        from email.utils import parseaddr

        def _header(headers_list: list, name: str, default: str = "") -> str:
            return next((h.get("value", "") for h in headers_list if h.get("name", "").lower() == name.lower()), default)

        try:
            async with httpx.AsyncClient() as client:
                headers = {"Authorization": f"Bearer {token}"}
                msg_url = f"https://gmail.googleapis.com/gmail/v1/users/me/messages/{message_id}"
                resp = await client.get(
                    msg_url,
                    headers=headers,
                    params={"format": "metadata", "metadataHeaders": ["Subject", "From", "Reply-To", "Message-ID", "References"]},
                    timeout=10.0,
                )
                if not resp.is_success:
                    return {"content": f"Failed to fetch original message for reply: {resp.text}", "is_error": True}

                original = resp.json()
                thread_id = original.get("threadId")
                headers_list = original.get("payload", {}).get("headers", [])
                subject = _header(headers_list, "Subject", "No Subject")
                reply_to = _header(headers_list, "Reply-To") or _header(headers_list, "From")
                original_message_id = _header(headers_list, "Message-ID")
                references = _header(headers_list, "References")
                recipient = parseaddr(reply_to)[1] or reply_to
                if not recipient:
                    return {"content": "Could not determine who to reply to.", "is_error": True}

                reply_subject = subject if subject.lower().startswith("re:") else f"Re: {subject}"
                mime_msg = MIMEText(body)
                mime_msg["to"] = recipient
                mime_msg["subject"] = reply_subject
                if original_message_id:
                    mime_msg["In-Reply-To"] = original_message_id
                    mime_msg["References"] = f"{references} {original_message_id}".strip()

                raw = _base64.urlsafe_b64encode(mime_msg.as_bytes()).decode("utf-8")
                send_url = "https://gmail.googleapis.com/gmail/v1/users/me/messages/send"
                send_resp = await client.post(
                    send_url,
                    headers={**headers, "Content-Type": "application/json"},
                    json={"raw": raw, "threadId": thread_id} if thread_id else {"raw": raw},
                    timeout=10.0,
                )
                if not send_resp.is_success:
                    return {"content": f"Failed to send Gmail reply: {send_resp.text}", "is_error": True}
                return {"content": f"Reply sent to {recipient} in thread {thread_id or message_id}.", "is_error": False}
        except Exception as e:
            logger.error(f"Error replying to Gmail message: {e}")
            return {"content": f"Error replying to email: {str(e)}", "is_error": True}

    def _get_email_config(self, request: Optional[ChatCompletionRequest] = None) -> dict:
        """Extract email IMAP/SMTP configuration from request or environment variables."""
        cfg = {}
        if request and getattr(request, "email_config", None) and isinstance(request.email_config, dict):
            cfg.update(request.email_config)

        # Fallback to environment variables
        cfg.setdefault("email_user", os.getenv("EMAIL_USER") or os.getenv("IMAP_USER") or os.getenv("SMTP_USER") or "")
        cfg.setdefault("email_pass", os.getenv("EMAIL_PASS") or os.getenv("IMAP_PASS") or os.getenv("SMTP_PASS") or os.getenv("EMAIL_PASSWORD") or "")
        cfg.setdefault("imap_server", os.getenv("IMAP_SERVER") or "")
        cfg.setdefault("imap_port", int(os.getenv("IMAP_PORT") or 993))
        cfg.setdefault("smtp_server", os.getenv("SMTP_SERVER") or "")
        cfg.setdefault("smtp_port", int(os.getenv("SMTP_PORT") or 587))
        cfg.setdefault("sender_name", os.getenv("SENDER_NAME") or "Meera AI")

        # Auto-infer servers from email domain if server was not explicitly set
        user = cfg.get("email_user", "").strip()
        if user and "@" in user:
            domain = user.split("@")[-1].lower()
            if not cfg.get("imap_server"):
                if "gmail" in domain:
                    cfg["imap_server"] = "imap.gmail.com"
                elif "outlook" in domain or "hotmail" in domain or "live" in domain:
                    cfg["imap_server"] = "outlook.office365.com"
                elif "yahoo" in domain:
                    cfg["imap_server"] = "imap.mail.yahoo.com"
                elif "icloud" in domain:
                    cfg["imap_server"] = "imap.mail.me.com"
            if not cfg.get("smtp_server"):
                if "gmail" in domain:
                    cfg["smtp_server"] = "smtp.gmail.com"
                elif "outlook" in domain or "hotmail" in domain or "live" in domain:
                    cfg["smtp_server"] = "smtp.office365.com"
                elif "yahoo" in domain:
                    cfg["smtp_server"] = "smtp.mail.yahoo.com"
                elif "icloud" in domain:
                    cfg["smtp_server"] = "smtp.mail.me.com"
        return cfg

    async def _exec_list_recent_emails(self, args: dict, request: Optional[ChatCompletionRequest] = None) -> dict:
        """Fetch recent emails via standard IMAP."""
        import imaplib
        import email
        from email.header import decode_header

        cfg = self._get_email_config(request)
        user = cfg.get("email_user")
        pwd = cfg.get("email_pass")
        server = cfg.get("imap_server")
        port = int(cfg.get("imap_port") or 993)

        if not user or not pwd or not server:
            return {
                "content": (
                    "Email IMAP configuration is missing. Please configure your email in the "
                    "Settings > Integrations > Email (IMAP) panel or set EMAIL_USER, EMAIL_PASS, "
                    "and IMAP_SERVER environment variables."
                ),
                "is_error": True,
            }

        folder = str(args.get("folder") or "INBOX").strip()
        limit = max(1, min(int(args.get("limit") or 10), 50))

        def _decode_header_str(val: Any) -> str:
            if not val:
                return ""
            decoded = []
            for part, enc in decode_header(str(val)):
                if isinstance(part, bytes):
                    decoded.append(part.decode(enc or "utf-8", errors="replace"))
                else:
                    decoded.append(str(part))
            return "".join(decoded)

        def _fetch_sync():
            mail = None
            try:
                if port == 993:
                    mail = imaplib.IMAP4_SSL(server, port, timeout=15)
                else:
                    mail = imaplib.IMAP4(server, port, timeout=15)
                    try:
                        mail.starttls()
                    except Exception:
                        pass
                mail.login(user, pwd)
                status, _ = mail.select(folder, readonly=True)
                if status != "OK":
                    return {"content": f"Failed to select mailbox folder '{folder}'.", "is_error": True}

                status, messages = mail.search(None, "ALL")
                if status != "OK" or not messages or not messages[0]:
                    return {"content": f"No emails found in folder '{folder}'.", "is_error": False}

                msg_ids = messages[0].split()
                recent_ids = msg_ids[-limit:]
                recent_ids.reverse()

                summaries = []
                for mid in recent_ids:
                    mid_str = mid.decode("utf-8", errors="ignore")
                    res, data = mail.fetch(mid, "(BODY.PEEK[HEADER.FIELDS (SUBJECT FROM TO DATE MESSAGE-ID)])")
                    if res != "OK" or not data or not isinstance(data[0], tuple):
                        continue
                    msg = email.message_from_bytes(data[0][1])
                    subject = _decode_header_str(msg.get("Subject", "No Subject"))
                    from_addr = _decode_header_str(msg.get("From", "Unknown Sender"))
                    to_addr = _decode_header_str(msg.get("To", ""))
                    date_hdr = _decode_header_str(msg.get("Date", ""))
                    msg_id_hdr = _decode_header_str(msg.get("Message-ID", ""))
                    summaries.append(
                        f"ID: {mid_str}\nFrom: {from_addr}\nTo: {to_addr}\nDate: {date_hdr}\nSubject: {subject}\nMessage-ID: {msg_id_hdr}\n---"
                    )

                if not summaries:
                    return {"content": f"No messages could be retrieved from '{folder}'.", "is_error": False}

                return {
                    "content": f"Found {len(summaries)} recent email(s) in '{folder}':\n\n" + "\n".join(summaries),
                    "is_error": False,
                }
            except Exception as exc:
                return {"content": f"IMAP error while listing emails: {exc}", "is_error": True}
            finally:
                if mail:
                    try:
                        mail.close()
                    except Exception:
                        pass
                    try:
                        mail.logout()
                    except Exception:
                        pass

        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(None, _fetch_sync)

    async def _exec_read_email(self, args: dict, request: Optional[ChatCompletionRequest] = None) -> dict:
        """Read a specific email's full content via standard IMAP."""
        import imaplib
        import email
        from email.header import decode_header

        cfg = self._get_email_config(request)
        user = cfg.get("email_user")
        pwd = cfg.get("email_pass")
        server = cfg.get("imap_server")
        port = int(cfg.get("imap_port") or 993)

        if not user or not pwd or not server:
            return {
                "content": "Email IMAP configuration is missing. Please configure your email in Settings > Integrations.",
                "is_error": True,
            }

        email_id = str(args.get("email_id") or args.get("message_id") or "").strip()
        if not email_id:
            return {"content": "read_email requires an 'email_id' or 'message_id'.", "is_error": True}

        folder = str(args.get("folder") or "INBOX").strip()

        def _decode_header_str(val: Any) -> str:
            if not val:
                return ""
            decoded = []
            for part, enc in decode_header(str(val)):
                if isinstance(part, bytes):
                    decoded.append(part.decode(enc or "utf-8", errors="replace"))
                else:
                    decoded.append(str(part))
            return "".join(decoded)

        def _extract_body(msg: email.message.Message) -> str:
            plain_body = ""
            html_body = ""
            if msg.is_multipart():
                for part in msg.walk():
                    content_type = part.get_content_type()
                    content_disposition = str(part.get("Content-Disposition") or "")
                    if "attachment" in content_disposition:
                        continue
                    payload = part.get_payload(decode=True)
                    if not payload:
                        continue
                    charset = part.get_content_charset() or "utf-8"
                    text = payload.decode(charset, errors="replace")
                    if content_type == "text/plain":
                        plain_body += text + "\n"
                    elif content_type == "text/html" and not plain_body:
                        html_body += text + "\n"
            else:
                payload = msg.get_payload(decode=True)
                if payload:
                    charset = msg.get_content_charset() or "utf-8"
                    text = payload.decode(charset, errors="replace")
                    if msg.get_content_type() == "text/html":
                        html_body = text
                    else:
                        plain_body = text

            if plain_body.strip():
                return plain_body.strip()
            if html_body.strip():
                clean = re.sub(r'<[^<]+?>', '', html_body)
                return clean.strip()
            return "(Empty message body)"

        def _read_sync():
            mail = None
            try:
                if port == 993:
                    mail = imaplib.IMAP4_SSL(server, port, timeout=15)
                else:
                    mail = imaplib.IMAP4(server, port, timeout=15)
                    try:
                        mail.starttls()
                    except Exception:
                        pass
                mail.login(user, pwd)
                mail.select(folder, readonly=True)

                res, data = mail.fetch(email_id.encode("utf-8"), "(RFC822)")
                if res != "OK" or not data or not isinstance(data[0], tuple):
                    status, search_res = mail.search(None, f'(HEADER Message-ID "{email_id}")')
                    if status == "OK" and search_res and search_res[0]:
                        matched_id = search_res[0].split()[-1]
                        res, data = mail.fetch(matched_id, "(RFC822)")
                    if res != "OK" or not data or not isinstance(data[0], tuple):
                        return {"content": f"Could not find email with ID '{email_id}' in '{folder}'.", "is_error": True}

                raw_bytes = data[0][1]
                msg = email.message_from_bytes(raw_bytes)

                subject = _decode_header_str(msg.get("Subject", "No Subject"))
                from_addr = _decode_header_str(msg.get("From", "Unknown Sender"))
                to_addr = _decode_header_str(msg.get("To", ""))
                date_hdr = _decode_header_str(msg.get("Date", ""))
                msg_id_hdr = _decode_header_str(msg.get("Message-ID", ""))
                reply_to = _decode_header_str(msg.get("Reply-To", ""))
                body_content = _extract_body(msg)

                return {
                    "content": (
                        f"ID: {email_id}\nFrom: {from_addr}\nTo: {to_addr}\n"
                        f"Reply-To: {reply_to}\nDate: {date_hdr}\n"
                        f"Subject: {subject}\nMessage-ID: {msg_id_hdr}\n\n"
                        f"--- Body ---\n{body_content}"
                    ),
                    "is_error": False,
                }
            except Exception as exc:
                return {"content": f"IMAP error reading email: {exc}", "is_error": True}
            finally:
                if mail:
                    try:
                        mail.close()
                    except Exception:
                        pass
                    try:
                        mail.logout()
                    except Exception:
                        pass

        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(None, _read_sync)

    async def _exec_send_email(self, args: dict, request: Optional[ChatCompletionRequest] = None) -> dict:
        """Send an email via standard SMTP."""
        import smtplib
        from email.mime.text import MIMEText
        from email.mime.multipart import MIMEMultipart
        from email.utils import formataddr

        cfg = self._get_email_config(request)
        user = cfg.get("email_user")
        pwd = cfg.get("email_pass")
        server = cfg.get("smtp_server")
        port = int(cfg.get("smtp_port") or 587)
        sender_name = cfg.get("sender_name") or "Meera AI"

        if not user or not pwd or not server:
            return {
                "content": (
                    "Email SMTP configuration is missing. Please configure your email in "
                    "Settings > Integrations > Email (IMAP) or set EMAIL_USER, EMAIL_PASS, "
                    "and SMTP_SERVER environment variables."
                ),
                "is_error": True,
            }

        to_addr = str(args.get("to") or "").strip()
        subject = str(args.get("subject") or "").strip()
        body = str(args.get("body") or "").strip()
        cc = str(args.get("cc") or "").strip()
        bcc = str(args.get("bcc") or "").strip()
        in_reply_to = str(args.get("in_reply_to") or "").strip()
        references = str(args.get("references") or "").strip()

        if not to_addr:
            return {"content": "send_email requires a recipient ('to').", "is_error": True}
        if not subject:
            subject = "(No Subject)"

        def _send_sync():
            try:
                msg = MIMEMultipart()
                msg["From"] = formataddr((sender_name, user))
                msg["To"] = to_addr
                msg["Subject"] = subject
                if cc:
                    msg["Cc"] = cc
                if in_reply_to:
                    msg["In-Reply-To"] = in_reply_to
                if references:
                    msg["References"] = references

                msg.attach(MIMEText(body, "plain", "utf-8"))

                recipients = [addr.strip() for addr in to_addr.split(",") if addr.strip()]
                if cc:
                    recipients.extend([addr.strip() for addr in cc.split(",") if addr.strip()])
                if bcc:
                    recipients.extend([addr.strip() for addr in bcc.split(",") if addr.strip()])

                if port == 465:
                    smtp = smtplib.SMTP_SSL(server, port, timeout=20)
                else:
                    smtp = smtplib.SMTP(server, port, timeout=20)
                    try:
                        smtp.ehlo()
                        smtp.starttls()
                        smtp.ehlo()
                    except Exception:
                        pass

                smtp.login(user, pwd)
                smtp.sendmail(user, recipients, msg.as_string())
                smtp.quit()

                return {
                    "content": f"Successfully sent email to '{to_addr}' with subject '{subject}'.",
                    "is_error": False,
                }
            except Exception as exc:
                return {"content": f"SMTP error sending email: {exc}", "is_error": True}

        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(None, _send_sync)

    async def _exec_reply_email(self, args: dict, request: Optional[ChatCompletionRequest] = None) -> dict:
        """Reply to an email via standard SMTP/IMAP."""
        email_id = str(args.get("email_id") or args.get("message_id") or "").strip()
        to_addr = str(args.get("to") or "").strip()
        subject = str(args.get("subject") or "").strip()
        body = str(args.get("body") or "").strip()
        in_reply_to = ""
        references = ""

        if email_id and (not to_addr or not subject):
            orig = await self._exec_read_email({"email_id": email_id, "folder": args.get("folder", "INBOX")}, request)
            if not orig.get("is_error") and orig.get("content"):
                lines = orig["content"].splitlines()
                orig_from = ""
                orig_sub = ""
                for line in lines:
                    if line.startswith("From: ") and not to_addr:
                        orig_from = line[6:].strip()
                    elif line.startswith("Reply-To: ") and line[10:].strip():
                        orig_from = line[10:].strip()
                    elif line.startswith("Subject: ") and not subject:
                        orig_sub = line[9:].strip()
                    elif line.startswith("Message-ID: "):
                        in_reply_to = line[12:].strip()
                        references = in_reply_to
                if not to_addr and orig_from:
                    to_addr = orig_from
                if not subject and orig_sub:
                    subject = orig_sub if orig_sub.lower().startswith("re:") else f"Re: {orig_sub}"

        if not to_addr:
            return {"content": "reply_email requires a recipient or valid email_id to reply to.", "is_error": True}
        if not subject:
            subject = "Re: Your message"

        args_to_send = {
            "to": to_addr,
            "subject": subject,
            "body": body,
            "in_reply_to": in_reply_to,
            "references": references,
        }
        return await self._exec_send_email(args_to_send, request)

    async def _exec_send_whatsapp_message(self, args: dict) -> dict:
        """Open or send a WhatsApp message to a phone number via deep link / browser."""
        import urllib.parse
        import platform
        import subprocess

        phone = str(args.get("phone") or "").strip()
        message = str(args.get("message") or args.get("text") or "").strip()

        if not message:
            return {"content": "send_whatsapp_message requires a 'message'.", "is_error": True}

        clean_phone = re.sub(r"[^\d]", "", phone)
        encoded_msg = urllib.parse.quote(message)

        if clean_phone:
            app_uri = f"whatsapp://send?phone={clean_phone}&text={encoded_msg}"
            web_url = f"https://web.whatsapp.com/send?phone={clean_phone}&text={encoded_msg}"
        else:
            app_uri = f"whatsapp://send?text={encoded_msg}"
            web_url = f"https://web.whatsapp.com/send?text={encoded_msg}"

        system = platform.system()
        method_used = ""

        try:
            if system == "Darwin":
                subprocess.run(["open", app_uri], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                method_used = "WhatsApp protocol on macOS"
            elif system == "Windows":
                try:
                    os.startfile(app_uri)
                    method_used = "WhatsApp protocol on Windows"
                except Exception:
                    subprocess.run(["explorer", web_url], check=False)
                    method_used = "WhatsApp Web in default browser"
            else:
                subprocess.run(["xdg-open", app_uri], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                method_used = "WhatsApp protocol via xdg-open"
        except Exception as exc:
            logger.warning(f"Failed to open native WhatsApp deep link: {exc}")

        recipient_info = f"to +{clean_phone}" if clean_phone else "(no recipient specified, text sharing mode)"
        return {
            "content": (
                f"WhatsApp message dispatched {recipient_info} via {method_used or 'protocol handler'}.\n"
                f"Direct WhatsApp link: {web_url}\n"
                f"Message preview: {message[:120]}..."
            ),
            "is_error": False,
            "whatsapp_link": web_url,
            "whatsapp_uri": app_uri,
        }

    def get_github_tool_definitions(self) -> list:
        """Private GitHub tools. OAuth tokens stay server-side and are never exposed to models."""
        return [
            {"type":"function","function":{"name":"search_github","description":"Search the user's private GitHub repositories and code. Use the connected GitHub account; never ask for a token if OAuth is connected.","parameters":{"type":"object","properties":{"query":{"type":"string","description":"GitHub search query."},"scope":{"type":"string","enum":["repositories","code","issues"],"description":"What to search."},"max_results":{"type":"integer","description":"Maximum results, default 8."}},"required":["query"]}},"mcp_server":"__builtin__"},
            {"type":"function","function":{"name":"read_github_file","description":"Read a file from a private GitHub repository at a ref/branch. Use after finding the repository/path.","parameters":{"type":"object","properties":{"owner":{"type":"string"},"repo":{"type":"string"},"path":{"type":"string"},"ref":{"type":"string","description":"Optional branch, tag, or commit."}},"required":["owner","repo","path"]}},"mcp_server":"__builtin__"},
            {"type":"function","function":{"name":"create_github_issue","description":"Create an issue in a private GitHub repository. Use only when the user explicitly asks; confirm title/body before submission if either is ambiguous.","parameters":{"type":"object","properties":{"owner":{"type":"string"},"repo":{"type":"string"},"title":{"type":"string"},"body":{"type":"string"}},"required":["owner","repo","title","body"]}},"mcp_server":"__builtin__"},
        ]

    def get_gdrive_tool_definitions(self) -> list:
        """Private Google Drive tools backed by the same Google OAuth connection."""
        return [
            {"type":"function","function":{"name":"search_gdrive","description":"Search the user's connected Google Drive for files by name or full-text query.","parameters":{"type":"object","properties":{"query":{"type":"string"},"max_results":{"type":"integer","description":"Maximum results, default 10."}},"required":["query"]}},"mcp_server":"__builtin__"},
            {"type":"function","function":{"name":"read_gdrive_file","description":"Read/export a Google Drive file the user has access to. Google Docs are exported as text; text files are returned directly.","parameters":{"type":"object","properties":{"file_id":{"type":"string"}},"required":["file_id"]}},"mcp_server":"__builtin__"},
        ]

    async def _execute_builtin_tool(self, tool_name: str, args: dict, messages: list = None, request: Optional[ChatCompletionRequest] = None, event_callback: Optional[Any] = None) -> dict:
        """Execute built-in tools (image search, web search, file tools)."""

        # `skip_terminal_autoexec` is a hard safety boundary for normal chat.
        # Keep this guard at the execution point as well as hiding terminal
        # schemas, because weak local models can emit raw tool syntax that the
        # recovery parser recognizes even when the schema was not offered.
        if request and request.skip_terminal_autoexec and (
            tool_name == "execute_terminal" or tool_name.startswith("terminal_")
        ):
            return {
                "content": "Terminal execution is disabled for this chat request.",
                "is_error": True,
            }

        # The model never supplies a token for any Gmail tool -- the tool
        # schemas don't even expose a `token` parameter. Access tokens are
        # looked up here, server-side, from self.oauth_tokens, refreshed if
        # needed, and used directly. This also means a mangled/typo'd token
        # from the model can never happen, since the model never types one.
        _GMAIL_TOOL_NAMES = ("search_gmail", "read_gmail_message", "send_gmail", "reply_gmail")
        gmail_token = None
        if tool_name in _GMAIL_TOOL_NAMES:
            gmail_entry = self.oauth_tokens.get("gmail") or self.oauth_tokens.get("google")
            if gmail_entry and gmail_entry.get("access_token"):
                if gmail_entry.get("expires_at") and time.time() > gmail_entry["expires_at"]:
                    gmail_entry = self._refresh_google_token_ref(gmail_entry)
                if gmail_entry.get("access_token"):
                    gmail_token = gmail_entry.get("access_token", "")
            if not gmail_token:
                email_cfg = self._get_email_config(request)
                if email_cfg.get("email_user") and email_cfg.get("email_pass"):
                    logger.info(f"Gmail OAuth token absent; routing {tool_name} through standard IMAP/SMTP")
                    if tool_name == "search_gmail":
                        return await self._exec_list_recent_emails(args, request)
                    elif tool_name == "read_gmail_message":
                        return await self._exec_read_email(args, request)
                    elif tool_name == "send_gmail":
                        return await self._exec_send_email(args, request)
                    elif tool_name == "reply_gmail":
                        return await self._exec_reply_email(args, request)
                return {
                    "content": (
                        "Gmail isn't connected yet and no IMAP/SMTP credentials were provided. "
                        "Please configure your email in Settings > Integrations > Email (IMAP) or connect your Gmail account."
                    ),
                    "is_error": True,
                }
        elif tool_name in ("search_github", "read_github_file", "create_github_issue"):
            github_entry = self.oauth_tokens.get("github") or {}
            github_token = str(github_entry.get("access_token") or "")
            if not github_token:
                return {"content": "GitHub is not connected yet. Connect GitHub from MeeraAI Settings or the in-chat Connect GitHub action.", "is_error": True, "integration_required": "github"}
            headers = {"Authorization": f"Bearer {github_token}", "Accept": "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28"}
            try:
                async with httpx.AsyncClient(timeout=30.0) as client:
                    if tool_name == "search_github":
                        query = str(args.get("query") or "").strip()
                        scope = str(args.get("scope") or "repositories").strip().lower()
                        limit = max(1, min(int(args.get("max_results") or 8), 20))
                        endpoint = {"repositories":"https://api.github.com/search/repositories","code":"https://api.github.com/search/code","issues":"https://api.github.com/search/issues"}.get(scope, "https://api.github.com/search/repositories")
                        resp = await client.get(endpoint, params={"q": query, "per_page": limit}, headers=headers); resp.raise_for_status(); data = resp.json()
                        items = data.get("items") or []
                        lines = []
                        for item in items[:limit]:
                            name = item.get("full_name") or item.get("name") or "unknown"
                            url = item.get("html_url") or ""
                            desc = (item.get("description") or "").replace("\n", " ")[:220]
                            lines.append(f"- **{name}** — {desc}\n  {url}")
                        return {"content": "GitHub search results:\n" + ("\n".join(lines) if lines else "No matching GitHub results found."), "is_error": False}
                    if tool_name == "read_github_file":
                        owner, repo, path = str(args.get("owner") or ""), str(args.get("repo") or ""), str(args.get("path") or "")
                        url = f"https://api.github.com/repos/{urllib.parse.quote(owner)}/{urllib.parse.quote(repo)}/contents/{urllib.parse.quote(path, safe='/')}"
                        resp = await client.get(url, params={"ref": str(args.get("ref") or "")} if args.get("ref") else None, headers=headers); resp.raise_for_status(); data = resp.json()
                        if isinstance(data, dict) and data.get("encoding") == "base64":
                            import base64
                            content = base64.b64decode(data.get("content", "")).decode("utf-8", errors="replace")
                        else: content = str(data.get("content") or "")
                        return {"content": f"GitHub file `{owner}/{repo}/{path}`\n\n```\n{content[:50000]}\n```", "is_error": False}
                    owner, repo, title, body = map(lambda k: str(args.get(k) or "").strip(), ("owner","repo","title","body"))
                    if not owner or not repo or not title or not body: return {"content":"owner, repo, title, and body are required.","is_error":True}
                    resp = await client.post(f"https://api.github.com/repos/{urllib.parse.quote(owner)}/{urllib.parse.quote(repo)}/issues", json={"title":title,"body":body}, headers=headers); resp.raise_for_status(); data=resp.json()
                    return {"content": f"Created GitHub issue **#{data.get('number')}**: {data.get('html_url')}", "is_error": False}
            except Exception as exc:
                return {"content": f"GitHub operation failed: {exc}", "is_error": True}

        elif tool_name in ("search_gdrive", "read_gdrive_file"):
            google_entry = self.oauth_tokens.get("gdrive") or self.oauth_tokens.get("google") or {}
            google_token = str(google_entry.get("access_token") or "")
            if not google_token:
                return {"content": "Google Drive is not connected yet. Connect Google Drive from MeeraAI Settings or the in-chat integration action.", "is_error": True, "integration_required": "gdrive"}
            headers = {"Authorization": f"Bearer {google_token}"}
            try:
                async with httpx.AsyncClient(timeout=30.0) as client:
                    if tool_name == "search_gdrive":
                        query = str(args.get("query") or "").strip().replace("'", "\'")
                        limit = max(1, min(int(args.get("max_results") or 10), 20))
                        q = f"trashed = false and fullText contains '{query}'"
                        resp = await client.get("https://www.googleapis.com/drive/v3/files", params={"q":q,"pageSize":limit,"fields":"files(id,name,mimeType,modifiedTime,webViewLink)"}, headers=headers); resp.raise_for_status(); files=resp.json().get("files") or []
                        lines=[f"- **{f.get('name')}** ({f.get('mimeType')}) — {f.get('webViewLink') or f.get('id')}" for f in files]
                        return {"content":"Google Drive results:\n" + ("\n".join(lines) if lines else "No matching Drive files found."),"is_error":False}
                    file_id=str(args.get("file_id") or "").strip()
                    meta=await client.get(f"https://www.googleapis.com/drive/v3/files/{urllib.parse.quote(file_id)}",params={"fields":"id,name,mimeType"},headers=headers); meta.raise_for_status(); info=meta.json(); mime=str(info.get("mimeType") or "")
                    if mime.startswith("application/vnd.google-apps.document"):
                        resp=await client.get(f"https://www.googleapis.com/drive/v3/files/{urllib.parse.quote(file_id)}/export",params={"mimeType":"text/plain"},headers=headers); resp.raise_for_status(); content=resp.text
                    else:
                        resp=await client.get(f"https://www.googleapis.com/drive/v3/files/{urllib.parse.quote(file_id)}",params={"alt":"media"},headers=headers); resp.raise_for_status(); content=resp.text
                    return {"content":f"Google Drive file **{info.get('name')}**\n\n{content[:50000]}","is_error":False}
            except Exception as exc:
                return {"content": f"Google Drive operation failed: {exc}", "is_error": True}

        screen_allowed = self._screen_control_allowed(request)
        screen_backends_available = self._screen_tools_available()

        if tool_name == "capture_screen":
            exec_mgr = get_exec_manager()
            screen_id = f"screen_{uuid.uuid4().hex[:8]}"
            if exec_mgr:
                exec_mgr.start(screen_id, "Screen: capture_screen", tool="screen")
            result = self._capture_screen_snapshot(args.get("region"), with_ocr=bool(args.get("ocr", True)))
            if not result.get("ok"):
                if exec_mgr:
                    exec_mgr.fail(screen_id, str(result.get("error", "Screen capture failed.")))
                return {"content": str(result.get("error", "Screen capture failed.")), "is_error": True}
            if exec_mgr:
                exec_mgr.complete(screen_id, f"Captured {result.get('width', 0)}x{result.get('height', 0)}")
            ocr_text = str(result.get("ocr_text") or "").strip()
            ocr_block = ocr_text[:6000] if ocr_text else "(no readable text found)"
            return {
                "content": (
                    f"Screen captured to `{result.get('path')}` via {result.get('backend')}.\n"
                    f"Size: {result.get('width')}x{result.get('height')}\n"
                    f"OCR text:\n{ocr_block}"
                ),
                "is_error": False,
            }

        if tool_name == "describe_screen":
            exec_mgr = get_exec_manager()
            screen_id = f"screen_{uuid.uuid4().hex[:8]}"
            if exec_mgr:
                exec_mgr.start(screen_id, "Screen: describe_screen", tool="screen")
            result = self._capture_screen_snapshot(args.get("region"), with_ocr=True)
            if not result.get("ok"):
                if exec_mgr:
                    exec_mgr.fail(screen_id, str(result.get("error", "Screen inspection failed.")))
                return {"content": str(result.get("error", "Screen inspection failed.")), "is_error": True}
            window_info = self._get_active_window_info()
            payload = {
                "capture_path": result.get("path"),
                "backend": result.get("backend"),
                "width": result.get("width"),
                "height": result.get("height"),
                "active_window": window_info if window_info.get("ok") else {"error": window_info.get("error", "unknown")},
                "ocr_text": (result.get("ocr_text") or "")[:8000],
            }
            if exec_mgr:
                exec_mgr.complete(screen_id, "Described live screen")
            return {
                "content": json.dumps(payload, indent=2, ensure_ascii=False),
                "is_error": False,
            }

        if tool_name == "active_window_info":
            exec_mgr = get_exec_manager()
            screen_id = f"screen_{uuid.uuid4().hex[:8]}"
            if exec_mgr:
                exec_mgr.start(screen_id, "Screen: active_window_info", tool="screen")
            result = self._get_active_window_info()
            if result.get("ok"):
                if exec_mgr:
                    exec_mgr.complete(screen_id, result.get("title") or "Active window found")
                return {"content": json.dumps(result, indent=2, ensure_ascii=False), "is_error": False}
            if exec_mgr:
                exec_mgr.fail(screen_id, str(result.get("error", "Active window lookup failed.")))
            return {"content": str(result.get("error", "Active window lookup failed.")), "is_error": True}

        if tool_name in {"mouse_move", "mouse_click", "mouse_scroll", "keyboard_type", "keyboard_press", "keyboard_hotkey"}:
            if not screen_backends_available or not HAS_PYAUTOGUI:
                return {"content": "Desktop control is unavailable because pyautogui is not installed or screen backends are missing.", "is_error": True}
            if not screen_allowed:
                return {
                    "content": "Desktop control is disabled for this turn. Ask the user to enable screen control or set MEERA_ALLOW_SCREEN_CONTROL=1.",
                    "is_error": True,
                }
            exec_mgr = get_exec_manager()
            screen_id = f"screen_{uuid.uuid4().hex[:8]}"
            if exec_mgr:
                exec_mgr.start(screen_id, f"Screen: {tool_name}", tool="screen")
            try:
                if tool_name == "mouse_move":
                    x = int(args.get("x"))
                    y = int(args.get("y"))
                    duration = float(args.get("duration") or 0.0)
                    pyautogui.moveTo(x, y, duration=max(0.0, duration))
                    result = {"content": f"Moved mouse to ({x}, {y}).", "is_error": False}
                elif tool_name == "mouse_click":
                    x = int(args.get("x"))
                    y = int(args.get("y"))
                    button = str(args.get("button") or "left")
                    clicks = max(1, int(args.get("clicks") or 1))
                    interval = max(0.0, float(args.get("interval") or 0.0))
                    pyautogui.click(x=x, y=y, clicks=clicks, interval=interval, button=button)
                    result = {"content": f"Clicked {button} at ({x}, {y}) {clicks} time(s).", "is_error": False}
                elif tool_name == "mouse_scroll":
                    clicks = int(args.get("clicks") or 0)
                    x = args.get("x")
                    y = args.get("y")
                    if x is not None and y is not None:
                        pyautogui.moveTo(int(x), int(y))
                    pyautogui.scroll(clicks)
                    result = {"content": f"Scrolled by {clicks}.", "is_error": False}
                elif tool_name == "keyboard_type":
                    text = str(args.get("text") or "")
                    interval = max(0.0, float(args.get("interval") or 0.0))
                    pyautogui.write(text, interval=interval)
                    result = {"content": f"Typed {len(text)} characters.", "is_error": False}
                elif tool_name == "keyboard_press":
                    key = str(args.get("key") or "").strip()
                    if not key:
                        return {"content": "keyboard_press requires a key name.", "is_error": True}
                    pyautogui.press(key)
                    result = {"content": f"Pressed key '{key}'.", "is_error": False}
                else:
                    keys = args.get("keys") or []
                    if isinstance(keys, str):
                        keys = [k.strip() for k in keys.split("+") if k.strip()]
                    if not isinstance(keys, list) or not keys:
                        return {"content": "keyboard_hotkey requires a non-empty list of keys.", "is_error": True}
                    keys = [str(k).strip() for k in keys if str(k).strip()]
                    pyautogui.hotkey(*keys)
                    result = {"content": f"Pressed hotkey: {' + '.join(keys)}.", "is_error": False}
            except Exception as exc:
                if exec_mgr:
                    exec_mgr.fail(screen_id, str(exc))
                return {"content": f"Desktop control failed: {exc}", "is_error": True}
            if exec_mgr:
                exec_mgr.complete(screen_id, result.get("content", "Desktop control complete"))
            return result

