    async def _exec_tar_tool(self, args: dict) -> dict:
        """Archive operations (tar)."""
        import shutil as _shutil
        tar_cmd = "tar" if _shutil.which("tar") else None
        if not tar_cmd:
            return {"content": "tar is not available.", "is_error": True}
        action = args.get("action", "create")
        tar_args = []
        if action == "create" or action == "c":
            tar_args = ["-cvf"]
            archive = args.get("archive", "archive.tar.gz")
            tar_args.append(archive)
            sources = args.get("sources", [])
            if isinstance(sources, str):
                sources = [sources]
            tar_args.extend(sources)
            if args.get("gzip") or archive.endswith(".gz"):
                tar_args[0] = "-czvf"
            elif args.get("bzip2") or archive.endswith(".bz2"):
                tar_args[0] = "-cjvf"
            elif args.get("xz") or archive.endswith(".xz"):
                tar_args[0] = "-cJvf"
        elif action == "extract" or action == "x":
            tar_args = ["-xvf"]
            archive = args.get("archive", "")
            if archive:
                tar_args.append(archive)
            dest = args.get("destination")
            if dest:
                tar_args.extend(["-C", dest])
            if args.get("gzip"):
                tar_args[0] = "-xzvf"
            elif args.get("bzip2"):
                tar_args[0] = "-xjvf"
        elif action == "list" or action == "t":
            tar_args = ["-tvf"]
            archive = args.get("archive", "")
            if archive:
                tar_args.append(archive)
        elif action == "append":
            tar_args = ["-rvf"]
            archive = args.get("archive", "")
            if archive:
                tar_args.append(archive)
            sources = args.get("sources", [])
            if isinstance(sources, str):
                sources = [sources]
            tar_args.extend(sources)
        else:
            return {"content": f"Unknown tar action: {action}. Use create, extract, list, or append.", "is_error": True}
        try:
            process = await _safe_create_subprocess_exec(
                tar_cmd, *tar_args,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                cwd=str(WORKSPACE_DIR),
                env={**os.environ, "TERM": "dumb"}
            )
            stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=300)
            out_str = stdout.decode('utf-8', errors='replace').strip()
            err_str = stderr.decode('utf-8', errors='replace').strip()
            output = ""
            if out_str:
                output += f"{out_str}\\n"
            if err_str:
                output += f"[STDERR] {err_str}\\n"
            if not output:
                output = f"tar {action} completed successfully."
            return {"content": output, "is_error": process.returncode != 0}
        except asyncio.TimeoutError:
            return {"content": "tar command timed out.", "is_error": True}
        except Exception as e:
            return {"content": f"tar error: {e}", "is_error": True}
    async def _exec_xargs_tool(self, args: dict) -> dict:
        """xargs - build and execute command lines."""
        import shutil as _shutil
        xargs_cmd = "xargs" if _shutil.which("xargs") else None
        if not xargs_cmd:
            return {"content": "xargs is not available.", "is_error": True}
        xargs_args = []
        command = args.get("command", "echo")
        delimiter = args.get("delimiter") or args.get("d")
        if delimiter:
            xargs_args.extend(["-d", delimiter])
        max_args = args.get("max_args") or args.get("n")
        if max_args:
            xargs_args.extend(["-n", str(max_args)])
        max_lines = args.get("max_lines") or args.get("L")
        if max_lines:
            xargs_args.extend(["-L", str(max_lines)])
        if args.get("no_run_if_empty"):
            xargs_args.append("-r")
        replace_str = args.get("replace") or args.get("I")
        if replace_str:
            xargs_args.extend(["-I", replace_str])
        null_terminated = args.get("null") or args.get("0")
        if null_terminated:
            xargs_args.append("-0")
        verbose = args.get("verbose") or args.get("t")
        if verbose:
            xargs_args.append("-t")
        dry_run = args.get("dry_run") or args.get("p")
        if dry_run:
            xargs_args.append("-p")
        xargs_args.append(command)
        # Extra command arguments
        extra_args = args.get("args", [])
        if isinstance(extra_args, list):
            xargs_args.extend(extra_args)
        input_text = args.get("input", "")
        try:
            process = await _safe_create_subprocess_exec(
                xargs_cmd, *xargs_args,
                stdin=asyncio.subprocess.PIPE,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                cwd=str(WORKSPACE_DIR),
                env={**os.environ, "TERM": "dumb"}
            )
            stdout, stderr = await process.communicate(input=(input_text + "\\n").encode() if input_text else None)
            out_str = stdout.decode('utf-8', errors='replace').strip()
            err_str = stderr.decode('utf-8', errors='replace').strip()
            output = ""
            if out_str:
                output += f"{out_str}\\n"
            if err_str:
                output += f"[STDERR] {err_str}\\n"
            if not output:
                output = "xargs completed."
            return {"content": output, "is_error": process.returncode != 0}
        except Exception as e:
            return {"content": f"xargs error: {e}", "is_error": True}
    async def _exec_alias_tool(self, args: dict) -> dict:
        """Shell alias management."""
        action = args.get("action", "list")
        name = args.get("name")
        value = args.get("value")
        # Note: Aliases are shell-specific and don't persist across processes.
        # This provides information about aliases but actual alias setting
        # requires shell configuration.
        if action == "create" and name and value:
            return {
                "content": f"To create alias '{name}={value}', add to your shell config:\\n"
                          f"Bash/Zsh: echo \\\"alias {name}='{value}'\\\" >> ~/.bashrc (or .zshrc)\\n"
                          f"Fish: alias --save {name} {value}\\n"
                          f"Then run: source ~/.bashrc",
                "is_error": False
            }
        elif action == "show" and name:
            return {
                "content": f"To show alias '{name}', run: type {name} or alias {name} in your shell.",
                "is_error": False
            }
        else:
            return {
                "content": "To list all aliases, run: alias in your shell.\\n"
                          "Common aliases can be added to ~/.bashrc, ~/.zshrc, or config.fish.",
                "is_error": False
            }
    async def _exec_export_tool(self, args: dict) -> dict:
        """Environment export helper."""
        var_name = args.get("name")
        value = args.get("value")
        if var_name and value is not None:
            os.environ[var_name] = str(value)
            return {
                "content": f"Exported {var_name}={value} for current session.\\n"
                          f"To make permanent, add to shell profile:\\n"
                          f"export {var_name}={value}",
                "is_error": False
            }
        elif var_name:
            current = os.environ.get(var_name, "(not set)")
            return {"content": f"{var_name}={current}", "is_error": False}
        else:
            return {"content": "Provide 'name' and optionally 'value' parameters.", "is_error": True}
    async def _exec_source_tool(self, args: dict) -> dict:
        """Source a shell script file."""
        file_path = args.get("path") or args.get("file", "")
        if not file_path:
            return {"content": "File path is required.", "is_error": True}
        # Source executes in current shell context - we simulate by reading and evaluating exports
        target = Path(file_path)
        if not target.is_absolute():
            target = WORKSPACE_DIR / target
        if not target.exists():
            return {"content": f"File not found: {file_path}", "is_error": True}
        try:
            content = target.read_text(encoding="utf-8", errors="replace")
            exported_vars = []
            for line in content.split("\\n"):
                line = line.strip()
                if line.startswith("export ") and "=" in line:
                    var_part = line[7:]  # Remove "export "
                    if "#" not in var_part.split("=")[0]:
                        key, _, val = var_part.partition("=")
                        key = key.strip()
                        val = val.strip().strip("'\"")
                        os.environ[key] = val
                        exported_vars.append(f"{key}={val}")
            result = f"Sourced {file_path}. Found {len(exported_vars)} export statements.\n"
            if exported_vars:
                result += "Exported variables:\n" + "\n".join(exported_vars)
            return {"content": result, "is_error": False}
        except Exception as e:
            return {"content": f"Source error: {e}", "is_error": True}
    async def _exec_cron_tool(self, args: dict) -> dict:
        """Cron job management."""
        import shutil as _shutil
        cron_cmd = "crontab" if _shutil.which("crontab") else None
        action = args.get("action", "list")
        if not cron_cmd:
            return {"content": "crontab is not available on this system.", "is_error": True}
        if action == "list":
            try:
                process = await _safe_create_subprocess_exec(
                    cron_cmd, "-l",
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                    env={**os.environ, "TERM": "dumb"}
                )
                stdout, stderr = await process.communicate()
                out_str = stdout.decode('utf-8', errors='replace').strip()
                if not out_str:
                    return {"content": "No crontab entries configured.", "is_error": False}
                return {"content": f"Current crontab:\\n{out_str}", "is_error": False}
            except Exception as e:
                return {"content": f"crontab error: {e}", "is_error": True}
        elif action == "add":
            schedule = args.get("schedule", "* * * * *")
            command = args.get("command", "")
            if not command:
                return {"content": "Command is required for adding cron job.", "is_error": True}
            entry = f"{schedule} {command}"
            try:
                # Read existing, append, write back
                proc_read = await _safe_create_subprocess_exec(
                    cron_cmd, "-l",
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.DEVNULL,
                    env={**os.environ, "TERM": "dumb"}
                )
                stdout, _ = await proc_read.communicate()
                existing = stdout.decode('utf-8', errors='replace')
                new_content = existing + "\\n" + entry + "\\n"
                proc_write = await _safe_create_subprocess_exec(
                    cron_cmd, "-",
                    stdin=asyncio.subprocess.PIPE,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                    env={**os.environ, "TERM": "dumb"}
                )
                stdout, stderr = await proc_write.communicate(input=new_content.encode())
                return {"content": f"Added cron job: {entry}", "is_error": proc_write.returncode != 0}
            except Exception as e:
                return {"content": f"cron add error: {e}", "is_error": True}
        elif action == "remove":
            return {"content": "To remove cron jobs, edit crontab directly: crontab -e", "is_error": False}
        elif action == "edit":
            return {"content": "To edit cron jobs, run: crontab -e", "is_error": False}
        else:
            return {"content": f"Unknown cron action: {action}. Use list, add, remove, or edit.", "is_error": True}
    async def _exec_service_tool(self, args: dict) -> dict:
        """System service management (systemd/sysvinit)."""
        import shutil as _shutil
        systemctl = "systemctl" if _shutil.which("systemctl") else None
        service_cmd = "service" if _shutil.which("service") else None
        if not systemctl and not service_cmd:
            return {"content": "Neither systemctl nor service command available.", "is_error": True}
        service_name = args.get("service", "")
        action = args.get("action", "status")
        cmd = systemctl or service_cmd
        cmd_args = [action]
        if systemctl:
            if service_name:
                cmd_args.append(service_name)
            if args.get("user_mode"):
                cmd_args.insert(0, "--user")
            if action == "status" and not args.get("no_pager"):
                cmd_args.insert(0, "--no-pager")
        else:
            if service_name:
                cmd_args.append(service_name)
            cmd_args.insert(0, action)
        try:
            process = await _safe_create_subprocess_exec(
                cmd, *cmd_args,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                env={**os.environ, "TERM": "dumb", "LANG": "C.UTF-8"}
            )
            stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=30)
            out_str = stdout.decode('utf-8', errors='replace').strip()
            err_str = stderr.decode('utf-8', errors='replace').strip()
            output = ""
            if out_str:
                output += f"{out_str}\\n"
            if err_str:
                output += f"[STDERR] {err_str}\\n"
            if not output:
                output = f"Service {action} completed."
            return {"content": output, "is_error": process.returncode != 0}
        except asyncio.TimeoutError:
            return {"content": "Service command timed out.", "is_error": True}
        except Exception as e:
            return {"content": f"Service error: {e}", "is_error": True}
    async def _exec_ssh_tool(self, args: dict) -> dict:
        """SSH connection operations."""
        import shutil as _shutil
        ssh_cmd = "ssh" if _shutil.which("ssh") else None
        if not ssh_cmd:
            return {"content": "SSH client is not installed.", "is_error": True}
        host = args.get("host", "")
        user = args.get("user", "")
        port = args.get("port", 22)
        command = args.get("command", "")
        key_file = args.get("key_file")
        if not host:
            return {"content": "Host is required for SSH.", "is_error": True}
        ssh_args = []
        if port != 22:
            ssh_args.extend(["-p", str(port)])
        if key_file:
            ssh_args.extend(["-i", key_file])
        if args.get("verbose"):
            ssh_args.append("-v")
        if args.get("strict_host_checking") == False:
            ssh_args.extend(["-o", "StrictHostKeyChecking=no"])
        if args.get("compression"):
            ssh_args.append("-C")
        # Build destination
        dest = f"{user}@{host}" if user else host
        ssh_args.append(dest)
        if command:
            ssh_args.append(command)
        # SSH interactive sessions need special handling
        if not command and not args.get("batch_mode"):
            return {
                "content": f"Interactive SSH session would connect to {dest}.\\n"
                          f"For non-interactive use, provide a 'command' parameter or set batch_mode=true.",
                "is_error": False
            }
        ssh_args.insert(0, "-o")
        ssh_args.insert(1, "BatchMode=yes")
        try:
            process = await _safe_create_subprocess_exec(
                ssh_cmd, *ssh_args,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                env={**os.environ, "TERM": "dumb"}
            )
            stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=int(args.get("timeout", 120)))
            out_str = stdout.decode('utf-8', errors='replace').strip()
            err_str = stderr.decode('utf-8', errors='replace').strip()
            output = ""
            if out_str:
                output += f"[STDOUT]\\n{out_str}\\n"
            if err_str:
                output += f"[STDERR]\\n{err_str}\\n"
            if not output:
                output = f"SSH to {dest} completed."
            return {"content": output, "is_error": process.returncode != 0}
        except asyncio.TimeoutError:
            return {"content": "SSH connection timed out.", "is_error": True}
        except Exception as e:
            return {"content": f"SSH error: {e}", "is_error": True}
    async def _exec_scp_tool(self, args: dict) -> dict:
        """SCP file transfer operations."""
        import shutil as _shutil
        scp_cmd = "scp" if _shutil.which("scp") else None
        if not scp_cmd:
            return {"content": "SCP is not installed.", "is_error": True}
        source = args.get("source", "") or args.get("src", "")
        destination = args.get("destination", "") or args.get("dest", "")
        if not source or not destination:
            return {"content": "Both source and destination are required.", "is_error": True}
        scp_args = []
        if args.get("recursive"):
            scp_args.append("-r")
        if args.get("preserve"):
            scp_args.append("-p")
        if args.get("verbose"):
            scp_args.append("-v")
        if args.get("compress"):
            scp_args.append("-C")
        port = args.get("port")
        if port:
            scp_args.extend(["-P", str(port)])
        key_file = args.get("key_file")
        if key_file:
            scp_args.extend(["-i", key_file])
        limit = args.get("limit")
        if limit:
            scp_args.extend(["-l", str(limit)])
        scp_args.extend([source, destination])
        try:
            process = await _safe_create_subprocess_exec(
                scp_cmd, *scp_args,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                env={**os.environ, "TERM": "dumb"}
            )
            stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=600)
            out_str = stdout.decode('utf-8', errors='replace').strip()
            err_str = stderr.decode('utf-8', errors='replace').strip()
            output = ""
            if out_str:
                output += f"{out_str}\\n"
            if err_str:
                output += f"[STDERR] {err_str}\\n"
            if not output:
                output = f"SCP transfer completed: {source} -> {destination}"
            return {"content": output, "is_error": process.returncode != 0}
        except asyncio.TimeoutError:
            return {"content": "SCP transfer timed out.", "is_error": True}
        except Exception as e:
            return {"content": f"SCP error: {e}", "is_error": True}
    async def _exec_rsync_tool(self, args: dict) -> dict:
        """Rsync file synchronization."""
        import shutil as _shutil
        rsync_cmd = "rsync" if _shutil.which("rsync") else None
        if not rsync_cmd:
            return {"content": "rsync is not installed.", "is_error": True}
        source = args.get("source", "") or args.get("src", "")
        destination = args.get("destination", "") or args.get("dest", "")
        if not source or not destination:
            return {"content": "Both source and destination are required.", "is_error": True}
        rsync_args = ["-avz"]  # Archive, verbose, compressed
        if args.get("dry_run"):
            rsync_args.append("--dry-run")
        if args.get("delete"):
            rsync_args.append("--delete")
        if args.get("exclude"):
            excludes = args.get("exclude")
            if isinstance(excludes, str):
                excludes = [excludes]
            for excl in excludes:
                rsync_args.extend(["--exclude", excl])
        if args.get("include"):
            includes = args.get("include")
            if isinstance(includes, str):
                includes = [includes]
            for incl in includes:
                rsync_args.extend(["--include", incl])
        if args.get("progress"):
            rsync_args.append("--progress")
        bandwidth_limit = args.get("bandwidth_limit")
        if bandwidth_limit:
            rsync_args.extend(["--bwlimit", str(bandwidth_limit)])
        ssh_args = args.get("ssh_options")
        if ssh_args:
            rsync_args.extend(["-e", f"ssh {ssh_args}"])
        rsync_args.extend([source, destination])
        try:
            process = await _safe_create_subprocess_exec(
                rsync_cmd, *rsync_args,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                env={**os.environ, "TERM": "dumb", "RSYNC_RSH": "ssh"}
            )
            stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=600)
            out_str = stdout.decode('utf-8', errors='replace').strip()
            err_str = stderr.decode('utf-8', errors='replace').strip()
            output = ""
            if out_str:
                output += f"{out_str}\\n"
            if err_str:
                output += f"[STDERR] {err_str}\\n"
            if not output:
                output = f"rsync completed: {source} -> {destination}"
            return {"content": output, "is_error": process.returncode != 0}
        except asyncio.TimeoutError:
            return {"content": "rsync timed out.", "is_error": True}
        except Exception as e:
            return {"content": f"rsync error: {e}", "is_error": True}
    async def _exec_watch_tool(self, args: dict) -> dict:
        """Watch command execution periodically."""
        import shutil as _shutil
        watch_cmd = "watch" if _shutil.which("watch") else None
        if not watch_cmd:
            return {"content": "watch is not available.", "is_error": True}
        watch_args = []
        interval = args.get("interval", 2)
        watch_args.extend(["-n", str(interval)])
        if args.get("no_title"):
            watch_args.append("-t")
        if args.get("color"):
            watch_args.append("-c")
        command = args.get("command", "")
        if not command:
            return {"content": "Command to watch is required.", "is_error": True}
        watch_args.append(command)
        # Run once for output (watch is interactive normally)
        watch_args.insert(0, "-e")
        try:
            process = await _safe_create_subprocess_exec(
                bash_cmd if (bash_cmd := _shutil.which("bash")) else "sh", "-c",
                f"{' '.join(watch_args)} || true; sleep {interval}; {' '.join(watch_args)}",
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                cwd=str(WORKSPACE_DIR),
                env={**os.environ, "TERM": "dumb"}
            )
            stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=30)
            out_str = stdout.decode('utf-8', errors='replace').strip()
            err_str = stderr.decode('utf-8', errors='replace').strip()
            output = f"Watching every {interval}s: {command}\\n"
            if out_str:
                output += f"\\n{out_str}"
            if err_str:
                output += f"\\n[STDERR] {err_str}"
            return {"content": output, "is_error": False}
        except asyncio.TimeoutError:
            return {"content": "Watch sample completed (would continue running).", "is_error": False}
        except Exception as e:
            return {"content": f"watch error: {e}", "is_error": True}
    async def _exec_time_tool(self, args: dict) -> dict:
        """Time command execution."""
        import shutil as _shutil
        time_cmd = "time" if _shutil.which("time") else None
        command = args.get("command", "")
        if not command:
            return {"content": "Command to time is required.", "is_error": True}
        format_str = args.get("format", "%E real, %U user, %S sys")
        if time_cmd:
            try:
                process = await _safe_create_subprocess_exec(
                    time_cmd, "-f", format_str, "bash", "-c", command,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                    cwd=str(WORKSPACE_DIR),
                    env={**os.environ, "TERM": "dumb"}
                )
                stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=int(args.get("timeout", 300)))
                out_str = stdout.decode('utf-8', errors='replace').strip()
                err_str = stderr.decode('utf-8', errors='replace').strip()
                output = f"Command: {command}\\n"
                if out_str:
                    output += f"\\n[Output]\\n{out_str}"
                if err_str:
                    output += f"\\n[Timing]\\n{err_str}"
                return {"content": output, "is_error": process.returncode != 0}
            except asyncio.TimeoutError:
                return {"content": "Timed command exceeded timeout.", "is_error": True}
            except Exception as e:
                return {"content": f"time error: {e}", "is_error": True}
        else:
            # Fallback: manual timing
            start = time.time()
            result = await self._exec_terminal_command({"command": command})
            elapsed = time.time() - start
            timing_info = f"\\n---\\nElapsed time: {elapsed:.3f}s ({elapsed/60:.1f}min)"
            result["content"] += timing_info
            return result
    async def _exec_date_tool(self, args: dict) -> dict:
        """Date/time operations."""
        import shutil as _shutil
        date_cmd = "date" if _shutil.which("date") else None
        action = args.get("action", "show")
        if date_cmd:
            date_args = []
            if action == "show":
                fmt = args.get("format", "+%Y-%m-%d %H:%M:%S %Z")
                date_args.append(fmt)
            elif action == "set":
                new_date = args.get("date_string", "")
                if not new_date:
                    return {"content": "date_string is required for setting date.", "is_error": True}
                date_args.extend(["-s", new_date])
            elif action == "parse":
                date_input = args.get("input", "")
                fmt = args.get("format", "+%Y-%m-%d %H:%M:%S")
                date_args.extend(["-d", date_input, fmt])
            try:
                process = await _safe_create_subprocess_exec(
                    date_cmd, *date_args,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE,
                    env={**os.environ, "TERM": "dumb"}
                )
                stdout, stderr = await process.communicate()
                out_str = stdout.decode('utf-8', errors='replace').strip()
                err_str = stderr.decode('utf-8', errors='replace').strip()
                output = out_str if out_str else f"date {action} completed."
                if err_str:
                    output += f"\\n[STDERR] {err_str}"
                return {"content": output, "is_error": bool(stderr)}
            except Exception as e:
                return {"content": f"date error: {e}", "is_error": True}
        else:
            # Fallback to Python datetime
            now = datetime.now(timezone.utc)
            if action == "show":
                return {"content": now.strftime("%Y-%m-%d %H:%M:%S UTC"), "is_error": False}
            elif action == "epoch":
                return {"content": str(int(now.timestamp())), "is_error": False}
            else:
                return {"content": f"Date: {now.isoformat()}", "is_error": False}
    async def _exec_iptables_tool(self, args: dict) -> dict:
        """Firewall/iptables management."""
        import shutil as _shutil
        iptables_cmd = "iptables" if _shutil.which("iptables") else None
        if not iptables_cmd:
            return {"content": "iptables is not available (requires root).", "is_error": True}
        action = args.get("action", "list")
        table = args.get("table", "filter")
        iptables_args = ["-t", table]
        if action == "list":
            iptables_args.extend(["-L", "-n", "-v"])
            chain = args.get("chain")
            if chain:
                iptables_args.append(chain)
            if args.get("line_numbers"):
                iptables_args.append("--line-numbers")
        elif action == "flush":
            iptables_args.extend(["-F"])
            chain = args.get("chain")
            if chain:
                iptables_args.append(chain)
        elif action == "append" or action == "add":
            iptables_args.extend(["-A", args.get("chain", "INPUT")])
            rule_parts = self._build_iptables_rule(args)
            iptables_args.extend(rule_parts)
        elif action == "insert":
            iptables_args.extend(["-I", args.get("chain", "INPUT")])
            position = args.get("position", 1)
            iptables_args.insert(3, str(position))
            rule_parts = self._build_iptables_rule(args)
            iptables_args.extend(rule_parts)
        elif action == "delete":
            iptables_args.extend(["-D", args.get("chain", "INPUT")])
            position = args.get("position")
            if position:
                iptables_args.append(str(position))
            else:
                rule_parts = self._build_iptables_rule(args)
                iptables_args.extend(rule_parts)
        elif action == "policy":
            iptables_args.extend(["-P", args.get("chain", "INPUT"), args.get("target", "ACCEPT").upper()])
        elif action == "new_chain":
            iptables_args.extend(["-N", args.get("chain", "")])
        elif action == "delete_chain":
            iptables_args.extend(["-X", args.get("chain", "")])
        else:
            return {"content": f"Unknown iptables action: {action}", "is_error": True}
        try:
            process = await _safe_create_subprocess_exec(
                "sudo", iptables_cmd, *iptables_args,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                env={**os.environ, "TERM": "dumb"}
            )
            stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=30)
            out_str = stdout.decode('utf-8', errors='replace').strip()
            err_str = stderr.decode('utf-8', errors='replace').strip()
            output = ""
            if out_str:
                output += f"{out_str}\\n"
            if err_str:
                output += f"[STDERR] {err_str}\\n"
            if not output:
                output = f"iptables {action} completed."
            return {"content": output, "is_error": process.returncode != 0}
        except asyncio.TimeoutError:
            return {"content": "iptables command timed out.", "is_error": True}
        except Exception as e:
            return {"content": f"iptables error: {e}", "is_error": True}
    @staticmethod
    def _build_iptables_rule(args: dict) -> list:
        """Build iptables rule components from args."""
        rule_parts = []
        protocol = args.get("protocol") or args.get("proto")
        if protocol:
            rule_parts.extend(["-p", protocol.upper()])
        source = args.get("source") or args.get("src")
        if source:
            rule_parts.extend(["-s", source])
        destination = args.get("destination") or args.get("dst")
        if destination:
            rule_parts.extend(["-d", destination])
        in_interface = args.get("in_interface") or args.get("i")
        if in_interface:
            rule_parts.extend(["-i", in_interface])
        out_interface = args.get("out_interface") or args.get("o")
        if out_interface:
            rule_parts.extend(["-o", out_interface])
        sport = args.get("source_port") or args.get("sport")
        if sport:
            rule_parts.extend(["--sport", str(sport)])
        dport = args.get("dest_port") or args.get("dport")
        if dport:
            rule_parts.extend(["--dport", str(dport)])
        jump = args.get("jump") or args.get("j") or args.get("target")
        if jump:
            rule_parts.extend(["-j", jump.upper()])
        state = args.get("state")
        if state:
            rule_parts.extend(["-m", "state", "--state", state])
        comment = args.get("comment")
        if comment:
            rule_parts.extend(["-m", "comment", "--comment", comment])
        limit = args.get("limit")
        if limit:
            rule_parts.extend(["-m", "limit", "--limit", str(limit)])
        return rule_parts
    async def _exec_systemctl_tool(self, args: dict) -> dict:
        """Systemd service management."""
        import shutil as _shutil
        systemctl_cmd = "systemctl" if _shutil.which("systemctl") else None
        if not systemctl_cmd:
            return {"content": "systemctl is not available.", "is_error": True}
        action = args.get("action", "status")
        unit = args.get("unit")
        systemctl_args = [action]
        if unit:
            systemctl_args.append(unit)
        if args.get("user_mode"):
            systemctl_args.insert(0, "--user")
        if args.get("no_pager") or (action == "status" and not args.get("pager")):
            systemctl_args.insert(0, "--no-pager")
        if args.get("quiet"):
            systemctl_args.append("-q")
        if args.get("full"):
            systemctl_args.append("--full")
        if args.get("type"):
            systemctl_args.extend(["--type", args.get("type")])
        state = args.get("state")
        if state:
            systemctl_args.extend(["--state", state])
        try:
            process = await _safe_create_subprocess_exec(
                systemctl_cmd, *systemctl_args,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                env={**os.environ, "TERM": "dumb", "LANG": "C.UTF-8", "SYSTEMD_COLORS": "0"}
            )
            stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=30)
            out_str = stdout.decode('utf-8', errors='replace').strip()
            err_str = stderr.decode('utf-8', errors='replace').strip()
            output = ""
            if out_str:
                output += f"{out_str}\\n"
            if err_str:
                output += f"[STDERR] {err_str}\\n"
            if not output:
                output = f"systemctl {action} completed." + (f" Unit: {unit}" if unit else "")
            return {"content": output, "is_error": process.returncode != 0}
        except asyncio.TimeoutError:
            return {"content": "systemctl command timed out.", "is_error": True}
        except Exception as e:
            return {"content": f"systemctl error: {e}", "is_error": True}
    async def _exec_journalctl_tool(self, args: dict) -> dict:
        """Journal/systemd log viewer."""
        import shutil as _shutil
        journalctl_cmd = "journalctl" if _shutil.which("journalctl") else None
        if not journalctl_cmd:
            return {"content": "journalctl is not available.", "is_error": True}
        journal_args = []
        unit = args.get("unit")
        if unit:
            journal_args.extend(["-u", unit])
        since = args.get("since")
        if since:
            journal_args.extend(["--since", since])
        until = args.get("until")
        if until:
            journal_args.extend(["--until", until])
        n_lines = args.get("n") or args.get("lines")
        if n_lines:
            journal_args.extend(["-n", str(n_lines)])
        if args.get("follow") or args.get("f"):
            journal_args.append("-f")
        if args.get("output"):
            journal_args.extend(["-o", args.get("output")])
        priority = args.get("priority") or args.get("p")
        if priority:
            journal_args.extend(["-p", str(priority)])
        identifier = args.get("identifier") or args.get("SYSLOG_IDENTIFIER")
        if identifier:
            journal_args.extend(["-t", identifier])
        grep_pattern = args.get("grep") or args.get("pattern")
        if grep_pattern:
            journal_args.extend(["--grep", grep_pattern])
        if args.get("no_pager"):
            journal_args.append("--no-pager")
        catalog = args.get("catalog")
        if catalog:
            journal_args.extend(["--catalog", catalog])
        boot = args.get("boot")
        if boot:
            if boot == "this":
                journal_args.append("-b")
            elif boot == "last":
                journal_args.extend(["-b", "-1"])
            else:
                journal_args.extend(["-b", str(boot)])
        try:
            process = await _safe_create_subprocess_exec(
                journalctl_cmd, *journal_args,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
                env={**os.environ, "TERM": "dumb", "LANG": "C.UTF-8", "SYSTEMD_COLORS": "0", "NO_COLOR": "1"}
            )
            stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=60)
            out_str = stdout.decode('utf-8', errors='replace').strip()
            err_str = stderr.decode('utf-8', errors='replace').strip()
            output = ""
            if out_str:
                output += f"{out_str}\\n"
            if err_str:
                output += f"[STDERR] {err_str}\\n"
            if not output:
                output = "No journal entries matched criteria."
            if len(output) > 50000:
                output = output[:50000] + "\\n...[Output truncated]"
            return {"content": output, "is_error": process.returncode != 0}
        except asyncio.TimeoutError:
            return {"content": "journalctl timed out.", "is_error": True}
        except Exception as e:
            return {"content": f"journalctl error: {e}", "is_error": True}

    def _find_tool_server(self, tool_name: str) -> Optional[str]:
        """Find which MCP server provides a given tool."""
        for name, conn in self.mcp_manager.connections.items():
            if conn.connected:
                for tool in conn.tools:
                    if tool.name == tool_name:
                        return name
        return None

    async def stop_generation(self):
        """Stop all active streams."""
        for task in self._active_streams:
            task.cancel()
        self._active_streams.clear()


