    @router.get("/api/documents/proxy")
    async def document_proxy(url: str):
        """Fetch and stream an internet document (like PDF) to bypass CORS and render in-app."""
        try:
            # We use an async client to stream the response
            async def generate():
                async with httpx.AsyncClient(verify=False, follow_redirects=True) as client:
                    async with client.stream("GET", url) as response:
                        response.raise_for_status()
                        async for chunk in response.aiter_bytes():
                            yield chunk
                            
            # Determine content type based on extension (default PDF)
            content_type = "application/pdf"
            if url.lower().endswith(".pdf"):
                content_type = "application/pdf"
            
            return StreamingResponse(generate(), media_type=content_type)
        except Exception as e:
            raise HTTPException(status_code=400, detail=str(e))

