    @router.post("/api/terminal/run")
    async def terminal_run(body: dict):
        command = str(body.get("command") or "").strip()
        if not command:
            raise HTTPException(status_code=400, detail="Command is required.")

        cwd_raw = str(body.get("cwd") or TERMINAL_ROOT_DIR).strip()
        # Normalize Windows-style separators on POSIX to avoid accidental escapes
        if os.name != "nt":
            cwd_raw = cwd_raw.replace("\\", "/")
        try:
            cwd_path = Path(cwd_raw).expanduser().resolve()
        except Exception as exc:
            raise HTTPException(status_code=400, detail=f"Invalid cwd: {exc}")
        if not cwd_path.exists() or not cwd_path.is_dir():
            raise HTTPException(status_code=400, detail=f"Working directory does not exist: {cwd_path}")

        cd_match = re.match(r"^\s*(?:cd|chdir|Set-Location|sl)\s*(.*)$", command, re.IGNORECASE)
        if cd_match:
            target_text = cd_match.group(1).strip().strip('"').strip("'")
            target_path = Path.home() if target_text in {"", "~"} else Path(target_text)
            if not target_path.is_absolute():
                target_path = cwd_path / target_path
            target_path = target_path.expanduser().resolve()
            if not target_path.exists() or not target_path.is_dir():
                return {"ok": False, "command": command, "cwd": str(cwd_path), "output": f"cd: no such directory: {target_path}", "exit_code": 1, "is_error": True}
            return {"ok": True, "command": command, "cwd": str(target_path), "output": "", "exit_code": 0, "is_error": False}

        result = await chat_service._exec_terminal_command({
            "command": command,
            "cwd": str(cwd_path),
            "confirmed": bool(body.get("confirmed", False)),
            "timeout": int(body.get("timeout") or 60),
            "goal": body.get("goal"),
            "model": body.get("model"),
        })
        explanation = ""
        _run_config = chat_service.persistence.config
        if _run_config.inference.mode == InferenceMode.CLOUD:
            _run_ready = bool(_run_config.inference.default_cloud_provider) and _run_config.inference.default_cloud_provider in _run_config.cloud_providers
            _run_forced_mode = "cloud" if _run_ready else None
            _run_forced_provider = _run_config.inference.default_cloud_provider if _run_ready else None
        else:
            _run_ready = NATIVE_GGUF_RUNTIME.is_loaded()
            _run_forced_mode = "local" if _run_ready else None
            _run_forced_provider = "__native__" if _run_ready else None
        _run_shell = str(result.get("shell") or ("cmd" if os.name == "nt" else "shell"))
        _run_cwd = str(result.get("cwd") or cwd_path)
        try:
            explanation = await chat_service._explain_terminal_result_llm(
                str(result.get("command") or command),
                str(result.get("content") or ""),
                int(result.get("exit_code") or 0),
                goal=body.get("goal"),
                model=body.get("model"),
                inference_mode=_run_forced_mode,
                provider=_run_forced_provider,
                shell=_run_shell,
                cwd=_run_cwd,
            )
        except Exception:
            explanation = chat_service._explain_terminal_result_fast(
                str(result.get("command") or command), str(result.get("content") or ""), int(result.get("exit_code") or 0),
                shell=_run_shell, cwd=_run_cwd,
            )
        return {
            "ok": not bool(result.get("is_error")),
            "command": result.get("command") or command,
            "cwd": str(result.get("cwd") or cwd_path),
            "output": str(result.get("content") or ""),
            "stdout": str(result.get("stdout") or ""),
            "stderr": str(result.get("stderr") or ""),
            "shell": str(result.get("shell") or ("cmd" if os.name == "nt" else "shell")),
            "attempts": result.get("attempts") or [],
            "exit_code": int(result.get("exit_code") if result.get("exit_code") is not None else (1 if result.get("is_error") else 0)),
            "is_error": bool(result.get("is_error")),
            "needs_confirmation": bool(result.get("needs_confirmation")),
            "reasoner_note": result.get("reasoner_note") or "",
            "explanation": explanation,
        }

    @router.post("/api/terminal/stream")
    async def terminal_stream(body: dict):
        command = str(body.get("command") or "").strip()
        if not command:
            raise HTTPException(status_code=400, detail="Command is required.")

        cwd_raw = str(body.get("cwd") or TERMINAL_ROOT_DIR).strip()
        # Normalize Windows-style separators on POSIX to avoid accidental escapes
        if os.name != "nt":
            cwd_raw = cwd_raw.replace("\\", "/")
        try:
            cwd_path = Path(cwd_raw).expanduser().resolve()
        except Exception as exc:
            raise HTTPException(status_code=400, detail=f"Invalid cwd: {exc}")
        if not cwd_path.exists() or not cwd_path.is_dir():
            raise HTTPException(status_code=400, detail=f"Working directory does not exist: {cwd_path}")

        cd_match = re.match(r"^\s*(?:cd|chdir|Set-Location|sl)\s*(.*)$", command, re.IGNORECASE)
        if cd_match:
            target_text = cd_match.group(1).strip().strip('"').strip("'")
            target_path = Path.home() if target_text in {"", "~"} else Path(target_text)
            if not target_path.is_absolute():
                target_path = cwd_path / target_path
            target_path = target_path.expanduser().resolve()

            async def cd_events():
                if target_path.exists() and target_path.is_dir():
                    yield f"data: {json.dumps({'type': 'start', 'command': command, 'cwd': str(cwd_path), 'shell': 'internal'})}\n\n"
                    yield f"data: {json.dumps({'type': 'done', 'command': command, 'cwd': str(target_path), 'exit_code': 0, 'is_error': False, 'attempts': []})}\n\n"
                    yield f"data: {json.dumps({'type': 'explain', 'text': 'Successfully changed working directory to **' + str(target_path) + '**.'})}\n\n"
                else:
                    yield f"data: {json.dumps({'type': 'start', 'command': command, 'cwd': str(cwd_path), 'shell': 'internal'})}\n\n"
                    yield f"data: {json.dumps({'type': 'stderr', 'text': f'cd: no such directory: {target_path}'})}\n\n"
                    yield f"data: {json.dumps({'type': 'done', 'command': command, 'cwd': str(cwd_path), 'exit_code': 1, 'is_error': True, 'attempts': []})}\n\n"
                    yield f"data: {json.dumps({'type': 'explain', 'text': 'Failed to change directory: **' + str(target_path) + '** does not exist or is inaccessible.'})}\n\n"

            return StreamingResponse(cd_events(), media_type="text/event-stream", headers={"Cache-Control": "no-cache", "Connection": "keep-alive", "X-Accel-Buffering": "no"})

        goal = str(body.get("goal") or command).strip()
        model = body.get("model")
        is_nl_query = (
            bool(body.get("natural_language"))
            or chat_service._looks_like_natural_language(command)
            or chat_service._detect_artifact_format(command) is not None
        )

        # Respect whatever the person actually chose in Settings
        # (config.inference.mode) -- this must NEVER invent its own
        # fallback behavior. If they're in local mode, only the loaded
        # native GGUF model is used, full stop; cloud is only ever used
        # when they've explicitly switched Settings to cloud mode with a
        # real provider configured there.
        #
        # This also must agree with the exact same readiness check the
        # real chat path uses (ChatService._determine_provider), NOT the
        # separate MODEL_LOAD_STATE bookkeeping dict -- that dict is only
        # ever a mirror of NATIVE_GGUF_RUNTIME's real in-memory state and
        # can lag behind it, which previously caused the terminal to claim
        # "No model is loaded" even while normal chat worked fine against
        # an already-loaded native model.
        _config = chat_service.persistence.config
        if _config.inference.mode == InferenceMode.CLOUD:
            model_ready = bool(_config.inference.default_cloud_provider) and _config.inference.default_cloud_provider in _config.cloud_providers
            forced_mode = "cloud" if model_ready else None
            forced_provider = _config.inference.default_cloud_provider if model_ready else None
        else:
            model_ready = NATIVE_GGUF_RUNTIME.is_loaded()
            forced_mode = "local" if model_ready else None
            forced_provider = "__native__" if model_ready else None

        async def stream_events():
            nonlocal command
            nonlocal forced_mode, forced_provider
            translation_note = ""
            artifact_fmt = chat_service._detect_artifact_format(command) if is_nl_query else None
            if artifact_fmt:
                if not model_ready:
                    load_result = chat_service._auto_load_model_with_stream(cwd_path, command)
                    async for chunk in load_result:
                        yield chunk
                    model_ready_now = NATIVE_GGUF_RUNTIME.is_loaded() or (
                        _config.inference.mode == InferenceMode.CLOUD
                        and bool(_config.inference.default_cloud_provider)
                        and _config.inference.default_cloud_provider in _config.cloud_providers
                    )
                    if not model_ready_now:
                        yield f"data: {json.dumps({'type': 'start', 'command': command, 'cwd': str(cwd_path), 'shell': 'internal'})}\n\n"
                        yield f"data: {json.dumps({'type': 'done', 'command': command, 'cwd': str(cwd_path), 'exit_code': 1, 'is_error': True, 'attempts': []})}\n\n"
                        yield f"data: {json.dumps({'type': 'explain', 'text': 'No local model could be auto-loaded, and no cloud provider is configured. Download a model in Settings → Models, or set up a cloud provider, then try again.'})}\n\n"
                        return
                    # A model just finished loading -- refresh readiness/forced routing for the rest of this request.
                    forced_mode_local = "local" if NATIVE_GGUF_RUNTIME.is_loaded() else forced_mode
                    forced_provider_local = "__native__" if NATIVE_GGUF_RUNTIME.is_loaded() else forced_provider
                else:
                    forced_mode_local = forced_mode
                    forced_provider_local = forced_provider
                yield f"data: {json.dumps({'type': 'start', 'command': command, 'cwd': str(cwd_path), 'shell': 'internal'})}\n\n"
                yield f"data: {json.dumps({'type': 'thinking', 'text': f'Writing a script to build the {artifact_fmt.upper()}…'})}\n\n"

                # Human-readable labels for each pipeline stage, shown in the
                # frontend's animated "Creating <file>…" card so the person
                # sees real, live progress (drafting -> writing -> generating
                # -> verifying -> done) instead of a long silent pause with
                # nothing on screen until the file suddenly appears.
                _stage_labels = {
                    "drafting": "Drafting the build script",
                    "writing": "Writing the build script to disk",
                    "generating": f"Generating the {artifact_fmt.upper()} content",
                    "verifying": "Verifying the file was created",
                    "done": "Finalizing",
                    "failed": "Failed",
                }
                progress_queue: "asyncio.Queue[dict]" = asyncio.Queue()

                async def _on_artifact_progress(stage: str, extra: dict) -> None:
                    await progress_queue.put({
                        "type": "creating_file",
                        "stage": stage,
                        "label": _stage_labels.get(stage, stage),
                        "name": extra.get("name"),
                        "format": extra.get("format"),
                    })

                pipeline_task = asyncio.create_task(chat_service._run_artifact_pipeline(
                    command, artifact_fmt, cwd_path,
                    model=model, inference_mode=forced_mode_local, provider=forced_provider_local,
                    on_progress=_on_artifact_progress,
                ))

                # Drain progress events as they arrive while the pipeline
                # task runs concurrently, so each stage reaches the browser
                # the instant it happens rather than being buffered until
                # the whole pipeline finishes.
                while not pipeline_task.done():
                    try:
                        event = await asyncio.wait_for(progress_queue.get(), timeout=0.25)
                        yield f"data: {json.dumps(event)}\n\n"
                    except asyncio.TimeoutError:
                        continue
                # Flush any remaining queued events emitted right before
                # the task finished.
                while not progress_queue.empty():
                    event = progress_queue.get_nowait()
                    yield f"data: {json.dumps(event)}\n\n"

                artifact_result = await pipeline_task
                if artifact_result.get("ok"):
                    stdout_msg = f"Created {artifact_result['name']} ({artifact_result['size']} bytes).\n"
                    yield f"data: {json.dumps({'type': 'stdout', 'text': stdout_msg})}\n\n"
                    yield f"data: {json.dumps({'type': 'artifact', 'name': artifact_result['name'], 'mime': artifact_result['mime'], 'size': artifact_result['size'], 'content_base64': artifact_result['content_base64']})}\n\n"
                    yield f"data: {json.dumps({'type': 'done', 'command': command, 'cwd': str(cwd_path), 'exit_code': 0, 'is_error': False, 'attempts': []})}\n\n"
                else:
                    err = f"Couldn't build the {artifact_fmt.upper()} ({artifact_result.get('stage', 'unknown')}): {artifact_result.get('error', 'unknown error')}"
                    yield f"data: {json.dumps({'type': 'stderr', 'text': err})}\n\n"
                    yield f"data: {json.dumps({'type': 'done', 'command': command, 'cwd': str(cwd_path), 'exit_code': 1, 'is_error': True, 'attempts': []})}\n\n"
                    build_error_text = artifact_result.get('error', 'unknown error')
                    explain_text = f"Could not build the {artifact_fmt.upper()} file: {build_error_text}. You can try again or adjust the request."
                    yield f"data: {json.dumps({'type': 'explain', 'text': explain_text})}\n\n"
                return
            if is_nl_query:
                if not model_ready:
                    load_result = chat_service._auto_load_model_with_stream(cwd_path, command)
                    async for chunk in load_result:
                        yield chunk
                    model_ready_now = NATIVE_GGUF_RUNTIME.is_loaded() or (
                        _config.inference.mode == InferenceMode.CLOUD
                        and bool(_config.inference.default_cloud_provider)
                        and _config.inference.default_cloud_provider in _config.cloud_providers
                    )
                    if not model_ready_now:
                        yield f"data: {json.dumps({'type': 'start', 'command': command, 'cwd': str(cwd_path), 'shell': 'internal'})}\n\n"
                        yield f"data: {json.dumps({'type': 'done', 'command': command, 'cwd': str(cwd_path), 'exit_code': 1, 'is_error': True, 'attempts': []})}\n\n"
                        yield f"data: {json.dumps({'type': 'explain', 'text': 'No local model could be auto-loaded, and no cloud provider is configured. Download a model in Settings → Models, or set up a cloud provider, then try again.'})}\n\n"
                        return
                    forced_mode = "local" if NATIVE_GGUF_RUNTIME.is_loaded() else forced_mode
                    forced_provider = "__native__" if NATIVE_GGUF_RUNTIME.is_loaded() else forced_provider
                yield f"data: {json.dumps({'type': 'thinking', 'text': 'Translating request into a shell command…'})}\n\n"
                translated = await chat_service._nl_to_shell_command(
                    command, str(cwd_path), model=model,
                    inference_mode=forced_mode, provider=forced_provider,
                )
                if translated.get("ok") and translated.get("command"):
                    translation_note = command
                    command = translated["command"]
                    yield f"data: {json.dumps({'type': 'repair', 'from': translation_note, 'to': command, 'reason': 'Translated natural-language request into a shell command.'})}\n\n"
                else:
                    err = translated.get("error") or "Could not translate the request into a command."
                    yield f"data: {json.dumps({'type': 'start', 'command': command, 'cwd': str(cwd_path), 'shell': 'internal'})}\n\n"
                    yield f"data: {json.dumps({'type': 'stderr', 'text': err})}\n\n"
                    yield f"data: {json.dumps({'type': 'done', 'command': command, 'cwd': str(cwd_path), 'exit_code': 1, 'is_error': True, 'attempts': []})}\n\n"
                    yield f"data: {json.dumps({'type': 'explain', 'text': f'Could not translate your request into a runnable command: {err}. Try rephrasing it more concretely, or type the shell command directly.'})}\n\n"
                    return
            current_command = command
            attempts = []
            seen = set()
            final_cwd = str(cwd_path)
            final_exit = 1
            final_error = True
            final_output = ""
            satisfied_note = ""

            for attempt_index in range(3):
                if current_command in seen:
                    break
                seen.add(current_command)
                shell = chat_service._terminal_shell_for_command(current_command, "windows" if os.name == "nt" else "posix")
                yield f"data: {json.dumps({'type': 'start', 'attempt': attempt_index + 1, 'command': current_command, 'cwd': final_cwd, 'shell': shell})}\n\n"

                stdout_parts: List[str] = []
                stderr_parts: List[str] = []
                try:
                    if os.name == "nt" and shell == "cmd":
                        proc = await _safe_create_subprocess_exec(
                            "cmd.exe", "/d", "/s", "/c", current_command,
                            stdout=asyncio.subprocess.PIPE,
                            stderr=asyncio.subprocess.PIPE,
                            cwd=final_cwd,
                            env={**os.environ, "TERM": "dumb"},
                        )
                    elif os.name == "nt":
                        proc = await _safe_create_subprocess_exec(
                            "powershell.exe", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", current_command,
                            stdout=asyncio.subprocess.PIPE,
                            stderr=asyncio.subprocess.PIPE,
                            cwd=final_cwd,
                            env={**os.environ, "TERM": "dumb"},
                        )
                    else:
                        proc = await _safe_create_subprocess_shell(
                            current_command,
                            stdout=asyncio.subprocess.PIPE,
                            stderr=asyncio.subprocess.PIPE,
                            cwd=final_cwd,
                            env={**os.environ, "TERM": "dumb"},
                        )

                    output_parts: List[str] = []
                    queue: asyncio.Queue = asyncio.Queue()

                    async def pump(stream, event_type: str, sink: List[str]):
                        while True:
                            chunk = await stream.readline()
                            if not chunk:
                                break
                            text = chunk.decode("utf-8", errors="replace")
                            output_parts.append(text)
                            sink.append(text)
                            await queue.put({"type": event_type, "text": text})

                    stdout_task = asyncio.create_task(pump(proc.stdout, "stdout", stdout_parts))
                    stderr_task = asyncio.create_task(pump(proc.stderr, "stderr", stderr_parts))
                    wait_task = asyncio.create_task(proc.wait())

                    # Enforce the timeout the frontend actually sent (it was
                    # being silently ignored before -- nothing here ever
                    # read body.get("timeout")). Without this, an
                    # interactive command with no args (bare `python`,
                    # `node`, `psql`, an editor, anything that waits on
                    # stdin instead of exiting) hangs proc.wait() forever,
                    # "done" never fires, and the client sits on "running..."
                    # with no way out short of a page reload.
                    try:
                        _requested_timeout_raw = float(body.get("timeout") or 120)
                    except (TypeError, ValueError):
                        _requested_timeout_raw = 120.0
                    requested_timeout = chat_service._estimate_command_timeout(current_command, _requested_timeout_raw)
                    proc_deadline = time.monotonic() + max(1.0, requested_timeout)
                    timed_out = False

                    while True:
                        if wait_task.done() and stdout_task.done() and stderr_task.done() and queue.empty():
                            break
                        if time.monotonic() > proc_deadline and not wait_task.done():
                            timed_out = True
                            try:
                                if os.name != "nt" and getattr(proc, "pid", None):
                                    try:
                                        os.killpg(os.getpgid(proc.pid), signal.SIGTERM)
                                    except Exception:
                                        pass
                                else:
                                    proc.kill()
                            except ProcessLookupError:
                                pass
                            except Exception:
                                pass
                            _timeout_first_word = re.split(r"\s+", current_command.strip().lower(), maxsplit=1)[0].strip("'\"") if current_command.strip() else ""
                            if _timeout_first_word in chat_service._INTERACTIVE_RISK_BINARIES:
                                _timeout_msg = (
                                    f"Command timed out after {requested_timeout:.0f}s and was terminated. "
                                    "If this was an interactive program (a REPL, a pager, an editor), it "
                                    "needs arguments or input piped in -- it cannot wait for keyboard input here."
                                )
                            else:
                                _timeout_msg = (
                                    f"Command timed out after {requested_timeout:.0f}s and was terminated. "
                                    "This can happen with very large searches or slow networks -- try narrowing "
                                    "the scope (a specific folder instead of the whole drive) or running it again."
                                )
                            yield f"data: {json.dumps({'type': 'stderr', 'text': _timeout_msg})}\n\n"
                            break
                        try:
                            item = await asyncio.wait_for(queue.get(), timeout=0.1)
                            yield f"data: {json.dumps(item)}\n\n"
                        except asyncio.TimeoutError:
                            continue

                    if timed_out:
                        for t in (stdout_task, stderr_task, wait_task):
                            t.cancel()
                        await asyncio.gather(stdout_task, stderr_task, wait_task, return_exceptions=True)
                        output = "".join(output_parts)
                        final_output = output
                        final_exit = -1
                        attempts.append({"command": current_command, "shell": shell, "exit_code": -1, "output_preview": (output[:500] + " [TIMED OUT]")})
                        final_error = True
                        break

                    await asyncio.gather(stdout_task, stderr_task, return_exceptions=True)
                    await wait_task
                    output = "".join(output_parts)
                    final_output = output
                    final_exit = proc.returncode or 0
                    probe = {"content": output, "exit_code": final_exit}
                    failed = chat_service._terminal_output_failed(probe)
                    attempts.append({"command": current_command, "shell": shell, "exit_code": final_exit, "output_preview": output[:500]})
                    final_error = failed
                    if not bool(body.get("auto_retry", True)) or not failed:
                        break

                    # Free regex table first (no LLM cost), then fall back to
                    # the goal-aware LLM reasoner for anything novel.
                    repaired = chat_service._repair_terminal_command_fast(current_command, output)
                    reason = "Output indicated this command failed; retrying with a known-good equivalent."
                    if not repaired and model_ready:
                        yield f"data: {json.dumps({'type': 'thinking', 'text': 'Command failed - reasoning about a fix from the real error output...'})}\n\n"
                        verdict = await chat_service._llm_terminal_reasoner(
                            goal=goal,
                            command=current_command,
                            shell=shell,
                            stdout="".join(stdout_parts),
                            stderr="".join(stderr_parts),
                            exit_code=final_exit,
                            history=attempts,
                            model=model,
                            inference_mode=forced_mode,
                            provider=forced_provider,
                        )
                        if verdict.get("action") == "satisfied":
                            final_error = False
                            satisfied_note = verdict.get("reason") or ""
                            yield f"data: {json.dumps({'type': 'thinking', 'text': satisfied_note or 'Output already answers the goal; treating as satisfied.'})}\n\n"
                            break
                        if verdict.get("action") == "retry" and verdict.get("command"):
                            repaired = verdict["command"]
                            reason = verdict.get("reason") or reason
                        else:
                            break
                    elif not repaired:
                        # No free regex fix, and no model loaded to reason
                        # about a real fix. Say so plainly instead of a
                        # silent give-up with no visible explanation.
                        yield f"data: {json.dumps({'type': 'thinking', 'text': 'Command failed and no model is loaded to suggest a fix.'})}\n\n"
                        break
                    if not repaired or repaired in seen:
                        break
                    yield f"data: {json.dumps({'type': 'repair', 'from': current_command, 'to': repaired, 'reason': reason})}\n\n"
                    current_command = repaired
                except Exception as exc:
                    attempts.append({"command": current_command, "shell": shell, "exit_code": 1, "output_preview": str(exc)[:500]})
                    yield f"data: {json.dumps({'type': 'stderr', 'text': f'Failed to execute command: {exc}'})}\n\n"
                    final_exit = 1
                    final_error = True
                    break

            yield f"data: {json.dumps({'type': 'done', 'command': current_command, 'cwd': final_cwd, 'exit_code': final_exit, 'is_error': final_error, 'attempts': attempts})}\n\n"

            # Final grounded explanation, streamed as its own event so the
            # UI can render it distinctly from raw terminal bytes.
            #
            # This call has no bound of its own -- chat_completion() is a
            # plain non-streaming await, so if the underlying model stalls
            # (same failure mode as the GGUF streaming path, just with no
            # protection at all here), this line never returns, "explain"
            # is never yielded, and the client sits on "Reading the real
            # output and preparing an answer..." forever with no recourse.
            # Bound it explicitly and always fall back to the free,
            # zero-cost explanation so the stream is guaranteed to close.
            try:
                if satisfied_note:
                    explanation = satisfied_note
                else:
                    # User requires the explanation to come from the local
                    # model specifically -- never fall through to a cloud
                    # provider or the "auto" default. If nothing is loaded
                    # yet, auto-load the best local GGUF model first (same
                    # helper the artifact_fmt branch above already uses)
                    # instead of giving up and using the canned fallback.
                    if not NATIVE_GGUF_RUNTIME.is_loaded():
                        yield f"data: {json.dumps({'type': 'thinking', 'text': 'No model is loaded -- auto-loading a local model to write the analysis...'})}\n\n"
                        load_result = chat_service._auto_load_model_with_stream(cwd_path, current_command)
                        async for chunk in load_result:
                            yield chunk
                    if NATIVE_GGUF_RUNTIME.is_loaded():
                        yield f"data: {json.dumps({'type': 'thinking', 'text': 'Reading the real command output...'})}\n\n"
                        yield f"data: {json.dumps({'type': 'thinking', 'text': 'Writing the analysis with the local model...'})}\n\n"

                        explanation_parts: List[str] = []
                        explain_deadline = time.monotonic() + 90.0

                        async def _drain_explanation_stream():
                            async for piece in chat_service._explain_terminal_result_llm_stream(
                                current_command, final_output, final_exit, goal=goal,
                                shell=shell, cwd=final_cwd,
                            ):
                                explanation_parts.append(piece)
                                yield piece

                        stream_iter = _drain_explanation_stream().__aiter__()
                        while True:
                            remaining = explain_deadline - time.monotonic()
                            if remaining <= 0:
                                raise asyncio.TimeoutError("Terminal explanation stream exceeded its time budget")
                            try:
                                piece = await asyncio.wait_for(stream_iter.__anext__(), timeout=remaining)
                            except StopAsyncIteration:
                                break
                            yield f"data: {json.dumps({'type': 'explain_chunk', 'text': piece})}\n\n"

                        explanation = "".join(explanation_parts).strip()
                        if not explanation:
                            explanation = chat_service._explain_terminal_result_fast(
                                current_command, final_output, final_exit, shell=shell, cwd=final_cwd,
                            )
                        yield f"data: {json.dumps({'type': 'thinking', 'text': 'Analysis ready.'})}\n\n"
                    else:
                        explanation = chat_service._explain_terminal_result_fast(
                            current_command, final_output, final_exit, shell=shell, cwd=final_cwd,
                        )
            except Exception as _explain_exc:
                logger.warning(f"Terminal final-explanation LLM path failed: {_explain_exc}")
                explanation = chat_service._explain_terminal_result_fast(
                    current_command, final_output, final_exit, shell=shell, cwd=final_cwd,
                )
            yield f"data: {json.dumps({'type': 'explain', 'text': explanation})}\n\n"

        return StreamingResponse(stream_events(), media_type="text/event-stream", headers={"Cache-Control": "no-cache", "Connection": "keep-alive", "X-Accel-Buffering": "no"})

    @router.post("/v1/chat/completions")
    @router.post("/api/v1/chat/completions")
    async def openai_chat_completion(request: ChatCompletionRequest):
        """OpenAI-compatible chat completion entry point. Delegates to the same
        ChatService used by /api/chat so grounding, RAG, MCP tools, and dual
        GGUF/cloud inference all behave identically across every chat route."""
        return await chat_service.chat_completion(request)

    def _build_chat_request(body: dict, stream: bool) -> ChatCompletionRequest:
        messages = body.get("messages")
        if not isinstance(messages, list) or not messages:
            message = str(body.get("message") or body.get("prompt") or "").strip()
            messages = [{"role": "user", "content": message}]

        model = str(body.get("model") or persistence.config.inference.default_model or "").strip()
        if not model:
            local_models = scan_local_gguf_library()
            model = str(local_models[0]["id"]) if local_models else "local-model"

        payload = {
            "model": model,
            "messages": messages,
            "temperature": body.get("temperature"),
            "top_p": body.get("top_p"),
            "top_k": body.get("top_k"),
            "max_tokens": body.get("max_tokens"),
            "reasoning": body.get("reasoning"),
            "strong_reasoning": body.get("strong_reasoning"),
            "voice_mode": bool(body.get("voice_mode", False)),
            "stream": stream,
            "stop": body.get("stop") or ["<|im_end|>", "<|eot_id|>", "<|end_of_text|>", "<end_of_turn>", "<|end|>", "<|endoftext|>", "</s>", "<eos>"],
            "frequency_penalty": body.get("frequency_penalty"),
            "presence_penalty": body.get("presence_penalty"),
            "repetition_penalty": body.get("repetition_penalty"),
            "tools": body.get("tools"),
            "tool_choice": body.get("tool_choice"),
            "response_format": body.get("response_format"),
            "seed": body.get("seed"),
            "inference_mode": body.get("inference_mode"),
            "provider": body.get("provider"),
            "conversation_id": body.get("conversation_id"),
            "user_context": body.get("user_context"),
            "use_rag": bool(body.get("use_rag", body.get("wikipedia_grounding", False))),
            "use_web_grounding": body.get("use_web_grounding") if "use_web_grounding" in body else None,
            "use_mcp": bool(body.get("use_mcp", True)),
            "enable_image_search": bool(body.get("enable_image_search", body.get("wikipedia_grounding", True))),
            "enable_file_tools": bool(body.get("enable_file_tools", True)),
            "rag_top_k": int(body.get("rag_top_k", 5) or 5),
            # These two were previously dropped here even though ChatCompletionRequest
            # supports them - /api/chat and /api/chat/stream (the routes the actual
            # frontend calls) take a raw `dict` and hand-pick which keys survive into
            # the validated request, so document_ids/attachments never reached
            # chat_completion() no matter what the frontend sent. That silent drop -
            # not the intent-routing logic - was why attached files were never read.
            "document_ids": body.get("document_ids"),
            "attachments": body.get("attachments"),
            "user_integrations": body.get("user_integrations"),
            "skip_terminal_autoexec": body.get("skip_terminal_autoexec"),
        }
        return ChatCompletionRequest(**{k: v for k, v in payload.items() if v is not None})

    def _extract_reply(response: dict) -> str:
        try:
            choice = (response.get("choices") or [{}])[0]
            message = choice.get("message") or {}
            content = message.get("content")
            if isinstance(content, str):
                return content
            if isinstance(content, list):
                return "\n".join(
                    str(part.get("text") or "")
                    for part in content
                    if isinstance(part, dict) and part.get("type") == "text"
                ).strip()
        except Exception:
            pass
        return ""

    def _runtime_error_reply(error: Exception) -> str:
        detail = getattr(error, "detail", None)
        message = str(detail or error).strip()
        local_models = scan_local_gguf_library()
        if local_models and (
            "connection" in message.lower()
            or "connect" in message.lower()
            or "all connection attempts failed" in message.lower()
        ):
            return (
                "Local GGUF model is detected and loaded in the library, but no local inference server is reachable. "
                "Start LM Studio, Ollama, or llama.cpp server, then reload the selected model."
            )
        return message or "Unable to generate a response."

    async def _fallback_reply_for_body(body: dict) -> str:
        messages = body.get("messages")
        if not isinstance(messages, list):
            messages = []
        last_user_msg = ""
        for message in reversed(messages):
            if isinstance(message, dict) and message.get("role") == "user":
                content = message.get("content", "")
                last_user_msg = content if isinstance(content, str) else str(content)
                break
        if not last_user_msg.strip():
            last_user_msg = str(body.get("message") or body.get("prompt") or "").strip()
        wants_web = bool(body.get("use_web_grounding", body.get("wikipedia_grounding", False)))
        if last_user_msg and wants_web:
            try:
                web_context = await image_search.web_summary(last_user_msg, 5)
                if web_context:
                    # NEVER expose the raw scraper/search payload to the user.
                    # This route is a last-resort path used when the normal chat
                    # pipeline produced no answer tokens. The previous code
                    # returned web_summary() verbatim, which leaked source
                    # metadata, URLs, dates, table-of-contents text, and search
                    # boilerplate directly into the chat bubble. Reuse the same
                    # deterministic grounded renderer as the main agent path.
                    cleaned = chat_service._build_grounded_web_fallback_reply(
                        last_user_msg, web_context
                    )
                    if cleaned:
                        return cleaned
                    return (
                        "I retrieved live web information, but I could not safely "
                        "turn it into a complete answer. Please retry the request."
                    )
            except Exception as exc:
                logger.debug(f"Fallback web grounding skipped: {exc}")
        return "The model did not return answer tokens for that request. Check that the selected local model runtime is running, then try again."

    @router.post("/api/chat")
    async def app_chat(body: dict):
        request = _build_chat_request(body, stream=False)
        try:
            response = await chat_service.chat_completion(request)
            reply = _extract_reply(response if isinstance(response, dict) else {})
            if not reply.strip():
                reply = await _fallback_reply_for_body(body)
            result = {
                "ok": True,
                "reply": reply,
                "model_id": request.model,
                "model_label": request.model,
            }
            # Auto-generate smart title for new conversations
            conv_id = body.get("conversation_id", "")
            if conv_id:
                conv = persistence.get_conversation(conv_id)
                if conv and (not conv.title or conv.title == "New Chat"):
                    smart_title = await _generate_title_from_messages(conv_id, conv)
                    if smart_title:
                        result["generated_title"] = smart_title
            return result
        except Exception as exc:
            reply = _runtime_error_reply(exc)
            if not reply.strip():
                reply = await _fallback_reply_for_body(body)
            return {
                "ok": False,
                "reply": reply,
                "error": reply,
                "model_id": request.model,
                "model_label": request.model,
            }

    async def _generate_title_from_messages(conv_id: str, conv) -> Optional[str]:
        """Fire-and-forget smart title generation using the model.
        Returns the generated title or None on failure."""
        try:
            first_user_msg = ""
            for msg in conv.messages:
                if msg.get("role") == "user":
                    content = msg.get("content", "")
                    if isinstance(content, str):
                        first_user_msg = content.strip()
                    elif isinstance(content, list):
                        first_user_msg = " ".join(
                            part.get("text", "") for part in content
                            if isinstance(part, dict) and part.get("type") == "text"
                        ).strip()
                    break

            if not first_user_msg:
                return None

            title_context = first_user_msg[:500]
            config = persistence.config
            mode = config.inference.mode
            if mode == InferenceMode.CLOUD:
                provider_id = config.inference.default_cloud_provider or next(iter(config.cloud_providers), "")
            else:
                provider_id = config.inference.default_local_provider or "lmstudio"

            model = conv.model or config.inference.default_model or ""
            if not model:
                local_models = scan_local_gguf_library()
                model = str(local_models[0]["id"]) if local_models else "local-model"

            title_messages = [
                {"role": "system", "content": (
                    "Generate a concise, smart conversation title (max 6 words). "
                    "Rules: Do NOT use the user's raw text. No quotes, no emojis. "
                    "Title case. For math: name the topic (e.g. 'Quadratic Equation Solving'). "
                    "For code: name the tech/task (e.g. 'Python API Development'). "
                    "For questions: name the topic (e.g. 'Quantum Physics Explained'). "
                    "Output ONLY the title, nothing else."
                )},
                {"role": "user", "content": title_context},
            ]

            if mode == InferenceMode.CLOUD:
                response = await cloud_engine.chat_completion(
                    provider_id, model, title_messages,
                    {"temperature": 0.3, "max_tokens": 30}, stream=False
                )
            else:
                response = await local_engine.chat_completion(
                    provider_id, model, title_messages,
                    {"temperature": 0.3, "max_tokens": 30}, stream=False
                )

            content = ""
            if isinstance(response, dict):
                content = (
                    response.get("choices", [{}])[0]
                    .get("message", {}).get("content", "")
                )
            if content:
                smart_title = re.sub(r'\s+', ' ', content.strip().strip('"').strip("'")).strip()
                if len(smart_title) > 80:
                    smart_title = smart_title[:77].rsplit(' ', 1)[0] + "..."
                if smart_title:
                    persistence.update_conversation_title(conv_id, smart_title)
                    return smart_title
        except Exception as e:
            logger.debug(f"Auto title generation skipped for {conv_id}: {e}")
        return None

    @router.post("/api/chat/stream")
    async def app_chat_stream(body: dict):
        request = _build_chat_request(body, stream=True)
        provider_id, mode = chat_service._determine_provider(request)
        request_messages = [m.model_dump(exclude_none=True) for m in request.messages]
        last_user_msg = chat_service._latest_user_message(request_messages)
        retrieval_route = chat_service._request_retrieval_route(
            last_user_msg, bool(body.get("voice_mode")),
        )

        def sse(event: str, payload: dict) -> str:
            return f"event: {event}\ndata: {json.dumps(payload, ensure_ascii=False)}\n\n"

        # `chat_completion` does real pre-processing work (RAG lookup, file
        # reading, live web search, query generation) before it can even
        # return a StreamingResponse, AND the agentic tool-calling loop keeps
        # calling tools (search_web, RAG, filesystem) throughout the token
        # stream *after* that too. Every one of those calls pushes an
        # ExecutionEvent onto `step_queue` via ExecutionManager, from
        # whatever coroutine happens to be running at the time.
        #
        # IMPORTANT: `chat_task` (chat_completion) completes as soon as it
        # *returns* the StreamingResponse object, which happens almost
        # immediately, before the response body is ever iterated. The actual
        # tool calls run later, inside `upstream.body_iterator`, once we
        # start consuming it below. A previous version of this endpoint only
        # drained `step_queue` while `chat_task` was still running, so every
        # execution event emitted during real tool calls (the ones the
        # frontend most wants to show) was pushed into a queue nobody was
        # reading anymore and silently lost.
        #
        # Fix: drain `step_queue` on its own background task for the ENTIRE
        # lifetime of the request, merging it with the token/thinking/step
        # chunks coming out of `upstream.body_iterator` via one shared queue.
        step_queue: "asyncio.Queue" = asyncio.Queue()
        merge_queue: "asyncio.Queue" = asyncio.Queue()
        _STEP_DONE = object()

        async def pump_step_queue():
            """Forward ExecutionManager events into merge_queue for as long
            as the request is alive, independent of what phase the model's
            own stream is in."""
            try:
                while True:
                    item = await step_queue.get()
                    if item is _STEP_DONE:
                        break
                    evt_type = item.get("type", "step") if isinstance(item, dict) else "step"
                    evt_data = item.get("data", item) if isinstance(item, dict) else item
                    await merge_queue.put(("event", evt_type, evt_data))
            except asyncio.CancelledError:
                pass

        pump_task = asyncio.create_task(pump_step_queue())

        # ------------------------------------------------------------------
        # LIFECYCLE ENGINE
        # ------------------------------------------------------------------
        # Root cause of the frontend being stuck on "Sending Request...":
        # the old stream() body began with `upstream = await chat_task`, so
        # the SSE generator produced ZERO bytes until chat_completion()
        # finished ALL of its pre-processing (RAG lookup, context building,
        # web search, etc). pump_step_queue() was already forwarding those
        # real _emit_step()/ExecutionManager events into merge_queue the
        # whole time -- but nothing was ever draining merge_queue and
        # yielding it to the client until chat_task resolved, so every
        # lifecycle stage arrived all-at-once, after the fact, instead of
        # live. The frontend just sat there with nothing to render.
        #
        # Fix: the generator now starts draining merge_queue on its very
        # first iteration, in parallel with chat_task actually running.
        # Real stage events (connecting -> understanding_context ->
        # searching_web -> reasoning -> composing -> streaming tokens) reach
        # the client the instant they're emitted, and only once chat_task
        # resolves do we start pumping the model's own token/thinking body.
        _LIFECYCLE_START = time.time()
        final_reply_parts: List[str] = []
        saw_done = False
        # Fast intro: keep the visible sequence polished without paying for
        # an extra model round just to say "let me check that."
        voice_mode = bool(body.get("voice_mode"))
        if retrieval_route == "web" and re.search(r"\b(?:news|headlines?|current events?)\b", last_user_msg, flags=re.I):
            initial_opening = "Let me check the latest headlines and verify what changed."
        elif retrieval_route == "web":
            initial_opening = "Let me check the live sources and pull together a clear answer."
        elif retrieval_route == "terminal":
            initial_opening = "Let me take a look at that."
        elif voice_mode:
            initial_opening = ""
        else:
            initial_opening = ""

        _last_lifecycle_id: Optional[str] = None
        _last_lifecycle_label: Optional[str] = None

        async def emit_lifecycle(stage: str, label: str, progress: int, detail: Optional[str] = None) -> None:
            """Synthetic, mechanical lifecycle markers for the connection
            itself (as opposed to _emit_step, which narrates the model's
            own work). Guarantees the client always has a real, current
            stage to render instead of a frozen placeholder.

            Self-completing, same pattern as _emit_step: starting a new
            lifecycle stage marks the previous one complete first, so the
            timeline only ever shows one lifecycle row RUNNING at a time
            instead of every stage that's ever fired all sitting open
            together."""
            nonlocal _last_lifecycle_id, _last_lifecycle_label
            if _last_lifecycle_id and _last_lifecycle_id != stage:
                await merge_queue.put((
                    "event",
                    "step",
                    {
                        "stage": _last_lifecycle_id,
                        "label": _last_lifecycle_label or "Done",
                        "progress": 100,
                        "ts": time.time(),
                        "source": "lifecycle",
                    },
                ))
            _last_lifecycle_id = stage
            _last_lifecycle_label = label
            await merge_queue.put((
                "event",
                "step",
                {
                    "stage": stage,
                    "label": label,
                    "progress": max(0, min(100, int(progress))),
                    "detail": detail,
                    "ts": time.time(),
                    "source": "lifecycle",
                },
            ))

        lifecycle_hidden = False

        async def hide_lifecycle() -> None:
            """Fires once, the instant the first real token/content chunk
            arrives from the model. Whatever lifecycle stage was still open
            at that point ('Receiving response' / 'Generating response')
            has nothing further to report once actual output exists, so
            it's marked complete and removed rather than left frozen.
            Uses whichever stage id was last opened, so it correctly covers
            both the hosted-provider path (streaming) and the native
            local-GGUF path (reasoning) without needing to know in advance
            which one is active."""
            nonlocal lifecycle_hidden, _last_lifecycle_id, _last_lifecycle_label
            if lifecycle_hidden:
                return
            lifecycle_hidden = True
            ids_to_clear = ["connecting", "streaming", "reasoning"]
            if _last_lifecycle_id and _last_lifecycle_id not in ids_to_clear:
                ids_to_clear.append(_last_lifecycle_id)
            await merge_queue.put((
                "event",
                "lifecycle_clear",
                {"ids": ids_to_clear, "ts": time.time()},
            ))



        async def run_pipeline():
            """Owns the full lifecycle of this request: wait for
            chat_completion() to hand back its StreamingResponse (emitting
            real progress the whole time via pump_step_queue, which is
            already running), then pump that response's own SSE body into
            merge_queue. Runs as its own task so the outer generator can
            start draining merge_queue immediately instead of blocking."""
            nonlocal final_reply_parts, saw_done
            try:
                route_provider, route_mode = chat_service._determine_provider(request)
                route_label = (
                    "Preparing local GGUF inference · on device"
                    if route_provider == "__native__" and route_mode == "local"
                    else "Connecting to local model server" if route_mode == "local"
                    else "Connecting to cloud provider · uses provider tokens"
                )
                await emit_lifecycle("connecting", route_label, 2)
                # Agentic coding and deep research remain fully usable locally, but surface a
                # first-class optional cloud connection CTA when no cloud provider is configured.
                # The frontend renders this as a button inside the chat; no API key is ever placed
                # into the model prompt or browser storage.
                if route_mode == "local" and (chat_service._is_deep_research_intent(last_user_msg) or chat_service._is_copilot_terminal_intent(last_user_msg)):
                    connected_clouds = [pid for pid, conn in chat_service.persistence.config.cloud_providers.items() if getattr(conn, "connected", False)]
                    if not connected_clouds:
                        await merge_queue.put(("raw", None, sse("cloud_connect_request", {
                            "title": "Connect a cloud provider for advanced agentic work",
                            "description": "Your local model can continue now. Connect an API provider if you want stronger coding/research models for this task.",
                            "action": "connect_cloud",
                            "settings_section": "models",
                        })))
                
                _config = chat_service.persistence.config
                _mode = request.inference_mode or _config.inference.mode
                # Only auto-load a native GGUF when the user did NOT pick a
                # local server provider explicitly. If they selected
                # LM Studio / Ollama / llama.cpp / KoboldCpp with a model,
                # honor that choice and talk to the server instead of
                # silently overriding it with native in-process inference.
                _local_server_providers = {"lmstudio", "ollama", "llamacpp", "koboldcpp"}
                _explicit_server_provider = bool(
                    request.provider and request.provider not in ("__native__", "native", "")
                )
                if _mode != InferenceMode.CLOUD and NATIVE_GGUF_RUNTIME.is_loading():
                    await emit_lifecycle("loading", "Finishing local model preparation...", 50)
                    await NATIVE_GGUF_RUNTIME.wait_for_pending_load()
                _should_auto_load = (
                    _mode != InferenceMode.CLOUD
                    and not NATIVE_GGUF_RUNTIME.is_loaded()
                    and not _explicit_server_provider
                )
                if _should_auto_load:
                    await emit_lifecycle("loading", "Auto-loading local model...", 5)
                    async def _on_progress(evt: dict) -> None:
                        prog = evt.get("progress", 0)
                        if prog == 0:
                            prog = 50
                        await emit_lifecycle("loading", f"Loading: {evt.get('label', '')}", prog)
                    
                    load_result = await chat_service._auto_load_best_local_model(on_progress=_on_progress)
                    if not load_result.get("ok"):
                        err_msg = load_result.get("error") or "Unknown error"
                        await emit_lifecycle("error", "Model load failed", 100, err_msg)
                        await merge_queue.put(("raw", None, sse("done", {
                            "error": f"Could not load local model: {err_msg}",
                            "reply": "",
                        })))
                        return

                # Private-data integration CTA works for both local and cloud models.
                # The actual OAuth credential remains server-side.
                _integration_request = None
                _lower_req = str(last_user_msg or "").lower()
                if re.search(r"\b(?:gmail|email|inbox|mail)\b", _lower_req) and not chat_service._gmail_connected():
                    _integration_request = {"app_id":"gmail","title":"Connect Gmail to use your private mail","description":"Meera can read, search, draft, reply, and send using your connected Gmail account.","action":"connect_integration"}
                elif re.search(r"\b(?:github|repository|repo|pull request|issue)\b", _lower_req) and not chat_service.oauth_tokens.get("github", {}).get("access_token"):
                    _integration_request = {"app_id":"github","title":"Connect GitHub to use your private repositories","description":"Meera can inspect private repositories, files, issues, and project data after you authorize GitHub.","action":"connect_integration"}
                elif re.search(r"\b(?:google drive|gdrive|drive file|drive files)\b", _lower_req) and not chat_service.oauth_tokens.get("gdrive", {}).get("access_token") and not chat_service.oauth_tokens.get("google", {}).get("access_token"):
                    _integration_request = {"app_id":"gdrive","title":"Connect Google Drive to use your private files","description":"Meera can search and read your Drive files with your permission.","action":"connect_integration"}
                if _integration_request:
                    await merge_queue.put(("raw", None, sse("integration_connect_request", _integration_request)))

                try:
                    chat_task = asyncio.create_task(chat_service.chat_completion(request, step_queue))
                    upstream = await chat_task
                except Exception as exc:
                    logger.error(f"chat_completion failed: {exc}\n{traceback.format_exc()}")
                    await emit_lifecycle("error", "Request failed", 100, str(exc)[:140])
                    await merge_queue.put(("raw", None, sse("done", {
                        "error": str(exc) or "The request failed unexpectedly.",
                        "reply": "",
                        "model_id": request.model,
                        "model_label": request.model,
                    })))
                    return

                if not isinstance(upstream, StreamingResponse):
                    # Defensive fallback: non-streaming result (shouldn't
                    # normally happen since request.stream is forced True).
                    reply = ""
                    try:
                        body_obj = getattr(upstream, "body", None)
                        if body_obj:
                            parsed = json.loads(body_obj)
                            reply = parsed.get("choices", [{}])[0].get("message", {}).get("content", "")
                    except Exception:
                        pass
                    await merge_queue.put(("raw", None, sse("done", {
                        "reply": reply, "model_id": request.model, "model_label": request.model,
                    })))
                    return

                # Removed redundant 'Receiving response' lifecycle emission

                try:
                    async for chunk in upstream.body_iterator:
                        text = chunk.decode("utf-8", errors="ignore") if isinstance(chunk, (bytes, bytearray)) else str(chunk)
                        for raw_event in [part for part in text.split("\n\n") if part.strip()]:
                            event_line = next((line for line in raw_event.splitlines() if line.startswith("event:")), "")
                            data_line = next((line for line in raw_event.splitlines() if line.startswith("data:")), "")
                            if event_line and data_line:
                                event_name = event_line.split(":", 1)[1].strip()
                                if event_name == "token":
                                    try:
                                        payload = json.loads(data_line.split(":", 1)[1].strip())
                                        chunk_text = str(payload.get("chunk") or "")
                                        if chunk_text:
                                            final_reply_parts.append(chunk_text)
                                            await hide_lifecycle()
                                    except Exception:
                                        pass
                                if event_name == "done":
                                    saw_done = True
                                    # Safety net: if the model produced zero
                                    # content tokens (empty completion, or an
                                    # error that still reached its `finally`),
                                    # the token-triggered clear above never
                                    # fires. `done` is emitted unconditionally
                                    # on every path, so clearing here too
                                    # guarantees the lifecycle rows never hang
                                    # forever even in that edge case.
                                if event_name in {
                                    "token", "thinking", "thinking_start", "thinking_end", "thinking_blocks",
                                    "step", "images", "user_data_request", "browser_screenshot", "browser_mission",
                                    "done", "document_ready", "clear_tokens", "execution",
                                    "subagent_start", "subagent_step", "subagent_done", "cloud_connect_request", "integration_connect_request"
                                }:
                                    await merge_queue.put(("raw", None, raw_event + "\n\n"))
                                continue

                            if not raw_event.startswith("data:"):
                                continue
                            data_text = raw_event.split(":", 1)[1].strip()
                            if data_text == "[DONE]":
                                continue
                            try:
                                parsed = json.loads(data_text)
                            except Exception:
                                continue
                            delta = (parsed.get("choices") or [{}])[0].get("delta") or {}
                            chunk_text = delta.get("content")
                            if isinstance(chunk_text, str) and chunk_text:
                                final_reply_parts.append(chunk_text)
                                await merge_queue.put(("event", "token", {"chunk": chunk_text}))
                                await hide_lifecycle()
                except Exception as exc:
                    logger.error(f"pump_body failed: {exc}\n{traceback.format_exc()}")
                    await emit_lifecycle("error", "Stream interrupted", 100, str(exc)[:140])
            finally:
                await merge_queue.put(("close", None, None))

        async def stream():
            if initial_opening:
                yield sse("intro", {"chunk": initial_opening})
            pipeline_task = asyncio.create_task(run_pipeline())

            try:
                # Drain the merged stream from the very first iteration --
                # execution events, lifecycle stages, and model output all
                # arrive interleaved, in true real-time arrival order, no
                # matter which phase chat_task/run_pipeline is currently in.
                while True:
                    kind, evt_type, evt_data = await merge_queue.get()
                    if kind == "close":
                        break
                    if kind == "raw":
                        yield evt_data
                        continue
                    yield sse(evt_type, evt_data)

                # The model's own stream has ended. Flush anything already
                # sitting in step_queue (e.g. a trailing exec_manager.complete()
                # fired the instant the last token went out) so nothing is
                # dropped.
                await asyncio.sleep(0)
                while not step_queue.empty():
                    try:
                        item = step_queue.get_nowait()
                    except Exception:
                        break
                    evt_type = item.get("type", "step") if isinstance(item, dict) else "step"
                    evt_data = item.get("data", item) if isinstance(item, dict) else item
                    yield sse(evt_type, evt_data)
            finally:
                # Covers both the normal-completion path above and a client
                # disconnect (GeneratorExit raised into this generator) --
                # either way, don't leak the background tasks.
                step_queue.put_nowait(_STEP_DONE)
                pump_task.cancel()
                pipeline_task.cancel()

            try:
                await pipeline_task
            except (Exception, asyncio.CancelledError) as exc:
                if not isinstance(exc, asyncio.CancelledError):
                    logger.error(f"run_pipeline failed: {exc}\n{traceback.format_exc()}")

            if not saw_done:
                fallback_reply = "".join(final_reply_parts).strip()
                if not fallback_reply:
                    try:
                        fallback_reply = await _fallback_reply_for_body(body)
                    except Exception as exc:
                        logger.error(f"stream fallback reply failed: {exc}\n{traceback.format_exc()}")
                        fallback_reply = "The model stream ended before returning answer tokens."
                done_payload = {
                    "reply": fallback_reply,
                    "model_id": request.model,
                    "model_label": request.model,
                }
                # Auto-generate a smart title if conversation is still "New Chat"
                conv_id = body.get("conversation_id", "")
                if conv_id:
                    conv = persistence.get_conversation(conv_id)
                    if conv and (not conv.title or conv.title == "New Chat"):
                        smart_title = await _generate_title_from_messages(conv_id, conv)
                        if smart_title:
                            done_payload["generated_title"] = smart_title
                yield sse("done", done_payload)

            # If the upstream emitted its own "done", also try title generation
            if saw_done:
                conv_id_for_title = body.get("conversation_id", "")
                if conv_id_for_title:
                    conv = persistence.get_conversation(conv_id_for_title)
                    if conv and (not conv.title or conv.title == "New Chat"):
                        smart_title = await _generate_title_from_messages(conv_id_for_title, conv)
                        if smart_title:
                            yield sse("title", {"title": smart_title})

        return StreamingResponse(
            stream(),
            media_type="text/event-stream",
            headers={
                # Never allow an intermediary/proxy/compression layer to coalesce
                # the model's SSE frames. This is a local desktop app, so each
                # token/phase event should reach fetch().body immediately.
                "Cache-Control": "no-cache, no-transform",
                "Connection": "keep-alive",
                "X-Accel-Buffering": "no",
                "Content-Encoding": "identity",
                "X-Content-Type-Options": "nosniff",
            },
        )

