    @router.post("/api/conversations/{conv_id}/generate-title")
    async def generate_smart_title(conv_id: str):
        """Use the AI model to generate a smart, concise conversation title
        based on the user's first message. The title is crafted by the model
        to be a clean, descriptive headline - not raw user text."""
        conv = persistence.get_conversation(conv_id)
        if not conv:
            raise HTTPException(404, "Conversation not found")

        # Only generate a title for "New Chat" or empty titles
        if conv.title and conv.title != "New Chat":
            return {"title": conv.title, "status": "already_named"}

        # Extract the first user message as context
        first_user_msg = ""
        for msg in conv.messages:
            if msg.get("role") == "user":
                content = msg.get("content", "")
                if isinstance(content, str):
                    first_user_msg = content.strip()
                elif isinstance(content, list):
                    # Multimodal content - extract text parts
                    first_user_msg = " ".join(
                        part.get("text", "") for part in content
                        if isinstance(part, dict) and part.get("type") == "text"
                    ).strip()
                break

        if not first_user_msg:
            return {"title": "New Chat", "status": "no_content"}

        # Truncate very long first messages
        title_context = first_user_msg[:500] if len(first_user_msg) > 500 else first_user_msg

        # Determine provider and model for title generation
        config = persistence.config
        mode = config.inference.mode
        if mode == InferenceMode.CLOUD:
            provider_id = config.inference.default_cloud_provider or ""
            if not provider_id:
                provider_id = next(iter(config.cloud_providers), "")
        else:
            provider_id = config.inference.default_local_provider or "lmstudio"

        model = conv.model or config.inference.default_model or ""
        if not model:
            local_models = scan_local_gguf_library()
            model = str(local_models[0]["id"]) if local_models else "local-model"

        title_prompt = (
            "You generate extremely concise, smart conversation titles. "
            "Given the user's first message below, output ONLY a short title "
            "(max 6 words) that captures the essence of the conversation. "
            "Rules:\n"
            "- Do NOT use the user's raw text as the title.\n"
            "- Do NOT use quotation marks, emojis, or special formatting.\n"
            "- Make it read like a polished headline or topic label.\n"
            "- Use title case (capitalize first letter of each word).\n"
            "- If the message is a math problem, name it by the math topic "
            "(e.g. 'Quadratic Equation Solving', 'Integral Calculus').\n"
            "- If it's a coding request, name the tech or task "
            "(e.g. 'Python API Development', 'React Component Build').\n"
            "- If it's a question about a person/place/thing, name the topic "
            "(e.g. 'Quantum Physics Explained', 'Roman Empire History').\n"
            "- For casual chat, summarize the vibe in 2-4 words.\n"
            "- Output ONLY the title text, nothing else.\n\n"
            f"User's message: {title_context}"
        )

        title_messages = [
            {"role": "system", "content": title_prompt},
            {"role": "user", "content": title_context},
        ]
        title_params = {"temperature": 0.3, "max_tokens": 30}

        try:
            if mode == InferenceMode.CLOUD:
                response = await cloud_engine.chat_completion(
                    provider_id, model, title_messages, title_params, stream=False
                )
            else:
                response = await local_engine.chat_completion(
                    provider_id, model, title_messages, title_params, stream=False
                )

            content = ""
            if isinstance(response, dict):
                content = (
                    response.get("choices", [{}])[0]
                    .get("message", {})
                    .get("content", "")
                )
            if content:
                # Clean up the title
                smart_title = content.strip().strip('"').strip("'").strip()
                # Remove any leading/trailing whitespace, newlines
                smart_title = re.sub(r'\s+', ' ', smart_title).strip()
                # Truncate to 80 chars
                if len(smart_title) > 80:
                    smart_title = smart_title[:77].rsplit(' ', 1)[0] + "..."

                if smart_title:
                    persistence.update_conversation_title(conv_id, smart_title)
                    return {"title": smart_title, "status": "generated"}
        except Exception as e:
            logger.warning(f"Smart title generation failed for {conv_id}: {e}")

        # Fallback: create a basic title from first few words
        fallback = first_user_msg[:50].strip()
        if len(first_user_msg) > 50:
            fallback = fallback.rsplit(' ', 1)[0] + "..."
        persistence.update_conversation_title(conv_id, fallback)
        return {"title": fallback, "status": "fallback"}

