    @router.get("/api/models/local", response_model=ModelsList)
    async def list_local_models(force_refresh: bool = False):
        models = await model_manager.get_local_models(force_refresh)
        local_scan = scan_local_gguf_library()
        seen = {model.id for model in models}
        for entry in local_scan:
            if entry["id"] not in seen:
                models.append(ModelInfo(
                    id=entry["id"],
                    name=entry["label"],
                    provider="local_disk",
                    owned_by=entry.get("repo_id") or entry["folder"],
                    quantization=str(entry.get("precision") or entry.get("quant_bits") or ""),
                    quant_category=None,
                    size_gb=round(float(entry.get("size_bytes", 0)) / (1024**3), 2) if entry.get("size_bytes") else None,
                    is_gguf=True,
                    is_local=True,
                    capabilities=entry.get("capabilities", ["streaming"]),
                    modified_at=None,
                ))
        return ModelsList(data=models)

