    @router.post("/api/models/token")
    async def save_hf_token(body: dict):
        token = str(body.get("token") or "").strip()
        if not token:
            raise HTTPException(400, "token is required")
        payload = read_json_object(HF_TOKEN_FILE, {"tokens": []})
        tokens = payload.get("tokens", [])
        if not isinstance(tokens, list):
            tokens = []
        tokens = [value for value in tokens if isinstance(value, str) and value.strip()]
        if token not in tokens:
            tokens.append(token)
        write_json_object(HF_TOKEN_FILE, {"tokens": tokens})
        return {"ok": True, "hf_token_set": True, "token_count": len(tokens), "message": "Hugging Face token saved."}

