    @router.get("/api/models/load/stream")
    async def load_model_stream():
        async def stream():
            last_snapshot = ""
            # Push an initial snapshot immediately so the frontend never
            # starts with a blank panel -- this is the single most
            # important fix for the "blank during first load" bug.
            snapshot = json.dumps(current_model_load_status(), sort_keys=True)
            yield f"data: {snapshot}\n\n"
            last_snapshot = snapshot
            # Keep the connection open, pushing every time the state
            # changes, until the load finishes (ready/error/idle).
            for _ in range(600):  # 5 minutes max
                await asyncio.sleep(0.5)
                status = current_model_load_status()
                snapshot = json.dumps(status, sort_keys=True)
                if snapshot != last_snapshot:
                    yield f"data: {snapshot}\n\n"
                    last_snapshot = snapshot
                terminal_status = status.get("status", "idle")
                if terminal_status in ("ready", "error", "idle"):
                    break
            yield "data: [DONE]\n\n"

        return StreamingResponse(
            stream(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "Connection": "keep-alive", "X-Accel-Buffering": "no"},
        )

