@asynccontextmanager
async def lifespan(app: FastAPI):
    """Application lifecycle manager."""
    logger.info(f"{APP_NAME} v{APP_VERSION} starting...")
    logger.info(f"BUILD TAG: {BUILD_TAG}")
    print(f"[MEERA BUILD TAG] {BUILD_TAG}", flush=True)

    # Initialize all services
    persistence = PersistenceManager()
    cloud_engine = CloudInferenceEngine(persistence)
    local_engine = LocalInferenceEngine(persistence)
    mcp_manager = MCPManager(persistence)
    rag_service = PageIndexingRAG(persistence, cloud_engine, local_engine)
    image_search = ImageSearchService(persistence)
    model_manager = GGUFModelManager(persistence, local_engine, cloud_engine)
    param_resolver = ParameterResolver(persistence.config.parameters)
    chat_service = ChatService(
        persistence, cloud_engine, local_engine, mcp_manager,
        rag_service, image_search, model_manager, param_resolver
    )

    browser_service = BrowserAutomationService()
    chat_service.browser_service = browser_service
    await browser_service.initialize()

    # Connect MCP servers
    await mcp_manager.initialize()

    # Create and mount router
    router = create_router(
        persistence, cloud_engine, local_engine, mcp_manager,
        rag_service, image_search, model_manager, param_resolver, chat_service
    )
    app.state.services = {
        "persistence": persistence,
        "cloud_engine": cloud_engine,
        "local_engine": local_engine,
        "mcp_manager": mcp_manager,
        "rag_service": rag_service,
        "image_search": image_search,
        "model_manager": model_manager,
        "chat_service": chat_service,
        "browser_service": browser_service,
    }
    app.include_router(router)

    logger.info("=================================")
    logger.info(f"| Inference Mode: {persistence.config.inference.mode.value}")
    logger.info(f"| MCP Servers: {len(mcp_manager.connections)}")
    logger.info(f"| RAG Documents: {len(persistence.list_rag_documents())}")

    # Initialize Meera Long-Term Memory System
    try:
        _mem_db_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data", "meera_memory.db")

        async def _memory_extract_callback(prompt: str) -> str:
            """Use the cloud LLM for memory fact extraction."""
            try:
                if cloud_engine and persistence.config.inference.mode == InferenceMode.CLOUD:
                    result = await cloud_engine.chat_completion(
                        messages=[{"role": "user", "content": prompt}],
                        params={"temperature": 0.1, "max_tokens": 500},
                        stream=False
                    )
                    if isinstance(result, dict):
                        return result.get("choices", [{}])[0].get("message", {}).get("content", "[]")
            except Exception:
                pass
            return "[]"

        async def _memory_route_callback(prompt: str) -> str:
            """Use the cloud LLM for memory routing decisions."""
            try:
                if cloud_engine and persistence.config.inference.mode == InferenceMode.CLOUD:
                    result = await cloud_engine.chat_completion(
                        messages=[{"role": "user", "content": prompt}],
                        params={"temperature": 0.0, "max_tokens": 10},
                        stream=False
                    )
                    if isinstance(result, dict):
                        return result.get("choices", [{}])[0].get("message", {}).get("content", "NO")
            except Exception:
                pass
            return "NO"

        async def _memory_embed_callback(text: str) -> list:
            """Use the existing RAG embedding infrastructure."""
            try:
                if rag_service:
                    return await rag_service._get_embedding(text)
            except Exception:
                pass
            # Fallback: deterministic hash-based embedding
            import struct
            h = hashlib.sha256(text.encode()).digest()
            return [struct.unpack('f', h[i:i+4])[0] % 1.0 for i in range(0, min(len(h), 128), 4)]

        init_meera_memory(_mem_db_path, _memory_extract_callback, _memory_route_callback, _memory_embed_callback)
        logger.info("| Meera Memory: ✅ Initialized")
    except Exception as e:
        logger.warning(f"| Meera Memory: ⚠️ Failed to initialize ({e})")

    logger.info(f"+=== Ready on http://127.0.0.1:8000 ===+")

    yield

    # Shutdown
    logger.info("Shutting down...")
    await mcp_manager.shutdown()
    await cloud_engine.close()
    await local_engine.close()
    await image_search.close()
    await browser_service.close()
    await asyncio.to_thread(MEERA_VOICE_ASR.close)
    await asyncio.to_thread(MEERA_VOICE_TTS.close)
    logger.info("Shutdown complete.")


def create_app() -> FastAPI:
    """Create and configure the FastAPI application."""
    app = FastAPI(
        title=APP_NAME,
        version=APP_VERSION,
        description=(
            "Professional Multi-Provider AI Chat Server with MCP, "
            "PageIndexing RAG, GGUF Model Management, and Image Search."
        ),
        docs_url="/api/docs",
        redoc_url="/api/redoc",
        openapi_url="/api/openapi.json",
        lifespan=lifespan,
    )

    # CORS - allow all origins for desktop app
    app.add_middleware(
        CORSMiddleware,
        allow_origins=["*"] if not os.environ.get("MEERA_CORS_STRICT") else ["http://localhost:3000", "http://127.0.0.1:3000"],
        allow_credentials=False if os.environ.get("MEERA_CORS_STRICT") else True,
        allow_methods=["*"],
        allow_headers=["*"],
        expose_headers=[
            "X-Meera-Voice-Engine",
            "X-Meera-Voice-Model",
            "X-Meera-Voice-Speaker",
            "X-Meera-Voice-Expression",
        ],
    )

    # Request logging middleware
    @app.middleware("http")
    async def log_requests(request: Request, call_next):
        start = time.time()
        response = await call_next(request)
        duration = time.time() - start
        if "/api/" in request.url.path:
            logger.debug(
                f"{request.method} {request.url.path} "
                f"â†’ {response.status_code} ({duration:.3f}s)"
            )
        return response

    # Global exception handler
    @app.exception_handler(Exception)
    async def global_exception_handler(request: Request, exc: Exception):
        logger.error(f"Unhandled exception: {exc}\n{traceback.format_exc()}")
        return JSONResponse(
            status_code=500,
            content={"error": str(exc), "type": type(exc).__name__}
        )

    # Simple health endpoint used by the desktop launcher
    @app.get("/health")
    async def health_check():
        return {"status": "healthy", "build_tag": BUILD_TAG}

    @app.post("/api/debug/parser")
    async def debug_parser(request: Request):
        body = await request.json()
        full_content = body.get("full_content", "")
        
        import re, json, uuid
        tool_calls_accum = []
        logs = []
        
        # 1. Check for <tool_call> XML blocks (with closing tag)
        tool_matches = re.finditer(r"<tool_call.*?>\s*({.*?})\s*</tool_call>", full_content, re.DOTALL | re.IGNORECASE)
        found_any = False
        for match in tool_matches:
            try:
                clean_str = re.sub(r'[\r\n]+', '', match.group(1))
                parsed_tool = json.loads(clean_str, strict=False)
                if "name" in parsed_tool and "arguments" in parsed_tool:
                    tool_calls_accum.append({"name": parsed_tool["name"]})
                    found_any = True
                    logs.append(f"Fallback 1 succeeded: {parsed_tool['name']}")
            except Exception as e:
                logs.append(f"Fallback 1 failed: {str(e)} for clean_str: {repr(clean_str)}")

        # 2. Fallback: <tool_call> without closing tag
        if not found_any:
            tc_open = re.search(r"<tool_call.*?>\s*({.*)", full_content, re.DOTALL | re.IGNORECASE)
            if tc_open:
                text_after_brace = tc_open.group(1)
                depth = 0
                in_string = False
                escape = False
                extracted_json = None
                
                for i, c in enumerate(text_after_brace):
                    if not escape and c == '"':
                        in_string = not in_string
                    if not in_string:
                        if c == '{': depth += 1
                        elif c == '}': depth -= 1
                    escape = (c == '\\' and not escape)
                    
                    if depth == 0 and i > 0:
                        extracted_json = text_after_brace[:i+1]
                        break
                        
                if extracted_json:
                    try:
                        clean_str = re.sub(r'[\r\n]+', '', extracted_json)
                        parsed_tool = json.loads(clean_str, strict=False)
                        if "name" in parsed_tool and "arguments" in parsed_tool:
                            tool_calls_accum.append({"name": parsed_tool["name"]})
                            found_any = True
                            logs.append(f"Fallback 2 succeeded: {parsed_tool['name']}")
                    except Exception as e:
                        logs.append(f"Fallback 2 failed: {str(e)} for clean_str: {repr(clean_str)}")
                else:
                    logs.append("Fallback 2 failed: extracted_json was None")

        return {"tool_calls_accum": tool_calls_accum, "logs": logs}

    @app.api_route("/api/documents/{filename}", methods=["GET", "HEAD"])
    async def serve_document(filename: str):
        """Serve generated research documents for download with path traversal defense."""
        from document_generator import DOCUMENTS_DIR
        clean_name = os.path.basename(filename)
        filepath = (DOCUMENTS_DIR / clean_name).resolve()
        if not filepath.exists() or not filepath.is_relative_to(DOCUMENTS_DIR.resolve()):
            raise HTTPException(status_code=404, detail="Document not found")
        content_types = {
            ".pdf": "application/pdf",
            ".docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            ".html": "text/html",
            ".md": "text/markdown",
        }
        ext = filepath.suffix.lower()
        media_type = content_types.get(ext, "application/octet-stream")
        from starlette.responses import FileResponse
        disposition = "inline" if ext in [".html", ".htm", ".pdf", ".md", ".txt"] else "attachment"
        return FileResponse(
            path=str(filepath),
            filename=filename,
            media_type=media_type,
            headers={"Content-Disposition": f'{disposition}; filename="{filename}"'}
        )

    return app


